// CalcName computes the Name calculated field
// Human-readable calculated display alias for the OntologyProfiles row.
// Formula: ={{Label}} & " " & {{Version}}
func (tc *OntologyProfile) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Label)), vS(" "), erbText(vStr(tc.Version))))
}

// CalcDaysSinceLastRevision computes the DaysSinceLastRevision calculated field
// Days since any revision.
// Formula: =IF({{LastRevisedAt}} = "", 0, DATETIME_DIFF({{AsOfInstant}}, {{LastRevisedAt}}, "days"))
func (tc *OntologyProfile) CalcDaysSinceLastRevision() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.LastRevisedAt))), func() Value { return vI(0) }, func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.LastRevisedAt), vS("days")) })))
}

// CalcDaysSinceMajorRevision computes the DaysSinceMajorRevision calculated field
// Days since the last major revision.
// Formula: =IF({{LastMajorRevisionAt}} = "", 0, DATETIME_DIFF({{AsOfInstant}}, {{LastMajorRevisionAt}}, "days"))
func (tc *OntologyProfile) CalcDaysSinceMajorRevision() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.LastMajorRevisionAt))), func() Value { return vI(0) }, func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.LastMajorRevisionAt), vS("days")) })))
}

// CalcDaysSinceDependencyReviewed computes the DaysSinceDependencyReviewed calculated field
// Days since our dependency review.
// Formula: =IF({{DependencyReviewedAt}} = "", 0, DATETIME_DIFF({{AsOfInstant}}, {{DependencyReviewedAt}}, "days"))
func (tc *OntologyProfile) CalcDaysSinceDependencyReviewed() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.DependencyReviewedAt))), func() Value { return vI(0) }, func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.DependencyReviewedAt), vS("days")) })))
}

// CalcRequiresFrequentReview computes the RequiresFrequentReview calculated field
// TRUE when the standard deprecates often or went through a major revision in the last two years.
// Formula: =OR({{RecentDeprecationCount}} >= 2, AND({{LastMajorRevisionAt}} <> "", {{DaysSinceMajorRevision}} < 730))
func (tc *OntologyProfile) CalcRequiresFrequentReview() *bool {
	return toBoolPtr(erbOr(erbBool3(erbCmp(vInt(tc.RecentDeprecationCount), ">=", vI(2))), erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.LastMajorRevisionAt))), erbBool3(erbCmp(vInt(tc.DaysSinceMajorRevision), "<", vI(730)))))))
}

// CalcChangeRateProfile computes the ChangeRateProfile calculated field
// How fast the standard changes: FrequentDeprecation, RecentMajorRevision, Dormant, or Unassessed.
// Formula: =IF({{RecentDeprecationCount}} >= 2, "FrequentDeprecation", IF(AND({{LastMajorRevisionAt}} <> "", {{DaysSinceMajorRevision}} < 730), "RecentMajorRevision", IF(AND({{LastRevisedAt}} <> "", {{DaysSinceLastRevision}} > 3650), "Dormant", "Unassessed")))
func (tc *OntologyProfile) CalcChangeRateProfile() *string {
	return toStringPtr(erbIf(erbBool3(erbCmp(vInt(tc.RecentDeprecationCount), ">=", vI(2))), func() Value { return vS("FrequentDeprecation") }, func() Value { return erbIf(erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.LastMajorRevisionAt))), erbBool3(erbCmp(vInt(tc.DaysSinceMajorRevision), "<", vI(730))))), func() Value { return vS("RecentMajorRevision") }, func() Value { return erbIf(erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.LastRevisedAt))), erbBool3(erbCmp(vInt(tc.DaysSinceLastRevision), ">", vI(3650))))), func() Value { return vS("Dormant") }, func() Value { return vS("Unassessed") }) }) }))
}

// CalcIsReviewOverdueForChangeRate computes the IsReviewOverdueForChangeRate calculated field
// TRUE when a fast-changing standard has not had its dependency reviewed in 180 days.
// Formula: =AND({{RequiresFrequentReview}}, OR({{DependencyReviewedAt}} = "", {{DaysSinceDependencyReviewed}} > 180))
func (tc *OntologyProfile) CalcIsReviewOverdueForChangeRate() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RequiresFrequentReview)), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.DependencyReviewedAt))), erbBool3(erbCmp(vInt(tc.DaysSinceDependencyReviewed), ">", vI(180)))))))
}

// CalcSkipsAdoptionPath computes the SkipsAdoptionPath calculated field
// TRUE when a later-stage standard was adopted before the earlier-stage standard it builds on, or with none.
// Formula: =AND({{AdoptionStage}} > 1, OR({{PrerequisiteProfile}} = "", {{PrerequisiteAdoptedAt}} = "", {{PrerequisiteAdoptedAt}} > {{AdoptedAt}}))
func (tc *OntologyProfile) CalcSkipsAdoptionPath() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vInt(tc.AdoptionStage)), ">", vI(1))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.PrerequisiteProfile))), erbBool3(erbIsBlank(vStr(tc.PrerequisiteAdoptedAt))), erbBool3(erbCmp(vStr(tc.PrerequisiteAdoptedAt), ">", erbNullif(vStr(tc.AdoptedAt))))))))
}

// CalcNamespaceIsHttp computes the NamespaceIsHttp calculated field
// Whether the namespace is an HTTP(S) URI, the first Linked Data requirement, rather than a urn: or other non-resolvable identifier.
// Formula: =OR(LEFT({{NamespaceIri}}, 7) = "http://", LEFT({{NamespaceIri}}, 8) = "https://")
func (tc *OntologyProfile) CalcNamespaceIsHttp() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbLeft(vStr(tc.NamespaceIri), vI(7)), vS("http://"))), erbBool3(erbEq(erbLeft(vStr(tc.NamespaceIri), vI(8)), vS("https://")))))
}

// CalcNamespaceDereferences computes the NamespaceDereferences calculated field
// The namespace is an HTTP URI and fetching it actually returned a document.
// Formula: =AND({{NamespaceIsHttp}}, {{NamespaceHttpStatus}} = 200)
func (tc *OntologyProfile) CalcNamespaceDereferences() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.NamespaceIsHttp)), erbBool3(erbEq(erbNullif(vInt(tc.NamespaceHttpStatus)), vI(200)))))
}

// CalcPublishesFollowingLinkedDataPrinciples computes the PublishesFollowingLinkedDataPrinciples calculated field
// The vocabulary is published the way Linked Data requires: an HTTP URI that resolves, serves RDF when asked for it, and carries links to other terms.
// Formula: =AND({{NamespaceDereferences}}, {{NamespaceServesRdf}}, {{MappingCount}} > 0)
func (tc *OntologyProfile) CalcPublishesFollowingLinkedDataPrinciples() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.NamespaceDereferences)), erbIsTrue(vBool(tc.NamespaceServesRdf)), erbBool3(erbCmp(vInt(tc.MappingCount), ">", vI(0)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *OntologyProfile) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "days_since_last_revision", func() { tc.DaysSinceLastRevision = tc.CalcDaysSinceLastRevision() })
	calcGuard(tc, "days_since_major_revision", func() { tc.DaysSinceMajorRevision = tc.CalcDaysSinceMajorRevision() })
	calcGuard(tc, "days_since_dependency_reviewed", func() { tc.DaysSinceDependencyReviewed = tc.CalcDaysSinceDependencyReviewed() })
	calcGuard(tc, "skips_adoption_path", func() { tc.SkipsAdoptionPath = tc.CalcSkipsAdoptionPath() })
	calcGuard(tc, "namespace_is_http", func() { tc.NamespaceIsHttp = tc.CalcNamespaceIsHttp() })
	// Level 2
	calcGuard(tc, "requires_frequent_review", func() { tc.RequiresFrequentReview = tc.CalcRequiresFrequentReview() })
	calcGuard(tc, "change_rate_profile", func() { tc.ChangeRateProfile = tc.CalcChangeRateProfile() })
	calcGuard(tc, "namespace_dereferences", func() { tc.NamespaceDereferences = tc.CalcNamespaceDereferences() })
	// Level 3
	calcGuard(tc, "is_review_overdue_for_change_rate", func() { tc.IsReviewOverdueForChangeRate = tc.CalcIsReviewOverdueForChangeRate() })
	calcGuard(tc, "publishes_following_linked_data_principles", func() { tc.PublishesFollowingLinkedDataPrinciples = tc.CalcPublishesFollowingLinkedDataPrinciples() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *OntologyProfile) ComputeAll() *OntologyProfile {
	tc.erbComputeCalculations()
	return tc
}

