// Organization represents a row in the Organizations table
type Organization struct {
	OrganizationId string `json:"organization_id"` // Stored logical identifier for one Organizations row.
	Name *string `json:"name"` // Human-readable calculated display alias for the Organizations row.
	DisplayName *string `json:"display_name"` // Organization's human-readable name.
	OrganizationType *string `json:"organization_type"` // Type such as Company, Department, Vendor, or Regulator.
	ExternalIdentifier *string `json:"external_identifier"` // Identifier in an operational directory or master-data system.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact RDF class IRI for the organization.
	FailedAiInitiativeCount *int `json:"failed_ai_initiative_count"` // AI initiatives that failed.
	OwnedProcedureCount *int `json:"owned_procedure_count"` // Procedures the organization has captured.
	AiFailsForLackOfCapturedKnowledge *bool `json:"ai_fails_for_lack_of_captured_knowledge"` // TRUE for an organization with a failed AI initiative that has captured no procedures.
	ProductDeliveryFunctionCount *int `json:"product_delivery_function_count"` // Functions that deliver the organization's own products.
	ProviderHeldDeliveryMethodCount *int `json:"provider_held_delivery_method_count"` // Of those, functions whose method knowledge a provider holds.
	IsHollowedOutFirm *bool `json:"is_hollowed_out_firm"` // TRUE when every function that delivers the organization's own products depends on method knowledge a provider holds.
	AuditFindingCount *int `json:"audit_finding_count"` // Audit items where the organization holds less knowledge than it needs.
	FilledKnowledgePositionCount *int `json:"filled_knowledge_position_count"` // Filled knowledge engineering, information architecture and ontology positions.
	HasKnowledgeFindingsWithoutKnowledgeStaff *bool `json:"has_knowledge_findings_without_knowledge_staff"` // TRUE when audits found knowledge shortfalls and the organization employs no knowledge engineer, information architect or ontologist to address them.
	DepartedHolderKnowHowCount *int `json:"departed_holder_know_how_count"` // Know-how whose carrier has left.
	LostDepartedKnowHowCount *int `json:"lost_departed_know_how_count"` // Know-how that left with its carrier, neither transferred nor captured.
	RetainedDepartedKnowHowPercent *float64 `json:"retained_departed_know_how_percent"` // Share of departed carriers' know-how the organization kept.
	MemoryLeavesWithStaff *bool `json:"memory_leaves_with_staff"` // TRUE when some know-how of people who left was not retained.
	CapturedOwnKnowHowCount *int `json:"captured_own_know_how_count"` // The organization's own know-how captured in its repository.
	DocumentationEntryCount *int `json:"documentation_entry_count"` // Repository entries for the organization's procedures.
	UnallocatedDocumentationCount *int `json:"unallocated_documentation_count"` // Entries written outside allotted time.
	TransferGivenCount *int `json:"transfer_given_count"` // Transfers given by the organization's people.
	UnallocatedTransferCount *int `json:"unallocated_transfer_count"` // Transfers given outside allotted time.
	TreatsKnowledgeWorkAsUnvalued *bool `json:"treats_knowledge_work_as_unvalued"` // TRUE when most documentation and knowledge transfer happens outside the time the organization allots.
	PersonCarriedKnowHowCount *int `json:"person_carried_know_how_count"` // Know-how carried by people.
	FacilityCarriedKnowHowCount *int `json:"facility_carried_know_how_count"` // Know-how carried by plants.
	SystemCarriedKnowHowCount *int `json:"system_carried_know_how_count"` // Know-how carried by systems.
	HoldsKnowHowInPeoplePlantsAndSystems *bool `json:"holds_know_how_in_people_plants_and_systems"` // TRUE when the organization's how-to-build knowledge is carried at once by people, plants and systems.
	StagedDeclineCount *int `json:"staged_decline_count"` // Capability declines that followed the decline of the preceding stage.
	ErodedInStages *bool `json:"eroded_in_stages"` // TRUE when facility investment, then engineer training, then how-to-make upkeep declined in sequence.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Organizations row.
// Formula: ={{DisplayName}}
func (tc *Organization) CalcName() *string {
	return toStringPtr(vStr(tc.DisplayName))
}

// CalcAiFailsForLackOfCapturedKnowledge computes the AiFailsForLackOfCapturedKnowledge calculated field
// TRUE for an organization with a failed AI initiative that has captured no procedures.
// Formula: =AND({{FailedAiInitiativeCount}} > 0, {{OwnedProcedureCount}} = 0)
func (tc *Organization) CalcAiFailsForLackOfCapturedKnowledge() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.FailedAiInitiativeCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.OwnedProcedureCount), vI(0)))))
}

// CalcIsHollowedOutFirm computes the IsHollowedOutFirm calculated field
// TRUE when every function that delivers the organization's own products depends on method knowledge a provider holds.
// Formula: =AND({{ProductDeliveryFunctionCount}} > 0, {{ProviderHeldDeliveryMethodCount}} = {{ProductDeliveryFunctionCount}})
func (tc *Organization) CalcIsHollowedOutFirm() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.ProductDeliveryFunctionCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.ProviderHeldDeliveryMethodCount), vInt(tc.ProductDeliveryFunctionCount)))))
}

// CalcHasKnowledgeFindingsWithoutKnowledgeStaff computes the HasKnowledgeFindingsWithoutKnowledgeStaff calculated field
// TRUE when audits found knowledge shortfalls and the organization employs no knowledge engineer, information architect or ontologist to address them.
// Formula: =AND({{AuditFindingCount}} > 0, {{FilledKnowledgePositionCount}} = 0)
func (tc *Organization) CalcHasKnowledgeFindingsWithoutKnowledgeStaff() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.AuditFindingCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.FilledKnowledgePositionCount), vI(0)))))
}

// CalcRetainedDepartedKnowHowPercent computes the RetainedDepartedKnowHowPercent calculated field
// Share of departed carriers' know-how the organization kept.
// Formula: =IF({{DepartedHolderKnowHowCount}} = 0, 100, ROUND(100 * ({{DepartedHolderKnowHowCount}} - {{LostDepartedKnowHowCount}}) / {{DepartedHolderKnowHowCount}}, 0))
func (tc *Organization) CalcRetainedDepartedKnowHowPercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbEq(vInt(tc.DepartedHolderKnowHowCount), vI(0))), func() Value { return vI(100) }, func() Value { return erbRound(erbDiv(erbMul(vI(100), erbSub(vInt(tc.DepartedHolderKnowHowCount), vInt(tc.LostDepartedKnowHowCount))), vInt(tc.DepartedHolderKnowHowCount)), vI(0)) }))
}

// CalcMemoryLeavesWithStaff computes the MemoryLeavesWithStaff calculated field
// TRUE when some know-how of people who left was not retained.
// Formula: =AND({{DepartedHolderKnowHowCount}} > 0, {{RetainedDepartedKnowHowPercent}} < 100)
func (tc *Organization) CalcMemoryLeavesWithStaff() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.DepartedHolderKnowHowCount), ">", vI(0))), erbBool3(erbCmp(vNum(tc.RetainedDepartedKnowHowPercent), "<", vI(100)))))
}

// CalcTreatsKnowledgeWorkAsUnvalued computes the TreatsKnowledgeWorkAsUnvalued calculated field
// TRUE when most documentation and knowledge transfer happens outside the time the organization allots.
// Formula: =AND({{DocumentationEntryCount}} + {{TransferGivenCount}} > 0, 2 * ({{UnallocatedDocumentationCount}} + {{UnallocatedTransferCount}}) > {{DocumentationEntryCount}} + {{TransferGivenCount}})
func (tc *Organization) CalcTreatsKnowledgeWorkAsUnvalued() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbAdd(vInt(tc.DocumentationEntryCount), vInt(tc.TransferGivenCount)), ">", vI(0))), erbBool3(erbCmp(erbMul(vI(2), erbAdd(vInt(tc.UnallocatedDocumentationCount), vInt(tc.UnallocatedTransferCount))), ">", erbAdd(vInt(tc.DocumentationEntryCount), vInt(tc.TransferGivenCount))))))
}

// CalcHoldsKnowHowInPeoplePlantsAndSystems computes the HoldsKnowHowInPeoplePlantsAndSystems calculated field
// TRUE when the organization's how-to-build knowledge is carried at once by people, plants and systems.
// Formula: =AND({{PersonCarriedKnowHowCount}} > 0, {{FacilityCarriedKnowHowCount}} > 0, {{SystemCarriedKnowHowCount}} > 0)
func (tc *Organization) CalcHoldsKnowHowInPeoplePlantsAndSystems() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.PersonCarriedKnowHowCount), ">", vI(0))), erbBool3(erbCmp(vInt(tc.FacilityCarriedKnowHowCount), ">", vI(0))), erbBool3(erbCmp(vInt(tc.SystemCarriedKnowHowCount), ">", vI(0)))))
}

// CalcErodedInStages computes the ErodedInStages calculated field
// TRUE when facility investment, then engineer training, then how-to-make upkeep declined in sequence.
// Formula: ={{StagedDeclineCount}} >= 2
func (tc *Organization) CalcErodedInStages() *bool {
	return toBoolPtr(erbCmp(vInt(tc.StagedDeclineCount), ">=", vI(2)))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *Organization) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "ai_fails_for_lack_of_captured_knowledge", func() { tc.AiFailsForLackOfCapturedKnowledge = tc.CalcAiFailsForLackOfCapturedKnowledge() })
	calcGuard(tc, "is_hollowed_out_firm", func() { tc.IsHollowedOutFirm = tc.CalcIsHollowedOutFirm() })
	calcGuard(tc, "has_knowledge_findings_without_knowledge_staff", func() { tc.HasKnowledgeFindingsWithoutKnowledgeStaff = tc.CalcHasKnowledgeFindingsWithoutKnowledgeStaff() })
	calcGuard(tc, "retained_departed_know_how_percent", func() { tc.RetainedDepartedKnowHowPercent = tc.CalcRetainedDepartedKnowHowPercent() })
	calcGuard(tc, "treats_knowledge_work_as_unvalued", func() { tc.TreatsKnowledgeWorkAsUnvalued = tc.CalcTreatsKnowledgeWorkAsUnvalued() })
	calcGuard(tc, "holds_know_how_in_people_plants_and_systems", func() { tc.HoldsKnowHowInPeoplePlantsAndSystems = tc.CalcHoldsKnowHowInPeoplePlantsAndSystems() })
	calcGuard(tc, "eroded_in_stages", func() { tc.ErodedInStages = tc.CalcErodedInStages() })
	// Level 2
	calcGuard(tc, "memory_leaves_with_staff", func() { tc.MemoryLeavesWithStaff = tc.CalcMemoryLeavesWithStaff() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *Organization) ComputeAll() *Organization {
	tc.erbComputeCalculations()
	return tc
}

