// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Agents row.
// Formula: ={{DisplayName}}
func (tc *Agent) CalcName() *string {
	return toStringPtr(vStr(tc.DisplayName))
}

// CalcIsStillEngaged computes the IsStillEngaged calculated field
// TRUE when this agent currently holds at least one role in the organization.
// Formula: ={{CountOfCurrentRoleAssignments}} > 0
func (tc *Agent) CalcIsStillEngaged() *bool {
	return toBoolPtr(erbCmp(vInt(tc.CountOfCurrentRoleAssignments), ">", vI(0)))
}

// CalcOverrideRatePercent computes the OverrideRatePercent calculated field
// Percentage of this agent's decisions that were overridden by a human.
// Formula: =IF({{DecisionCount}} = 0, 0, ({{OverriddenDecisionCount}} * 100) / {{DecisionCount}})
func (tc *Agent) CalcOverrideRatePercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbEq(vNum(tc.DecisionCount), vI(0))), func() Value { return vI(0) }, func() Value { return erbDiv(erbMul(vNum(tc.OverriddenDecisionCount), vI(100)), vNum(tc.DecisionCount)) }))
}

// CalcIsNonHuman computes the IsNonHuman calculated field
// TRUE when this agent is an AI agent or an automated pipeline.
// Formula: =NOT({{AgentKind}} = "Human")
func (tc *Agent) CalcIsNonHuman() *bool {
	return toBoolPtr(erbNot(erbBool3(erbEq(erbNullif(vStr(tc.AgentKind)), vS("Human")))))
}

// CalcIsOperatingOutsideBoundary computes the IsOperatingOutsideBoundary calculated field
// TRUE when this agent has made at least one decision an authority boundary forbids.
// Formula: ={{BoundaryViolationCount}} > 0
func (tc *Agent) CalcIsOperatingOutsideBoundary() *bool {
	return toBoolPtr(erbCmp(vNum(tc.BoundaryViolationCount), ">", vI(0)))
}

// CalcDraftRewriteRatePercent computes the DraftRewriteRatePercent calculated field
// Percentage of this agent's drafting output that a human rewrote.
// Formula: =IF({{DraftDecisionCount}} = 0, 0, ({{OverriddenDraftCount}} * 100) / {{DraftDecisionCount}})
func (tc *Agent) CalcDraftRewriteRatePercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbEq(vNum(tc.DraftDecisionCount), vI(0))), func() Value { return vI(0) }, func() Value { return erbDiv(erbMul(vNum(tc.OverriddenDraftCount), vI(100)), vNum(tc.DraftDecisionCount)) }))
}

// CalcIsRecognizedBroker computes the IsRecognizedBroker calculated field
// TRUE when at least three people actively rely on this agent as an informal knowledge broker.
// Formula: ={{TimesNamedAsBroker}} >= 3
func (tc *Agent) CalcIsRecognizedBroker() *bool {
	return toBoolPtr(erbCmp(vNum(tc.TimesNamedAsBroker), ">=", vI(3)))
}

// CalcHasAtRiskKnowledgeReliance computes the HasAtRiskKnowledgeReliance calculated field
// TRUE when people are actively relying on this agent even though they have already left every role.
// Formula: ={{AtRiskRelianceCount}} > 0
func (tc *Agent) CalcHasAtRiskKnowledgeReliance() *bool {
	return toBoolPtr(erbCmp(vNum(tc.AtRiskRelianceCount), ">", vI(0)))
}

// CalcIsOrganizationAgent computes the IsOrganizationAgent calculated field
// TRUE for an organization acting as an agent.
// Formula: ={{RepresentsOrganization}} <> ""
func (tc *Agent) CalcIsOrganizationAgent() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.RepresentsOrganization)))
}

// CalcAiTaskCompletionPercent computes the AiTaskCompletionPercent calculated field
// Share of the agent's tasks that completed.
// Formula: =IF({{AnswerCount}} = 0, 0, ROUND(100 * {{AiTaskCompletedCount}} / {{AnswerCount}}, 1))
func (tc *Agent) CalcAiTaskCompletionPercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbEq(vInt(tc.AnswerCount), vI(0))), func() Value { return vI(0) }, func() Value { return erbRound(erbDiv(erbMul(vI(100), vInt(tc.AiTaskCompletedCount)), vInt(tc.AnswerCount)), vI(1)) }))
}

// CalcIsBelowTaskCompletionTarget computes the IsBelowTaskCompletionTarget calculated field
// TRUE for an AI agent completing fewer than 80% of its tasks.
// Formula: =AND({{AnswerCount}} > 0, {{AiTaskCompletionPercent}} < 80)
func (tc *Agent) CalcIsBelowTaskCompletionTarget() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.AnswerCount), ">", vI(0))), erbBool3(erbCmp(vNum(tc.AiTaskCompletionPercent), "<", vI(80)))))
}

// CalcLacksRuntimeKnowledgeIntegration computes the LacksRuntimeKnowledgeIntegration calculated field
// TRUE for an AI agent that answers people but receives no knowledge at run time.
// Formula: =AND({{AgentKind}} = "AIAgent", {{AnswerCount}} > 0, {{RuntimeIntegrationCount}} = 0)
func (tc *Agent) CalcLacksRuntimeKnowledgeIntegration() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AgentKind)), vS("AIAgent"))), erbBool3(erbCmp(vInt(tc.AnswerCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.RuntimeIntegrationCount), vI(0)))))
}

// CalcIsUntrackedAiConsumer computes the IsUntrackedAiConsumer calculated field
// TRUE for an AI agent that consumes knowledge but whose retrievals are never logged.
// Formula: =AND({{AgentKind}} = "AIAgent", {{AnswerCount}} > 0, {{SearchEventCount}} = 0)
func (tc *Agent) CalcIsUntrackedAiConsumer() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AgentKind)), vS("AIAgent"))), erbBool3(erbCmp(vInt(tc.AnswerCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.SearchEventCount), vI(0)))))
}

// CalcCategoryNotAvailableAsInference computes the CategoryNotAvailableAsInference calculated field
// TRUE for an agent named in accountability assertions whose category the graph never infers.
// Formula: =AND({{AccountabilityAssertionCount}} > 0, {{InferredCategoryCount}} = 0)
func (tc *Agent) CalcCategoryNotAvailableAsInference() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.AccountabilityAssertionCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.InferredCategoryCount), vI(0)))))
}

// CalcIsUnclassifiedAgent computes the IsUnclassifiedAgent calculated field
// TRUE when an agent is not classified as a person, AI agent, automated pipeline or organization.
// Formula: =AND({{AgentKind}} <> "Human", {{AgentKind}} <> "AIAgent", {{AgentKind}} <> "AutomatedPipeline", {{AgentKind}} <> "Organization")
func (tc *Agent) CalcIsUnclassifiedAgent() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNe(erbNullif(vStr(tc.AgentKind)), vS("Human"))), erbBool3(erbNe(erbNullif(vStr(tc.AgentKind)), vS("AIAgent"))), erbBool3(erbNe(erbNullif(vStr(tc.AgentKind)), vS("AutomatedPipeline"))), erbBool3(erbNe(erbNullif(vStr(tc.AgentKind)), vS("Organization")))))
}

// CalcIsAiAgentWithoutModelVersion computes the IsAiAgentWithoutModelVersion calculated field
// TRUE for an AI agent carrying no model version identifier.
// Formula: =AND({{AgentKind}} = "AIAgent", {{VersionOrEmploymentKey}} = "")
func (tc *Agent) CalcIsAiAgentWithoutModelVersion() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AgentKind)), vS("AIAgent"))), erbBool3(erbIsBlank(vStr(tc.VersionOrEmploymentKey)))))
}

// CalcHasProducedArtifacts computes the HasProducedArtifacts calculated field
// TRUE when some artifact is attributed to the agent.
// Formula: ={{AttributedArtifactCount}} > 0
func (tc *Agent) CalcHasProducedArtifacts() *bool {
	return toBoolPtr(erbCmp(vInt(tc.AttributedArtifactCount), ">", vI(0)))
}

// CalcHasArtifactBlastRadius computes the HasArtifactBlastRadius calculated field
// TRUE when moving the agent to another version affects steps downstream of its artifacts.
// Formula: ={{ArtifactBlastRadiusStepCount}} > 0
func (tc *Agent) CalcHasArtifactBlastRadius() *bool {
	return toBoolPtr(erbCmp(vInt(tc.ArtifactBlastRadiusStepCount), ">", vI(0)))
}

// CalcIsAiAgentNotFilledFromRegistry computes the IsAiAgentNotFilledFromRegistry calculated field
// TRUE for an AI agent individual that no registry record supplies, or whose version disagrees with the registry.
// Formula: =AND({{AgentKind}} = "AIAgent", {{RegistryVersionMatchCount}} = 0)
func (tc *Agent) CalcIsAiAgentNotFilledFromRegistry() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AgentKind)), vS("AIAgent"))), erbBool3(erbEq(vInt(tc.RegistryVersionMatchCount), vI(0)))))
}

// CalcIsAiAgentWithoutAccountableHuman computes the IsAiAgentWithoutAccountableHuman calculated field
// TRUE for an AI agent currently filling a role with no human person accountable for it.
// Formula: =AND({{AgentKind}} = "AIAgent", {{CountOfCurrentRoleAssignments}} > 0, {{CurrentAccountableHumanCount}} = 0)
func (tc *Agent) CalcIsAiAgentWithoutAccountableHuman() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AgentKind)), vS("AIAgent"))), erbBool3(erbCmp(vInt(tc.CountOfCurrentRoleAssignments), ">", vI(0))), erbBool3(erbEq(vInt(tc.CurrentAccountableHumanCount), vI(0)))))
}

// CalcIsBoundarySpanner computes the IsBoundarySpanner calculated field
// TRUE when the agent belongs to two or more communities of practice.
// Formula: ={{CommunityCount}} >= 2
func (tc *Agent) CalcIsBoundarySpanner() *bool {
	return toBoolPtr(erbCmp(vInt(tc.CommunityCount), ">=", vI(2)))
}

// CalcIsUnidentifiedBoundarySpanner computes the IsUnidentifiedBoundarySpanner calculated field
// TRUE when a person connecting communities was never found by a network analysis.
// Formula: =AND({{IsBoundarySpanner}}, {{SnaIdentificationCount}} = 0)
func (tc *Agent) CalcIsUnidentifiedBoundarySpanner() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsBoundarySpanner)), erbBool3(erbEq(vInt(tc.SnaIdentificationCount), vI(0)))))
}

// CalcLacksTimeToMentor computes the LacksTimeToMentor calculated field
// TRUE when a mentor's protected hours fall short of what their active mentorships need.
// Formula: =AND({{RequiredMentoringHoursPerWeek}} > 0, {{ProtectedMentoringHoursPerWeek}} < {{RequiredMentoringHoursPerWeek}})
func (tc *Agent) CalcLacksTimeToMentor() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vNum(tc.RequiredMentoringHoursPerWeek), ">", vI(0))), erbBool3(erbCmp(erbNullif(vNum(tc.ProtectedMentoringHoursPerWeek)), "<", vNum(tc.RequiredMentoringHoursPerWeek)))))
}

// CalcIsUnrewardedSharer computes the IsUnrewardedSharer calculated field
// TRUE when someone who repeatedly passes know-how on has never been recognized for it.
// Formula: =AND({{TransfersGivenCount}} >= 2, {{RecognitionCount}} = 0)
func (tc *Agent) CalcIsUnrewardedSharer() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.TransfersGivenCount), ">=", vI(2))), erbBool3(erbEq(vInt(tc.RecognitionCount), vI(0)))))
}

// CalcArtifactBlastRadiusStepCount computes the ArtifactBlastRadiusStepCount calculated field
// For an AI agent, the steps downstream of the steps it holds, found by traversing the artifact hand-off closure.
// Formula: =IF({{AgentKind}} = "AIAgent", {{DownstreamOfHeldStepsCount}}, 0)
func (tc *Agent) CalcArtifactBlastRadiusStepCount() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.AgentKind)), vS("AIAgent"))), func() Value { return vInt(tc.DownstreamOfHeldStepsCount) }, func() Value { return vI(0) })))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *Agent) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_still_engaged", func() { tc.IsStillEngaged = tc.CalcIsStillEngaged() })
	calcGuard(tc, "override_rate_percent", func() { tc.OverrideRatePercent = tc.CalcOverrideRatePercent() })
	calcGuard(tc, "is_non_human", func() { tc.IsNonHuman = tc.CalcIsNonHuman() })
	calcGuard(tc, "is_operating_outside_boundary", func() { tc.IsOperatingOutsideBoundary = tc.CalcIsOperatingOutsideBoundary() })
	calcGuard(tc, "draft_rewrite_rate_percent", func() { tc.DraftRewriteRatePercent = tc.CalcDraftRewriteRatePercent() })
	calcGuard(tc, "is_recognized_broker", func() { tc.IsRecognizedBroker = tc.CalcIsRecognizedBroker() })
	calcGuard(tc, "has_at_risk_knowledge_reliance", func() { tc.HasAtRiskKnowledgeReliance = tc.CalcHasAtRiskKnowledgeReliance() })
	calcGuard(tc, "is_organization_agent", func() { tc.IsOrganizationAgent = tc.CalcIsOrganizationAgent() })
	calcGuard(tc, "ai_task_completion_percent", func() { tc.AiTaskCompletionPercent = tc.CalcAiTaskCompletionPercent() })
	calcGuard(tc, "lacks_runtime_knowledge_integration", func() { tc.LacksRuntimeKnowledgeIntegration = tc.CalcLacksRuntimeKnowledgeIntegration() })
	calcGuard(tc, "is_untracked_ai_consumer", func() { tc.IsUntrackedAiConsumer = tc.CalcIsUntrackedAiConsumer() })
	calcGuard(tc, "category_not_available_as_inference", func() { tc.CategoryNotAvailableAsInference = tc.CalcCategoryNotAvailableAsInference() })
	calcGuard(tc, "is_unclassified_agent", func() { tc.IsUnclassifiedAgent = tc.CalcIsUnclassifiedAgent() })
	calcGuard(tc, "is_ai_agent_without_model_version", func() { tc.IsAiAgentWithoutModelVersion = tc.CalcIsAiAgentWithoutModelVersion() })
	calcGuard(tc, "has_produced_artifacts", func() { tc.HasProducedArtifacts = tc.CalcHasProducedArtifacts() })
	calcGuard(tc, "is_ai_agent_not_filled_from_registry", func() { tc.IsAiAgentNotFilledFromRegistry = tc.CalcIsAiAgentNotFilledFromRegistry() })
	calcGuard(tc, "is_ai_agent_without_accountable_human", func() { tc.IsAiAgentWithoutAccountableHuman = tc.CalcIsAiAgentWithoutAccountableHuman() })
	calcGuard(tc, "is_boundary_spanner", func() { tc.IsBoundarySpanner = tc.CalcIsBoundarySpanner() })
	calcGuard(tc, "lacks_time_to_mentor", func() { tc.LacksTimeToMentor = tc.CalcLacksTimeToMentor() })
	calcGuard(tc, "is_unrewarded_sharer", func() { tc.IsUnrewardedSharer = tc.CalcIsUnrewardedSharer() })
	calcGuard(tc, "artifact_blast_radius_step_count", func() { tc.ArtifactBlastRadiusStepCount = tc.CalcArtifactBlastRadiusStepCount() })
	// Level 2
	calcGuard(tc, "is_below_task_completion_target", func() { tc.IsBelowTaskCompletionTarget = tc.CalcIsBelowTaskCompletionTarget() })
	calcGuard(tc, "has_artifact_blast_radius", func() { tc.HasArtifactBlastRadius = tc.CalcHasArtifactBlastRadius() })
	calcGuard(tc, "is_unidentified_boundary_spanner", func() { tc.IsUnidentifiedBoundarySpanner = tc.CalcIsUnidentifiedBoundarySpanner() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *Agent) ComputeAll() *Agent {
	tc.erbComputeCalculations()
	return tc
}

