func (tc *Agent) erbLoad(row map[string]any) {
	for key, value := range row {
		switch key {
		case "agent_id", "name", "display_name", "agent_kind", "organization", "contact_address", "version_or_employment_key", "count_of_current_role_assignments", "is_still_engaged", "decision_count", "overridden_decision_count", "override_rate_percent", "is_non_human", "boundary_violation_count", "is_operating_outside_boundary", "draft_decision_count", "overridden_draft_count", "draft_rewrite_rate_percent", "times_named_as_broker", "is_recognized_broker", "at_risk_reliance_count", "has_at_risk_knowledge_reliance", "semantic_type_iri", "represents_organization", "is_organization_agent", "answer_count", "ai_task_completed_count", "ai_task_completion_percent", "is_below_task_completion_target", "runtime_integration_count", "lacks_runtime_knowledge_integration", "search_event_count", "is_untracked_ai_consumer", "accountability_assertion_count", "inferred_category_count", "category_not_available_as_inference", "is_unclassified_agent", "is_ai_agent_without_model_version", "attributed_artifact_count", "has_produced_artifacts", "has_artifact_blast_radius", "registry_version_match_count", "is_ai_agent_not_filled_from_registry", "current_accountable_human_count", "is_ai_agent_without_accountable_human", "service_started_at", "departure_at", "protected_mentoring_hours_per_week", "community_count", "is_boundary_spanner", "sna_identification_count", "is_unidentified_boundary_spanner", "located_know_how_count", "required_mentoring_hours_per_week", "lacks_time_to_mentor", "transfers_given_count", "recognition_count", "is_unrewarded_sharer", "downstream_of_held_steps_count", "artifact_blast_radius_step_count":
			tc.erbSet(key, fromJSON(value))
		}
	}
}

func (tc *Agent) erbErrors() map[string]string {
	if tc.ErbErrors == nil {
		tc.ErbErrors = map[string]string{}
	}
	return tc.ErbErrors
}

func (tc *Agent) erbResetErrors() { tc.ErbErrors = nil }

func (tc *Agent) erbAggregate(name string) Value { return tc.erbAggregates[name] }

func (tc *Agent) erbSetAggregate(name string, v Value) {
	if tc.erbAggregates == nil {
		tc.erbAggregates = map[string]Value{}
	}
	tc.erbAggregates[name] = v
}

// LoadAgentRecords reads Agents rows from a JSON array file.
func LoadAgentRecords(path string) ([]Agent, error) {
	records, err := loadRecords(path, func() Record { return &Agent{} })
	if err != nil {
		return nil, err
	}
	rows := make([]Agent, len(records))
	for i, r := range records {
		rows[i] = *r.(*Agent)
	}
	return rows, nil
}

// =============================================================================
// ROLES TABLE
// Stable organizational functions separated from the agents that currently fill them. Maps to pro:Role.
// =============================================================================

// Role represents a row in the Roles table
type Role struct {
	RoleId string `json:"role_id"` // Stored logical identifier for one Roles row.
	Name *string `json:"name"` // Human-readable calculated display alias for the Roles row.
	Label *string `json:"label"` // Human-readable role label.
	Organization *string `json:"organization"` // Organization that owns the role.
	CurrentAgent *string `json:"current_agent"` // Current agent filling the role; history is retained in RoleAssignments.
	CurrentAgentKind *string `json:"current_agent_kind"` // Agent category of the current role filler.
	Responsibility *string `json:"responsibility"` // Accountability and responsibility assigned to the role.
	ActiveAssignmentCount *float64 `json:"active_assignment_count"` // Total number of assignment rows ever recorded against this role.
	CurrentlyCoveredAssignmentCount *float64 `json:"currently_covered_assignment_count"` // Number of assignment rows for this role that are in force right now.
	HasNoCurrentHolder *bool `json:"has_no_current_holder"` // TRUE when no assignment currently covers this role — the role is uncovered.
	CountOfAwaitedDecisions *int `json:"count_of_awaited_decisions"` // How many change requests name this role as the deciding authority.
	CurrentAssignment *string `json:"current_assignment"` // The RoleAssignments id of the assignment by which this role is currently held. Deliberately a raw identifier, not a relationship: RoleAssignments already points at Roles, so an FK back would make the two mutually dependent and this rulebook must stay acyclic.
	CurrentAssignmentValidFrom *string `json:"current_assignment_valid_from"` // Start of the currently-in-force assignment for this role.
	IsNonHumanHeld *bool `json:"is_non_human_held"` // TRUE when the role's current agent is an AI agent or automated pipeline.
	IsUngovernedNonHumanRole *bool `json:"is_ungoverned_non_human_role"` // TRUE when a role is pointed at a non-human agent but has no assignment row granting it.
	DepartedAssignmentCount *float64 `json:"departed_assignment_count"` // How many assignments to this role have ended.
	HasLostAHolder *bool `json:"has_lost_a_holder"` // Whether anyone has ever departed this role.
	IsVacatedRole *bool `json:"is_vacated_role"` // A role somebody departed and that nobody currently covers.
	UngroundedBoundaryCount *float64 `json:"ungrounded_boundary_count"` // How many boundaries constrain this role on lapsed authority.
	IsGovernedByLapsedAuthority *bool `json:"is_governed_by_lapsed_authority"` // TRUE when at least one constraint on this role rests on knowledge that is no longer valid.
	UnescalatedRefusalCount *float64 `json:"unescalated_refusal_count"` // How many refusals this role should have been told about and was not.
	UnauthorizedEnforcementAssignmentCount *float64 `json:"unauthorized_enforcement_assignment_count"` // How many current assignments of this role are unauthorized enforcement assignments.
	IsUngovernedEnforcementRole *bool `json:"is_ungoverned_enforcement_role"` // TRUE when a role that enforces controls on others is held with no recorded authorization.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact semantic type IRI for the role.
	SpecializesRole *string `json:"specializes_role"` // Role this one specializes.
	SeniorityLevel *string `json:"seniority_level"` // Senior, Deputy, or blank.
	RoleFamily *string `json:"role_family"` // Family of roles doing the same kind of work.
	SpecializedRoleFamily *string `json:"specialized_role_family"` // Family of the specialized role.
	SpecializationCount *int `json:"specialization_count"` // Roles that specialize this one.
	HasSpecializations *bool `json:"has_specializations"` // TRUE when another role specializes this one.
	IsSeniorVariantNotSpecialization *bool `json:"is_senior_variant_not_specialization"` // TRUE when a senior version of a role is not recorded as a specialization of a role in its own family.
	OrganizationType *string `json:"organization_type"` // Kind of organization the role sits in.
	IsNotHousedInDepartment *bool `json:"is_not_housed_in_department"` // TRUE when the role sits directly in a company or division rather than a department.
	CapabilityTagCount *int `json:"capability_tag_count"` // Capability tags.
	ComplianceReviewTagCount *int `json:"compliance_review_tag_count"` // Compliance-review capability tags.
	HasComplianceReviewCapability *bool `json:"has_compliance_review_capability"` // TRUE when the role carries the compliance-review capability.
	RoleMentionCount *int `json:"role_mention_count"` // Source mentions judged to mean this role.
	UnresolvedRoleMentionCount *int `json:"unresolved_role_mention_count"` // Such mentions whose wording the role vocabulary does not resolve.
	IsMissedByPhraseQuery *bool `json:"is_missed_by_phrase_query"` // TRUE when a query for this role through the role vocabulary misses a process that mentions it in other words.
	PreferredKnowledgeForm *string `json:"preferred_knowledge_form"` // Whether people in the role prefer knowledge as Prose or as a Diagram.
	EscalationBackupRole *string `json:"escalation_backup_role"` // Role that backs this one up on escalation.
	CurrentHolderName *string `json:"current_holder_name"` // Name of the person or system holding the role.
	BackupRoleHolder *string `json:"backup_role_holder"` // Agent holding the escalation backup role.
	HasEscalationBackup *bool `json:"has_escalation_backup"` // TRUE when the role names an escalation backup role.
	HasUnfilledEscalationBackup *bool `json:"has_unfilled_escalation_backup"` // TRUE when the escalation backup role has nobody in it.
	ReleaseApprovalStepCount *int `json:"release_approval_step_count"` // Production release approval gates assigned to the role.
	IsProductionReleaseApprover *bool `json:"is_production_release_approver"` // TRUE for the role that approves production releases.
	ApprovalStepCount *int `json:"approval_step_count"` // Approval steps assigned to the role.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Roles row.
// Formula: ={{Label}}
func (tc *Role) CalcName() *string {
	return toStringPtr(vStr(tc.Label))
}

// CalcHasNoCurrentHolder computes the HasNoCurrentHolder calculated field
// TRUE when no assignment currently covers this role — the role is uncovered.
// Formula: ={{CurrentlyCoveredAssignmentCount}} = 0
func (tc *Role) CalcHasNoCurrentHolder() *bool {
	return toBoolPtr(erbEq(vNum(tc.CurrentlyCoveredAssignmentCount), vI(0)))
}

// CalcIsNonHumanHeld computes the IsNonHumanHeld calculated field
// TRUE when the role's current agent is an AI agent or automated pipeline.
// Formula: =NOT({{CurrentAgentKind}} = "Human")
func (tc *Role) CalcIsNonHumanHeld() *bool {
	return toBoolPtr(erbNot(erbBool3(erbEq(vStr(tc.CurrentAgentKind), vS("Human")))))
}

// CalcIsUngovernedNonHumanRole computes the IsUngovernedNonHumanRole calculated field
// TRUE when a role is pointed at a non-human agent but has no assignment row granting it.
// Formula: =AND({{IsNonHumanHeld}}, {{HasNoCurrentHolder}})
func (tc *Role) CalcIsUngovernedNonHumanRole() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsNonHumanHeld)), erbBool3(vBool(tc.HasNoCurrentHolder))))
}

// CalcHasLostAHolder computes the HasLostAHolder calculated field
// Whether anyone has ever departed this role.
// Formula: ={{DepartedAssignmentCount}} > 0
func (tc *Role) CalcHasLostAHolder() *bool {
	return toBoolPtr(erbCmp(vNum(tc.DepartedAssignmentCount), ">", vI(0)))
}

// CalcIsVacatedRole computes the IsVacatedRole calculated field
// A role somebody departed and that nobody currently covers.
// Formula: =AND({{HasLostAHolder}}, {{HasNoCurrentHolder}})
func (tc *Role) CalcIsVacatedRole() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasLostAHolder)), erbBool3(vBool(tc.HasNoCurrentHolder))))
}

// CalcIsGovernedByLapsedAuthority computes the IsGovernedByLapsedAuthority calculated field
// TRUE when at least one constraint on this role rests on knowledge that is no longer valid.
// Formula: =({{UngroundedBoundaryCount}} > 0)
func (tc *Role) CalcIsGovernedByLapsedAuthority() *bool {
	return toBoolPtr(erbCmp(vNum(tc.UngroundedBoundaryCount), ">", vI(0)))
}

// CalcIsUngovernedEnforcementRole computes the IsUngovernedEnforcementRole calculated field
// TRUE when a role that enforces controls on others is held with no recorded authorization.
// Formula: =({{UnauthorizedEnforcementAssignmentCount}} > 0)
func (tc *Role) CalcIsUngovernedEnforcementRole() *bool {
	return toBoolPtr(erbCmp(vNum(tc.UnauthorizedEnforcementAssignmentCount), ">", vI(0)))
}

// CalcHasSpecializations computes the HasSpecializations calculated field
// TRUE when another role specializes this one.
// Formula: ={{SpecializationCount}} > 0
func (tc *Role) CalcHasSpecializations() *bool {
	return toBoolPtr(erbCmp(vInt(tc.SpecializationCount), ">", vI(0)))
}

// CalcIsSeniorVariantNotSpecialization computes the IsSeniorVariantNotSpecialization calculated field
// TRUE when a senior version of a role is not recorded as a specialization of a role in its own family.
// Formula: =AND({{SeniorityLevel}} = "Senior", OR({{SpecializesRole}} = "", {{SpecializedRoleFamily}} <> {{RoleFamily}}))
func (tc *Role) CalcIsSeniorVariantNotSpecialization() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.SeniorityLevel)), vS("Senior"))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.SpecializesRole))), erbBool3(erbNe(vStr(tc.SpecializedRoleFamily), erbNullif(vStr(tc.RoleFamily))))))))
}

// CalcIsNotHousedInDepartment computes the IsNotHousedInDepartment calculated field
// TRUE when the role sits directly in a company or division rather than a department.
// Formula: ={{OrganizationType}} <> "Department"
func (tc *Role) CalcIsNotHousedInDepartment() *bool {
	return toBoolPtr(erbNe(vStr(tc.OrganizationType), vS("Department")))
}

// CalcHasComplianceReviewCapability computes the HasComplianceReviewCapability calculated field
// TRUE when the role carries the compliance-review capability.
// Formula: ={{ComplianceReviewTagCount}} > 0
func (tc *Role) CalcHasComplianceReviewCapability() *bool {
	return toBoolPtr(erbCmp(vInt(tc.ComplianceReviewTagCount), ">", vI(0)))
}

// CalcIsMissedByPhraseQuery computes the IsMissedByPhraseQuery calculated field
// TRUE when a query for this role through the role vocabulary misses a process that mentions it in other words.
// Formula: ={{UnresolvedRoleMentionCount}} > 0
func (tc *Role) CalcIsMissedByPhraseQuery() *bool {
	return toBoolPtr(erbCmp(vInt(tc.UnresolvedRoleMentionCount), ">", vI(0)))
}

// CalcHasEscalationBackup computes the HasEscalationBackup calculated field
// TRUE when the role names an escalation backup role.
// Formula: ={{EscalationBackupRole}} <> ""
func (tc *Role) CalcHasEscalationBackup() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.EscalationBackupRole)))
}

// CalcHasUnfilledEscalationBackup computes the HasUnfilledEscalationBackup calculated field
// TRUE when the escalation backup role has nobody in it.
// Formula: =AND({{EscalationBackupRole}} <> "", {{BackupRoleHolder}} = "")
func (tc *Role) CalcHasUnfilledEscalationBackup() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.EscalationBackupRole))), erbBool3(erbIsBlank(vStr(tc.BackupRoleHolder)))))
}

// CalcIsProductionReleaseApprover computes the IsProductionReleaseApprover calculated field
// TRUE for the role that approves production releases.
// Formula: ={{ReleaseApprovalStepCount}} > 0
func (tc *Role) CalcIsProductionReleaseApprover() *bool {
	return toBoolPtr(erbCmp(vInt(tc.ReleaseApprovalStepCount), ">", vI(0)))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *Role) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_no_current_holder", func() { tc.HasNoCurrentHolder = tc.CalcHasNoCurrentHolder() })
	calcGuard(tc, "is_non_human_held", func() { tc.IsNonHumanHeld = tc.CalcIsNonHumanHeld() })
	calcGuard(tc, "has_lost_a_holder", func() { tc.HasLostAHolder = tc.CalcHasLostAHolder() })
	calcGuard(tc, "is_governed_by_lapsed_authority", func() { tc.IsGovernedByLapsedAuthority = tc.CalcIsGovernedByLapsedAuthority() })
	calcGuard(tc, "is_ungoverned_enforcement_role", func() { tc.IsUngovernedEnforcementRole = tc.CalcIsUngovernedEnforcementRole() })
	calcGuard(tc, "has_specializations", func() { tc.HasSpecializations = tc.CalcHasSpecializations() })
	calcGuard(tc, "is_senior_variant_not_specialization", func() { tc.IsSeniorVariantNotSpecialization = tc.CalcIsSeniorVariantNotSpecialization() })
	calcGuard(tc, "is_not_housed_in_department", func() { tc.IsNotHousedInDepartment = tc.CalcIsNotHousedInDepartment() })
	calcGuard(tc, "has_compliance_review_capability", func() { tc.HasComplianceReviewCapability = tc.CalcHasComplianceReviewCapability() })
	calcGuard(tc, "is_missed_by_phrase_query", func() { tc.IsMissedByPhraseQuery = tc.CalcIsMissedByPhraseQuery() })
	calcGuard(tc, "has_escalation_backup", func() { tc.HasEscalationBackup = tc.CalcHasEscalationBackup() })
	calcGuard(tc, "has_unfilled_escalation_backup", func() { tc.HasUnfilledEscalationBackup = tc.CalcHasUnfilledEscalationBackup() })
	calcGuard(tc, "is_production_release_approver", func() { tc.IsProductionReleaseApprover = tc.CalcIsProductionReleaseApprover() })
	// Level 2
	calcGuard(tc, "is_ungoverned_non_human_role", func() { tc.IsUngovernedNonHumanRole = tc.CalcIsUngovernedNonHumanRole() })
	calcGuard(tc, "is_vacated_role", func() { tc.IsVacatedRole = tc.CalcIsVacatedRole() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *Role) ComputeAll() *Role {
	tc.erbComputeCalculations()
	return tc
}

