func (tc *Role) erbLoad(row map[string]any) {
	for key, value := range row {
		switch key {
		case "role_id", "name", "label", "organization", "current_agent", "current_agent_kind", "responsibility", "active_assignment_count", "currently_covered_assignment_count", "has_no_current_holder", "count_of_awaited_decisions", "current_assignment", "current_assignment_valid_from", "is_non_human_held", "is_ungoverned_non_human_role", "departed_assignment_count", "has_lost_a_holder", "is_vacated_role", "ungrounded_boundary_count", "is_governed_by_lapsed_authority", "unescalated_refusal_count", "unauthorized_enforcement_assignment_count", "is_ungoverned_enforcement_role", "semantic_type_iri", "specializes_role", "seniority_level", "role_family", "specialized_role_family", "specialization_count", "has_specializations", "is_senior_variant_not_specialization", "organization_type", "is_not_housed_in_department", "capability_tag_count", "compliance_review_tag_count", "has_compliance_review_capability", "role_mention_count", "unresolved_role_mention_count", "is_missed_by_phrase_query", "preferred_knowledge_form", "escalation_backup_role", "current_holder_name", "backup_role_holder", "has_escalation_backup", "has_unfilled_escalation_backup", "release_approval_step_count", "is_production_release_approver", "approval_step_count":
			tc.erbSet(key, fromJSON(value))
		}
	}
}

func (tc *Role) erbErrors() map[string]string {
	if tc.ErbErrors == nil {
		tc.ErbErrors = map[string]string{}
	}
	return tc.ErbErrors
}

func (tc *Role) erbResetErrors() { tc.ErbErrors = nil }

func (tc *Role) erbAggregate(name string) Value { return tc.erbAggregates[name] }

func (tc *Role) erbSetAggregate(name string, v Value) {
	if tc.erbAggregates == nil {
		tc.erbAggregates = map[string]Value{}
	}
	tc.erbAggregates[name] = v
}

// LoadRoleRecords reads Roles rows from a JSON array file.
func LoadRoleRecords(path string) ([]Role, error) {
	records, err := loadRecords(path, func() Record { return &Role{} })
	if err != nil {
		return nil, err
	}
	rows := make([]Role, len(records))
	for i, r := range records {
		rows[i] = *r.(*Role)
	}
	return rows, nil
}

// =============================================================================
// ROLEASSIGNMENTS TABLE
// Time-bounded records of agents holding roles. Maps to pro:RoleInTime and preserves assignment history instead of overwriting it.
// =============================================================================

// RoleAssignment represents a row in the RoleAssignments table
type RoleAssignment struct {
	RoleAssignmentId string `json:"role_assignment_id"` // Stored logical identifier for one RoleAssignments row.
	Name *string `json:"name"` // Human-readable calculated display alias for the RoleAssignments row.
	Role *string `json:"role"` // Role held during the assignment.
	Agent *string `json:"agent"` // Agent holding the role.
	ValidFrom *string `json:"valid_from"` // Start of the assignment's valid-time interval.
	ValidTo *string `json:"valid_to"` // End of the assignment's valid-time interval; null means open-ended.
	Reason *string `json:"reason"` // Rationale for the assignment or reassignment.
	Status *string `json:"status"` // Active, Superseded, Planned, or Revoked.
	EvaluationContext *string `json:"evaluation_context"` // The evaluation context this assignment's currency is judged under.
	AsOfInstant *string `json:"as_of_instant"` // The evaluation instant this assignment's currency is judged against.
	IsCurrent *bool `json:"is_current"` // TRUE when the assignment is valid now.
	CurrentAgentKey *string `json:"current_agent_key"` // Echoes the Agent id only while this assignment is current; empty otherwise. Lets a parent count CURRENT assignments with a single-criterion COUNTIFS, which is the only shape this transpiler translates correctly.
	IsCurrentlyValid *bool `json:"is_currently_valid"` // TRUE when this role assignment is active and has not lapsed.
	AgentRoleKey *string `json:"agent_role_key"` // Composite agent+role key, emitted only for currently-valid assignments.
	HasDeparted *bool `json:"has_departed"` // TRUE when this role assignment has ended — the agent no longer holds the role.
	CoversNow *bool `json:"covers_now"` // TRUE when this assignment is both status-Active and inside its valid-time window right now.
	RoleWhenCovering *string `json:"role_when_covering"` // Echoes the role id when this assignment is currently in force, blank otherwise.
	AgentKind *string `json:"agent_kind"` // Whether the agent holding this assignment is Human, AIAgent, or AutomatedPipeline.
	IsNonHumanAssignment *bool `json:"is_non_human_assignment"` // TRUE when this assignment places a non-human agent into the role.
	SupersedesAssignment *string `json:"supersedes_assignment"` // The assignment this one replaced, if any.
	PredecessorAgentKind *string `json:"predecessor_agent_kind"` // Agent kind of the assignment this one superseded.
	IsHumanToNonHumanHandover *bool `json:"is_human_to_non_human_handover"` // TRUE when this assignment handed a role from a human to a non-human agent.
	ApprovingAuthorityRole *string `json:"approving_authority_role"` // Role that approved this assignment.
	AuthorizingChangeRequest *string `json:"authorizing_change_request"` // Change request under which this assignment was approved.
	IsUnauthorizedNonHumanAssignment *bool `json:"is_unauthorized_non_human_assignment"` // TRUE when a non-human agent holds this role with no approving authority recorded at all. An authority named without a change request is still an authority; the separate WasAuthorizedByChangeRequest column carries that weaker distinction.
	WasAuthorizedByChangeRequest *bool `json:"was_authorized_by_change_request"` // TRUE when this assignment's authorization is traceable to a change request, not merely to a named role. The stronger form of authorization, kept separate so the weaker one is not silently reported as unauthorized.
	DecisionCount *float64 `json:"decision_count"` // Decisions made under this assignment.
	OverriddenDecisionCount *float64 `json:"overridden_decision_count"` // Decisions made under this assignment that a human corrected or reversed.
	OverrideRatePercent *float64 `json:"override_rate_percent"` // Percentage of decisions under this assignment that a human overrode.
	PredecessorOverrideRatePercent *float64 `json:"predecessor_override_rate_percent"` // Override rate of the assignment this one superseded.
	QualityRegressedVsPredecessor *bool `json:"quality_regressed_vs_predecessor"` // TRUE when this assignment is overridden by humans more often than the assignment it replaced.
	DepartedRoleKey *string `json:"departed_role_key"` // Composite-key echo: the role this assignment covered when the assignment has ended, blank otherwise.
	MinimumDecisionsForComparison *int `json:"minimum_decisions_for_comparison"` // The number of decisions below which an override-rate comparison is not considered evidentially meaningful for this role.
	PredecessorDecisionCount *float64 `json:"predecessor_decision_count"` // How many decisions the superseded assignment produced.
	HasSufficientSample *bool `json:"has_sufficient_sample"` // TRUE when this assignment has produced enough decisions for its override rate to mean anything.
	PredecessorHasSufficientSample *bool `json:"predecessor_has_sufficient_sample"` // TRUE when the predecessor assignment produced enough decisions to compare against.
	ComparisonIsEvidentiallySound *bool `json:"comparison_is_evidentially_sound"` // TRUE when both sides of the override-rate comparison rest on adequate samples.
	SingleOverrideSwingPercent *float64 `json:"single_override_swing_percent"` // How many percentage points one additional override would move this assignment's rate. The fragility of the number.
	QualityVerdictIsUnsupported *bool `json:"quality_verdict_is_unsupported"` // TRUE when a quality verdict is being reported for this assignment on a sample too small to support it.
	IsUnmeasuredAutomationHandover *bool `json:"is_unmeasured_automation_handover"` // TRUE when a human-to-machine handover is operating without a statistically meaningful quality comparison behind it.
	ErrorCorrectionCount *float64 `json:"error_correction_count"` // How many of this assignment's decisions were overridden because they were wrong.
	ErrorRatePercent *float64 `json:"error_rate_percent"` // Percentage of this assignment's decisions overridden as errors -- the override rate with reserved-judgment overrides removed.
	AuthorizationDecidedAt *string `json:"authorization_decided_at"` // When the approving authority actually granted this assignment. Empty when no authorization was ever recorded.
	AuthorizationReviewedAt *string `json:"authorization_reviewed_at"` // When the authorization for this assignment was last re-examined.
	AuthorizationReviewCadenceDays *int `json:"authorization_review_cadence_days"` // How often this assignment's authorization is promised to be re-examined.
	HasDatedAuthorization *bool `json:"has_dated_authorization"` // TRUE when this assignment carries both a named approving authority and the date they granted it.
	DaysSinceAuthorizationReview *int `json:"days_since_authorization_review"` // How long since this assignment's authorization was last re-examined.
	AuthorizationIsOverdueForReview *bool `json:"authorization_is_overdue_for_review"` // TRUE when the promised re-examination interval has elapsed without a review.
	IsStandingUnreviewedAutomation *bool `json:"is_standing_unreviewed_automation"` // TRUE when a currently-active non-human assignment has been running past its authorization review date.
	IsUnconditionedAutomationHandover *bool `json:"is_unconditioned_automation_handover"` // TRUE when a human-to-machine handover was authorized with no promised review cadence at all -- granted once, permanently.
	MaxTolerableErrorRatePercent *int `json:"max_tolerable_error_rate_percent"` // The error rate at or above which this assignment must stop making decisions unaided.
	ExceedsTolerableErrorRate *bool `json:"exceeds_tolerable_error_rate"` // TRUE when this assignment's error rate has reached the threshold set when it was authorized.
	BoundaryViolationCountForAssignment *float64 `json:"boundary_violation_count_for_assignment"` // How many decisions under this assignment violated an authority boundary.
	HasAnyBoundaryViolation *bool `json:"has_any_boundary_violation"` // TRUE when any decision under this assignment crossed a boundary it was forbidden to cross.
	HasUngroundedGoverningBoundary *bool `json:"has_ungrounded_governing_boundary"` // TRUE when at least one boundary constraining this assignment's role rests on lapsed knowledge.
	SuspensionConditionMet *bool `json:"suspension_condition_met"` // TRUE when any pre-declared condition requiring this assignment to stop deciding unaided has been met.
	IsOperatingUnderMetSuspensionCondition *bool `json:"is_operating_under_met_suspension_condition"` // TRUE when a suspension condition has been met and the assignment is nonetheless still active and still deciding.
	HasDeclaredSuspensionCondition *bool `json:"has_declared_suspension_condition"` // TRUE when this assignment has any pre-declared condition under which it must stop at all.
	HasApprovingAuthority *bool `json:"has_approving_authority"` // TRUE when a role is recorded as having approved this assignment.
	HasAuthorizingChangeRequest *bool `json:"has_authorizing_change_request"` // TRUE when a change request is recorded as the governance vehicle for this assignment.
	IsEnforcementRole *bool `json:"is_enforcement_role"` // Whether this role's function is to enforce controls on other agents' actions.
	IsUnauthorizedEnforcementAgent *bool `json:"is_unauthorized_enforcement_agent"` // TRUE when a non-human agent enforces controls on others while holding no recorded authorization of its own.
	GovernanceEvidenceCount *int `json:"governance_evidence_count"` // How many independent governance artifacts back this assignment: an approving role, an authorizing change request.
	UnauthorizedEnforcementRoleKey *string `json:"unauthorized_enforcement_role_key"` // Echoes the role only for non-human assignments nobody authorized; empty otherwise.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact class IRI for the assignment event.
	ForProcedureVersion *string `json:"for_procedure_version"` // Procedure version the role is held for (pro:relatesTo).
	ScopedVersionStatus *string `json:"scoped_version_status"` // Status of that version.
	IsScopedToRetiredVersion *bool `json:"is_scoped_to_retired_version"` // TRUE when a current assignment is held for a version that is deprecated or archived.
	PredecessorValidTo *string `json:"predecessor_valid_to"` // When the superseded assignment ended.
	PredecessorLacksValidityEnd *bool `json:"predecessor_lacks_validity_end"` // TRUE when an assignment supersedes one whose validity period was never closed.
	AgentVersionKey *string `json:"agent_version_key"` // Model version or employment key of the assigned agent.
	AgentRolePairKey *string `json:"agent_role_pair_key"` // Agent and role, as one key, regardless of validity.
	IsOpenEnded *bool `json:"is_open_ended"` // TRUE when the assignment has no end.
	RoleApprovalStepCount *int `json:"role_approval_step_count"` // Approval steps assigned to the role.
	ReceivesApprovalNoticesNow *bool `json:"receives_approval_notices_now"` // TRUE when the assignment currently covers a role that approval steps are assigned to, so its agent is who approval notices go to.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the RoleAssignments row.
// Formula: ={{Role}} & " @ " & {{ValidFrom}}
func (tc *RoleAssignment) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Role)), vS(" @ "), erbDatetimeText(vStr(tc.ValidFrom))))
}

// CalcIsCurrent computes the IsCurrent calculated field
// TRUE when the assignment is valid now.
// Formula: =AND({{ValidFrom}} <= {{AsOfInstant}}, OR({{ValidTo}} = "", {{ValidTo}} > {{AsOfInstant}}))
func (tc *RoleAssignment) CalcIsCurrent() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vStr(tc.ValidFrom)), "<=", vStr(tc.AsOfInstant))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.ValidTo))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidTo)), ">", vStr(tc.AsOfInstant)))))))
}

// CalcCurrentAgentKey computes the CurrentAgentKey calculated field
// Echoes the Agent id only while this assignment is current; empty otherwise. Lets a parent count CURRENT assignments with a single-criterion COUNTIFS, which is the only shape this transpiler translates correctly.
// Formula: =IF({{IsCurrent}}, {{Agent}}, "")
func (tc *RoleAssignment) CalcCurrentAgentKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsCurrent)), func() Value { return vStr(tc.Agent) }, func() Value { return vS("") }))
}

// CalcIsCurrentlyValid computes the IsCurrentlyValid calculated field
// TRUE when this role assignment is active and has not lapsed.
// Formula: =AND({{Status}} = "Active", OR({{ValidTo}} = "", {{ValidTo}} > {{AsOfInstant}}))
func (tc *RoleAssignment) CalcIsCurrentlyValid() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Active"))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.ValidTo))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidTo)), ">", vStr(tc.AsOfInstant)))))))
}

// CalcAgentRoleKey computes the AgentRoleKey calculated field
// Composite agent+role key, emitted only for currently-valid assignments.
// Formula: =IF({{IsCurrentlyValid}}, {{Agent}} & "|" & {{Role}}, "")
func (tc *RoleAssignment) CalcAgentRoleKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsCurrentlyValid)), func() Value { return erbConcat(erbText(vStr(tc.Agent)), vS("|"), erbText(vStr(tc.Role))) }, func() Value { return vS("") }))
}

// CalcHasDeparted computes the HasDeparted calculated field
// TRUE when this role assignment has ended — the agent no longer holds the role.
// Formula: =AND({{ValidTo}} <> "", {{ValidTo}} <= {{AsOfInstant}})
func (tc *RoleAssignment) CalcHasDeparted() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ValidTo))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidTo)), "<=", vStr(tc.AsOfInstant)))))
}

// CalcCoversNow computes the CoversNow calculated field
// TRUE when this assignment is both status-Active and inside its valid-time window right now.
// Formula: =AND({{Status}} = "Active", {{ValidFrom}} <= {{AsOfInstant}}, OR({{ValidTo}} = "", {{ValidTo}} > {{AsOfInstant}}))
func (tc *RoleAssignment) CalcCoversNow() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Active"))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidFrom)), "<=", vStr(tc.AsOfInstant))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.ValidTo))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidTo)), ">", vStr(tc.AsOfInstant)))))))
}

// CalcRoleWhenCovering computes the RoleWhenCovering calculated field
// Echoes the role id when this assignment is currently in force, blank otherwise.
// Formula: =IF({{CoversNow}}, {{Role}}, "")
func (tc *RoleAssignment) CalcRoleWhenCovering() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.CoversNow)), func() Value { return vStr(tc.Role) }, func() Value { return vS("") }))
}

// CalcIsNonHumanAssignment computes the IsNonHumanAssignment calculated field
// TRUE when this assignment places a non-human agent into the role.
// Formula: =NOT({{AgentKind}} = "Human")
func (tc *RoleAssignment) CalcIsNonHumanAssignment() *bool {
	return toBoolPtr(erbNot(erbBool3(erbEq(vStr(tc.AgentKind), vS("Human")))))
}

// CalcIsHumanToNonHumanHandover computes the IsHumanToNonHumanHandover calculated field
// TRUE when this assignment handed a role from a human to a non-human agent.
// Formula: =AND({{PredecessorAgentKind}} = "Human", {{IsNonHumanAssignment}})
func (tc *RoleAssignment) CalcIsHumanToNonHumanHandover() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(vStr(tc.PredecessorAgentKind), vS("Human"))), erbBool3(vBool(tc.IsNonHumanAssignment))))
}

// CalcIsUnauthorizedNonHumanAssignment computes the IsUnauthorizedNonHumanAssignment calculated field
// TRUE when a non-human agent holds this role with no approving authority recorded at all. An authority named without a change request is still an authority; the separate WasAuthorizedByChangeRequest column carries that weaker distinction.
// Formula: =AND({{IsNonHumanAssignment}}, NOT({{HasApprovingAuthority}}))
func (tc *RoleAssignment) CalcIsUnauthorizedNonHumanAssignment() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsNonHumanAssignment)), erbBool3(erbNot(erbBool3(vBool(tc.HasApprovingAuthority))))))
}

// CalcWasAuthorizedByChangeRequest computes the WasAuthorizedByChangeRequest calculated field
// TRUE when this assignment's authorization is traceable to a change request, not merely to a named role. The stronger form of authorization, kept separate so the weaker one is not silently reported as unauthorized.
// Formula: =AND({{HasApprovingAuthority}}, {{AuthorizingChangeRequest}} <> "")
func (tc *RoleAssignment) CalcWasAuthorizedByChangeRequest() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasApprovingAuthority)), erbBool3(erbIsNotBlank(vStr(tc.AuthorizingChangeRequest)))))
}

// CalcOverrideRatePercent computes the OverrideRatePercent calculated field
// Percentage of decisions under this assignment that a human overrode.
// Formula: =IF({{DecisionCount}} = 0, 0, ({{OverriddenDecisionCount}} * 100) / {{DecisionCount}})
func (tc *RoleAssignment) CalcOverrideRatePercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbEq(vNum(tc.DecisionCount), vI(0))), func() Value { return vI(0) }, func() Value { return erbDiv(erbMul(vNum(tc.OverriddenDecisionCount), vI(100)), vNum(tc.DecisionCount)) }))
}

// CalcQualityRegressedVsPredecessor computes the QualityRegressedVsPredecessor calculated field
// TRUE when this assignment is overridden by humans more often than the assignment it replaced.
// Formula: =AND({{SupersedesAssignment}} <> "", {{OverrideRatePercent}} > {{PredecessorOverrideRatePercent}})
func (tc *RoleAssignment) CalcQualityRegressedVsPredecessor() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.SupersedesAssignment))), erbBool3(erbCmp(vNum(tc.OverrideRatePercent), ">", vNum(tc.PredecessorOverrideRatePercent)))))
}

// CalcDepartedRoleKey computes the DepartedRoleKey calculated field
// Composite-key echo: the role this assignment covered when the assignment has ended, blank otherwise.
// Formula: =IF({{HasDeparted}}, {{Role}}, "")
func (tc *RoleAssignment) CalcDepartedRoleKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.HasDeparted)), func() Value { return vStr(tc.Role) }, func() Value { return vS("") }))
}

// CalcHasSufficientSample computes the HasSufficientSample calculated field
// TRUE when this assignment has produced enough decisions for its override rate to mean anything.
// Formula: ={{DecisionCount}} >= {{MinimumDecisionsForComparison}}
func (tc *RoleAssignment) CalcHasSufficientSample() *bool {
	return toBoolPtr(erbCmp(vNum(tc.DecisionCount), ">=", erbNullif(vInt(tc.MinimumDecisionsForComparison))))
}

// CalcPredecessorHasSufficientSample computes the PredecessorHasSufficientSample calculated field
// TRUE when the predecessor assignment produced enough decisions to compare against.
// Formula: ={{PredecessorDecisionCount}} >= {{MinimumDecisionsForComparison}}
func (tc *RoleAssignment) CalcPredecessorHasSufficientSample() *bool {
	return toBoolPtr(erbCmp(vNum(tc.PredecessorDecisionCount), ">=", erbNullif(vInt(tc.MinimumDecisionsForComparison))))
}

// CalcComparisonIsEvidentiallySound computes the ComparisonIsEvidentiallySound calculated field
// TRUE when both sides of the override-rate comparison rest on adequate samples.
// Formula: =AND({{HasSufficientSample}}, {{PredecessorHasSufficientSample}})
func (tc *RoleAssignment) CalcComparisonIsEvidentiallySound() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasSufficientSample)), erbBool3(vBool(tc.PredecessorHasSufficientSample))))
}

// CalcSingleOverrideSwingPercent computes the SingleOverrideSwingPercent calculated field
// How many percentage points one additional override would move this assignment's rate. The fragility of the number.
// Formula: =IF({{DecisionCount}} > 0, 100 / {{DecisionCount}}, 0)
func (tc *RoleAssignment) CalcSingleOverrideSwingPercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbCmp(vNum(tc.DecisionCount), ">", vI(0))), func() Value { return erbDiv(vI(100), vNum(tc.DecisionCount)) }, func() Value { return vI(0) }))
}

// CalcQualityVerdictIsUnsupported computes the QualityVerdictIsUnsupported calculated field
// TRUE when a quality verdict is being reported for this assignment on a sample too small to support it.
// Formula: =AND(NOT({{ComparisonIsEvidentiallySound}}), NOT({{QualityRegressedVsPredecessor}}))
func (tc *RoleAssignment) CalcQualityVerdictIsUnsupported() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNot(erbBool3(vBool(tc.ComparisonIsEvidentiallySound)))), erbBool3(erbNot(erbBool3(vBool(tc.QualityRegressedVsPredecessor))))))
}

// CalcIsUnmeasuredAutomationHandover computes the IsUnmeasuredAutomationHandover calculated field
// TRUE when a human-to-machine handover is operating without a statistically meaningful quality comparison behind it.
// Formula: =AND({{IsHumanToNonHumanHandover}}, NOT({{ComparisonIsEvidentiallySound}}))
func (tc *RoleAssignment) CalcIsUnmeasuredAutomationHandover() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsHumanToNonHumanHandover)), erbBool3(erbNot(erbBool3(vBool(tc.ComparisonIsEvidentiallySound))))))
}

// CalcErrorRatePercent computes the ErrorRatePercent calculated field
// Percentage of this assignment's decisions overridden as errors -- the override rate with reserved-judgment overrides removed.
// Formula: =IF({{DecisionCount}} > 0, {{ErrorCorrectionCount}} * 100 / {{DecisionCount}}, 0)
func (tc *RoleAssignment) CalcErrorRatePercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbCmp(vNum(tc.DecisionCount), ">", vI(0))), func() Value { return erbDiv(erbMul(vNum(tc.ErrorCorrectionCount), vI(100)), vNum(tc.DecisionCount)) }, func() Value { return vI(0) }))
}

// CalcHasDatedAuthorization computes the HasDatedAuthorization calculated field
// TRUE when this assignment carries both a named approving authority and the date they granted it.
// Formula: =AND({{ApprovingAuthorityRole}} <> "", {{AuthorizationDecidedAt}} <> "")
func (tc *RoleAssignment) CalcHasDatedAuthorization() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ApprovingAuthorityRole))), erbBool3(erbIsNotBlank(vStr(tc.AuthorizationDecidedAt)))))
}

// CalcDaysSinceAuthorizationReview computes the DaysSinceAuthorizationReview calculated field
// How long since this assignment's authorization was last re-examined.
// Formula: =IF({{AuthorizationReviewedAt}} <> "", DATETIME_DIFF({{AsOfInstant}}, {{AuthorizationReviewedAt}}, "days"), DATETIME_DIFF({{AsOfInstant}}, {{ValidFrom}}, "days"))
func (tc *RoleAssignment) CalcDaysSinceAuthorizationReview() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbIsNotBlank(vStr(tc.AuthorizationReviewedAt))), func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.AuthorizationReviewedAt), vS("days")) }, func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.ValidFrom), vS("days")) })))
}

// CalcAuthorizationIsOverdueForReview computes the AuthorizationIsOverdueForReview calculated field
// TRUE when the promised re-examination interval has elapsed without a review.
// Formula: =AND({{AuthorizationReviewCadenceDays}} > 0, {{DaysSinceAuthorizationReview}} > {{AuthorizationReviewCadenceDays}})
func (tc *RoleAssignment) CalcAuthorizationIsOverdueForReview() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vInt(tc.AuthorizationReviewCadenceDays)), ">", vI(0))), erbBool3(erbCmp(vInt(tc.DaysSinceAuthorizationReview), ">", erbNullif(vInt(tc.AuthorizationReviewCadenceDays))))))
}

// CalcIsStandingUnreviewedAutomation computes the IsStandingUnreviewedAutomation calculated field
// TRUE when a currently-active non-human assignment has been running past its authorization review date.
// Formula: =AND({{CoversNow}}, AND({{IsNonHumanAssignment}}, {{AuthorizationIsOverdueForReview}}))
func (tc *RoleAssignment) CalcIsStandingUnreviewedAutomation() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.CoversNow)), erbBool3(erbAnd(erbBool3(vBool(tc.IsNonHumanAssignment)), erbBool3(vBool(tc.AuthorizationIsOverdueForReview))))))
}

// CalcIsUnconditionedAutomationHandover computes the IsUnconditionedAutomationHandover calculated field
// TRUE when a human-to-machine handover was authorized with no promised review cadence at all -- granted once, permanently.
// Formula: =AND({{IsHumanToNonHumanHandover}}, {{AuthorizationReviewCadenceDays}} = 0)
func (tc *RoleAssignment) CalcIsUnconditionedAutomationHandover() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsHumanToNonHumanHandover)), erbBool3(erbEq(erbNullif(vInt(tc.AuthorizationReviewCadenceDays)), vI(0)))))
}

// CalcExceedsTolerableErrorRate computes the ExceedsTolerableErrorRate calculated field
// TRUE when this assignment's error rate has reached the threshold set when it was authorized.
// Formula: =AND({{MaxTolerableErrorRatePercent}} > 0, {{ErrorRatePercent}} >= {{MaxTolerableErrorRatePercent}})
func (tc *RoleAssignment) CalcExceedsTolerableErrorRate() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vInt(tc.MaxTolerableErrorRatePercent)), ">", vI(0))), erbBool3(erbCmp(vNum(tc.ErrorRatePercent), ">=", erbNullif(vInt(tc.MaxTolerableErrorRatePercent))))))
}

// CalcHasAnyBoundaryViolation computes the HasAnyBoundaryViolation calculated field
// TRUE when any decision under this assignment crossed a boundary it was forbidden to cross.
// Formula: =({{BoundaryViolationCountForAssignment}} > 0)
func (tc *RoleAssignment) CalcHasAnyBoundaryViolation() *bool {
	return toBoolPtr(erbCmp(vNum(tc.BoundaryViolationCountForAssignment), ">", vI(0)))
}

// CalcSuspensionConditionMet computes the SuspensionConditionMet calculated field
// TRUE when any pre-declared condition requiring this assignment to stop deciding unaided has been met.
// Formula: =OR({{ExceedsTolerableErrorRate}}, OR({{HasAnyBoundaryViolation}}, {{HasUngroundedGoverningBoundary}}))
func (tc *RoleAssignment) CalcSuspensionConditionMet() *bool {
	return toBoolPtr(erbOr(erbBool3(vBool(tc.ExceedsTolerableErrorRate)), erbBool3(erbOr(erbBool3(vBool(tc.HasAnyBoundaryViolation)), erbBool3(vBool(tc.HasUngroundedGoverningBoundary))))))
}

// CalcIsOperatingUnderMetSuspensionCondition computes the IsOperatingUnderMetSuspensionCondition calculated field
// TRUE when a suspension condition has been met and the assignment is nonetheless still active and still deciding.
// Formula: =AND({{SuspensionConditionMet}}, AND({{CoversNow}}, {{IsNonHumanAssignment}}))
func (tc *RoleAssignment) CalcIsOperatingUnderMetSuspensionCondition() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.SuspensionConditionMet)), erbBool3(erbAnd(erbBool3(vBool(tc.CoversNow)), erbBool3(vBool(tc.IsNonHumanAssignment))))))
}

// CalcHasDeclaredSuspensionCondition computes the HasDeclaredSuspensionCondition calculated field
// TRUE when this assignment has any pre-declared condition under which it must stop at all.
// Formula: ={{MaxTolerableErrorRatePercent}} > 0
func (tc *RoleAssignment) CalcHasDeclaredSuspensionCondition() *bool {
	return toBoolPtr(erbCmp(erbNullif(vInt(tc.MaxTolerableErrorRatePercent)), ">", vI(0)))
}

// CalcHasApprovingAuthority computes the HasApprovingAuthority calculated field
// TRUE when a role is recorded as having approved this assignment.
// Formula: ={{ApprovingAuthorityRole}} <> ""
func (tc *RoleAssignment) CalcHasApprovingAuthority() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.ApprovingAuthorityRole)))
}

// CalcHasAuthorizingChangeRequest computes the HasAuthorizingChangeRequest calculated field
// TRUE when a change request is recorded as the governance vehicle for this assignment.
// Formula: ={{AuthorizingChangeRequest}} <> ""
func (tc *RoleAssignment) CalcHasAuthorizingChangeRequest() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.AuthorizingChangeRequest)))
}

// CalcIsUnauthorizedEnforcementAgent computes the IsUnauthorizedEnforcementAgent calculated field
// TRUE when a non-human agent enforces controls on others while holding no recorded authorization of its own.
// Formula: =AND({{IsEnforcementRole}}, {{IsUnauthorizedNonHumanAssignment}})
func (tc *RoleAssignment) CalcIsUnauthorizedEnforcementAgent() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsEnforcementRole)), erbBool3(vBool(tc.IsUnauthorizedNonHumanAssignment))))
}

// CalcGovernanceEvidenceCount computes the GovernanceEvidenceCount calculated field
// How many independent governance artifacts back this assignment: an approving role, an authorizing change request.
// Formula: =IF({{HasApprovingAuthority}}, 1, 0) + IF({{HasAuthorizingChangeRequest}}, 1, 0)
func (tc *RoleAssignment) CalcGovernanceEvidenceCount() *int {
	return toIntPtr(erbInteger(erbAdd(erbIf(erbBool3(vBool(tc.HasApprovingAuthority)), func() Value { return vI(1) }, func() Value { return vI(0) }), erbIf(erbBool3(vBool(tc.HasAuthorizingChangeRequest)), func() Value { return vI(1) }, func() Value { return vI(0) }))))
}

// CalcUnauthorizedEnforcementRoleKey computes the UnauthorizedEnforcementRoleKey calculated field
// Echoes the role only for non-human assignments nobody authorized; empty otherwise.
// Formula: =IF({{IsUnauthorizedNonHumanAssignment}}, {{Role}}, "")
func (tc *RoleAssignment) CalcUnauthorizedEnforcementRoleKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUnauthorizedNonHumanAssignment)), func() Value { return vStr(tc.Role) }, func() Value { return vS("") }))
}

// CalcIsScopedToRetiredVersion computes the IsScopedToRetiredVersion calculated field
// TRUE when a current assignment is held for a version that is deprecated or archived.
// Formula: =AND({{IsCurrent}}, OR({{ScopedVersionStatus}} = "Deprecated", {{ScopedVersionStatus}} = "Archived"))
func (tc *RoleAssignment) CalcIsScopedToRetiredVersion() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsCurrent)), erbBool3(erbOr(erbBool3(erbEq(vStr(tc.ScopedVersionStatus), vS("Deprecated"))), erbBool3(erbEq(vStr(tc.ScopedVersionStatus), vS("Archived")))))))
}

// CalcPredecessorLacksValidityEnd computes the PredecessorLacksValidityEnd calculated field
// TRUE when an assignment supersedes one whose validity period was never closed.
// Formula: =AND({{SupersedesAssignment}} <> "", {{PredecessorValidTo}} = "")
func (tc *RoleAssignment) CalcPredecessorLacksValidityEnd() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.SupersedesAssignment))), erbBool3(erbIsBlank(vStr(tc.PredecessorValidTo)))))
}

// CalcAgentRolePairKey computes the AgentRolePairKey calculated field
// Agent and role, as one key, regardless of validity.
// Formula: ={{Agent}} & "|" & {{Role}}
func (tc *RoleAssignment) CalcAgentRolePairKey() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Agent)), vS("|"), erbText(vStr(tc.Role))))
}

// CalcIsOpenEnded computes the IsOpenEnded calculated field
// TRUE when the assignment has no end.
// Formula: ={{ValidTo}} = ""
func (tc *RoleAssignment) CalcIsOpenEnded() *bool {
	return toBoolPtr(erbIsBlank(vStr(tc.ValidTo)))
}

// CalcReceivesApprovalNoticesNow computes the ReceivesApprovalNoticesNow calculated field
// TRUE when the assignment currently covers a role that approval steps are assigned to, so its agent is who approval notices go to.
// Formula: =AND({{CoversNow}}, {{RoleApprovalStepCount}} > 0)
func (tc *RoleAssignment) CalcReceivesApprovalNoticesNow() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.CoversNow)), erbBool3(erbCmp(vInt(tc.RoleApprovalStepCount), ">", vI(0)))))
}

