// =============================================================================

// Mentorship represents a row in the Mentorships table
type Mentorship struct {
	MentorshipId string `json:"mentorship_id"` // Stored logical identifier for one Mentorships row.
	Name *string `json:"name"` // Human-readable calculated display alias for the Mentorships row.
	CommunityOfPractice *string `json:"community_of_practice"` // Community in which the mentorship operates.
	MentorAgent *string `json:"mentor_agent"` // Experienced practitioner serving as mentor.
	LearnerAgent *string `json:"learner_agent"` // Practitioner learning the procedure.
	ValidFrom *string `json:"valid_from"` // Mentorship start.
	ValidTo *string `json:"valid_to"` // Mentorship end.
	LearningObjective *string `json:"learning_objective"` // Procedural capability to be transferred.
	EvidenceOfCompletion *string `json:"evidence_of_completion"` // Evidence showing completion or competence.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension class IRI.
	EvaluationContext *string `json:"evaluation_context"` // The instant the row is judged against.
	AsOfInstant *string `json:"as_of_instant"` // The modeled evaluation instant.
	MentorshipForm *string `json:"mentorship_form"` // Mentoring or Apprenticeship.
	EmployerWorkerObligation *string `json:"employer_worker_obligation"` // The obligations between employer and worker that make the training worth investing in.
	ExpectedWeeklyHours *float64 `json:"expected_weekly_hours"` // Weekly mentor hours the mentorship needs.
	IsActive *bool `json:"is_active"` // TRUE when the mentorship runs at the evaluation instant.
	DaysSinceStarted *int `json:"days_since_started"` // Days since the mentorship began.
	IsRecentApprenticeship *bool `json:"is_recent_apprenticeship"` // TRUE for an apprenticeship started within three years.
	CommunityLabel *string `json:"community_label"` // The name of the community of practice this mentorship belongs to.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Mentorships row.
// Formula: ={{MentorAgent}} & " -> " & {{LearnerAgent}}
func (tc *Mentorship) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.MentorAgent)), vS(" -> "), erbText(vStr(tc.LearnerAgent))))
}

// CalcIsActive computes the IsActive calculated field
// TRUE when the mentorship runs at the evaluation instant.
// Formula: =AND({{ValidFrom}} <> "", {{ValidFrom}} <= {{AsOfInstant}}, OR({{ValidTo}} = "", {{ValidTo}} >= {{AsOfInstant}}))
func (tc *Mentorship) CalcIsActive() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ValidFrom))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidFrom)), "<=", vStr(tc.AsOfInstant))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.ValidTo))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidTo)), ">=", vStr(tc.AsOfInstant)))))))
}

// CalcDaysSinceStarted computes the DaysSinceStarted calculated field
// Days since the mentorship began.
// Formula: =IF({{ValidFrom}} = "", 99999, DATETIME_DIFF({{AsOfInstant}}, {{ValidFrom}}, "days"))
func (tc *Mentorship) CalcDaysSinceStarted() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.ValidFrom))), func() Value { return vI(99999) }, func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.ValidFrom), vS("days")) })))
}

// CalcIsRecentApprenticeship computes the IsRecentApprenticeship calculated field
// TRUE for an apprenticeship started within three years.
// Formula: =AND({{MentorshipForm}} = "Apprenticeship", {{DaysSinceStarted}} >= 0, {{DaysSinceStarted}} <= 1095)
func (tc *Mentorship) CalcIsRecentApprenticeship() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.MentorshipForm)), vS("Apprenticeship"))), erbBool3(erbCmp(vInt(tc.DaysSinceStarted), ">=", vI(0))), erbBool3(erbCmp(vInt(tc.DaysSinceStarted), "<=", vI(1095)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *Mentorship) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_active", func() { tc.IsActive = tc.CalcIsActive() })
	calcGuard(tc, "days_since_started", func() { tc.DaysSinceStarted = tc.CalcDaysSinceStarted() })
	// Level 2
	calcGuard(tc, "is_recent_apprenticeship", func() { tc.IsRecentApprenticeship = tc.CalcIsRecentApprenticeship() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *Mentorship) ComputeAll() *Mentorship {
	tc.erbComputeCalculations()
	return tc
}

