// CalcName computes the Name calculated field
// Human-readable calculated display alias for the ProcedureTypes row.
// Formula: ={{Label}}
func (tc *ProcedureType) CalcName() *string {
	return toStringPtr(vStr(tc.Label))
}

// CalcHasNarrowerTypes computes the HasNarrowerTypes calculated field
// TRUE when narrower process types fall under the node.
// Formula: ={{NarrowerTypeCount}} > 0
func (tc *ProcedureType) CalcHasNarrowerTypes() *bool {
	return toBoolPtr(erbCmp(vInt(tc.NarrowerTypeCount), ">", vI(0)))
}

// CalcIsDetachedFromTaxonomy computes the IsDetachedFromTaxonomy calculated field
// TRUE when a node below domain rank has no broader node.
// Formula: =AND({{TaxonomyRank}} <> "FunctionalDomain", {{BroaderProcedureType}} = "")
func (tc *ProcedureType) CalcIsDetachedFromTaxonomy() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNe(erbNullif(vStr(tc.TaxonomyRank)), vS("FunctionalDomain"))), erbBool3(erbIsBlank(vStr(tc.BroaderProcedureType)))))
}

// CalcIsUnreachableByNavigation computes the IsUnreachableByNavigation calculated field
// TRUE when navigating down from the functional domains never reaches this node.
// Formula: =OR({{IsDetachedFromTaxonomy}}, AND({{BroaderProcedureType}} <> "", {{BroaderIsDetached}} = TRUE))
func (tc *ProcedureType) CalcIsUnreachableByNavigation() *bool {
	return toBoolPtr(erbOr(erbBool3(vBool(tc.IsDetachedFromTaxonomy)), erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.BroaderProcedureType))), erbBool3(erbEq(vBool(tc.BroaderIsDetached), vB(true)))))))
}

// CalcIsArbitraryGrouping computes the IsArbitraryGrouping calculated field
// TRUE when a grouping has members but names no distinction, or none of its members has the distinction it names.
// Formula: =AND({{MemberCount}} > 0, OR({{DistinguishingFacet}} = "", {{MembersLackingDistinctionCount}} = {{MemberCount}}))
func (tc *ProcedureType) CalcIsArbitraryGrouping() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.MemberCount), ">", vI(0))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.DistinguishingFacet))), erbBool3(erbEq(vInt(tc.MembersLackingDistinctionCount), vInt(tc.MemberCount)))))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ProcedureType) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_narrower_types", func() { tc.HasNarrowerTypes = tc.CalcHasNarrowerTypes() })
	calcGuard(tc, "is_detached_from_taxonomy", func() { tc.IsDetachedFromTaxonomy = tc.CalcIsDetachedFromTaxonomy() })
	calcGuard(tc, "is_arbitrary_grouping", func() { tc.IsArbitraryGrouping = tc.CalcIsArbitraryGrouping() })
	// Level 2
	calcGuard(tc, "is_unreachable_by_navigation", func() { tc.IsUnreachableByNavigation = tc.CalcIsUnreachableByNavigation() })
}

