// ProcedureVersionLink represents a row in the ProcedureVersionLinks table
type ProcedureVersionLink struct {
	ProcedureVersionLinkId string `json:"procedure_version_link_id"` // Stored logical identifier for one ProcedureVersionLinks row.
	Name *string `json:"name"` // Human-readable calculated display alias for the ProcedureVersionLinks row.
	PreviousProcedureVersion *string `json:"previous_procedure_version"` // Earlier version.
	NextProcedureVersion *string `json:"next_procedure_version"` // Later version.
	RelationIri *string `json:"relation_iri"` // Exact version relation IRI.
	ChangeSummary *string `json:"change_summary"` // Summary of semantic change across the edge.
	SupersededVersionKey *string `json:"superseded_version_key"` // Echoes the superseded (previous) version id for rows that express a next-version relation. Supersession is carried by RelationIri here, not by a separate link-kind column.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the ProcedureVersionLinks row.
// Formula: ={{PreviousProcedureVersion}} & " -> " & {{NextProcedureVersion}}
func (tc *ProcedureVersionLink) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.PreviousProcedureVersion)), vS(" -> "), erbText(vStr(tc.NextProcedureVersion))))
}

// CalcSupersededVersionKey computes the SupersededVersionKey calculated field
// Echoes the superseded (previous) version id for rows that express a next-version relation. Supersession is carried by RelationIri here, not by a separate link-kind column.
// Formula: =IF({{RelationIri}} = "https://w3id.org/pko#nextVersion", {{PreviousProcedureVersion}}, "")
func (tc *ProcedureVersionLink) CalcSupersededVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.RelationIri)), vS("https://w3id.org/pko#nextVersion"))), func() Value { return vStr(tc.PreviousProcedureVersion) }, func() Value { return vS("") }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ProcedureVersionLink) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "superseded_version_key", func() { tc.SupersededVersionKey = tc.CalcSupersededVersionKey() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ProcedureVersionLink) ComputeAll() *ProcedureVersionLink {
	tc.erbComputeCalculations()
	return tc
}

