// =============================================================================
// STEPREQUIREMENTS TABLE
// Many-to-many Step/Requirement semantics normalized into an ERB junction table.
// =============================================================================

// StepRequirement represents a row in the StepRequirements table
type StepRequirement struct {
	StepRequirementId string `json:"step_requirement_id"` // Stored logical identifier for one StepRequirements row.
	Name *string `json:"name"` // Human-readable calculated display alias for the StepRequirements row.
	Step *string `json:"step"` // Step side of the relationship.
	Requirement *string `json:"requirement"` // Requirement side of the relationship.
	RequirementIsBlocking *bool `json:"requirement_is_blocking"` // Whether this spec-side step/requirement binding names a blocking control.
	BlockingStepKey *string `json:"blocking_step_key"` // Echoes the Step id only when the bound requirement is blocking; empty otherwise.
	StepWhenBlocking *string `json:"step_when_blocking"` // Echoes the step id when the bound requirement is blocking, blank otherwise.
	RequirementLacksWitness *bool `json:"requirement_lacks_witness"` // Whether the requirement bound at this step is a blocking control with no computed witness.
	UnwitnessedStepKey *string `json:"unwitnessed_step_key"` // Echoes the step id when the requirement bound here has no computed witness.
	SatisfactionCountForBinding *float64 `json:"satisfaction_count_for_binding"` // How many times this specific (step, requirement) binding has been evaluated in any execution.
	BindingWasEverExercised *bool `json:"binding_was_ever_exercised"` // TRUE when this specific (step, requirement) pair has been evaluated at least once.
	IsUnexercisedBlockingBinding *bool `json:"is_unexercised_blocking_binding"` // TRUE for a blocking control bound to a step where it has never actually been evaluated.
	UnexercisedBindingRequirementKey *string `json:"unexercised_binding_requirement_key"` // Echoes the requirement id when this binding has never been exercised.
	RequirementIsRegulatory *bool `json:"requirement_is_regulatory"` // Whether a regulation imposes the requirement.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the StepRequirements row.
// Formula: ={{Step}} & " / " & {{Requirement}}
func (tc *StepRequirement) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Step)), vS(" / "), erbText(vStr(tc.Requirement))))
}

// CalcBlockingStepKey computes the BlockingStepKey calculated field
// Echoes the Step id only when the bound requirement is blocking; empty otherwise.
// Formula: =IF({{RequirementIsBlocking}}, {{Step}}, "")
func (tc *StepRequirement) CalcBlockingStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.RequirementIsBlocking)), func() Value { return vStr(tc.Step) }, func() Value { return vS("") }))
}

// CalcStepWhenBlocking computes the StepWhenBlocking calculated field
// Echoes the step id when the bound requirement is blocking, blank otherwise.
// Formula: =IF({{RequirementIsBlocking}}, {{Step}}, "")
func (tc *StepRequirement) CalcStepWhenBlocking() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.RequirementIsBlocking)), func() Value { return vStr(tc.Step) }, func() Value { return vS("") }))
}

// CalcUnwitnessedStepKey computes the UnwitnessedStepKey calculated field
// Echoes the step id when the requirement bound here has no computed witness.
// Formula: =IF({{RequirementLacksWitness}}, {{Step}}, "")
func (tc *StepRequirement) CalcUnwitnessedStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.RequirementLacksWitness)), func() Value { return vStr(tc.Step) }, func() Value { return vS("") }))
}

// CalcBindingWasEverExercised computes the BindingWasEverExercised calculated field
// TRUE when this specific (step, requirement) pair has been evaluated at least once.
// Formula: ={{SatisfactionCountForBinding}} > 0
func (tc *StepRequirement) CalcBindingWasEverExercised() *bool {
	return toBoolPtr(erbCmp(vNum(tc.SatisfactionCountForBinding), ">", vI(0)))
}

// CalcIsUnexercisedBlockingBinding computes the IsUnexercisedBlockingBinding calculated field
// TRUE for a blocking control bound to a step where it has never actually been evaluated.
// Formula: =AND({{RequirementIsBlocking}}, NOT({{BindingWasEverExercised}}))
func (tc *StepRequirement) CalcIsUnexercisedBlockingBinding() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RequirementIsBlocking)), erbBool3(erbNot(erbBool3(vBool(tc.BindingWasEverExercised))))))
}

// CalcUnexercisedBindingRequirementKey computes the UnexercisedBindingRequirementKey calculated field
// Echoes the requirement id when this binding has never been exercised.
// Formula: =IF({{IsUnexercisedBlockingBinding}}, {{Requirement}}, "")
func (tc *StepRequirement) CalcUnexercisedBindingRequirementKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUnexercisedBlockingBinding)), func() Value { return vStr(tc.Requirement) }, func() Value { return vS("") }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *StepRequirement) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "blocking_step_key", func() { tc.BlockingStepKey = tc.CalcBlockingStepKey() })
	calcGuard(tc, "step_when_blocking", func() { tc.StepWhenBlocking = tc.CalcStepWhenBlocking() })
	calcGuard(tc, "unwitnessed_step_key", func() { tc.UnwitnessedStepKey = tc.CalcUnwitnessedStepKey() })
	calcGuard(tc, "binding_was_ever_exercised", func() { tc.BindingWasEverExercised = tc.CalcBindingWasEverExercised() })
	// Level 2
	calcGuard(tc, "is_unexercised_blocking_binding", func() { tc.IsUnexercisedBlockingBinding = tc.CalcIsUnexercisedBlockingBinding() })
	// Level 3
	calcGuard(tc, "unexercised_binding_requirement_key", func() { tc.UnexercisedBindingRequirementKey = tc.CalcUnexercisedBindingRequirementKey() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *StepRequirement) ComputeAll() *StepRequirement {
	tc.erbComputeCalculations()
	return tc
}

