// =============================================================================
// ELICITATIONSESSIONS TABLE
// Structured knowledge-elicitation events involving practitioners and knowledge engineers. Explicit ERB-PKO extension, modeled as prov:Activity.
// =============================================================================

// ElicitationSession represents a row in the ElicitationSessions table
type ElicitationSession struct {
	ElicitationSessionId string `json:"elicitation_session_id"` // Stored logical identifier for one ElicitationSessions row.
	Name *string `json:"name"` // Human-readable calculated display alias for the ElicitationSessions row.
	ProcedureVersion *string `json:"procedure_version"` // Procedure version whose knowledge was elicited.
	Method *string `json:"method"` // The knowledge method this session used.
	StartedAt *string `json:"started_at"` // Start time; maps to prov:startedAtTime.
	EndedAt *string `json:"ended_at"` // End time; maps to prov:endedAtTime.
	PractitionerAgent *string `json:"practitioner_agent"` // Domain practitioner providing knowledge.
	FacilitatorAgent *string `json:"facilitator_agent"` // Person facilitating elicitation.
	Summary *string `json:"summary"` // What was learned and captured.
	Status *string `json:"status"` // Draft, Reviewed, Approved, or Rejected.
	EvaluationContext *string `json:"evaluation_context"` // The evaluation context this row's time-dependent witnesses are judged under.
	AsOfInstant *string `json:"as_of_instant"` // The evaluation instant this row's time-dependent witnesses are judged against.
	DaysSinceElicited *int `json:"days_since_elicited"` // Days elapsed since this elicitation session concluded.
	IsSingleWitnessMethod *bool `json:"is_single_witness_method"` // TRUE when this session captured one practitioner's account rather than a group's.
	PractitionerIsStillEngaged *bool `json:"practitioner_is_still_engaged"` // Whether the practitioner whose knowledge this session captured still holds a role here.
	ValidFragmentsProduced *float64 `json:"valid_fragments_produced"` // How many currently-valid knowledge fragments this one session produced.
	IsHighYieldSession *bool `json:"is_high_yield_session"` // A session that alone underwrites three or more currently-valid claims.
	IsConcentratedSingleWitness *bool `json:"is_concentrated_single_witness"` // One unrepeated session with one witness that underwrites three or more live claims.
	IsStaleConcentratedWitness *bool `json:"is_stale_concentrated_witness"` // A concentrated single-witness session more than 180 days old — matching the single-witness expiry horizon loop 1 already established.
	ConcentratedSessionVersionKey *string `json:"concentrated_session_version_key"` // Composite-key echo: this session's procedure version when the session is a concentrated single witness, blank otherwise.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Class IRI used in semantic projection.
	ObserverStance *string `json:"observer_stance"` // For observation: NonParticipantObservation, Shadowing or LegitimatePeripheralParticipation.
	Setting *string `json:"setting"` // InSitu (where the work is done), Office or Remote.
	RecordingReference *string `json:"recording_reference"` // The recording of the practitioner's work made during the session, when one was made.
	PractitionerReviewedAt *string `json:"practitioner_reviewed_at"` // When the practitioner reviewed the recording afterward to explain their reasoning.
	ElicitationMode *string `json:"elicitation_mode"` // The family of elicitation the session's method belongs to.
	IsInterview *bool `json:"is_interview"` // TRUE for an interview session.
	IsWorkshop *bool `json:"is_workshop"` // TRUE for a workshop session.
	WhyProbeCount *int `json:"why_probe_count"` // Probes asking why a choice is made.
	ShortfallProbeCount *int `json:"shortfall_probe_count"` // Probes asking what happens when the procedure falls short.
	IsInterviewWithoutWhyProbe *bool `json:"is_interview_without_why_probe"` // TRUE for an interview that never asked why a choice is made.
	IsInterviewWithoutShortfallProbe *bool `json:"is_interview_without_shortfall_probe"` // TRUE for an interview that never asked what happens when the procedure falls short.
	InitiatorCount *int `json:"initiator_count"` // Participants who start the process.
	ExecutorCount *int `json:"executor_count"` // Participants who carry the process out.
	DependentCount *int `json:"dependent_count"` // Participants who depend on the process's results.
	UninvitedParticipantCount *int `json:"uninvited_participant_count"` // Participants whose position is normally not invited.
	GathersWholeProcessChain *bool `json:"gathers_whole_process_chain"` // TRUE for a workshop that gathered people who start, carry out and depend on the process.
	IsWorkshopWithoutUsualOutsiders *bool `json:"is_workshop_without_usual_outsiders"` // TRUE for a workshop in which nobody normally left out took part.
	MethodFamily *string `json:"method_family"` // The family of the session's method.
	FacilitatorKnowledgeEngineerRoleCount *int `json:"facilitator_knowledge_engineer_role_count"` // Knowledge engineer roles the facilitator currently holds.
	FacilitatorIsKnowledgeEngineer *bool `json:"facilitator_is_knowledge_engineer"` // TRUE when the session was run by the organization's knowledge engineer.
	IsGenericOrUnskilledCapture *bool `json:"is_generic_or_unskilled_capture"` // TRUE when a session captured knowledge with a method outside the elicitation family or without a skilled elicitor running it.
	IsKeFieldSession *bool `json:"is_ke_field_session"` // TRUE for a session the knowledge engineer ran where the work is done.
	IsReviewedRecording *bool `json:"is_reviewed_recording"` // TRUE when the practitioner reviewed a recording of their own work afterward to explain it.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the ElicitationSessions row.
// Formula: ={{Method}} & " / " & {{StartedAt}}
func (tc *ElicitationSession) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Method)), vS(" / "), erbDatetimeText(vStr(tc.StartedAt))))
}

// CalcDaysSinceElicited computes the DaysSinceElicited calculated field
// Days elapsed since this elicitation session concluded.
// Formula: =DATETIME_DIFF({{AsOfInstant}}, {{EndedAt}}, "days")
func (tc *ElicitationSession) CalcDaysSinceElicited() *int {
	return toIntPtr(erbInteger(erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.EndedAt), vS("days"))))
}

// CalcIsSingleWitnessMethod computes the IsSingleWitnessMethod calculated field
// TRUE when this session captured one practitioner's account rather than a group's.
// Formula: =OR({{Method}} = "Shadowing", {{Method}} = "PractitionerInterview")
func (tc *ElicitationSession) CalcIsSingleWitnessMethod() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("Shadowing"))), erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("PractitionerInterview")))))
}

// CalcIsHighYieldSession computes the IsHighYieldSession calculated field
// A session that alone underwrites three or more currently-valid claims.
// Formula: ={{ValidFragmentsProduced}} >= 3
func (tc *ElicitationSession) CalcIsHighYieldSession() *bool {
	return toBoolPtr(erbCmp(vNum(tc.ValidFragmentsProduced), ">=", vI(3)))
}

// CalcIsConcentratedSingleWitness computes the IsConcentratedSingleWitness calculated field
// One unrepeated session with one witness that underwrites three or more live claims.
// Formula: =AND({{IsSingleWitnessMethod}}, {{IsHighYieldSession}})
func (tc *ElicitationSession) CalcIsConcentratedSingleWitness() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsSingleWitnessMethod)), erbBool3(vBool(tc.IsHighYieldSession))))
}

// CalcIsStaleConcentratedWitness computes the IsStaleConcentratedWitness calculated field
// A concentrated single-witness session more than 180 days old — matching the single-witness expiry horizon loop 1 already established.
// Formula: =AND({{IsConcentratedSingleWitness}}, {{DaysSinceElicited}} > 180)
func (tc *ElicitationSession) CalcIsStaleConcentratedWitness() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsConcentratedSingleWitness)), erbBool3(erbCmp(vInt(tc.DaysSinceElicited), ">", vI(180)))))
}

// CalcConcentratedSessionVersionKey computes the ConcentratedSessionVersionKey calculated field
// Composite-key echo: this session's procedure version when the session is a concentrated single witness, blank otherwise.
// Formula: =IF({{IsConcentratedSingleWitness}}, {{ProcedureVersion}}, "")
func (tc *ElicitationSession) CalcConcentratedSessionVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsConcentratedSingleWitness)), func() Value { return vStr(tc.ProcedureVersion) }, func() Value { return vS("") }))
}

// CalcElicitationMode computes the ElicitationMode calculated field
// The family of elicitation the session's method belongs to.
// Formula: =IF({{Method}} = "PractitionerInterview", "Interview", IF({{Method}} = "Shadowing", "Observation", IF({{Method}} = "FacilitatedWorkshop", "Workshop", IF({{Method}} = "CriticalIncidentTechnique", "Incident", IF(OR({{Method}} = "ThinkAloudProtocol", {{Method}} = "RetrospectiveProtocol", {{Method}} = "ConceptLaddering", {{Method}} = "RepertoryGrid"), "Protocol", "Other")))))
func (tc *ElicitationSession) CalcElicitationMode() *string {
	return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("PractitionerInterview"))), func() Value { return vS("Interview") }, func() Value { return erbIf(erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("Shadowing"))), func() Value { return vS("Observation") }, func() Value { return erbIf(erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("FacilitatedWorkshop"))), func() Value { return vS("Workshop") }, func() Value { return erbIf(erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("CriticalIncidentTechnique"))), func() Value { return vS("Incident") }, func() Value { return erbIf(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("ThinkAloudProtocol"))), erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("RetrospectiveProtocol"))), erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("ConceptLaddering"))), erbBool3(erbEq(erbNullif(vStr(tc.Method)), vS("RepertoryGrid"))))), func() Value { return vS("Protocol") }, func() Value { return vS("Other") }) }) }) }) }))
}

// CalcIsInterview computes the IsInterview calculated field
// TRUE for an interview session.
// Formula: ={{ElicitationMode}} = "Interview"
func (tc *ElicitationSession) CalcIsInterview() *bool {
	return toBoolPtr(erbEq(vStr(tc.ElicitationMode), vS("Interview")))
}

// CalcIsWorkshop computes the IsWorkshop calculated field
// TRUE for a workshop session.
// Formula: ={{ElicitationMode}} = "Workshop"
func (tc *ElicitationSession) CalcIsWorkshop() *bool {
	return toBoolPtr(erbEq(vStr(tc.ElicitationMode), vS("Workshop")))
}

// CalcIsInterviewWithoutWhyProbe computes the IsInterviewWithoutWhyProbe calculated field
// TRUE for an interview that never asked why a choice is made.
// Formula: =AND({{IsInterview}}, {{WhyProbeCount}} = 0)
func (tc *ElicitationSession) CalcIsInterviewWithoutWhyProbe() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsInterview)), erbBool3(erbEq(vInt(tc.WhyProbeCount), vI(0)))))
}

// CalcIsInterviewWithoutShortfallProbe computes the IsInterviewWithoutShortfallProbe calculated field
// TRUE for an interview that never asked what happens when the procedure falls short.
// Formula: =AND({{IsInterview}}, {{ShortfallProbeCount}} = 0)
func (tc *ElicitationSession) CalcIsInterviewWithoutShortfallProbe() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsInterview)), erbBool3(erbEq(vInt(tc.ShortfallProbeCount), vI(0)))))
}

// CalcGathersWholeProcessChain computes the GathersWholeProcessChain calculated field
// TRUE for a workshop that gathered people who start, carry out and depend on the process.
// Formula: =AND({{IsWorkshop}}, {{InitiatorCount}} > 0, {{ExecutorCount}} > 0, {{DependentCount}} > 0)
func (tc *ElicitationSession) CalcGathersWholeProcessChain() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsWorkshop)), erbBool3(erbCmp(vInt(tc.InitiatorCount), ">", vI(0))), erbBool3(erbCmp(vInt(tc.ExecutorCount), ">", vI(0))), erbBool3(erbCmp(vInt(tc.DependentCount), ">", vI(0)))))
}

// CalcIsWorkshopWithoutUsualOutsiders computes the IsWorkshopWithoutUsualOutsiders calculated field
// TRUE for a workshop in which nobody normally left out took part.
// Formula: =AND({{IsWorkshop}}, {{UninvitedParticipantCount}} = 0)
func (tc *ElicitationSession) CalcIsWorkshopWithoutUsualOutsiders() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsWorkshop)), erbBool3(erbEq(vInt(tc.UninvitedParticipantCount), vI(0)))))
}

// CalcFacilitatorIsKnowledgeEngineer computes the FacilitatorIsKnowledgeEngineer calculated field
// TRUE when the session was run by the organization's knowledge engineer.
// Formula: ={{FacilitatorKnowledgeEngineerRoleCount}} > 0
func (tc *ElicitationSession) CalcFacilitatorIsKnowledgeEngineer() *bool {
	return toBoolPtr(erbCmp(vInt(tc.FacilitatorKnowledgeEngineerRoleCount), ">", vI(0)))
}

// CalcIsGenericOrUnskilledCapture computes the IsGenericOrUnskilledCapture calculated field
// TRUE when a session captured knowledge with a method outside the elicitation family or without a skilled elicitor running it.
// Formula: =AND({{Method}} <> "", OR({{MethodFamily}} <> "Elicitation", NOT({{FacilitatorIsKnowledgeEngineer}})))
func (tc *ElicitationSession) CalcIsGenericOrUnskilledCapture() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.Method))), erbBool3(erbOr(erbBool3(erbNe(vStr(tc.MethodFamily), vS("Elicitation"))), erbBool3(erbNot(erbBool3(vBool(tc.FacilitatorIsKnowledgeEngineer))))))))
}

// CalcIsKeFieldSession computes the IsKeFieldSession calculated field
// TRUE for a session the knowledge engineer ran where the work is done.
// Formula: =AND({{FacilitatorIsKnowledgeEngineer}}, {{Setting}} = "InSitu")
func (tc *ElicitationSession) CalcIsKeFieldSession() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.FacilitatorIsKnowledgeEngineer)), erbBool3(erbEq(erbNullif(vStr(tc.Setting)), vS("InSitu")))))
}

// CalcIsReviewedRecording computes the IsReviewedRecording calculated field
// TRUE when the practitioner reviewed a recording of their own work afterward to explain it.
// Formula: =AND({{RecordingReference}} <> "", {{PractitionerReviewedAt}} <> "")
func (tc *ElicitationSession) CalcIsReviewedRecording() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.RecordingReference))), erbBool3(erbIsNotBlank(vStr(tc.PractitionerReviewedAt)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ElicitationSession) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "days_since_elicited", func() { tc.DaysSinceElicited = tc.CalcDaysSinceElicited() })
	calcGuard(tc, "is_single_witness_method", func() { tc.IsSingleWitnessMethod = tc.CalcIsSingleWitnessMethod() })
	calcGuard(tc, "is_high_yield_session", func() { tc.IsHighYieldSession = tc.CalcIsHighYieldSession() })
	calcGuard(tc, "elicitation_mode", func() { tc.ElicitationMode = tc.CalcElicitationMode() })
	calcGuard(tc, "facilitator_is_knowledge_engineer", func() { tc.FacilitatorIsKnowledgeEngineer = tc.CalcFacilitatorIsKnowledgeEngineer() })
	calcGuard(tc, "is_reviewed_recording", func() { tc.IsReviewedRecording = tc.CalcIsReviewedRecording() })
	// Level 2
	calcGuard(tc, "is_concentrated_single_witness", func() { tc.IsConcentratedSingleWitness = tc.CalcIsConcentratedSingleWitness() })
	calcGuard(tc, "is_interview", func() { tc.IsInterview = tc.CalcIsInterview() })
	calcGuard(tc, "is_workshop", func() { tc.IsWorkshop = tc.CalcIsWorkshop() })
	calcGuard(tc, "is_generic_or_unskilled_capture", func() { tc.IsGenericOrUnskilledCapture = tc.CalcIsGenericOrUnskilledCapture() })
	calcGuard(tc, "is_ke_field_session", func() { tc.IsKeFieldSession = tc.CalcIsKeFieldSession() })
	// Level 3
	calcGuard(tc, "is_stale_concentrated_witness", func() { tc.IsStaleConcentratedWitness = tc.CalcIsStaleConcentratedWitness() })
	calcGuard(tc, "concentrated_session_version_key", func() { tc.ConcentratedSessionVersionKey = tc.CalcConcentratedSessionVersionKey() })
	calcGuard(tc, "is_interview_without_why_probe", func() { tc.IsInterviewWithoutWhyProbe = tc.CalcIsInterviewWithoutWhyProbe() })
	calcGuard(tc, "is_interview_without_shortfall_probe", func() { tc.IsInterviewWithoutShortfallProbe = tc.CalcIsInterviewWithoutShortfallProbe() })
	calcGuard(tc, "gathers_whole_process_chain", func() { tc.GathersWholeProcessChain = tc.CalcGathersWholeProcessChain() })
	calcGuard(tc, "is_workshop_without_usual_outsiders", func() { tc.IsWorkshopWithoutUsualOutsiders = tc.CalcIsWorkshopWithoutUsualOutsiders() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ElicitationSession) ComputeAll() *ElicitationSession {
	tc.erbComputeCalculations()
	return tc
}

