// EXPLANATIONS TABLE
// Explainable derivation artifacts associated with procedural decisions. Maps to pko:Explanation and pko:hasExplanation.
// =============================================================================

// Explanation represents a row in the Explanations table
type Explanation struct {
	ExplanationId string `json:"explanation_id"` // Stored logical identifier for one Explanations row.
	Name *string `json:"name"` // Human-readable calculated display alias for the Explanations row.
	ProcedureVersion *string `json:"procedure_version"` // Procedure version explained.
	Step *string `json:"step"` // Step explained.
	Title *string `json:"title"` // Explanation title.
	Description *string `json:"description"` // What the explanation traces.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact PKO class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Explanations row.
// Formula: ={{Title}}
func (tc *Explanation) CalcName() *string {
	return toStringPtr(vStr(tc.Title))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *Explanation) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *Explanation) ComputeAll() *Explanation {
	tc.erbComputeCalculations()
	return tc
}

func (tc *Explanation) erbGet(field string) Value {
	switch field {
	case "explanation_id":
		return vStrPlain(tc.ExplanationId)
	case "name":
		return vStr(tc.Name)
	case "procedure_version":
		return vStr(tc.ProcedureVersion)
	case "step":
		return vStr(tc.Step)
	case "title":
		return vStr(tc.Title)
	case "description":
		return vStr(tc.Description)
	case "semantic_type_iri":
		return vStr(tc.SemanticTypeIri)
	}
	panic("Explanations has no field " + field)
}

func (tc *Explanation) erbSet(field string, v Value) {
	switch field {
	case "explanation_id":
		tc.ExplanationId = strPlain(v)
	case "name":
		tc.Name = toStringPtr(v)
	case "procedure_version":
		tc.ProcedureVersion = toStringPtr(v)
	case "step":
		tc.Step = toStringPtr(v)
	case "title":
		tc.Title = toStringPtr(v)
	case "description":
		tc.Description = toStringPtr(v)
	case "semantic_type_iri":
		tc.SemanticTypeIri = toStringPtr(v)
	default:
		panic("Explanations has no field " + field)
	}
}

func (tc *Explanation) erbLoad(row map[string]any) {
	for key, value := range row {
		switch key {
		case "explanation_id", "name", "procedure_version", "step", "title", "description", "semantic_type_iri":
			tc.erbSet(key, fromJSON(value))
		}
	}
}

func (tc *Explanation) erbErrors() map[string]string {
	if tc.ErbErrors == nil {
		tc.ErbErrors = map[string]string{}
	}
	return tc.ErbErrors
}

func (tc *Explanation) erbResetErrors() { tc.ErbErrors = nil }

func (tc *Explanation) erbAggregate(name string) Value { return tc.erbAggregates[name] }

func (tc *Explanation) erbSetAggregate(name string, v Value) {
	if tc.erbAggregates == nil {
		tc.erbAggregates = map[string]Value{}
	}
	tc.erbAggregates[name] = v
}

// LoadExplanationRecords reads Explanations rows from a JSON array file.
func LoadExplanationRecords(path string) ([]Explanation, error) {
	records, err := loadRecords(path, func() Record { return &Explanation{} })
	if err != nil {
		return nil, err
	}
	rows := make([]Explanation, len(records))
	for i, r := range records {
		rows[i] = *r.(*Explanation)
	}
	return rows, nil
}

// =============================================================================
// PROCEDUREEXECUTIONS TABLE
// Concrete enactments of procedure specifications. Maps to pko:ProcedureExecution and remains separate from ProcedureVersions.
// =============================================================================

// ProcedureExecution represents a row in the ProcedureExecutions table
type ProcedureExecution struct {
	ProcedureExecutionId string `json:"procedure_execution_id"` // Stored logical identifier for one ProcedureExecutions row.
	Name *string `json:"name"` // Human-readable calculated display alias for the ProcedureExecutions row.
	ProcedureVersion *string `json:"procedure_version"` // Exact procedure specification executed; maps to pko:hasExecutedProcedure.
	ExecutionStatus *string `json:"execution_status"` // PKO execution status: InProgress, Completed, Paused, or Cancelled.
	StartedAt *string `json:"started_at"` // Execution start; maps to prov:startedAtTime.
	EndedAt *string `json:"ended_at"` // Execution end; maps to prov:endedAtTime.
	ExecutedByAgent *string `json:"executed_by_agent"` // Agent accountable for the overall execution; maps to pko:wasExecutedBy.
	Context *string `json:"context"` // Execution-specific scope or target.
	OperationalRecordUri *string `json:"operational_record_uri"` // Identifier in the operational execution system.
	ExpectedStepCount *float64 `json:"expected_step_count"` // How many steps this execution was supposed to perform.
	CompletedStepCount *float64 `json:"completed_step_count"` // How many steps of this execution actually reached Completed.
	ControlBreachCount *float64 `json:"control_breach_count"` // Total step executions in this run that carry at least one control breach.
	LateStepCount *float64 `json:"late_step_count"` // How many steps in this execution ran long.
	IsStructurallyComplete *bool `json:"is_structurally_complete"` // TRUE when every specified step of the procedure version reached Completed in this execution.
	DivergedFromSpecification *bool `json:"diverged_from_specification"` // TRUE when the execution either skipped specified steps or carried at least one control breach.
	AllBlockingControlsEvaluated *bool `json:"all_blocking_controls_evaluated"` // TRUE when every blocking requirement bound to every step of this execution received a satisfaction record.
	UnevaluatedBlockingTotal *float64 `json:"unevaluated_blocking_total"` // How many step executions in this run left at least one blocking control unevaluated.
	SeparationOfDutiesHeld *bool `json:"separation_of_duties_held"` // TRUE when no agent both prepared and approved within this execution.
	SeparationViolationCount *float64 `json:"separation_violation_count"` // Number of segregation-of-duties violations in this execution.
	IsAttestationReady *bool `json:"is_attestation_ready"` // TRUE only when every step completed, no control breached, every blocking control was actually evaluated, and segregation of duties held.
	AttestationBlockerSummary *string `json:"attestation_blocker_summary"` // Names the highest-severity reason the attestation cannot be signed, or empty when it can.
	ExecutedVersionIsFit *bool `json:"executed_version_is_fit"` // Whether the procedure version this execution ran against is currently fit to execute.
	SignedAgainstUnfitVersion *bool `json:"signed_against_unfit_version"` // TRUE when a completed execution was run against a procedure version the organization no longer stands behind.
	AssertedOnlyControlCount *float64 `json:"asserted_only_control_count"` // How many blocking controls in this execution passed on human assertion alone.
	AssuranceIsMostlyAsserted *bool `json:"assurance_is_mostly_asserted"` // TRUE when any blocking control in this execution passed without a computed witness behind it.
	UnreachableHandlingFailureCount *float64 `json:"unreachable_handling_failure_count"` // Number of deliveries in this execution where unreachable handling was wrong -- either fabricated acknowledgement or no exception invoked.
	RetentionBreachCount *float64 `json:"retention_breach_count"` // Number of transmitted messages in this execution whose text we no longer hold despite an active retention obligation.
	ClearedLegalReviewCount *float64 `json:"cleared_legal_review_count"` // How many passed legal reviews exist for this execution.
	HasClearedLegalReview *bool `json:"has_cleared_legal_review"` // TRUE when legal review has passed for this execution.
	AbandonedFailureCount *float64 `json:"abandoned_failure_count"` // Number of failed deliveries in this run that nobody picked up.
	DeliveredCount *float64 `json:"delivered_count"` // Number of confirmed-delivered messages in this run.
	TotalDeliveryAttemptCount *float64 `json:"total_delivery_attempt_count"` // Total delivery records of any status for this run.
	HasAbandonedFailures *bool `json:"has_abandoned_failures"` // TRUE when this run has any untriaged delivery failure.
	MishandledRefusalCount *float64 `json:"mishandled_refusal_count"` // Number of gate refusals in this run that were either overridden or silently dropped.
	UncleanStepCount *float64 `json:"unclean_step_count"` // Number of step executions in this run that were not clean.
	RanClean *bool `json:"ran_clean"` // TRUE when every step execution in this run was clean.
	CountOfApprovalExecutions *int `json:"count_of_approval_executions"` // How many human approval gates were executed in this run.
	HasHumanApproval *bool `json:"has_human_approval"` // TRUE when at least one human approval gate was executed in this run.
	CountOfDeliveryExecutions *int `json:"count_of_delivery_executions"` // How many times the send step ran in this execution.
	HasDelivered *bool `json:"has_delivered"` // TRUE when this run has sent communications to employees.
	DeliveredWithoutApproval *bool `json:"delivered_without_approval"` // TRUE when a run sent employee communications without executing a human approval gate.
	InvalidApprovalCount *float64 `json:"invalid_approval_count"` // Number of approval-type requirements in this run that are incomplete or non-human-evaluated.
	ApprovalChainIsComplete *bool `json:"approval_chain_is_complete"` // TRUE when every approval-type requirement in this run is fully satisfied by a human.
	VacuouslyCleanStepCount *float64 `json:"vacuously_clean_step_count"` // How many steps in this run were clean only because nothing checked them.
	PreparationStepCount *float64 `json:"preparation_step_count"` // How many preparation steps this execution actually ran.
	ApprovalStepCount *float64 `json:"approval_step_count"` // How many approval steps this execution actually ran.
	SeparationWasTestable *bool `json:"separation_was_testable"` // TRUE when this execution contained both a preparation step and an approval step, so segregation of duties had an opportunity to fail.
	SeparationHeldUnderTest *bool `json:"separation_held_under_test"` // TRUE only when segregation of duties both could have failed and did not.
	SeparationIsVacuouslyGreen *bool `json:"separation_is_vacuously_green"` // TRUE when the segregation control reports as held on a run where it could not have failed.
	SeparationAssuranceNote *string `json:"separation_assurance_note"` // The sentence that goes into the control narrative for this execution.
	UngovernedDivergenceCount *float64 `json:"ungoverned_divergence_count"` // How many steps in this run departed from spec with nothing authorising the departure.
	DivergenceWasFullyGoverned *bool `json:"divergence_was_fully_governed"` // TRUE when this run departed from specification and every departure was authorised.
	ComputedlyWitnessedControlCount *float64 `json:"computedly_witnessed_control_count"` // How many blocking controls in this run were cleared by something computed.
	EvaluatedControlCount *float64 `json:"evaluated_control_count"` // Total blocking controls actually evaluated in this run, computed and asserted together.
	ComputedAssuranceRatio *float64 `json:"computed_assurance_ratio"` // The fraction of evaluated blocking controls in this run that rest on a computed witness rather than a human assertion.
	InterestedPartyAssertionCount *float64 `json:"interested_party_assertion_count"` // How many controls in this run were cleared by assertion from someone with an interest in the outcome.
	AssuranceGrade *string `json:"assurance_grade"` // Names the quality of the assurance behind this execution, worst case first.
	AttestationWouldBeWeaklyBased *bool `json:"attestation_would_be_weakly_based"` // TRUE when the model says I may sign, but the basis for that permission is mostly or partly unwitnessed assertion.
	IndependentHumanObservationCount *float64 `json:"independent_human_observation_count"` // How many verifications in this run were independently observed by a human with evidence attached.
	HasAnyIndependentObservation *bool `json:"has_any_independent_observation"` // TRUE when at least one verification in this run was independently observed by a human.
	SelfAttestedApprovalCount *float64 `json:"self_attested_approval_count"` // How many approval steps in this run rested on self-attestation.
	AssuranceChainIsCircular *bool `json:"assurance_chain_is_circular"` // TRUE when every approval in this run rests on self-attestation and no independent human observation exists anywhere in it.
	LatestAttestationInstant *string `json:"latest_attestation_instant"` // The most recent signature instant for this execution.
	HasBeenAttested *bool `json:"has_been_attested"` // TRUE when someone has signed for this execution.
	AttestationCount *float64 `json:"attestation_count"` // How many signatures exist against this execution.
	PostAttestationScoreCount *float64 `json:"post_attestation_score_count"` // How many controls were scored after this execution was signed.
	BasisChangedAfterSignature *bool `json:"basis_changed_after_signature"` // TRUE when controls this attestation depended on were scored after the signature was given.
	RequiresReAttestation *bool `json:"requires_re_attestation"` // TRUE when the basis changed after signature AND the execution no longer reads as attestable.
	IntendedRecipientCount *float64 `json:"intended_recipient_count"` // How many sends this campaign proposed to make.
	ReachedRecipientCount *float64 `json:"reached_recipient_count"` // How many of those sends actually left our systems.
	SilentlyDroppedCount *float64 `json:"silently_dropped_count"` // How many intended recipients disappeared from this campaign with no record.
	DeliveryYieldPercent *float64 `json:"delivery_yield_percent"` // Percentage of intended recipients who actually received the communication.
	CampaignSilentlyLostAudience *bool `json:"campaign_silently_lost_audience"` // TRUE when a campaign lost intended recipients without producing any record of the loss.
	UnrecordedRefusalCount *float64 `json:"unrecorded_refusal_count"` // How many sends this execution refused without recording the refusal anywhere.
	HasUnrecordedRefusals *bool `json:"has_unrecorded_refusals"` // TRUE when this run contains at least one refusal that left no trace anywhere.
	IndependentlyConfirmedIntentCount *float64 `json:"independently_confirmed_intent_count"` // How many of this execution's send decisions were corroborated by a delivery record.
	SendDecisionsAreEntirelySelfWitnessed *bool `json:"send_decisions_are_entirely_self_witnessed"` // TRUE when no send decision in this run was confirmed by anything other than the pipeline itself.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact PKO class IRI.
	Title *string `json:"title"` // Execution title (dct:title).
	Description *string `json:"description"` // Execution description (dct:description).
	ConfirmedByAgent *string `json:"confirmed_by_agent"` // Who confirmed the execution (pko:wasConfirmedBy).
	Facility *string `json:"facility"` // Where it ran.
	Shift *string `json:"shift"` // Day or Night, where the work runs in shifts.
	ExecutedOnMachine *string `json:"executed_on_machine"` // Machine the procedure was executed on (pko-ind:isExecutedOnMachine).
	Observations *string `json:"observations"` // What the executor noticed.
	Outcome *string `json:"outcome"` // How it turned out.
	ParticipantCount *int `json:"participant_count"` // Associated agents besides the executor.
	DeviatingStepCount *int `json:"deviating_step_count"` // Step executions that recorded a deviation.
	HasStepDeviation *bool `json:"has_step_deviation"` // TRUE when any step deviated.
	DeviatingFacilityKey *string `json:"deviating_facility_key"` // Facility key when the run deviated.
	CleanFacilityKey *string `json:"clean_facility_key"` // Facility key when the run did not deviate.
	DeviatingDayVersionKey *string `json:"deviating_day_version_key"` // Version key for a deviating day-shift run.
	DeviatingNightVersionKey *string `json:"deviating_night_version_key"` // Version key for a deviating night-shift run.
	StatusChangeCount *int `json:"status_change_count"` // Status changes recorded against the execution itself.
	ClaimsCompletionWithoutAllSteps *bool `json:"claims_completion_without_all_steps"` // TRUE when an execution is marked completed but not every specified step completed.
	IsUnconfirmedCompletion *bool `json:"is_unconfirmed_completion"` // TRUE when an execution completed with nobody recorded as confirming it.
	HasNoRecordedOutcome *bool `json:"has_no_recorded_outcome"` // TRUE when an execution records no outcome.
	FeedbackCount *int `json:"feedback_count"` // Feedback filed about the execution.
	IsUnreportedMistake *bool `json:"is_unreported_mistake"` // TRUE when an execution deviated from its steps and nobody filed any feedback about it.
	OwnerOrganization *string `json:"owner_organization"` // The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
	StoppedAtKnowledgeGap *string `json:"stopped_at_knowledge_gap"` // The knowledge gap this run stopped at: the procedure had no answer, so the run ended instead of someone guessing.
	StoppedAtGapStatement *string `json:"stopped_at_gap_statement"` // What nobody knows, in the gap this run stopped at.
	StoppedAtGapStatus *string `json:"stopped_at_gap_status"` // Whether the gap this run stopped at is still open.
	StoppedAtGapChangeTitle *string `json:"stopped_at_gap_change_title"` // The change to the book that answers the gap this run stopped at.
	StoppedAtGapChangeStatus *string `json:"stopped_at_gap_change_status"` // Where the change that answers this run's gap has got to.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the ProcedureExecutions row.
// Formula: ={{ProcedureVersion}} & " / " & {{Context}}
func (tc *ProcedureExecution) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ProcedureVersion)), vS(" / "), erbText(vStr(tc.Context))))
}

// CalcIsStructurallyComplete computes the IsStructurallyComplete calculated field
// TRUE when every specified step of the procedure version reached Completed in this execution.
// Formula: ={{CompletedStepCount}} >= {{ExpectedStepCount}}
func (tc *ProcedureExecution) CalcIsStructurallyComplete() *bool {
	return toBoolPtr(erbCmp(vNum(tc.CompletedStepCount), ">=", vNum(tc.ExpectedStepCount)))
}

// CalcDivergedFromSpecification computes the DivergedFromSpecification calculated field
// TRUE when the execution either skipped specified steps or carried at least one control breach.
// Formula: =OR(NOT({{IsStructurallyComplete}}), {{ControlBreachCount}} > 0)
func (tc *ProcedureExecution) CalcDivergedFromSpecification() *bool {
	return toBoolPtr(erbOr(erbBool3(erbNot(erbBool3(vBool(tc.IsStructurallyComplete)))), erbBool3(erbCmp(vNum(tc.ControlBreachCount), ">", vI(0)))))
}

// CalcAllBlockingControlsEvaluated computes the AllBlockingControlsEvaluated calculated field
// TRUE when every blocking requirement bound to every step of this execution received a satisfaction record.
// Formula: ={{UnevaluatedBlockingTotal}} = 0
func (tc *ProcedureExecution) CalcAllBlockingControlsEvaluated() *bool {
	return toBoolPtr(erbEq(vNum(tc.UnevaluatedBlockingTotal), vI(0)))
}

// CalcSeparationOfDutiesHeld computes the SeparationOfDutiesHeld calculated field
// TRUE when no agent both prepared and approved within this execution.
// Formula: ={{SeparationViolationCount}} = 0
func (tc *ProcedureExecution) CalcSeparationOfDutiesHeld() *bool {
	return toBoolPtr(erbEq(vNum(tc.SeparationViolationCount), vI(0)))
}

// CalcIsAttestationReady computes the IsAttestationReady calculated field
// TRUE only when every step completed, no control breached, every blocking control was actually evaluated, and segregation of duties held.
// Formula: =AND({{IsStructurallyComplete}}, NOT({{DivergedFromSpecification}}), {{AllBlockingControlsEvaluated}}, {{SeparationOfDutiesHeld}})
func (tc *ProcedureExecution) CalcIsAttestationReady() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsStructurallyComplete)), erbBool3(erbNot(erbBool3(vBool(tc.DivergedFromSpecification)))), erbBool3(vBool(tc.AllBlockingControlsEvaluated)), erbBool3(vBool(tc.SeparationOfDutiesHeld))))
}

// CalcAttestationBlockerSummary computes the AttestationBlockerSummary calculated field
// Names the highest-severity reason the attestation cannot be signed, or empty when it can.
// Formula: =IF({{IsAttestationReady}}, "", IF(NOT({{IsStructurallyComplete}}), "Incomplete: specified steps did not all complete.", IF({{SeparationViolationCount}} > 0, "Segregation of duties violated.", IF({{UnevaluatedBlockingTotal}} > 0, "Blocking controls were never evaluated.", "Control breach recorded on one or more steps."))))
func (tc *ProcedureExecution) CalcAttestationBlockerSummary() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsAttestationReady)), func() Value { return vS("") }, func() Value { return erbIf(erbBool3(erbNot(erbBool3(vBool(tc.IsStructurallyComplete)))), func() Value { return vS("Incomplete: specified steps did not all complete.") }, func() Value { return erbIf(erbBool3(erbCmp(vNum(tc.SeparationViolationCount), ">", vI(0))), func() Value { return vS("Segregation of duties violated.") }, func() Value { return erbIf(erbBool3(erbCmp(vNum(tc.UnevaluatedBlockingTotal), ">", vI(0))), func() Value { return vS("Blocking controls were never evaluated.") }, func() Value { return vS("Control breach recorded on one or more steps.") }) }) }) }))
}

// CalcSignedAgainstUnfitVersion computes the SignedAgainstUnfitVersion calculated field
// TRUE when a completed execution was run against a procedure version the organization no longer stands behind.
// Formula: =AND({{ExecutionStatus}} = "Completed", NOT({{ExecutedVersionIsFit}}))
func (tc *ProcedureExecution) CalcSignedAgainstUnfitVersion() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed"))), erbBool3(erbNot(erbBool3(vBool(tc.ExecutedVersionIsFit))))))
}

// CalcAssuranceIsMostlyAsserted computes the AssuranceIsMostlyAsserted calculated field
// TRUE when any blocking control in this execution passed without a computed witness behind it.
// Formula: ={{AssertedOnlyControlCount}} > 0
func (tc *ProcedureExecution) CalcAssuranceIsMostlyAsserted() *bool {
	return toBoolPtr(erbCmp(vNum(tc.AssertedOnlyControlCount), ">", vI(0)))
}

// CalcHasClearedLegalReview computes the HasClearedLegalReview calculated field
// TRUE when legal review has passed for this execution.
// Formula: ={{ClearedLegalReviewCount}} > 0
func (tc *ProcedureExecution) CalcHasClearedLegalReview() *bool {
	return toBoolPtr(erbCmp(vNum(tc.ClearedLegalReviewCount), ">", vI(0)))
}

// CalcHasAbandonedFailures computes the HasAbandonedFailures calculated field
// TRUE when this run has any untriaged delivery failure.
// Formula: ={{AbandonedFailureCount}} > 0
func (tc *ProcedureExecution) CalcHasAbandonedFailures() *bool {
	return toBoolPtr(erbCmp(vNum(tc.AbandonedFailureCount), ">", vI(0)))
}

// CalcRanClean computes the RanClean calculated field
// TRUE when every step execution in this run was clean.
// Formula: ={{UncleanStepCount}} = 0
func (tc *ProcedureExecution) CalcRanClean() *bool {
	return toBoolPtr(erbEq(vNum(tc.UncleanStepCount), vI(0)))
}

// CalcHasHumanApproval computes the HasHumanApproval calculated field
// TRUE when at least one human approval gate was executed in this run.
// Formula: ={{CountOfApprovalExecutions}} > 0
func (tc *ProcedureExecution) CalcHasHumanApproval() *bool {
	return toBoolPtr(erbCmp(vInt(tc.CountOfApprovalExecutions), ">", vI(0)))
}

// CalcHasDelivered computes the HasDelivered calculated field
// TRUE when this run has sent communications to employees.
// Formula: ={{CountOfDeliveryExecutions}} > 0
func (tc *ProcedureExecution) CalcHasDelivered() *bool {
	return toBoolPtr(erbCmp(vInt(tc.CountOfDeliveryExecutions), ">", vI(0)))
}

// CalcDeliveredWithoutApproval computes the DeliveredWithoutApproval calculated field
// TRUE when a run sent employee communications without executing a human approval gate.
// Formula: =AND({{HasDelivered}}, NOT({{HasHumanApproval}}))
func (tc *ProcedureExecution) CalcDeliveredWithoutApproval() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasDelivered)), erbBool3(erbNot(erbBool3(vBool(tc.HasHumanApproval))))))
}

// CalcApprovalChainIsComplete computes the ApprovalChainIsComplete calculated field
// TRUE when every approval-type requirement in this run is fully satisfied by a human.
// Formula: ={{InvalidApprovalCount}} = 0
func (tc *ProcedureExecution) CalcApprovalChainIsComplete() *bool {
	return toBoolPtr(erbEq(vNum(tc.InvalidApprovalCount), vI(0)))
}

// CalcSeparationWasTestable computes the SeparationWasTestable calculated field
// TRUE when this execution contained both a preparation step and an approval step, so segregation of duties had an opportunity to fail.
// Formula: =AND({{PreparationStepCount}} > 0, {{ApprovalStepCount}} > 0)
func (tc *ProcedureExecution) CalcSeparationWasTestable() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vNum(tc.PreparationStepCount), ">", vI(0))), erbBool3(erbCmp(vNum(tc.ApprovalStepCount), ">", vI(0)))))
}

// CalcSeparationHeldUnderTest computes the SeparationHeldUnderTest calculated field
// TRUE only when segregation of duties both could have failed and did not.
// Formula: =AND({{SeparationWasTestable}}, {{SeparationOfDutiesHeld}})
func (tc *ProcedureExecution) CalcSeparationHeldUnderTest() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.SeparationWasTestable)), erbBool3(vBool(tc.SeparationOfDutiesHeld))))
}

// CalcSeparationIsVacuouslyGreen computes the SeparationIsVacuouslyGreen calculated field
// TRUE when the segregation control reports as held on a run where it could not have failed.
// Formula: =AND({{SeparationOfDutiesHeld}}, NOT({{SeparationWasTestable}}))
func (tc *ProcedureExecution) CalcSeparationIsVacuouslyGreen() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.SeparationOfDutiesHeld)), erbBool3(erbNot(erbBool3(vBool(tc.SeparationWasTestable))))))
}

// CalcSeparationAssuranceNote computes the SeparationAssuranceNote calculated field
// The sentence that goes into the control narrative for this execution.
// Formula: =IF({{SeparationViolationCount}} > 0, "Violated: same agent prepared and approved.", IF({{SeparationIsVacuouslyGreen}}, "Not tested: this run had no preparation/approval pair.", "Held under test."))
func (tc *ProcedureExecution) CalcSeparationAssuranceNote() *string {
	return toStringPtr(erbIf(erbBool3(erbCmp(vNum(tc.SeparationViolationCount), ">", vI(0))), func() Value { return vS("Violated: same agent prepared and approved.") }, func() Value { return erbIf(erbBool3(vBool(tc.SeparationIsVacuouslyGreen)), func() Value { return vS("Not tested: this run had no preparation/approval pair.") }, func() Value { return vS("Held under test.") }) }))
}

// CalcDivergenceWasFullyGoverned computes the DivergenceWasFullyGoverned calculated field
// TRUE when this run departed from specification and every departure was authorised.
// Formula: =AND({{DivergedFromSpecification}}, {{UngovernedDivergenceCount}} = 0)
func (tc *ProcedureExecution) CalcDivergenceWasFullyGoverned() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.DivergedFromSpecification)), erbBool3(erbEq(vNum(tc.UngovernedDivergenceCount), vI(0)))))
}

// CalcEvaluatedControlCount computes the EvaluatedControlCount calculated field
// Total blocking controls actually evaluated in this run, computed and asserted together.
// Formula: ={{ComputedlyWitnessedControlCount}} + {{AssertedOnlyControlCount}}
func (tc *ProcedureExecution) CalcEvaluatedControlCount() *float64 {
	return toFloatPtr(erbAdd(vNum(tc.ComputedlyWitnessedControlCount), vNum(tc.AssertedOnlyControlCount)))
}

// CalcComputedAssuranceRatio computes the ComputedAssuranceRatio calculated field
// The fraction of evaluated blocking controls in this run that rest on a computed witness rather than a human assertion.
// Formula: =IF({{EvaluatedControlCount}} = 0, 0, {{ComputedlyWitnessedControlCount}} / {{EvaluatedControlCount}})
func (tc *ProcedureExecution) CalcComputedAssuranceRatio() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbEq(vNum(tc.EvaluatedControlCount), vI(0))), func() Value { return vI(0) }, func() Value { return erbDiv(vNum(tc.ComputedlyWitnessedControlCount), vNum(tc.EvaluatedControlCount)) }))
}

// CalcAssuranceGrade computes the AssuranceGrade calculated field
// Names the quality of the assurance behind this execution, worst case first.
// Formula: =IF({{EvaluatedControlCount}} = 0, "None: no blocking control was evaluated.", IF({{InterestedPartyAssertionCount}} > 0, "Weak: at least one control rests on an interested-party assertion.", IF({{ComputedAssuranceRatio}} < 0.5, "Thin: most controls rest on human assertion.", IF({{ComputedAssuranceRatio}} < 1, "Mixed: computed and asserted controls.", "Computed: every evaluated control has a witness."))))
func (tc *ProcedureExecution) CalcAssuranceGrade() *string {
	return toStringPtr(erbIf(erbBool3(erbEq(vNum(tc.EvaluatedControlCount), vI(0))), func() Value { return vS("None: no blocking control was evaluated.") }, func() Value { return erbIf(erbBool3(erbCmp(vNum(tc.InterestedPartyAssertionCount), ">", vI(0))), func() Value { return vS("Weak: at least one control rests on an interested-party assertion.") }, func() Value { return erbIf(erbBool3(erbCmp(vNum(tc.ComputedAssuranceRatio), "<", vF(0.5))), func() Value { return vS("Thin: most controls rest on human assertion.") }, func() Value { return erbIf(erbBool3(erbCmp(vNum(tc.ComputedAssuranceRatio), "<", vI(1))), func() Value { return vS("Mixed: computed and asserted controls.") }, func() Value { return vS("Computed: every evaluated control has a witness.") }) }) }) }))
}

// CalcAttestationWouldBeWeaklyBased computes the AttestationWouldBeWeaklyBased calculated field
// TRUE when the model says I may sign, but the basis for that permission is mostly or partly unwitnessed assertion.
// Formula: =AND({{IsAttestationReady}}, OR({{InterestedPartyAssertionCount}} > 0, {{ComputedAssuranceRatio}} < 0.5))
func (tc *ProcedureExecution) CalcAttestationWouldBeWeaklyBased() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsAttestationReady)), erbBool3(erbOr(erbBool3(erbCmp(vNum(tc.InterestedPartyAssertionCount), ">", vI(0))), erbBool3(erbCmp(vNum(tc.ComputedAssuranceRatio), "<", vF(0.5)))))))
}

// CalcHasAnyIndependentObservation computes the HasAnyIndependentObservation calculated field
// TRUE when at least one verification in this run was independently observed by a human.
// Formula: ={{IndependentHumanObservationCount}} > 0
func (tc *ProcedureExecution) CalcHasAnyIndependentObservation() *bool {
	return toBoolPtr(erbCmp(vNum(tc.IndependentHumanObservationCount), ">", vI(0)))
}

// CalcAssuranceChainIsCircular computes the AssuranceChainIsCircular calculated field
// TRUE when every approval in this run rests on self-attestation and no independent human observation exists anywhere in it.
// Formula: =AND({{SelfAttestedApprovalCount}} > 0, NOT({{HasAnyIndependentObservation}}))
func (tc *ProcedureExecution) CalcAssuranceChainIsCircular() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vNum(tc.SelfAttestedApprovalCount), ">", vI(0))), erbBool3(erbNot(erbBool3(vBool(tc.HasAnyIndependentObservation))))))
}

// CalcHasBeenAttested computes the HasBeenAttested calculated field
// TRUE when someone has signed for this execution.
// Formula: ={{AttestationCount}} > 0
func (tc *ProcedureExecution) CalcHasBeenAttested() *bool {
	return toBoolPtr(erbCmp(vNum(tc.AttestationCount), ">", vI(0)))
}

// CalcBasisChangedAfterSignature computes the BasisChangedAfterSignature calculated field
// TRUE when controls this attestation depended on were scored after the signature was given.
// Formula: =AND({{HasBeenAttested}}, {{PostAttestationScoreCount}} > 0)
func (tc *ProcedureExecution) CalcBasisChangedAfterSignature() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasBeenAttested)), erbBool3(erbCmp(vNum(tc.PostAttestationScoreCount), ">", vI(0)))))
}

// CalcRequiresReAttestation computes the RequiresReAttestation calculated field
// TRUE when the basis changed after signature AND the execution no longer reads as attestable.
// Formula: =AND({{BasisChangedAfterSignature}}, NOT({{IsAttestationReady}}))
func (tc *ProcedureExecution) CalcRequiresReAttestation() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.BasisChangedAfterSignature)), erbBool3(erbNot(erbBool3(vBool(tc.IsAttestationReady))))))
}

// CalcDeliveryYieldPercent computes the DeliveryYieldPercent calculated field
// Percentage of intended recipients who actually received the communication.
// Formula: =IF({{IntendedRecipientCount}} > 0, {{ReachedRecipientCount}} * 100 / {{IntendedRecipientCount}}, 0)
func (tc *ProcedureExecution) CalcDeliveryYieldPercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbCmp(vNum(tc.IntendedRecipientCount), ">", vI(0))), func() Value { return erbDiv(erbMul(vNum(tc.ReachedRecipientCount), vI(100)), vNum(tc.IntendedRecipientCount)) }, func() Value { return vI(0) }))
}

// CalcCampaignSilentlyLostAudience computes the CampaignSilentlyLostAudience calculated field
// TRUE when a campaign lost intended recipients without producing any record of the loss.
// Formula: =({{SilentlyDroppedCount}} > 0)
func (tc *ProcedureExecution) CalcCampaignSilentlyLostAudience() *bool {
	return toBoolPtr(erbCmp(vNum(tc.SilentlyDroppedCount), ">", vI(0)))
}

// CalcHasUnrecordedRefusals computes the HasUnrecordedRefusals calculated field
// TRUE when this run contains at least one refusal that left no trace anywhere.
// Formula: =({{UnrecordedRefusalCount}} > 0)
func (tc *ProcedureExecution) CalcHasUnrecordedRefusals() *bool {
	return toBoolPtr(erbCmp(vNum(tc.UnrecordedRefusalCount), ">", vI(0)))
}

// CalcSendDecisionsAreEntirelySelfWitnessed computes the SendDecisionsAreEntirelySelfWitnessed calculated field
// TRUE when no send decision in this run was confirmed by anything other than the pipeline itself.
// Formula: =AND({{IntendedRecipientCount}} > 0, {{IndependentlyConfirmedIntentCount}} = 0)
func (tc *ProcedureExecution) CalcSendDecisionsAreEntirelySelfWitnessed() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vNum(tc.IntendedRecipientCount), ">", vI(0))), erbBool3(erbEq(vNum(tc.IndependentlyConfirmedIntentCount), vI(0)))))
}

// CalcHasStepDeviation computes the HasStepDeviation calculated field
// TRUE when any step deviated.
// Formula: ={{DeviatingStepCount}} > 0
func (tc *ProcedureExecution) CalcHasStepDeviation() *bool {
	return toBoolPtr(erbCmp(vInt(tc.DeviatingStepCount), ">", vI(0)))
}

// CalcDeviatingFacilityKey computes the DeviatingFacilityKey calculated field
// Facility key when the run deviated.
// Formula: =IF({{HasStepDeviation}}, {{Facility}}, "")
func (tc *ProcedureExecution) CalcDeviatingFacilityKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.HasStepDeviation)), func() Value { return vStr(tc.Facility) }, func() Value { return vS("") }))
}

// CalcCleanFacilityKey computes the CleanFacilityKey calculated field
// Facility key when the run did not deviate.
// Formula: =IF(AND({{Facility}} <> "", {{HasStepDeviation}} = FALSE), {{Facility}}, "")
func (tc *ProcedureExecution) CalcCleanFacilityKey() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.Facility))), erbBool3(erbEq(vBool(tc.HasStepDeviation), vB(false))))), func() Value { return vStr(tc.Facility) }, func() Value { return vS("") }))
}

// CalcDeviatingDayVersionKey computes the DeviatingDayVersionKey calculated field
// Version key for a deviating day-shift run.
// Formula: =IF(AND({{HasStepDeviation}}, {{Shift}} = "Day"), {{ProcedureVersion}}, "")
func (tc *ProcedureExecution) CalcDeviatingDayVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(vBool(tc.HasStepDeviation)), erbBool3(erbEq(erbNullif(vStr(tc.Shift)), vS("Day"))))), func() Value { return vStr(tc.ProcedureVersion) }, func() Value { return vS("") }))
}

// CalcDeviatingNightVersionKey computes the DeviatingNightVersionKey calculated field
// Version key for a deviating night-shift run.
// Formula: =IF(AND({{HasStepDeviation}}, {{Shift}} = "Night"), {{ProcedureVersion}}, "")
func (tc *ProcedureExecution) CalcDeviatingNightVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(vBool(tc.HasStepDeviation)), erbBool3(erbEq(erbNullif(vStr(tc.Shift)), vS("Night"))))), func() Value { return vStr(tc.ProcedureVersion) }, func() Value { return vS("") }))
}

// CalcClaimsCompletionWithoutAllSteps computes the ClaimsCompletionWithoutAllSteps calculated field
// TRUE when an execution is marked completed but not every specified step completed.
// Formula: =AND({{ExecutionStatus}} = "Completed", {{CompletedStepCount}} < {{ExpectedStepCount}})
func (tc *ProcedureExecution) CalcClaimsCompletionWithoutAllSteps() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed"))), erbBool3(erbCmp(vNum(tc.CompletedStepCount), "<", vNum(tc.ExpectedStepCount)))))
}

// CalcIsUnconfirmedCompletion computes the IsUnconfirmedCompletion calculated field
// TRUE when an execution completed with nobody recorded as confirming it.
// Formula: =AND({{ExecutionStatus}} = "Completed", {{ConfirmedByAgent}} = "")
func (tc *ProcedureExecution) CalcIsUnconfirmedCompletion() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed"))), erbBool3(erbIsBlank(vStr(tc.ConfirmedByAgent)))))
}

// CalcHasNoRecordedOutcome computes the HasNoRecordedOutcome calculated field
// TRUE when an execution records no outcome.
// Formula: ={{Outcome}} = ""
func (tc *ProcedureExecution) CalcHasNoRecordedOutcome() *bool {
	return toBoolPtr(erbIsBlank(vStr(tc.Outcome)))
}

// CalcIsUnreportedMistake computes the IsUnreportedMistake calculated field
// TRUE when an execution deviated from its steps and nobody filed any feedback about it.
// Formula: =AND({{HasStepDeviation}}, {{FeedbackCount}} = 0)
func (tc *ProcedureExecution) CalcIsUnreportedMistake() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasStepDeviation)), erbBool3(erbEq(vInt(tc.FeedbackCount), vI(0)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
