// LoadProcedureExecutionRecords reads ProcedureExecutions rows from a JSON array file.
func LoadProcedureExecutionRecords(path string) ([]ProcedureExecution, error) {
	records, err := loadRecords(path, func() Record { return &ProcedureExecution{} })
	if err != nil {
		return nil, err
	}
	rows := make([]ProcedureExecution, len(records))
	for i, r := range records {
		rows[i] = *r.(*ProcedureExecution)
	}
	return rows, nil
}

// =============================================================================
// STEPEXECUTIONS TABLE
// Concrete executions of specified steps. Maps to pko:StepExecution, hasExecutedStep, includesStepExecution, and nextStepExecution.
// =============================================================================

// StepExecution represents a row in the StepExecutions table
type StepExecution struct {
	StepExecutionId string `json:"step_execution_id"` // Stored logical identifier for one StepExecutions row.
	Name *string `json:"name"` // Human-readable calculated display alias for the StepExecutions row.
	ProcedureExecution *string `json:"procedure_execution"` // Parent procedure execution.
	Step *string `json:"step"` // Specified step executed; maps to pko:hasExecutedStep.
	ExecutedByAgent *string `json:"executed_by_agent"` // Agent executing the step; maps to pko:wasExecutedBy.
	ExecutionStatus *string `json:"execution_status"` // InProgress, Completed, Paused, Cancelled, or Failed.
	StartedAt *string `json:"started_at"` // Execution start.
	EndedAt *string `json:"ended_at"` // Execution end.
	VerificationResult *string `json:"verification_result"` // PASS, WARN, FAIL, or PENDING.
	Deviation *string `json:"deviation"` // Observed deviation from the specification.
	ActualDurationMinutes *int `json:"actual_duration_minutes"` // Observed duration in minutes.
	ExpectedDurationMinutes *int `json:"expected_duration_minutes"` // Expected duration from the specification.
	IsLate *bool `json:"is_late"` // TRUE when actual duration exceeds expected duration.
	BlockingUnmetCount *float64 `json:"blocking_unmet_count"` // How many blocking requirements attached to this step execution are recorded as not fully satisfied.
	BlockingUnmetCountSafe *float64 `json:"blocking_unmet_count_safe"` // Count of blocking-but-unmet requirements on this step execution, computed via the single-criterion key so no criterion is dropped.
	ProceededPastBlockingControl *bool `json:"proceeded_past_blocking_control"` // TRUE when a step execution reached Completed even though a blocking requirement on it was never fully satisfied.
	ExpectedBlockingCount *float64 `json:"expected_blocking_count"` // How many blocking requirements this execution's step was supposed to have evaluated.
	EvaluatedBlockingCount *float64 `json:"evaluated_blocking_count"` // How many blocking requirements actually received a satisfaction record on this step execution, at any level.
	UnevaluatedBlockingCount *float64 `json:"unevaluated_blocking_count"` // Blocking requirements that were bound to this step but never assessed on this execution.
	HasUnevaluatedBlockingControl *bool `json:"has_unevaluated_blocking_control"` // TRUE when at least one blocking control bound to this step was never evaluated on this execution.
	StaleAuthoritativeSourceCount *float64 `json:"stale_authoritative_source_count"` // Number of stale authoritative sources bound to the step this execution ran.
	RanOnStaleAuthoritativeSource *bool `json:"ran_on_stale_authoritative_source"` // TRUE when this execution's step depends on at least one authoritative source that is outside its freshness SLA.
	HasDeviationNote *bool `json:"has_deviation_note"` // TRUE when a human recorded some deviation narrative on this execution.
	IsLateAndUnexplained *bool `json:"is_late_and_unexplained"` // TRUE when the execution exceeded its expected duration and no deviation was recorded.
	AvailableExceptionCountForStep *float64 `json:"available_exception_count_for_step"` // How many active exceptions were available to this execution's step.
	HadUninvokedExceptionAvailable *bool `json:"had_uninvoked_exception_available"` // TRUE when an execution ran long with no explanation despite the specification defining an active exception for exactly that situation.
	ExpectedVerificationCount *float64 `json:"expected_verification_count"` // How many verifications this execution was supposed to perform.
	PerformedVerificationCount *float64 `json:"performed_verification_count"` // How many verification outcomes were actually recorded against this execution.
	SkippedVerificationCount *float64 `json:"skipped_verification_count"` // Declared verifications with no recorded outcome on this execution.
	HasSkippedVerification *bool `json:"has_skipped_verification"` // TRUE when a declared verification was never performed on this execution.
	ClaimsPassWithoutEvidence *bool `json:"claims_pass_without_evidence"` // TRUE when an execution asserts PASS while at least one declared verification has no recorded outcome.
	StepIsPreparation *bool `json:"step_is_preparation"` // Whether this execution ran a preparation step.
	StepIsApproval *bool `json:"step_is_approval"` // Whether this execution ran an approval step.
	PreparerAgentKey *string `json:"preparer_agent_key"` // Composite execution+agent key, emitted only for preparation steps.
	ApproverAgentKey *string `json:"approver_agent_key"` // Composite execution+agent key, emitted only for approval steps.
	PreparedByThisAgentCount *float64 `json:"prepared_by_this_agent_count"` // On an approval row, how many preparation steps in the SAME procedure execution were run by this same agent.
	ViolatesSeparationOfDuties *bool `json:"violates_separation_of_duties"` // TRUE when the agent approving this step also prepared work earlier in the same procedure execution.
	RequiredRoleForStep *string `json:"required_role_for_step"` // The role the specification assigns to this step.
	ExecutorRoleKey *string `json:"executor_role_key"` // The agent+role pair that would need to exist as a valid assignment for this execution to be properly authorized.
	ExecutorAuthorityCount *float64 `json:"executor_authority_count"` // How many currently-valid role assignments grant this executor the role their step required.
	ExecutorHeldRequiredRole *bool `json:"executor_held_required_role"` // TRUE when the executing agent holds a currently-valid assignment to the role the step required.
	IsUnauthorizedApproval *bool `json:"is_unauthorized_approval"` // TRUE when an approval step was executed by an agent who does not hold the required approving role.
	CompletedExecutionKey *string `json:"completed_execution_key"` // Echoes the parent execution id only for completed steps.
	ControlBreachExecutionKey *string `json:"control_breach_execution_key"` // Echoes the parent execution id when this step execution carries ANY control breach.
	LateExecutionKey *string `json:"late_execution_key"` // Echoes the parent execution id only for steps that ran past their expected duration.
	ExecutorAgentKind *string `json:"executor_agent_kind"` // Human, AIAgent, or AutomatedPipeline — what kind of agent actually ran this step.
	ExecutorIsHuman *bool `json:"executor_is_human"` // TRUE when a human executed this step.
	StepRequiresHumanConfirmation *bool `json:"step_requires_human_confirmation"` // Whether the specification requires this step to be human-confirmed.
	NonHumanRanHumanStep *bool `json:"non_human_ran_human_step"` // TRUE when a step requiring human confirmation was executed by an AI agent or automated pipeline.
	NonHumanApproval *bool `json:"non_human_approval"` // TRUE when an approval-authority step was executed by a non-human agent, regardless of the RequiresHumanConfirmation flag.
	UnevaluatedBlockingExecutionKey *string `json:"unevaluated_blocking_execution_key"` // Echoes the parent execution id when this step left a blocking control unevaluated.
	SeparationViolationExecutionKey *string `json:"separation_violation_execution_key"` // Echoes the parent execution id when this step execution violates segregation of duties.
	SelfWitnessedVerificationCount *float64 `json:"self_witnessed_verification_count"` // How many of this execution's verifications were observed by the same agent who ran the step.
	UnbackedVerificationCount *float64 `json:"unbacked_verification_count"` // How many verifications on this execution recorded a matching signal with no retained evidence artifact.
	ApprovalRestsOnSelfAttestation *bool `json:"approval_rests_on_self_attestation"` // TRUE when an approval step's verification was either self-witnessed by the approver or never performed at all.
	ExceptionInvocationCount *float64 `json:"exception_invocation_count"` // How many specified exceptions were invoked during this step execution.
	RanUnderException *bool `json:"ran_under_exception"` // TRUE when this execution invoked at least one specified exception.
	IsCompleted *bool `json:"is_completed"` // TRUE when this step execution reached a completed state.
	IsVerificationPassed *bool `json:"is_verification_passed"` // TRUE only when this step execution's verification actually passed. PENDING and FAIL are both not-passed.
	IsLegalReviewStep *bool `json:"is_legal_review_step"` // TRUE for executions of the legal and privacy review step.
	ClearedLegalReviewKey *string `json:"cleared_legal_review_key"` // Carries the execution id only when this row is a PASSED legal review; empty string otherwise.
	AssignedRole *string `json:"assigned_role"` // The role the specification assigns to this step.
	RoleCurrentAgent *string `json:"role_current_agent"` // The agent currently designated to hold the step's assigned role.
	ExecutorIsDesignatedAgent *bool `json:"executor_is_designated_agent"` // TRUE when the agent that executed the step is the agent currently designated for the step's role.
	InputsWereFreshAtRun *bool `json:"inputs_were_fresh_at_run"` // Freshness verdict for the step this execution ran.
	RanOnStaleInputs *bool `json:"ran_on_stale_inputs"` // TRUE when an execution completed even though its step's authoritative inputs are stale.
	UnresolvedIssueCount *float64 `json:"unresolved_issue_count"` // Number of unresolved issue occurrences recorded against this execution.
	HasDeviation *bool `json:"has_deviation"` // TRUE when a deviation from the specification was recorded.
	IsClean *bool `json:"is_clean"` // TRUE when this execution passed verification, deviated from nothing, left no open issue, and finished on time.
	ProcedureExecutionWhenUnclean *string `json:"procedure_execution_when_unclean"` // Echoes the parent execution id when this step execution is not clean, blank otherwise.
	EvaluatedRequirementCount *float64 `json:"evaluated_requirement_count"` // Number of requirements actually scored against this execution.
	RequiredBlockingCount *int `json:"required_blocking_count"` // Number of blocking requirements the specification demands for this step.
	HasUnevaluatedBlockingRequirement *bool `json:"has_unevaluated_blocking_requirement"` // TRUE when fewer requirements were scored than the step has blocking requirements.
	ExecutingAgentKind *string `json:"executing_agent_kind"` // The kind of agent that actually performed this step execution.
	WasExecutedBySoftware *bool `json:"was_executed_by_software"` // TRUE when software actually performed this step.
	StepIsSoftwareAssigned *bool `json:"step_is_software_assigned"` // Whether the step being executed was specified as a software step.
	SoftwareDidHumanWork *bool `json:"software_did_human_work"` // TRUE when software performed a step the procedure specified for a human.
	IsApprovalExecution *bool `json:"is_approval_execution"` // Whether this execution is of a designated human approval gate.
	IsVerified *bool `json:"is_verified"` // TRUE when this execution recorded a positive verification outcome.
	UnconfirmedNonHumanDecisionCount *float64 `json:"unconfirmed_non_human_decision_count"` // Number of material non-human decisions in this execution that no human confirmed.
	RequiresHumanConfirmation *bool `json:"requires_human_confirmation"` // Whether the specification requires human confirmation for this step.
	HumanConfirmationMissing *bool `json:"human_confirmation_missing"` // TRUE when a step requiring human confirmation contains unconfirmed material non-human decisions.
	DraftedFromUnusableSource *bool `json:"drafted_from_unusable_source"` // TRUE when a drafting execution completed despite an unapproved or stale source at its step.
	InputsWereUsable *bool `json:"inputs_were_usable"` // Source-usability verdict for the step this execution ran.
	SoftwareExecutionStepKey *string `json:"software_execution_step_key"` // Composite-key echo: the step this execution ran when it was carried out by software, blank otherwise.
	StepControlKind *string `json:"step_control_kind"` // The control kind of the step this execution ran.
	UnfalsifiedClearanceCount *float64 `json:"unfalsified_clearance_count"` // How many of this step's blocking clearances came from controls that have never once failed.
	AllClearancesAreUnfalsified *bool `json:"all_clearances_are_unfalsified"` // TRUE when every blocking control evaluated on this step is one that has never returned a negative result.
	StaleAtRunCount *float64 `json:"stale_at_run_count"` // How many authoritative sources this step read that were already out of SLA when it read them.
	WasStaleWhenIRanIt *bool `json:"was_stale_when_i_ran_it"` // TRUE when this execution consumed at least one authoritative source that was stale at the time of reading.
	StalenessAnswerIsTenseDependent *bool `json:"staleness_answer_is_tense_dependent"` // TRUE when the as-of-now staleness verdict disagrees with the as-of-run verdict for the same step.
	HasAnyDeclaredCheck *bool `json:"has_any_declared_check"` // TRUE when the specification declared at least one verification or one blocking requirement for this step.
	PerformedCheckCount *float64 `json:"performed_check_count"` // Total number of checks actually carried out on this execution, verifications plus blocking-control evaluations.
	DeclaredCheckCount *float64 `json:"declared_check_count"` // Total number of checks the specification called for on this step.
	IsUncheckedByDesign *bool `json:"is_unchecked_by_design"` // TRUE when the specification asked for no verification and no blocking control on this step at all.
	IsVacuouslyClean *bool `json:"is_vacuously_clean"` // TRUE when this execution reads clean and nothing was ever declared that could have made it read otherwise.
	IsSubstantivelyClean *bool `json:"is_substantively_clean"` // TRUE when this execution is clean AND every declared check was actually performed.
	VacuouslyCleanExecutionKey *string `json:"vacuously_clean_execution_key"` // Echoes the parent execution id when this step is vacuously clean.
	UncorroboratedPassCount *float64 `json:"uncorroborated_pass_count"` // How many of this step's passing verifications were observed by the executor with no evidence attached.
	EvidencePositionIsWeak *bool `json:"evidence_position_is_weak"` // TRUE when every verification performed on this step was an uncorroborated self-witnessed pass.
	PreparationExecutionKey *string `json:"preparation_execution_key"` // Echoes the parent execution id when this step execution is a preparation step.
	ApprovalExecutionKey *string `json:"approval_execution_key"` // Echoes the parent execution id when this step execution is an approval step.
	HasGoverningInstrument *bool `json:"has_governing_instrument"` // TRUE when this step's departure from spec is covered by an invoked exception or an approved change request against its procedure version.
	HasApprovedChangeCoverage *bool `json:"has_approved_change_coverage"` // Whether the procedure version this step belongs to has an approved change request that could account for a departure.
	VersionOfStep *string `json:"version_of_step"` // The procedure version this step execution's specification step belongs to.
	IsUngovernedDivergence *bool `json:"is_ungoverned_divergence"` // TRUE when this step departed from specification and no exception or approved change covers it.
	UngovernedDivergenceExecutionKey *string `json:"ungoverned_divergence_execution_key"` // Echoes the parent execution id when this step diverged without governance.
	SelfAttestedApprovalExecutionKey *string `json:"self_attested_approval_execution_key"` // Echoes the parent execution id when this approval rested on self-attestation.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact PKO class IRI.
	PreviousStepExecution *string `json:"previous_step_execution"` // Step execution that ran immediately before (pko:previousStepExecution).
	ConfirmedByAgent *string `json:"confirmed_by_agent"` // Who confirmed the step (pko:wasConfirmedBy).
	Description *string `json:"description"` // What happened during the step (dct:description).
	PreviousExecutedStep *string `json:"previous_executed_step"` // Step the previous step execution ran.
	SpecifiedTransitionFromPreviousCount *int `json:"specified_transition_from_previous_count"` // Transitions the specification allows from the previous step to this one.
	IsOutOfSpecifiedOrder *bool `json:"is_out_of_specified_order"` // TRUE when a step ran straight after a step the specification does not let lead to it.
	ExecutionVersion *string `json:"execution_version"` // Version the parent procedure execution enacts.
	ExecutesStepOfOtherVersion *bool `json:"executes_step_of_other_version"` // TRUE when a step execution records a step from a different specification than the one its procedure execution enacts.
	RepetitionCount *int `json:"repetition_count"` // Times this step ran within the same procedure execution.
	StepMaxRepetitions *int `json:"step_max_repetitions"` // Maximum repetitions the specification allows.
	ExceedsMaxRepetitions *bool `json:"exceeds_max_repetitions"` // TRUE when a step ran more often in one execution than its specification allows.
	LacksRequiredConfirmation *bool `json:"lacks_required_confirmation"` // TRUE when a step that requires human confirmation completed with nobody recorded as confirming it.
	FailedPreconditionCount *int `json:"failed_precondition_count"` // Preconditions that did not hold.
	ViolatedInvariantCount *int `json:"violated_invariant_count"` // Invariants that did not hold.
	ProceededDespiteFailedPrecondition *bool `json:"proceeded_despite_failed_precondition"` // TRUE when a step completed although one of its preconditions was checked and did not hold.
	UnescalatedDangerCueCount *int `json:"unescalated_danger_cue_count"` // Danger cues seen and not escalated.
	IgnoredDangerCue *bool `json:"ignored_danger_cue"` // TRUE when a danger cue was observed during the step and nobody escalated it.
	UsedEntityCount *int `json:"used_entity_count"` // Entities used.
	GeneratedEntityCount *int `json:"generated_entity_count"` // Entities generated.
	StepInputVariableCount *int `json:"step_input_variable_count"` // Inputs the step declares.
	RanWithoutDeclaredInputs *bool `json:"ran_without_declared_inputs"` // TRUE when a completed step declares inputs but its execution records none of them being used.
	StepPrerequisite *string `json:"step_prerequisite"` // Step the specification requires to be complete first.
	CompletedPrerequisiteRunCount *int `json:"completed_prerequisite_run_count"` // Completed executions of that prerequisite step in the same procedure execution.
	RanBeforePrerequisiteCompleted *bool `json:"ran_before_prerequisite_completed"` // TRUE when a step ran in an execution where its declared prerequisite never completed.
	DeviationExecutionKey *string `json:"deviation_execution_key"` // Procedure execution key when the step deviated.
	BrokeInvariant *bool `json:"broke_invariant"` // TRUE when an invariant did not hold during the step.
	IsBlockedByIncompletePrerequisite *bool `json:"is_blocked_by_incomplete_prerequisite"` // TRUE for an unfinished step whose prerequisite has not completed in the same execution.
	OwnerOrganization *string `json:"owner_organization"` // The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
	IncompleteCueObservationCount *int `json:"incomplete_cue_observation_count"` // Warning signs observed on this step execution that mean the step is not finished.
	IsBlockedByObservedCue *bool `json:"is_blocked_by_observed_cue"` // A warning sign that means 'not finished' was seen on this step execution, so the normal next step must not be offered; only a fallback is.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the StepExecutions row.
// Formula: ={{ProcedureExecution}} & " / " & {{Step}}
func (tc *StepExecution) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ProcedureExecution)), vS(" / "), erbText(vStr(tc.Step))))
}

// CalcActualDurationMinutes computes the ActualDurationMinutes calculated field
// Observed duration in minutes.
// Formula: =IF({{EndedAt}} = "", 0, DATETIME_DIFF({{EndedAt}}, {{StartedAt}}, "minutes"))
func (tc *StepExecution) CalcActualDurationMinutes() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.EndedAt))), func() Value { return vI(0) }, func() Value { return erbDatetimeDiff(vStr(tc.EndedAt), vStr(tc.StartedAt), vS("minutes")) })))
}

// CalcIsLate computes the IsLate calculated field
// TRUE when actual duration exceeds expected duration.
// Formula: ={{ActualDurationMinutes}} > {{ExpectedDurationMinutes}}
func (tc *StepExecution) CalcIsLate() *bool {
	return toBoolPtr(erbCmp(vInt(tc.ActualDurationMinutes), ">", vInt(tc.ExpectedDurationMinutes)))
}

// CalcProceededPastBlockingControl computes the ProceededPastBlockingControl calculated field
// TRUE when a step execution reached Completed even though a blocking requirement on it was never fully satisfied.
// Formula: =AND({{ExecutionStatus}} = "Completed", {{BlockingUnmetCountSafe}} > 0)
func (tc *StepExecution) CalcProceededPastBlockingControl() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed"))), erbBool3(erbCmp(vNum(tc.BlockingUnmetCountSafe), ">", vI(0)))))
}

// CalcUnevaluatedBlockingCount computes the UnevaluatedBlockingCount calculated field
// Blocking requirements that were bound to this step but never assessed on this execution.
// Formula: ={{ExpectedBlockingCount}} - {{EvaluatedBlockingCount}}
func (tc *StepExecution) CalcUnevaluatedBlockingCount() *float64 {
	return toFloatPtr(erbSub(vNum(tc.ExpectedBlockingCount), vNum(tc.EvaluatedBlockingCount)))
}

// CalcHasUnevaluatedBlockingControl computes the HasUnevaluatedBlockingControl calculated field
// TRUE when at least one blocking control bound to this step was never evaluated on this execution.
// Formula: ={{UnevaluatedBlockingCount}} > 0
func (tc *StepExecution) CalcHasUnevaluatedBlockingControl() *bool {
	return toBoolPtr(erbCmp(vNum(tc.UnevaluatedBlockingCount), ">", vI(0)))
}

// CalcRanOnStaleAuthoritativeSource computes the RanOnStaleAuthoritativeSource calculated field
// TRUE when this execution's step depends on at least one authoritative source that is outside its freshness SLA.
// Formula: ={{StaleAuthoritativeSourceCount}} > 0
func (tc *StepExecution) CalcRanOnStaleAuthoritativeSource() *bool {
	return toBoolPtr(erbCmp(vNum(tc.StaleAuthoritativeSourceCount), ">", vI(0)))
}

// CalcHasDeviationNote computes the HasDeviationNote calculated field
// TRUE when a human recorded some deviation narrative on this execution.
// Formula: ={{Deviation}} <> ""
func (tc *StepExecution) CalcHasDeviationNote() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.Deviation)))
}

// CalcIsLateAndUnexplained computes the IsLateAndUnexplained calculated field
// TRUE when the execution exceeded its expected duration and no deviation was recorded.
// Formula: =AND({{IsLate}}, NOT({{HasDeviationNote}}))
func (tc *StepExecution) CalcIsLateAndUnexplained() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsLate)), erbBool3(erbNot(erbBool3(vBool(tc.HasDeviationNote))))))
}

// CalcHadUninvokedExceptionAvailable computes the HadUninvokedExceptionAvailable calculated field
// TRUE when an execution ran long with no explanation despite the specification defining an active exception for exactly that situation.
// Formula: =AND({{IsLateAndUnexplained}}, {{AvailableExceptionCountForStep}} > 0)
func (tc *StepExecution) CalcHadUninvokedExceptionAvailable() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsLateAndUnexplained)), erbBool3(erbCmp(vNum(tc.AvailableExceptionCountForStep), ">", vI(0)))))
}

// CalcSkippedVerificationCount computes the SkippedVerificationCount calculated field
// Declared verifications with no recorded outcome on this execution.
// Formula: ={{ExpectedVerificationCount}} - {{PerformedVerificationCount}}
func (tc *StepExecution) CalcSkippedVerificationCount() *float64 {
	return toFloatPtr(erbSub(vNum(tc.ExpectedVerificationCount), vNum(tc.PerformedVerificationCount)))
}

// CalcHasSkippedVerification computes the HasSkippedVerification calculated field
// TRUE when a declared verification was never performed on this execution.
// Formula: ={{SkippedVerificationCount}} > 0
func (tc *StepExecution) CalcHasSkippedVerification() *bool {
	return toBoolPtr(erbCmp(vNum(tc.SkippedVerificationCount), ">", vI(0)))
}

// CalcClaimsPassWithoutEvidence computes the ClaimsPassWithoutEvidence calculated field
// TRUE when an execution asserts PASS while at least one declared verification has no recorded outcome.
// Formula: =AND({{VerificationResult}} = "PASS", {{HasSkippedVerification}})
func (tc *StepExecution) CalcClaimsPassWithoutEvidence() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.VerificationResult)), vS("PASS"))), erbBool3(vBool(tc.HasSkippedVerification))))
}

// CalcPreparerAgentKey computes the PreparerAgentKey calculated field
// Composite execution+agent key, emitted only for preparation steps.
// Formula: =IF({{StepIsPreparation}}, {{ProcedureExecution}} & "|" & {{ExecutedByAgent}}, "")
func (tc *StepExecution) CalcPreparerAgentKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.StepIsPreparation)), func() Value { return erbConcat(erbText(vStr(tc.ProcedureExecution)), vS("|"), erbText(vStr(tc.ExecutedByAgent))) }, func() Value { return vS("") }))
}

// CalcApproverAgentKey computes the ApproverAgentKey calculated field
// Composite execution+agent key, emitted only for approval steps.
// Formula: =IF({{StepIsApproval}}, {{ProcedureExecution}} & "|" & {{ExecutedByAgent}}, "")
func (tc *StepExecution) CalcApproverAgentKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.StepIsApproval)), func() Value { return erbConcat(erbText(vStr(tc.ProcedureExecution)), vS("|"), erbText(vStr(tc.ExecutedByAgent))) }, func() Value { return vS("") }))
}

// CalcViolatesSeparationOfDuties computes the ViolatesSeparationOfDuties calculated field
// TRUE when the agent approving this step also prepared work earlier in the same procedure execution.
// Formula: =AND({{StepIsApproval}}, {{PreparedByThisAgentCount}} > 0)
func (tc *StepExecution) CalcViolatesSeparationOfDuties() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.StepIsApproval)), erbBool3(erbCmp(vNum(tc.PreparedByThisAgentCount), ">", vI(0)))))
}

// CalcExecutorRoleKey computes the ExecutorRoleKey calculated field
// The agent+role pair that would need to exist as a valid assignment for this execution to be properly authorized.
// Formula: ={{ExecutedByAgent}} & "|" & {{RequiredRoleForStep}}
func (tc *StepExecution) CalcExecutorRoleKey() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ExecutedByAgent)), vS("|"), erbText(vStr(tc.RequiredRoleForStep))))
}

// CalcExecutorHeldRequiredRole computes the ExecutorHeldRequiredRole calculated field
// TRUE when the executing agent holds a currently-valid assignment to the role the step required.
// Formula: ={{ExecutorAuthorityCount}} > 0
func (tc *StepExecution) CalcExecutorHeldRequiredRole() *bool {
	return toBoolPtr(erbCmp(vNum(tc.ExecutorAuthorityCount), ">", vI(0)))
}

// CalcIsUnauthorizedApproval computes the IsUnauthorizedApproval calculated field
// TRUE when an approval step was executed by an agent who does not hold the required approving role.
// Formula: =AND({{StepIsApproval}}, NOT({{ExecutorHeldRequiredRole}}))
func (tc *StepExecution) CalcIsUnauthorizedApproval() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.StepIsApproval)), erbBool3(erbNot(erbBool3(vBool(tc.ExecutorHeldRequiredRole))))))
}

// CalcCompletedExecutionKey computes the CompletedExecutionKey calculated field
// Echoes the parent execution id only for completed steps.
// Formula: =IF({{ExecutionStatus}} = "Completed", {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcCompletedExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed"))), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcControlBreachExecutionKey computes the ControlBreachExecutionKey calculated field
// Echoes the parent execution id when this step execution carries ANY control breach.
// Formula: =IF(OR({{ProceededPastBlockingControl}}, {{ViolatesSeparationOfDuties}}, {{IsUnauthorizedApproval}}, {{ClaimsPassWithoutEvidence}}), {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcControlBreachExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(erbOr(erbBool3(vBool(tc.ProceededPastBlockingControl)), erbBool3(vBool(tc.ViolatesSeparationOfDuties)), erbBool3(vBool(tc.IsUnauthorizedApproval)), erbBool3(vBool(tc.ClaimsPassWithoutEvidence)))), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcLateExecutionKey computes the LateExecutionKey calculated field
// Echoes the parent execution id only for steps that ran past their expected duration.
// Formula: =IF({{IsLate}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcLateExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsLate)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcExecutorIsHuman computes the ExecutorIsHuman calculated field
// TRUE when a human executed this step.
// Formula: ={{ExecutorAgentKind}} = "Human"
func (tc *StepExecution) CalcExecutorIsHuman() *bool {
	return toBoolPtr(erbEq(vStr(tc.ExecutorAgentKind), vS("Human")))
}

// CalcNonHumanRanHumanStep computes the NonHumanRanHumanStep calculated field
// TRUE when a step requiring human confirmation was executed by an AI agent or automated pipeline.
// Formula: =AND({{StepRequiresHumanConfirmation}}, NOT({{ExecutorIsHuman}}))
func (tc *StepExecution) CalcNonHumanRanHumanStep() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.StepRequiresHumanConfirmation)), erbBool3(erbNot(erbBool3(vBool(tc.ExecutorIsHuman))))))
}

// CalcNonHumanApproval computes the NonHumanApproval calculated field
// TRUE when an approval-authority step was executed by a non-human agent, regardless of the RequiresHumanConfirmation flag.
// Formula: =AND({{StepIsApproval}}, NOT({{ExecutorIsHuman}}))
func (tc *StepExecution) CalcNonHumanApproval() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.StepIsApproval)), erbBool3(erbNot(erbBool3(vBool(tc.ExecutorIsHuman))))))
}

// CalcUnevaluatedBlockingExecutionKey computes the UnevaluatedBlockingExecutionKey calculated field
// Echoes the parent execution id when this step left a blocking control unevaluated.
// Formula: =IF({{HasUnevaluatedBlockingControl}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcUnevaluatedBlockingExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.HasUnevaluatedBlockingControl)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcSeparationViolationExecutionKey computes the SeparationViolationExecutionKey calculated field
// Echoes the parent execution id when this step execution violates segregation of duties.
// Formula: =IF({{ViolatesSeparationOfDuties}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcSeparationViolationExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.ViolatesSeparationOfDuties)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcApprovalRestsOnSelfAttestation computes the ApprovalRestsOnSelfAttestation calculated field
// TRUE when an approval step's verification was either self-witnessed by the approver or never performed at all.
// Formula: =AND({{StepIsApproval}}, OR({{SelfWitnessedVerificationCount}} > 0, {{HasSkippedVerification}}))
func (tc *StepExecution) CalcApprovalRestsOnSelfAttestation() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.StepIsApproval)), erbBool3(erbOr(erbBool3(erbCmp(vNum(tc.SelfWitnessedVerificationCount), ">", vI(0))), erbBool3(vBool(tc.HasSkippedVerification))))))
}

// CalcRanUnderException computes the RanUnderException calculated field
// TRUE when this execution invoked at least one specified exception.
// Formula: ={{ExceptionInvocationCount}} > 0
func (tc *StepExecution) CalcRanUnderException() *bool {
	return toBoolPtr(erbCmp(vNum(tc.ExceptionInvocationCount), ">", vI(0)))
}

// CalcIsCompleted computes the IsCompleted calculated field
// TRUE when this step execution reached a completed state.
// Formula: ={{ExecutionStatus}} = "Completed"
func (tc *StepExecution) CalcIsCompleted() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed")))
}

// CalcIsVerificationPassed computes the IsVerificationPassed calculated field
// TRUE only when this step execution's verification actually passed. PENDING and FAIL are both not-passed.
// Formula: ={{VerificationResult}} = "PASS"
func (tc *StepExecution) CalcIsVerificationPassed() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.VerificationResult)), vS("PASS")))
}

// CalcIsLegalReviewStep computes the IsLegalReviewStep calculated field
// TRUE for executions of the legal and privacy review step.
// Formula: ={{Step}} = "policy-04"
func (tc *StepExecution) CalcIsLegalReviewStep() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.Step)), vS("policy-04")))
}

// CalcClearedLegalReviewKey computes the ClearedLegalReviewKey calculated field
// Carries the execution id only when this row is a PASSED legal review; empty string otherwise.
// Formula: =IF(AND({{IsLegalReviewStep}}, {{IsVerificationPassed}}), {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcClearedLegalReviewKey() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(vBool(tc.IsLegalReviewStep)), erbBool3(vBool(tc.IsVerificationPassed)))), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcExecutorIsDesignatedAgent computes the ExecutorIsDesignatedAgent calculated field
// TRUE when the agent that executed the step is the agent currently designated for the step's role.
// Formula: ={{ExecutedByAgent}} = {{RoleCurrentAgent}}
func (tc *StepExecution) CalcExecutorIsDesignatedAgent() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.ExecutedByAgent)), vStr(tc.RoleCurrentAgent)))
}

// CalcRanOnStaleInputs computes the RanOnStaleInputs calculated field
// TRUE when an execution completed even though its step's authoritative inputs are stale.
// Formula: =AND({{ExecutionStatus}} = "Completed", NOT({{InputsWereFreshAtRun}}))
func (tc *StepExecution) CalcRanOnStaleInputs() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed"))), erbBool3(erbNot(erbBool3(vBool(tc.InputsWereFreshAtRun))))))
}

// CalcHasDeviation computes the HasDeviation calculated field
// TRUE when a deviation from the specification was recorded.
// Formula: ={{Deviation}} <> ""
func (tc *StepExecution) CalcHasDeviation() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.Deviation)))
}

// CalcIsClean computes the IsClean calculated field
// TRUE when this execution passed verification, deviated from nothing, left no open issue, and finished on time.
// Formula: =AND({{VerificationResult}} = "PASS", NOT({{HasDeviation}}), {{UnresolvedIssueCount}} = 0, NOT({{IsLate}}))
func (tc *StepExecution) CalcIsClean() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.VerificationResult)), vS("PASS"))), erbBool3(erbNot(erbBool3(vBool(tc.HasDeviation)))), erbBool3(erbEq(vNum(tc.UnresolvedIssueCount), vI(0))), erbBool3(erbNot(erbBool3(vBool(tc.IsLate))))))
}

// CalcProcedureExecutionWhenUnclean computes the ProcedureExecutionWhenUnclean calculated field
// Echoes the parent execution id when this step execution is not clean, blank otherwise.
// Formula: =IF({{IsClean}}, "", {{ProcedureExecution}})
func (tc *StepExecution) CalcProcedureExecutionWhenUnclean() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsClean)), func() Value { return vS("") }, func() Value { return vStr(tc.ProcedureExecution) }))
}

// CalcHasUnevaluatedBlockingRequirement computes the HasUnevaluatedBlockingRequirement calculated field
// TRUE when fewer requirements were scored than the step has blocking requirements.
// Formula: ={{EvaluatedRequirementCount}} < {{RequiredBlockingCount}}
func (tc *StepExecution) CalcHasUnevaluatedBlockingRequirement() *bool {
	return toBoolPtr(erbCmp(vNum(tc.EvaluatedRequirementCount), "<", vInt(tc.RequiredBlockingCount)))
}

// CalcWasExecutedBySoftware computes the WasExecutedBySoftware calculated field
// TRUE when software actually performed this step.
// Formula: =OR({{ExecutingAgentKind}} = "AIAgent", {{ExecutingAgentKind}} = "AutomatedPipeline")
func (tc *StepExecution) CalcWasExecutedBySoftware() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(vStr(tc.ExecutingAgentKind), vS("AIAgent"))), erbBool3(erbEq(vStr(tc.ExecutingAgentKind), vS("AutomatedPipeline")))))
}

// CalcSoftwareDidHumanWork computes the SoftwareDidHumanWork calculated field
// TRUE when software performed a step the procedure specified for a human.
// Formula: =AND({{WasExecutedBySoftware}}, NOT({{StepIsSoftwareAssigned}}))
func (tc *StepExecution) CalcSoftwareDidHumanWork() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.WasExecutedBySoftware)), erbBool3(erbNot(erbBool3(vBool(tc.StepIsSoftwareAssigned))))))
}

// CalcIsVerified computes the IsVerified calculated field
// TRUE when this execution recorded a positive verification outcome.
// Formula: =AND({{VerificationResult}} <> "", {{VerificationResult}} <> "PENDING", {{VerificationResult}} <> "FAIL")
func (tc *StepExecution) CalcIsVerified() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.VerificationResult))), erbBool3(erbNe(erbNullif(vStr(tc.VerificationResult)), vS("PENDING"))), erbBool3(erbNe(erbNullif(vStr(tc.VerificationResult)), vS("FAIL")))))
}

// CalcHumanConfirmationMissing computes the HumanConfirmationMissing calculated field
// TRUE when a step requiring human confirmation contains unconfirmed material non-human decisions.
// Formula: =AND({{RequiresHumanConfirmation}}, {{UnconfirmedNonHumanDecisionCount}} > 0)
func (tc *StepExecution) CalcHumanConfirmationMissing() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RequiresHumanConfirmation)), erbBool3(erbCmp(vNum(tc.UnconfirmedNonHumanDecisionCount), ">", vI(0)))))
}

// CalcDraftedFromUnusableSource computes the DraftedFromUnusableSource calculated field
// TRUE when a drafting execution completed despite an unapproved or stale source at its step.
// Formula: =AND({{ExecutionStatus}} = "Completed", NOT({{InputsWereUsable}}))
func (tc *StepExecution) CalcDraftedFromUnusableSource() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed"))), erbBool3(erbNot(erbBool3(vBool(tc.InputsWereUsable))))))
}

// CalcSoftwareExecutionStepKey computes the SoftwareExecutionStepKey calculated field
// Composite-key echo: the step this execution ran when it was carried out by software, blank otherwise.
// Formula: =IF({{WasExecutedBySoftware}}, {{Step}}, "")
func (tc *StepExecution) CalcSoftwareExecutionStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.WasExecutedBySoftware)), func() Value { return vStr(tc.Step) }, func() Value { return vS("") }))
}

// CalcAllClearancesAreUnfalsified computes the AllClearancesAreUnfalsified calculated field
// TRUE when every blocking control evaluated on this step is one that has never returned a negative result.
// Formula: =AND({{EvaluatedBlockingCount}} > 0, {{UnfalsifiedClearanceCount}} >= {{EvaluatedBlockingCount}})
func (tc *StepExecution) CalcAllClearancesAreUnfalsified() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vNum(tc.EvaluatedBlockingCount), ">", vI(0))), erbBool3(erbCmp(vNum(tc.UnfalsifiedClearanceCount), ">=", vNum(tc.EvaluatedBlockingCount)))))
}

// CalcWasStaleWhenIRanIt computes the WasStaleWhenIRanIt calculated field
// TRUE when this execution consumed at least one authoritative source that was stale at the time of reading.
// Formula: ={{StaleAtRunCount}} > 0
func (tc *StepExecution) CalcWasStaleWhenIRanIt() *bool {
	return toBoolPtr(erbCmp(vNum(tc.StaleAtRunCount), ">", vI(0)))
}

// CalcStalenessAnswerIsTenseDependent computes the StalenessAnswerIsTenseDependent calculated field
// TRUE when the as-of-now staleness verdict disagrees with the as-of-run verdict for the same step.
// Formula: =NOT({{WasStaleWhenIRanIt}} = {{RanOnStaleAuthoritativeSource}})
func (tc *StepExecution) CalcStalenessAnswerIsTenseDependent() *bool {
	return toBoolPtr(erbNot(erbBool3(erbEq(vBool(tc.WasStaleWhenIRanIt), vBool(tc.RanOnStaleAuthoritativeSource)))))
}

// CalcHasAnyDeclaredCheck computes the HasAnyDeclaredCheck calculated field
// TRUE when the specification declared at least one verification or one blocking requirement for this step.
// Formula: =OR({{ExpectedVerificationCount}} > 0, {{ExpectedBlockingCount}} > 0)
func (tc *StepExecution) CalcHasAnyDeclaredCheck() *bool {
	return toBoolPtr(erbOr(erbBool3(erbCmp(vNum(tc.ExpectedVerificationCount), ">", vI(0))), erbBool3(erbCmp(vNum(tc.ExpectedBlockingCount), ">", vI(0)))))
}

// CalcPerformedCheckCount computes the PerformedCheckCount calculated field
// Total number of checks actually carried out on this execution, verifications plus blocking-control evaluations.
// Formula: ={{PerformedVerificationCount}} + {{EvaluatedBlockingCount}}
func (tc *StepExecution) CalcPerformedCheckCount() *float64 {
	return toFloatPtr(erbAdd(vNum(tc.PerformedVerificationCount), vNum(tc.EvaluatedBlockingCount)))
}

// CalcDeclaredCheckCount computes the DeclaredCheckCount calculated field
// Total number of checks the specification called for on this step.
// Formula: ={{ExpectedVerificationCount}} + {{ExpectedBlockingCount}}
func (tc *StepExecution) CalcDeclaredCheckCount() *float64 {
	return toFloatPtr(erbAdd(vNum(tc.ExpectedVerificationCount), vNum(tc.ExpectedBlockingCount)))
}

// CalcIsUncheckedByDesign computes the IsUncheckedByDesign calculated field
// TRUE when the specification asked for no verification and no blocking control on this step at all.
// Formula: ={{DeclaredCheckCount}} = 0
func (tc *StepExecution) CalcIsUncheckedByDesign() *bool {
	return toBoolPtr(erbEq(vNum(tc.DeclaredCheckCount), vI(0)))
}

// CalcIsVacuouslyClean computes the IsVacuouslyClean calculated field
// TRUE when this execution reads clean and nothing was ever declared that could have made it read otherwise.
// Formula: =AND({{IsClean}}, {{IsUncheckedByDesign}})
func (tc *StepExecution) CalcIsVacuouslyClean() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsClean)), erbBool3(vBool(tc.IsUncheckedByDesign))))
}

// CalcIsSubstantivelyClean computes the IsSubstantivelyClean calculated field
// TRUE when this execution is clean AND every declared check was actually performed.
// Formula: =AND({{IsClean}}, {{PerformedCheckCount}} >= {{DeclaredCheckCount}}, {{DeclaredCheckCount}} > 0)
func (tc *StepExecution) CalcIsSubstantivelyClean() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsClean)), erbBool3(erbCmp(vNum(tc.PerformedCheckCount), ">=", vNum(tc.DeclaredCheckCount))), erbBool3(erbCmp(vNum(tc.DeclaredCheckCount), ">", vI(0)))))
}

// CalcVacuouslyCleanExecutionKey computes the VacuouslyCleanExecutionKey calculated field
// Echoes the parent execution id when this step is vacuously clean.
// Formula: =IF({{IsVacuouslyClean}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcVacuouslyCleanExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsVacuouslyClean)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcEvidencePositionIsWeak computes the EvidencePositionIsWeak calculated field
// TRUE when every verification performed on this step was an uncorroborated self-witnessed pass.
// Formula: =AND({{PerformedVerificationCount}} > 0, {{UncorroboratedPassCount}} >= {{PerformedVerificationCount}})
func (tc *StepExecution) CalcEvidencePositionIsWeak() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vNum(tc.PerformedVerificationCount), ">", vI(0))), erbBool3(erbCmp(vNum(tc.UncorroboratedPassCount), ">=", vNum(tc.PerformedVerificationCount)))))
}

// CalcPreparationExecutionKey computes the PreparationExecutionKey calculated field
// Echoes the parent execution id when this step execution is a preparation step.
// Formula: =IF({{StepIsPreparation}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcPreparationExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.StepIsPreparation)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcApprovalExecutionKey computes the ApprovalExecutionKey calculated field
// Echoes the parent execution id when this step execution is an approval step.
// Formula: =IF({{StepIsApproval}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcApprovalExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.StepIsApproval)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcHasGoverningInstrument computes the HasGoverningInstrument calculated field
// TRUE when this step's departure from spec is covered by an invoked exception or an approved change request against its procedure version.
// Formula: =OR({{RanUnderException}}, {{HasApprovedChangeCoverage}})
func (tc *StepExecution) CalcHasGoverningInstrument() *bool {
	return toBoolPtr(erbOr(erbBool3(vBool(tc.RanUnderException)), erbBool3(vBool(tc.HasApprovedChangeCoverage))))
}

// CalcIsUngovernedDivergence computes the IsUngovernedDivergence calculated field
// TRUE when this step departed from specification and no exception or approved change covers it.
// Formula: =AND(OR({{HasDeviation}}, {{IsLate}}, {{ProceededPastBlockingControl}}), NOT({{HasGoverningInstrument}}))
func (tc *StepExecution) CalcIsUngovernedDivergence() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(vBool(tc.HasDeviation)), erbBool3(vBool(tc.IsLate)), erbBool3(vBool(tc.ProceededPastBlockingControl)))), erbBool3(erbNot(erbBool3(vBool(tc.HasGoverningInstrument))))))
}

// CalcUngovernedDivergenceExecutionKey computes the UngovernedDivergenceExecutionKey calculated field
// Echoes the parent execution id when this step diverged without governance.
// Formula: =IF({{IsUngovernedDivergence}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcUngovernedDivergenceExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUngovernedDivergence)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcSelfAttestedApprovalExecutionKey computes the SelfAttestedApprovalExecutionKey calculated field
// Echoes the parent execution id when this approval rested on self-attestation.
// Formula: =IF({{ApprovalRestsOnSelfAttestation}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcSelfAttestedApprovalExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.ApprovalRestsOnSelfAttestation)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcIsOutOfSpecifiedOrder computes the IsOutOfSpecifiedOrder calculated field
// TRUE when a step ran straight after a step the specification does not let lead to it.
// Formula: =AND({{PreviousStepExecution}} <> "", {{SpecifiedTransitionFromPreviousCount}} = 0)
func (tc *StepExecution) CalcIsOutOfSpecifiedOrder() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.PreviousStepExecution))), erbBool3(erbEq(vInt(tc.SpecifiedTransitionFromPreviousCount), vI(0)))))
}

// CalcExecutesStepOfOtherVersion computes the ExecutesStepOfOtherVersion calculated field
// TRUE when a step execution records a step from a different specification than the one its procedure execution enacts.
// Formula: ={{VersionOfStep}} <> {{ExecutionVersion}}
func (tc *StepExecution) CalcExecutesStepOfOtherVersion() *bool {
	return toBoolPtr(erbNe(vStr(tc.VersionOfStep), vStr(tc.ExecutionVersion)))
}

// CalcExceedsMaxRepetitions computes the ExceedsMaxRepetitions calculated field
// TRUE when a step ran more often in one execution than its specification allows.
// Formula: =AND({{StepMaxRepetitions}} > 0, {{RepetitionCount}} > {{StepMaxRepetitions}})
func (tc *StepExecution) CalcExceedsMaxRepetitions() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.StepMaxRepetitions), ">", vI(0))), erbBool3(erbCmp(vInt(tc.RepetitionCount), ">", vInt(tc.StepMaxRepetitions)))))
}

// CalcLacksRequiredConfirmation computes the LacksRequiredConfirmation calculated field
// TRUE when a step that requires human confirmation completed with nobody recorded as confirming it.
// Formula: =AND({{StepRequiresHumanConfirmation}}, {{IsCompleted}}, {{ConfirmedByAgent}} = "")
func (tc *StepExecution) CalcLacksRequiredConfirmation() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.StepRequiresHumanConfirmation)), erbBool3(vBool(tc.IsCompleted)), erbBool3(erbIsBlank(vStr(tc.ConfirmedByAgent)))))
}

// CalcProceededDespiteFailedPrecondition computes the ProceededDespiteFailedPrecondition calculated field
// TRUE when a step completed although one of its preconditions was checked and did not hold.
// Formula: =AND({{FailedPreconditionCount}} > 0, {{IsCompleted}})
func (tc *StepExecution) CalcProceededDespiteFailedPrecondition() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.FailedPreconditionCount), ">", vI(0))), erbBool3(vBool(tc.IsCompleted))))
}

// CalcIgnoredDangerCue computes the IgnoredDangerCue calculated field
// TRUE when a danger cue was observed during the step and nobody escalated it.
// Formula: ={{UnescalatedDangerCueCount}} > 0
func (tc *StepExecution) CalcIgnoredDangerCue() *bool {
	return toBoolPtr(erbCmp(vInt(tc.UnescalatedDangerCueCount), ">", vI(0)))
}

// CalcRanWithoutDeclaredInputs computes the RanWithoutDeclaredInputs calculated field
// TRUE when a completed step declares inputs but its execution records none of them being used.
// Formula: =AND({{IsCompleted}}, {{StepInputVariableCount}} > 0, {{UsedEntityCount}} = 0)
func (tc *StepExecution) CalcRanWithoutDeclaredInputs() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsCompleted)), erbBool3(erbCmp(vInt(tc.StepInputVariableCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.UsedEntityCount), vI(0)))))
}

// CalcRanBeforePrerequisiteCompleted computes the RanBeforePrerequisiteCompleted calculated field
// TRUE when a step ran in an execution where its declared prerequisite never completed.
// Formula: =AND({{StepPrerequisite}} <> "", {{CompletedPrerequisiteRunCount}} = 0)
func (tc *StepExecution) CalcRanBeforePrerequisiteCompleted() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.StepPrerequisite))), erbBool3(erbEq(vInt(tc.CompletedPrerequisiteRunCount), vI(0)))))
}

// CalcDeviationExecutionKey computes the DeviationExecutionKey calculated field
// Procedure execution key when the step deviated.
// Formula: =IF({{HasDeviation}}, {{ProcedureExecution}}, "")
func (tc *StepExecution) CalcDeviationExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.HasDeviation)), func() Value { return vStr(tc.ProcedureExecution) }, func() Value { return vS("") }))
}

// CalcBrokeInvariant computes the BrokeInvariant calculated field
// TRUE when an invariant did not hold during the step.
// Formula: ={{ViolatedInvariantCount}} > 0
func (tc *StepExecution) CalcBrokeInvariant() *bool {
	return toBoolPtr(erbCmp(vInt(tc.ViolatedInvariantCount), ">", vI(0)))
}

// CalcIsBlockedByIncompletePrerequisite computes the IsBlockedByIncompletePrerequisite calculated field
// TRUE for an unfinished step whose prerequisite has not completed in the same execution.
// Formula: =AND({{StepPrerequisite}} <> "", {{CompletedPrerequisiteRunCount}} = 0, {{ExecutionStatus}} <> "Completed")
func (tc *StepExecution) CalcIsBlockedByIncompletePrerequisite() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.StepPrerequisite))), erbBool3(erbEq(vInt(tc.CompletedPrerequisiteRunCount), vI(0))), erbBool3(erbNe(erbNullif(vStr(tc.ExecutionStatus)), vS("Completed")))))
}

// CalcIsBlockedByObservedCue computes the IsBlockedByObservedCue calculated field
// A warning sign that means 'not finished' was seen on this step execution, so the normal next step must not be offered; only a fallback is.
// Formula: ={{IncompleteCueObservationCount}} > 0
func (tc *StepExecution) CalcIsBlockedByObservedCue() *bool {
	return toBoolPtr(erbCmp(vInt(tc.IncompleteCueObservationCount), ">", vI(0)))
}

