	calcGuard(tc, "declared_check_count", func() { tc.DeclaredCheckCount = tc.CalcDeclaredCheckCount() })
	calcGuard(tc, "evidence_position_is_weak", func() { tc.EvidencePositionIsWeak = tc.CalcEvidencePositionIsWeak() })
