// ISSUEOCCURRENCES TABLE
// Concrete issue events during execution. Maps to pko:IssueOccurrence, hasEncounteredError, wasEncounteredBy, issueCause, and issueSolution.
// =============================================================================

// IssueOccurrence represents a row in the IssueOccurrences table
type IssueOccurrence struct {
	IssueOccurrenceId string `json:"issue_occurrence_id"` // Stored logical identifier for one IssueOccurrences row.
	Name *string `json:"name"` // Human-readable calculated display alias for the IssueOccurrences row.
	StepExecution *string `json:"step_execution"` // Step execution during which the issue occurred.
	Error *string `json:"error"` // Error encountered.
	EncounteredByAgent *string `json:"encountered_by_agent"` // Agent that encountered or reported the issue.
	OccurredAt *string `json:"occurred_at"` // Occurrence time.
	IssueCause *string `json:"issue_cause"` // Execution-specific cause; maps to pko:issueCause.
	IssueSolution *string `json:"issue_solution"` // Applied solution; maps to pko:issueSolution.
	Status *string `json:"status"` // Open, Monitoring, Resolved, or Closed.
	IsUnresolved *bool `json:"is_unresolved"` // TRUE when this issue occurrence has not been closed out.
	StepExecutionWhenUnresolved *string `json:"step_execution_when_unresolved"` // Echoes the step-execution id when the issue is unresolved, blank otherwise.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact PKO class IRI.
	ExecutedStep *string `json:"executed_step"` // Step the issue occurred on.
	FailedConditionCountOnRun *int `json:"failed_condition_count_on_run"` // Conditions that did not hold on the same step execution.
	CoincidedWithFailedCondition *bool `json:"coincided_with_failed_condition"` // TRUE when the issue occurred on a step execution where a checked condition did not hold.
	HasNoRecordedSolution *bool `json:"has_no_recorded_solution"` // TRUE when an issue records no solution.
	RedesignChangeRequest *string `json:"redesign_change_request"` // The change request that redesigned the procedure in response to the failure.
	RedesignImplementedAt *string `json:"redesign_implemented_at"` // When that redesign was implemented.
	IsFailureWithoutLandedRedesign *bool `json:"is_failure_without_landed_redesign"` // TRUE when a recorded failure has no redesign, or its redesign never landed.
	ImprovementCyclePath *string `json:"improvement_cycle_path"` // Failure observed, how it was recorded, and the redesign that followed.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the IssueOccurrences row.
// Formula: ={{Error}} & " @ " & {{OccurredAt}}
func (tc *IssueOccurrence) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Error)), vS(" @ "), erbDatetimeText(vStr(tc.OccurredAt))))
}

// CalcIsUnresolved computes the IsUnresolved calculated field
// TRUE when this issue occurrence has not been closed out.
// Formula: =OR({{Status}} = "Open", {{Status}} = "Investigating", {{Status}} = "Monitoring")
func (tc *IssueOccurrence) CalcIsUnresolved() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Open"))), erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Investigating"))), erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Monitoring")))))
}

// CalcStepExecutionWhenUnresolved computes the StepExecutionWhenUnresolved calculated field
// Echoes the step-execution id when the issue is unresolved, blank otherwise.
// Formula: =IF({{IsUnresolved}}, {{StepExecution}}, "")
func (tc *IssueOccurrence) CalcStepExecutionWhenUnresolved() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUnresolved)), func() Value { return vStr(tc.StepExecution) }, func() Value { return vS("") }))
}

// CalcCoincidedWithFailedCondition computes the CoincidedWithFailedCondition calculated field
// TRUE when the issue occurred on a step execution where a checked condition did not hold.
// Formula: ={{FailedConditionCountOnRun}} > 0
func (tc *IssueOccurrence) CalcCoincidedWithFailedCondition() *bool {
	return toBoolPtr(erbCmp(vInt(tc.FailedConditionCountOnRun), ">", vI(0)))
}

// CalcHasNoRecordedSolution computes the HasNoRecordedSolution calculated field
// TRUE when an issue records no solution.
// Formula: ={{IssueSolution}} = ""
func (tc *IssueOccurrence) CalcHasNoRecordedSolution() *bool {
	return toBoolPtr(erbIsBlank(vStr(tc.IssueSolution)))
}

// CalcIsFailureWithoutLandedRedesign computes the IsFailureWithoutLandedRedesign calculated field
// TRUE when a recorded failure has no redesign, or its redesign never landed.
// Formula: =OR({{RedesignChangeRequest}} = "", {{RedesignImplementedAt}} = "")
func (tc *IssueOccurrence) CalcIsFailureWithoutLandedRedesign() *bool {
	return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.RedesignChangeRequest))), erbBool3(erbIsBlank(vStr(tc.RedesignImplementedAt)))))
}

// CalcImprovementCyclePath computes the ImprovementCyclePath calculated field
// Failure observed, how it was recorded, and the redesign that followed.
// Formula: =IF({{RedesignChangeRequest}} = "", "", "Observed at " & {{ExecutedStep}} & " by " & {{EncounteredByAgent}} & "; recorded as " & {{Error}} & " (" & {{IssueCause}} & "); redesigned by " & {{RedesignChangeRequest}})
func (tc *IssueOccurrence) CalcImprovementCyclePath() *string {
	return toStringPtr(erbIf(erbBool3(erbIsBlank(vStr(tc.RedesignChangeRequest))), func() Value { return vS("") }, func() Value { return erbConcat(vS("Observed at "), erbText(vStr(tc.ExecutedStep)), vS(" by "), erbText(vStr(tc.EncounteredByAgent)), vS("; recorded as "), erbText(vStr(tc.Error)), vS(" ("), erbText(vStr(tc.IssueCause)), vS("); redesigned by "), erbText(vStr(tc.RedesignChangeRequest))) }))
}

