	calcGuard(tc, "coincided_with_failed_condition", func() { tc.CoincidedWithFailedCondition = tc.CalcCoincidedWithFailedCondition() })
	calcGuard(tc, "has_no_recorded_solution", func() { tc.HasNoRecordedSolution = tc.CalcHasNoRecordedSolution() })
	calcGuard(tc, "is_failure_without_landed_redesign", func() { tc.IsFailureWithoutLandedRedesign = tc.CalcIsFailureWithoutLandedRedesign() })
