	calcGuard(tc, "is_still_pending", func() { tc.IsStillPending = tc.CalcIsStillPending() })
	calcGuard(tc, "awaits_authority_decision", func() { tc.AwaitsAuthorityDecision = tc.CalcAwaitsAuthorityDecision() })
