// OperationalBinding represents a row in the OperationalBindings table
type OperationalBinding struct {
	OperationalBindingId string `json:"operational_binding_id"` // Stored logical identifier for one OperationalBindings row.
	Name *string `json:"name"` // Human-readable calculated display alias for the OperationalBindings row.
	ProcedureVersion *string `json:"procedure_version"` // Procedure version using the binding.
	Step *string `json:"step"` // Step using the binding.
	Resource *string `json:"resource"` // Bound operational resource.
	AccessMode *string `json:"access_mode"` // Read, Write, ReadWrite, Subscribe, or Publish.
	RecordOrSchemaKey *string `json:"record_or_schema_key"` // Operational record, table, event, or schema key.
	LastObservedAt *string `json:"last_observed_at"` // Most recent successful observation.
	FreshnessSlaMinutes *int `json:"freshness_sla_minutes"` // Maximum allowed data age.
	IsAuthoritative *bool `json:"is_authoritative"` // TRUE when the binding is authoritative for the represented fact.
	EvaluationContext *string `json:"evaluation_context"` // The evaluation context this row's time-dependent witnesses are judged under.
	AsOfInstant *string `json:"as_of_instant"` // The evaluation instant this row's time-dependent witnesses are judged against.
	AgeMinutes *int `json:"age_minutes"` // Current observed age.
	IsFresh *bool `json:"is_fresh"` // TRUE when within freshness SLA.
	StaleBindingStepKey *string `json:"stale_binding_step_key"` // Echoes the bound Step id only when the binding is outside its freshness SLA.
	AuthoritativeStaleStepKey *string `json:"authoritative_stale_step_key"` // Echoes the bound Step id only when an AUTHORITATIVE binding is stale.
	IsStaleAndAuthoritative *bool `json:"is_stale_and_authoritative"` // TRUE when an authoritative binding has aged past its freshness SLA.
	StepWhenStale *string `json:"step_when_stale"` // Echoes the step id when this authoritative binding is stale, blank otherwise.
	ResourceIsApproved *bool `json:"resource_is_approved"` // Whether the resource behind this binding is an approved source.
	IsUsableForDrafting *bool `json:"is_usable_for_drafting"` // TRUE when this binding points at an approved source that is still inside its freshness SLA.
	StepWhenUnusable *string `json:"step_when_unusable"` // Echoes the step id when this binding is NOT usable for drafting, blank otherwise.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the OperationalBindings row.
// Formula: ={{Step}} & " / " & {{RecordOrSchemaKey}}
func (tc *OperationalBinding) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Step)), vS(" / "), erbText(vStr(tc.RecordOrSchemaKey))))
}

// CalcAgeMinutes computes the AgeMinutes calculated field
// Current observed age.
// Formula: =DATETIME_DIFF({{AsOfInstant}}, {{LastObservedAt}}, "minutes")
func (tc *OperationalBinding) CalcAgeMinutes() *int {
	return toIntPtr(erbInteger(erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.LastObservedAt), vS("minutes"))))
}

// CalcIsFresh computes the IsFresh calculated field
// TRUE when within freshness SLA.
// Formula: ={{AgeMinutes}} <= {{FreshnessSlaMinutes}}
func (tc *OperationalBinding) CalcIsFresh() *bool {
	return toBoolPtr(erbCmp(vInt(tc.AgeMinutes), "<=", erbNullif(vInt(tc.FreshnessSlaMinutes))))
}

// CalcStaleBindingStepKey computes the StaleBindingStepKey calculated field
// Echoes the bound Step id only when the binding is outside its freshness SLA.
// Formula: =IF(NOT({{IsFresh}}), {{Step}}, "")
func (tc *OperationalBinding) CalcStaleBindingStepKey() *string {
	return toStringPtr(erbIf(erbBool3(erbNot(erbBool3(vBool(tc.IsFresh)))), func() Value { return vStr(tc.Step) }, func() Value { return vS("") }))
}

// CalcAuthoritativeStaleStepKey computes the AuthoritativeStaleStepKey calculated field
// Echoes the bound Step id only when an AUTHORITATIVE binding is stale.
// Formula: =IF(AND(NOT({{IsFresh}}), {{IsAuthoritative}}), {{Step}}, "")
func (tc *OperationalBinding) CalcAuthoritativeStaleStepKey() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(erbNot(erbBool3(vBool(tc.IsFresh)))), erbIsTrue(vBool(tc.IsAuthoritative)))), func() Value { return vStr(tc.Step) }, func() Value { return vS("") }))
}

// CalcIsStaleAndAuthoritative computes the IsStaleAndAuthoritative calculated field
// TRUE when an authoritative binding has aged past its freshness SLA.
// Formula: =AND({{IsAuthoritative}}, NOT({{IsFresh}}))
func (tc *OperationalBinding) CalcIsStaleAndAuthoritative() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsAuthoritative)), erbBool3(erbNot(erbBool3(vBool(tc.IsFresh))))))
}

// CalcStepWhenStale computes the StepWhenStale calculated field
// Echoes the step id when this authoritative binding is stale, blank otherwise.
// Formula: =IF({{IsStaleAndAuthoritative}}, {{Step}}, "")
func (tc *OperationalBinding) CalcStepWhenStale() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsStaleAndAuthoritative)), func() Value { return vStr(tc.Step) }, func() Value { return vS("") }))
}

// CalcIsUsableForDrafting computes the IsUsableForDrafting calculated field
// TRUE when this binding points at an approved source that is still inside its freshness SLA.
// Formula: =AND({{ResourceIsApproved}}, {{IsFresh}})
func (tc *OperationalBinding) CalcIsUsableForDrafting() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.ResourceIsApproved)), erbBool3(vBool(tc.IsFresh))))
}

// CalcStepWhenUnusable computes the StepWhenUnusable calculated field
// Echoes the step id when this binding is NOT usable for drafting, blank otherwise.
// Formula: =IF({{IsUsableForDrafting}}, "", {{Step}})
func (tc *OperationalBinding) CalcStepWhenUnusable() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUsableForDrafting)), func() Value { return vS("") }, func() Value { return vStr(tc.Step) }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *OperationalBinding) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "age_minutes", func() { tc.AgeMinutes = tc.CalcAgeMinutes() })
	// Level 2
	calcGuard(tc, "is_fresh", func() { tc.IsFresh = tc.CalcIsFresh() })
	// Level 3
	calcGuard(tc, "stale_binding_step_key", func() { tc.StaleBindingStepKey = tc.CalcStaleBindingStepKey() })
	calcGuard(tc, "authoritative_stale_step_key", func() { tc.AuthoritativeStaleStepKey = tc.CalcAuthoritativeStaleStepKey() })
	calcGuard(tc, "is_stale_and_authoritative", func() { tc.IsStaleAndAuthoritative = tc.CalcIsStaleAndAuthoritative() })
	calcGuard(tc, "is_usable_for_drafting", func() { tc.IsUsableForDrafting = tc.CalcIsUsableForDrafting() })
	// Level 4
	calcGuard(tc, "step_when_stale", func() { tc.StepWhenStale = tc.CalcStepWhenStale() })
	calcGuard(tc, "step_when_unusable", func() { tc.StepWhenUnusable = tc.CalcStepWhenUnusable() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *OperationalBinding) ComputeAll() *OperationalBinding {
	tc.erbComputeCalculations()
	return tc
}

