// RULEBOOKFIELDS TABLE
// A complete census of every field in this rulebook. Reconciled from the real schemas by tools/reconcile_field_catalog.py — never hand-maintained. Fields invented by a witness loop carry an InventedForQuestion FK.
// =============================================================================

// RulebookField represents a row in the RulebookFields table
type RulebookField struct {
	RulebookFieldId string `json:"rulebook_field_id"` // Stored logical identifier for one RulebookFields row. Formed as <TargetTable>.<FieldName>.
	Name *string `json:"name"` // Human-readable calculated display alias for the RulebookFields row.
	TargetTable *string `json:"target_table"` // The table this field lives on.
	FieldName *string `json:"field_name"` // The field's name within its table.
	FieldType *string `json:"field_type"` // raw, calculated, lookup, relationship, or aggregation.
	Datatype *string `json:"datatype"` // The field's declared datatype.
	Formula *string `json:"formula"` // The field's formula when it is derived. Null for raw and relationship fields.
	RelatedTo *string `json:"related_to"` // For a relationship field, the table it points at. Structural catalog metadata beside FieldType and Datatype; the published vocabulary reads it to give each object property its range.
	InventedForQuestion *string `json:"invented_for_question"` // The role question that motivated this field's existence. Null for fields that predate the witness-loop exercise.
	IsDerived *bool `json:"is_derived"` // TRUE when this field is computed rather than stored.
	IsWitness *bool `json:"is_witness"` // TRUE when this field exists because a role asked a question. These are the fields the witness loops added.
	DisagreeingSubstrateCount *float64 `json:"disagreeing_substrate_count"` // How many substrates computed this field differently from the answer key in the latest conformance run. 0 means every substrate agreed.
	IsSubstrateContested *bool `json:"is_substrate_contested"` // True when at least one substrate disagrees about this field's values.
	MeasuredSubstantiveCount *int `json:"measured_substantive_count"` // Rows of this field's vw_* column holding a substantive value (not blank, false or zero), measured in Postgres by tools/measure_catalog.py.
	MeasuredDistinctValueCount *int `json:"measured_distinct_value_count"` // Distinct values of this field's vw_* column, with blank counted as one value, measured in Postgres.
	HasMeasuredData *bool `json:"has_measured_data"` // TRUE when Postgres holds at least one substantive value (not blank, false or zero) for this field.
	IsDiscriminating *bool `json:"is_discriminating"` // TRUE when the field takes at least two distinct values over the seed data, so it can tell rows apart. An all-true or all-false witness states nothing.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the RulebookFields row.
// Formula: ={{TargetTable}} & "." & {{FieldName}}
func (tc *RulebookField) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.TargetTable)), vS("."), erbText(vStr(tc.FieldName))))
}

// CalcIsDerived computes the IsDerived calculated field
// TRUE when this field is computed rather than stored.
// Formula: =OR({{FieldType}} = "calculated", {{FieldType}} = "lookup", {{FieldType}} = "aggregation")
func (tc *RulebookField) CalcIsDerived() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.FieldType)), vS("calculated"))), erbBool3(erbEq(erbNullif(vStr(tc.FieldType)), vS("lookup"))), erbBool3(erbEq(erbNullif(vStr(tc.FieldType)), vS("aggregation")))))
}

// CalcIsWitness computes the IsWitness calculated field
// TRUE when this field exists because a role asked a question. These are the fields the witness loops added.
// Formula: ={{InventedForQuestion}} <> ""
func (tc *RulebookField) CalcIsWitness() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.InventedForQuestion)))
}

// CalcIsSubstrateContested computes the IsSubstrateContested calculated field
// True when at least one substrate disagrees about this field's values.
// Formula: ={{DisagreeingSubstrateCount}} > 0
func (tc *RulebookField) CalcIsSubstrateContested() *bool {
	return toBoolPtr(erbCmp(vNum(tc.DisagreeingSubstrateCount), ">", vI(0)))
}

// CalcHasMeasuredData computes the HasMeasuredData calculated field
// TRUE when Postgres holds at least one substantive value (not blank, false or zero) for this field.
// Formula: ={{MeasuredSubstantiveCount}} > 0
func (tc *RulebookField) CalcHasMeasuredData() *bool {
	return toBoolPtr(erbCmp(erbNullif(vInt(tc.MeasuredSubstantiveCount)), ">", vI(0)))
}

// CalcIsDiscriminating computes the IsDiscriminating calculated field
// TRUE when the field takes at least two distinct values over the seed data, so it can tell rows apart. An all-true or all-false witness states nothing.
// Formula: ={{MeasuredDistinctValueCount}} >= 2
func (tc *RulebookField) CalcIsDiscriminating() *bool {
	return toBoolPtr(erbCmp(erbNullif(vInt(tc.MeasuredDistinctValueCount)), ">=", vI(2)))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *RulebookField) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_derived", func() { tc.IsDerived = tc.CalcIsDerived() })
	calcGuard(tc, "is_witness", func() { tc.IsWitness = tc.CalcIsWitness() })
	calcGuard(tc, "is_substrate_contested", func() { tc.IsSubstrateContested = tc.CalcIsSubstrateContested() })
	calcGuard(tc, "has_measured_data", func() { tc.HasMeasuredData = tc.CalcHasMeasuredData() })
	calcGuard(tc, "is_discriminating", func() { tc.IsDiscriminating = tc.CalcIsDiscriminating() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *RulebookField) ComputeAll() *RulebookField {
	tc.erbComputeCalculations()
	return tc
}

