// VerificationOutcome represents a row in the VerificationOutcomes table
type VerificationOutcome struct {
	VerificationOutcomeId string `json:"verification_outcome_id"` // Stored logical identifier for one VerificationOutcomes row.
	Name *string `json:"name"` // Human-readable calculated display alias.
	StepExecution *string `json:"step_execution"` // The execution during which the verification was performed.
	StepVerification *string `json:"step_verification"` // The declared verification being performed.
	ObservedSignalValue *string `json:"observed_signal_value"` // The value the signal actually read at verification time.
	ObservedByAgent *string `json:"observed_by_agent"` // Agent who observed the signal.
	ObservedAt *string `json:"observed_at"` // When the signal was observed.
	EvidenceUri *string `json:"evidence_uri"` // Pointer to the retained artifact backing the observation.
	ExpectedSignalValue *string `json:"expected_signal_value"` // The value the specification expects.
	SignalIdentifier *string `json:"signal_identifier"` // Which signal this outcome concerns.
	SignalMatchesExpected *bool `json:"signal_matches_expected"` // TRUE when the observed value equals the expected value.
	HasEvidence *bool `json:"has_evidence"` // TRUE when a retained artifact backs this observation.
	IsUnbackedObservation *bool `json:"is_unbacked_observation"` // TRUE when a verification was recorded as matching but no evidence artifact was retained.
	IsSelfWitnessed *bool `json:"is_self_witnessed"` // TRUE when the agent who observed the verification signal is the same agent who executed the step being verified.
	StepExecutorAgent *string `json:"step_executor_agent"` // The agent who executed the step this verification outcome concerns.
	SelfWitnessedStepKey *string `json:"self_witnessed_step_key"` // Echoes the StepExecution id only for self-witnessed verifications.
	UnbackedStepKey *string `json:"unbacked_step_key"` // Echoes the StepExecution id when a verification matched but retained no evidence.
	IsSelfWitnessedAndUnbacked *bool `json:"is_self_witnessed_and_unbacked"` // TRUE when the executor observed their own passing signal and attached no evidence.
	IsUncorroboratedPass *bool `json:"is_uncorroborated_pass"` // TRUE when a PASSING signal was self-observed with no evidence behind it.
	UncorroboratedPassStepKey *string `json:"uncorroborated_pass_step_key"` // Echoes the step execution id when this outcome is an uncorroborated pass.
	ObserverIsNonHuman *bool `json:"observer_is_non_human"` // Whether the agent who recorded this observation is non-human. Agents has no PrimaryRole column and an FK from Agents back to Roles would create a table cycle, so the independence question is answered by agent kind rather than by role.
	ObserverIsIndependentOfExecutor *bool `json:"observer_is_independent_of_executor"` // TRUE when someone other than the step's executor recorded the observation.
	IsIndependentHumanObservation *bool `json:"is_independent_human_observation"` // TRUE when a human other than the step's executor observed this signal and attached evidence.
	IndependentObservationExecutionKey *string `json:"independent_observation_execution_key"` // Echoes the parent execution id when this is an independent human observation.
	ParentProcedureExecutionOfOutcome *string `json:"parent_procedure_execution_of_outcome"` // The procedure execution this verification outcome belongs to.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension IRI — PKO 2.0.0 has no execution-side verification outcome class.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias.
// Formula: ={{StepExecution}} & " / " & {{StepVerification}}
func (tc *VerificationOutcome) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.StepExecution)), vS(" / "), erbText(vStr(tc.StepVerification))))
}

// CalcSignalMatchesExpected computes the SignalMatchesExpected calculated field
// TRUE when the observed value equals the expected value.
// Formula: ={{ObservedSignalValue}} = {{ExpectedSignalValue}}
func (tc *VerificationOutcome) CalcSignalMatchesExpected() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.ObservedSignalValue)), vStr(tc.ExpectedSignalValue)))
}

// CalcHasEvidence computes the HasEvidence calculated field
// TRUE when a retained artifact backs this observation.
// Formula: ={{EvidenceUri}} <> ""
func (tc *VerificationOutcome) CalcHasEvidence() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.EvidenceUri)))
}

// CalcIsUnbackedObservation computes the IsUnbackedObservation calculated field
// TRUE when a verification was recorded as matching but no evidence artifact was retained.
// Formula: =AND({{SignalMatchesExpected}}, NOT({{HasEvidence}}))
func (tc *VerificationOutcome) CalcIsUnbackedObservation() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.SignalMatchesExpected)), erbBool3(erbNot(erbBool3(vBool(tc.HasEvidence))))))
}

// CalcIsSelfWitnessed computes the IsSelfWitnessed calculated field
// TRUE when the agent who observed the verification signal is the same agent who executed the step being verified.
// Formula: ={{ObservedByAgent}} = {{StepExecutorAgent}}
func (tc *VerificationOutcome) CalcIsSelfWitnessed() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.ObservedByAgent)), vStr(tc.StepExecutorAgent)))
}

// CalcSelfWitnessedStepKey computes the SelfWitnessedStepKey calculated field
// Echoes the StepExecution id only for self-witnessed verifications.
// Formula: =IF({{IsSelfWitnessed}}, {{StepExecution}}, "")
func (tc *VerificationOutcome) CalcSelfWitnessedStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsSelfWitnessed)), func() Value { return vStr(tc.StepExecution) }, func() Value { return vS("") }))
}

// CalcUnbackedStepKey computes the UnbackedStepKey calculated field
// Echoes the StepExecution id when a verification matched but retained no evidence.
// Formula: =IF({{IsUnbackedObservation}}, {{StepExecution}}, "")
func (tc *VerificationOutcome) CalcUnbackedStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUnbackedObservation)), func() Value { return vStr(tc.StepExecution) }, func() Value { return vS("") }))
}

// CalcIsSelfWitnessedAndUnbacked computes the IsSelfWitnessedAndUnbacked calculated field
// TRUE when the executor observed their own passing signal and attached no evidence.
// Formula: =AND({{IsSelfWitnessed}}, NOT({{HasEvidence}}))
func (tc *VerificationOutcome) CalcIsSelfWitnessedAndUnbacked() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsSelfWitnessed)), erbBool3(erbNot(erbBool3(vBool(tc.HasEvidence))))))
}

// CalcIsUncorroboratedPass computes the IsUncorroboratedPass calculated field
// TRUE when a PASSING signal was self-observed with no evidence behind it.
// Formula: =AND({{SignalMatchesExpected}}, {{IsSelfWitnessedAndUnbacked}})
func (tc *VerificationOutcome) CalcIsUncorroboratedPass() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.SignalMatchesExpected)), erbBool3(vBool(tc.IsSelfWitnessedAndUnbacked))))
}

// CalcUncorroboratedPassStepKey computes the UncorroboratedPassStepKey calculated field
// Echoes the step execution id when this outcome is an uncorroborated pass.
// Formula: =IF({{IsUncorroboratedPass}}, {{StepExecution}}, "")
func (tc *VerificationOutcome) CalcUncorroboratedPassStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUncorroboratedPass)), func() Value { return vStr(tc.StepExecution) }, func() Value { return vS("") }))
}

// CalcObserverIsIndependentOfExecutor computes the ObserverIsIndependentOfExecutor calculated field
// TRUE when someone other than the step's executor recorded the observation.
// Formula: =NOT({{IsSelfWitnessed}})
func (tc *VerificationOutcome) CalcObserverIsIndependentOfExecutor() *bool {
	return toBoolPtr(erbNot(erbBool3(vBool(tc.IsSelfWitnessed))))
}

// CalcIsIndependentHumanObservation computes the IsIndependentHumanObservation calculated field
// TRUE when a human other than the step's executor observed this signal and attached evidence.
// Formula: =AND(NOT({{ObserverIsNonHuman}}), NOT({{IsSelfWitnessed}}), {{HasEvidence}})
func (tc *VerificationOutcome) CalcIsIndependentHumanObservation() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNot(erbBool3(vBool(tc.ObserverIsNonHuman)))), erbBool3(erbNot(erbBool3(vBool(tc.IsSelfWitnessed)))), erbBool3(vBool(tc.HasEvidence))))
}

// CalcIndependentObservationExecutionKey computes the IndependentObservationExecutionKey calculated field
// Echoes the parent execution id when this is an independent human observation.
// Formula: =IF({{IsIndependentHumanObservation}}, {{ParentProcedureExecutionOfOutcome}}, "")
func (tc *VerificationOutcome) CalcIndependentObservationExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsIndependentHumanObservation)), func() Value { return vStr(tc.ParentProcedureExecutionOfOutcome) }, func() Value { return vS("") }))
}

