	calcGuard(tc, "is_self_witnessed_and_unbacked", func() { tc.IsSelfWitnessedAndUnbacked = tc.CalcIsSelfWitnessedAndUnbacked() })
	calcGuard(tc, "observer_is_independent_of_executor", func() { tc.ObserverIsIndependentOfExecutor = tc.CalcObserverIsIndependentOfExecutor() })
	calcGuard(tc, "is_independent_human_observation", func() { tc.IsIndependentHumanObservation = tc.CalcIsIndependentHumanObservation() })
	// Level 3
	calcGuard(tc, "unbacked_step_key", func() { tc.UnbackedStepKey = tc.CalcUnbackedStepKey() })
	calcGuard(tc, "is_uncorroborated_pass", func() { tc.IsUncorroboratedPass = tc.CalcIsUncorroboratedPass() })
	calcGuard(tc, "independent_observation_execution_key", func() { tc.IndependentObservationExecutionKey = tc.CalcIndependentObservationExecutionKey() })
	// Level 4
