// OBSERVEDTRANSITIONS TABLE
// The proxy above cannot tell a walked fallback from a happy-path step that happens to share an endpoint. PKO models Transition as a first-class thing; its execution counterpart is missing. Without a table that records WHICH transition a step execution arrived by, 'has this fallback ever been walked' is permanently unanswerable rather than merely unanswered. This is an extension (https://effortlessapi.github.io/effortless-rulebooks/ns/pko-extension#ObservedTransition), not a native PKO term.
// =============================================================================

// ObservedTransition represents a row in the ObservedTransitions table
type ObservedTransition struct {
	ObservedTransitionId string `json:"observed_transition_id"` // Stored logical identifier for one ObservedTransitions row.
	Name *string `json:"name"` // Human-readable calculated display alias.
	ProcedureExecution string `json:"procedure_execution"` // The procedure execution during which this transition was traversed.
	StepTransition string `json:"step_transition"` // The specification-level transition that was actually taken.
	ArrivingStepExecution *string `json:"arriving_step_execution"` // The step execution that this traversal produced.
	ObservedAt *string `json:"observed_at"` // When the traversal occurred.
	TriggerReason *string `json:"trigger_reason"` // Why this path rather than the default was taken.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias.
// Formula: ={{StepTransition}} & " @ " & {{ObservedAt}}
func (tc *ObservedTransition) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStrPlain(tc.StepTransition)), vS(" @ "), erbDatetimeText(vStr(tc.ObservedAt))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ObservedTransition) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ObservedTransition) ComputeAll() *ObservedTransition {
	tc.erbComputeCalculations()
	return tc
}

func (tc *ObservedTransition) erbGet(field string) Value {
	switch field {
	case "observed_transition_id":
		return vStrPlain(tc.ObservedTransitionId)
	case "name":
		return vStr(tc.Name)
	case "procedure_execution":
		return vStrPlain(tc.ProcedureExecution)
	case "step_transition":
		return vStrPlain(tc.StepTransition)
	case "arriving_step_execution":
		return vStr(tc.ArrivingStepExecution)
	case "observed_at":
		return vStr(tc.ObservedAt)
	case "trigger_reason":
		return vStr(tc.TriggerReason)
	case "semantic_type_iri":
		return vStr(tc.SemanticTypeIri)
	}
	panic("ObservedTransitions has no field " + field)
}

func (tc *ObservedTransition) erbSet(field string, v Value) {
	switch field {
	case "observed_transition_id":
		tc.ObservedTransitionId = strPlain(v)
	case "name":
		tc.Name = toStringPtr(v)
	case "procedure_execution":
		tc.ProcedureExecution = strPlain(v)
	case "step_transition":
		tc.StepTransition = strPlain(v)
	case "arriving_step_execution":
		tc.ArrivingStepExecution = toStringPtr(v)
	case "observed_at":
		tc.ObservedAt = toStringPtr(v)
	case "trigger_reason":
		tc.TriggerReason = toStringPtr(v)
	case "semantic_type_iri":
		tc.SemanticTypeIri = toStringPtr(v)
	default:
		panic("ObservedTransitions has no field " + field)
	}
}

func (tc *ObservedTransition) erbLoad(row map[string]any) {
	for key, value := range row {
		switch key {
		case "observed_transition_id", "name", "procedure_execution", "step_transition", "arriving_step_execution", "observed_at", "trigger_reason", "semantic_type_iri":
			tc.erbSet(key, fromJSON(value))
		}
	}
}

func (tc *ObservedTransition) erbErrors() map[string]string {
	if tc.ErbErrors == nil {
		tc.ErbErrors = map[string]string{}
	}
	return tc.ErbErrors
}

func (tc *ObservedTransition) erbResetErrors() { tc.ErbErrors = nil }

func (tc *ObservedTransition) erbAggregate(name string) Value { return tc.erbAggregates[name] }

func (tc *ObservedTransition) erbSetAggregate(name string, v Value) {
	if tc.erbAggregates == nil {
		tc.erbAggregates = map[string]Value{}
	}
	tc.erbAggregates[name] = v
}

// LoadObservedTransitionRecords reads ObservedTransitions rows from a JSON array file.
func LoadObservedTransitionRecords(path string) ([]ObservedTransition, error) {
	records, err := loadRecords(path, func() Record { return &ObservedTransition{} })
	if err != nil {
		return nil, err
	}
	rows := make([]ObservedTransition, len(records))
	for i, r := range records {
		rows[i] = *r.(*ObservedTransition)
	}
	return rows, nil
}

