func (tc *SendIntent) erbErrors() map[string]string {
	if tc.ErbErrors == nil {
		tc.ErbErrors = map[string]string{}
	}
	return tc.ErbErrors
}

func (tc *SendIntent) erbResetErrors() { tc.ErbErrors = nil }

func (tc *SendIntent) erbAggregate(name string) Value { return tc.erbAggregates[name] }

func (tc *SendIntent) erbSetAggregate(name string, v Value) {
	if tc.erbAggregates == nil {
		tc.erbAggregates = map[string]Value{}
	}
	tc.erbAggregates[name] = v
}

// LoadSendIntentRecords reads SendIntents rows from a JSON array file.
func LoadSendIntentRecords(path string) ([]SendIntent, error) {
	records, err := loadRecords(path, func() Record { return &SendIntent{} })
	if err != nil {
		return nil, err
	}
	rows := make([]SendIntent, len(records))
	for i, r := range records {
		rows[i] = *r.(*SendIntent)
	}
	return rows, nil
}

