func (tc *AccessPrincipal) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_no_access", func() { tc.HasNoAccess = tc.CalcHasNoAccess() })
	calcGuard(tc, "is_over_privileged", func() { tc.IsOverPrivileged = tc.CalcIsOverPrivileged() })
}

