// =============================================================================
// ACCESSPOLICIES TABLE
// Row-level security policies: the VERTICAL cut. One row per principal x table x command, carrying the predicate that decides which rows are visible. RowPredicate is emitted verbatim into a Postgres USING clause, so it may call any SECURITY DEFINER calc_* function and therefore reference inference fields many hops down the DAG.
// =============================================================================

// AccessPolicie represents a row in the AccessPolicies table
type AccessPolicie struct {
	AccessPolicyId string `json:"access_policy_id"` // Stored logical identifier, e.g. 'pol-controller-procedures-select'.
	Name *string `json:"name"` // Human-readable calculated display alias.
	Principal *string `json:"principal"` // Principal this policy grants to.
	TargetTable *string `json:"target_table"` // Rulebook table this policy guards.
	Command *string `json:"command"` // SQL command the policy governs: SELECT, INSERT, UPDATE, DELETE or ALL.
	RowPredicate *string `json:"row_predicate"` // SQL boolean expression emitted into USING(...). Empty means all rows of the table. Must not sub-select the guarded table -- Postgres raises infinite recursion; route such predicates through a SECURITY DEFINER function instead.
	CheckPredicate *string `json:"check_predicate"` // SQL boolean expression emitted into WITH CHECK(...) for write commands. Empty reuses RowPredicate.
	Rationale *string `json:"rationale"` // Why this principal is entitled to these rows, in the granting authority's words.
	ReferencesInference *bool `json:"references_inference"` // True when RowPredicate calls a calc_* function, i.e. the cut depends on a derived field rather than a stored column.
	IsWriteCommand *bool `json:"is_write_command"` // True when this policy governs a mutating command.
	IsUnrestricted *bool `json:"is_unrestricted"` // True when the policy carries no predicate, exposing every row of the target table to the principal.
	PrincipalIsAdmin *bool `json:"principal_is_admin"` // Whether the granted principal is an administrator.
	IsUnrestrictedNonAdminGrant *bool `json:"is_unrestricted_non_admin_grant"` // True when a non-administrator principal is granted an unrestricted policy -- a whole-table exposure that no row predicate narrows. The single highest-signal privilege-escalation witness in the model.
	IsUnwitnessedWrite *bool `json:"is_unwitnessed_write"` // True when a write policy has no denial test proving it refuses out-of-scope rows. An untested write grant is an assertion, not evidence.
	DenialTestCount *float64 `json:"denial_test_count"` // Number of denial tests seeded against this policy.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias.
// Formula: ={{Principal}} & " " & {{Command}} & " " & {{TargetTable}}
func (tc *AccessPolicie) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Principal)), vS(" "), erbText(vStr(tc.Command)), vS(" "), erbText(vStr(tc.TargetTable))))
}

// CalcIsWriteCommand computes the IsWriteCommand calculated field
// True when this policy governs a mutating command.
// Formula: =OR({{Command}} = "INSERT", {{Command}} = "UPDATE", {{Command}} = "DELETE", {{Command}} = "ALL")
func (tc *AccessPolicie) CalcIsWriteCommand() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.Command)), vS("INSERT"))), erbBool3(erbEq(erbNullif(vStr(tc.Command)), vS("UPDATE"))), erbBool3(erbEq(erbNullif(vStr(tc.Command)), vS("DELETE"))), erbBool3(erbEq(erbNullif(vStr(tc.Command)), vS("ALL")))))
}

// CalcIsUnrestricted computes the IsUnrestricted calculated field
// True when the policy carries no predicate, exposing every row of the target table to the principal.
// Formula: ={{RowPredicate}} = ""
func (tc *AccessPolicie) CalcIsUnrestricted() *bool {
	return toBoolPtr(erbIsBlank(vStr(tc.RowPredicate)))
}

// CalcIsUnrestrictedNonAdminGrant computes the IsUnrestrictedNonAdminGrant calculated field
// True when a non-administrator principal is granted an unrestricted policy -- a whole-table exposure that no row predicate narrows. The single highest-signal privilege-escalation witness in the model.
// Formula: =AND({{IsUnrestricted}}, NOT({{PrincipalIsAdmin}}))
func (tc *AccessPolicie) CalcIsUnrestrictedNonAdminGrant() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsUnrestricted)), erbBool3(erbNot(erbBool3(vBool(tc.PrincipalIsAdmin))))))
}

// CalcIsUnwitnessedWrite computes the IsUnwitnessedWrite calculated field
// True when a write policy has no denial test proving it refuses out-of-scope rows. An untested write grant is an assertion, not evidence.
// Formula: =AND({{IsWriteCommand}}, {{DenialTestCount}} = 0)
func (tc *AccessPolicie) CalcIsUnwitnessedWrite() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsWriteCommand)), erbBool3(erbEq(vNum(tc.DenialTestCount), vI(0)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *AccessPolicie) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_write_command", func() { tc.IsWriteCommand = tc.CalcIsWriteCommand() })
	calcGuard(tc, "is_unrestricted", func() { tc.IsUnrestricted = tc.CalcIsUnrestricted() })
	// Level 2
	calcGuard(tc, "is_unrestricted_non_admin_grant", func() { tc.IsUnrestrictedNonAdminGrant = tc.CalcIsUnrestrictedNonAdminGrant() })
	calcGuard(tc, "is_unwitnessed_write", func() { tc.IsUnwitnessedWrite = tc.CalcIsUnwitnessedWrite() })
}

