type AccessDenialTest struct {
	AccessDenialTestId string `json:"access_denial_test_id"` // Stored logical identifier, e.g. 'deny-analyst-other-org-procedures'.
	Name *string `json:"name"` // Human-readable calculated display alias.
	TargetPolicy *string `json:"target_policy"` // Policy this test exercises.
	Principal *string `json:"principal"` // Principal the query runs as.
	TargetTable *string `json:"target_table"` // Table queried.
	ForbiddenRowId *string `json:"forbidden_row_id"` // Primary key of the row that must be invisible to this principal.
	ExpectedVisible *bool `json:"expected_visible"` // False for a denial test: the row must not appear. True asserts a row the principal is entitled to does appear.
	ObservedVisible *bool `json:"observed_visible"` // What the substrate actually returned on the last run. Written back by the verifier, never hand-set.
	LastRunAt *string `json:"last_run_at"` // When this test was last executed against Postgres.
	HasRun *bool `json:"has_run"` // True once the test has been executed at least once.
	IsPassing *bool `json:"is_passing"` // True when observed visibility matches expectation.
	IsLeak *bool `json:"is_leak"` // True when a row that must be invisible was returned. A confirmed access-control breach.
	IsUnproven *bool `json:"is_unproven"` // True when the test has never run, so it proves nothing regardless of how it is written.
	Rationale *string `json:"rationale"` // Why this row must (or must not) be visible, and which predicate it exercises.
	IsPositiveControl *bool `json:"is_positive_control"` // True when this test asserts a row the principal IS entitled to. A denial suite with no positive controls cannot distinguish a working policy from one that denies everything.
	ForbiddenTable *string `json:"forbidden_table"` // For a table-absence witness: the table that must NOT exist in this principal's schema. Selecting it must raise 'relation does not exist', not return zero rows.
	ForbiddenColumn *string `json:"forbidden_column"` // For a column-absence witness: the column that must NOT exist in this principal's view. Selecting it must raise 'column does not exist', not return null.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias.
// Formula: ={{Principal}} & " must not see " & {{ForbiddenRowId}}
func (tc *AccessDenialTest) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Principal)), vS(" must not see "), erbText(vStr(tc.ForbiddenRowId))))
}

// CalcHasRun computes the HasRun calculated field
// True once the test has been executed at least once.
// Formula: ={{LastRunAt}} <> ""
func (tc *AccessDenialTest) CalcHasRun() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.LastRunAt)))
}

// CalcIsPassing computes the IsPassing calculated field
// True when observed visibility matches expectation.
// Formula: ={{ObservedVisible}} = {{ExpectedVisible}}
func (tc *AccessDenialTest) CalcIsPassing() *bool {
	return toBoolPtr(erbEq(erbNullif(vBool(tc.ObservedVisible)), erbNullif(vBool(tc.ExpectedVisible))))
}

// CalcIsLeak computes the IsLeak calculated field
// True when a row that must be invisible was returned. A confirmed access-control breach.
// Formula: =AND(NOT({{ExpectedVisible}}), {{ObservedVisible}})
func (tc *AccessDenialTest) CalcIsLeak() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNot(erbIsTrue(vBool(tc.ExpectedVisible)))), erbIsTrue(vBool(tc.ObservedVisible))))
}

// CalcIsUnproven computes the IsUnproven calculated field
// True when the test has never run, so it proves nothing regardless of how it is written.
// Formula: =NOT({{HasRun}})
func (tc *AccessDenialTest) CalcIsUnproven() *bool {
	return toBoolPtr(erbNot(erbBool3(vBool(tc.HasRun))))
}

// CalcIsPositiveControl computes the IsPositiveControl calculated field
// True when this test asserts a row the principal IS entitled to. A denial suite with no positive controls cannot distinguish a working policy from one that denies everything.
// Formula: ={{ExpectedVisible}}
func (tc *AccessDenialTest) CalcIsPositiveControl() *bool {
	return toBoolPtr(vBool(tc.ExpectedVisible))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *AccessDenialTest) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_run", func() { tc.HasRun = tc.CalcHasRun() })
	calcGuard(tc, "is_passing", func() { tc.IsPassing = tc.CalcIsPassing() })
	calcGuard(tc, "is_leak", func() { tc.IsLeak = tc.CalcIsLeak() })
	calcGuard(tc, "is_positive_control", func() { tc.IsPositiveControl = tc.CalcIsPositiveControl() })
	// Level 2
	calcGuard(tc, "is_unproven", func() { tc.IsUnproven = tc.CalcIsUnproven() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *AccessDenialTest) ComputeAll() *AccessDenialTest {
	tc.erbComputeCalculations()
	return tc
}

