// =============================================================================
// APPUSERS TABLE
// Sign-in identities. One row per person or automation that can authenticate. EmailAddress is what a verified token asserts; everything else about the caller is resolved from here inside the database, never trusted from the token.
// =============================================================================

// AppUser represents a row in the AppUsers table
type AppUser struct {
	AppUserId string `json:"app_user_id"` // Stored logical identifier, e.g. 'user-maria-chen'.
	Name *string `json:"name"` // Human-readable calculated display alias.
	EmailAddress *string `json:"email_address"` // Verified email. The one claim magic-links vouches for, and the join key from a token back to this row.
	DisplayName *string `json:"display_name"` // Name shown in the console.
	LinkedAgent *string `json:"linked_agent"` // Domain agent this sign-in identity corresponds to.
	IsEnabled *bool `json:"is_enabled"` // False disables sign-in without deleting the identity or its history.
	AgentKind *string `json:"agent_kind"` // Whether the linked agent is Human, AIAgent or AutomatedPipeline.
	Organization *string `json:"organization"` // Organization inherited from the linked agent; the tenancy claim baked into issued tokens.
	AssignmentCount *float64 `json:"assignment_count"` // Number of principals this user may act as.
	HasNoPrincipal *bool `json:"has_no_principal"` // True when the user may act as no principal at all, so a successfully verified token still grants nothing. Authentication without authorization.
	HoldsMultiplePrincipals *bool `json:"holds_multiple_principals"` // True when the user may act as more than one principal, so the principal cannot be inferred from the email alone and must be chosen explicitly at sign-in.
	IsNonHumanSignIn *bool `json:"is_non_human_sign_in"` // True when a non-human agent has a sign-in identity. Pipelines and AI agents authenticate too, and their tokens are scoped exactly like a person's.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias.
// Formula: ={{DisplayName}}
func (tc *AppUser) CalcName() *string {
	return toStringPtr(vStr(tc.DisplayName))
}

// CalcHasNoPrincipal computes the HasNoPrincipal calculated field
// True when the user may act as no principal at all, so a successfully verified token still grants nothing. Authentication without authorization.
// Formula: ={{AssignmentCount}} = 0
func (tc *AppUser) CalcHasNoPrincipal() *bool {
	return toBoolPtr(erbEq(vNum(tc.AssignmentCount), vI(0)))
}

// CalcHoldsMultiplePrincipals computes the HoldsMultiplePrincipals calculated field
// True when the user may act as more than one principal, so the principal cannot be inferred from the email alone and must be chosen explicitly at sign-in.
// Formula: ={{AssignmentCount}} > 1
func (tc *AppUser) CalcHoldsMultiplePrincipals() *bool {
	return toBoolPtr(erbCmp(vNum(tc.AssignmentCount), ">", vI(1)))
}

// CalcIsNonHumanSignIn computes the IsNonHumanSignIn calculated field
// True when a non-human agent has a sign-in identity. Pipelines and AI agents authenticate too, and their tokens are scoped exactly like a person's.
// Formula: =OR({{AgentKind}} = "AIAgent", {{AgentKind}} = "AutomatedPipeline")
func (tc *AppUser) CalcIsNonHumanSignIn() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(vStr(tc.AgentKind), vS("AIAgent"))), erbBool3(erbEq(vStr(tc.AgentKind), vS("AutomatedPipeline")))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *AppUser) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_no_principal", func() { tc.HasNoPrincipal = tc.CalcHasNoPrincipal() })
	calcGuard(tc, "holds_multiple_principals", func() { tc.HoldsMultiplePrincipals = tc.CalcHoldsMultiplePrincipals() })
	calcGuard(tc, "is_non_human_sign_in", func() { tc.IsNonHumanSignIn = tc.CalcIsNonHumanSignIn() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *AppUser) ComputeAll() *AppUser {
	tc.erbComputeCalculations()
	return tc
}

