// =============================================================================
// VOCABULARIES TABLE
// A controlled vocabulary / SKOS-style concept scheme — one facet of standardized terminology (e.g. a family of control categories) that Requirements and other rows can point at instead of restating the concept in free text each time.
// =============================================================================

// Vocabularie represents a row in the Vocabularies table
type Vocabularie struct {
	VocabularyId string `json:"vocabulary_id"` // Stored logical identifier for one Vocabularies row.
	Name *string `json:"name"` // Human-readable calculated display alias for the Vocabularies row.
	Title *string `json:"title"` // Human-facing name of this controlled vocabulary.
	SchemeUri *string `json:"scheme_uri"` // SKOS ConceptScheme IRI for this vocabulary.
	GoverningRole *string `json:"governing_role"` // Role accountable for defining and maintaining terms in this vocabulary.
	TermCount *float64 `json:"term_count"` // How many terms belong to this vocabulary.
	OrphanTermCount *float64 `json:"orphan_term_count"` // How many terms in this vocabulary have never actually been used.
	HasOrphanTerms *bool `json:"has_orphan_terms"` // TRUE when this vocabulary has at least one defined-but-unused term.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension class IRI.
	SchemeKind *string `json:"scheme_kind"` // ControlledVocabulary, Taxonomy or Thesaurus.
	ModelLayer *string `json:"model_layer"` // VocabularyLayer for controlled concept schemes, kept apart from the ontology layer.
	GovernedDimension *string `json:"governed_dimension"` // What the scheme controls: Activity, Role, WorkflowStatus, ArtifactType, AgentCapability, ...
	PublicationFormat *string `json:"publication_format"` // How the scheme is published: SKOS Turtle, or a PDF glossary.
	Prefix *string `json:"prefix"` // Namespace prefix.
	EstablishedAt *string `json:"established_at"` // When vocabulary control was established.
	OntologyModelingStartedAt *string `json:"ontology_modeling_started_at"` // When ontology modeling for the same domain began.
	GovernsProcedure *string `json:"governs_procedure"` // Procedure whose knowledge the scheme controls.
	IsMachineAccessible *bool `json:"is_machine_accessible"` // TRUE when the scheme has an IRI and is published as SKOS.
	ManagedSchemeProcedureKey *string `json:"managed_scheme_procedure_key"` // Procedure key when the scheme's metadata is managed.
	OrganizedTranscriptCount *int `json:"organized_transcript_count"` // Transcript materials organized into the scheme.
	OrganizedFieldNotesCount *int `json:"organized_field_notes_count"` // FieldNotes materials organized into the scheme.
	OrganizedProcessMapCount *int `json:"organized_process_map_count"` // ProcessMap materials organized into the scheme.
	OrganizedMinedEventTraceCount *int `json:"organized_mined_event_trace_count"` // MinedEventTrace materials organized into the scheme.
	OrganizedDocumentExcerptCount *int `json:"organized_document_excerpt_count"` // DocumentExcerpt materials organized into the scheme.
	OrganizedMaterialCount *int `json:"organized_material_count"` // Materials organized into the scheme.
	OrganizedKindCount *int `json:"organized_kind_count"` // Different kinds of material the scheme holds.
	IsSingleKindFrame *bool `json:"is_single_kind_frame"` // TRUE when a scheme organizes several materials but only one kind of knowledge.
	LatestOrganizedMaterialAt *string `json:"latest_organized_material_at"` // Most recent collection date among materials organized into the scheme.
	RefinementCount *int `json:"refinement_count"` // Refinements made to the scheme.
	IsFrozenDespiteNewCollection *bool `json:"is_frozen_despite_new_collection"` // TRUE when material collected after the scheme was established has never led to a refinement.
	OntologyPrecededVocabularyControl *bool `json:"ontology_preceded_vocabulary_control"` // TRUE when ontology modeling began before vocabulary control was established for the domain.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Vocabularies row.
// Formula: ={{Title}}
func (tc *Vocabularie) CalcName() *string {
	return toStringPtr(vStr(tc.Title))
}

// CalcHasOrphanTerms computes the HasOrphanTerms calculated field
// TRUE when this vocabulary has at least one defined-but-unused term.
// Formula: ={{OrphanTermCount}} > 0
func (tc *Vocabularie) CalcHasOrphanTerms() *bool {
	return toBoolPtr(erbCmp(vNum(tc.OrphanTermCount), ">", vI(0)))
}

// CalcIsMachineAccessible computes the IsMachineAccessible calculated field
// TRUE when the scheme has an IRI and is published as SKOS.
// Formula: =AND({{SchemeUri}} <> "", {{PublicationFormat}} = "SKOS Turtle")
func (tc *Vocabularie) CalcIsMachineAccessible() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.SchemeUri))), erbBool3(erbEq(erbNullif(vStr(tc.PublicationFormat)), vS("SKOS Turtle")))))
}

// CalcManagedSchemeProcedureKey computes the ManagedSchemeProcedureKey calculated field
// Procedure key when the scheme's metadata is managed.
// Formula: =IF(AND({{GoverningRole}} <> "", {{EstablishedAt}} <> ""), {{GovernsProcedure}}, "")
func (tc *Vocabularie) CalcManagedSchemeProcedureKey() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.GoverningRole))), erbBool3(erbIsNotBlank(vStr(tc.EstablishedAt))))), func() Value { return vStr(tc.GovernsProcedure) }, func() Value { return vS("") }))
}

// CalcOrganizedKindCount computes the OrganizedKindCount calculated field
// Different kinds of material the scheme holds.
// Formula: =IF({{OrganizedTranscriptCount}} > 0, 1, 0) + IF({{OrganizedFieldNotesCount}} > 0, 1, 0) + IF({{OrganizedProcessMapCount}} > 0, 1, 0) + IF({{OrganizedMinedEventTraceCount}} > 0, 1, 0) + IF({{OrganizedDocumentExcerptCount}} > 0, 1, 0)
func (tc *Vocabularie) CalcOrganizedKindCount() *int {
	return toIntPtr(erbInteger(erbAdd(erbAdd(erbAdd(erbAdd(erbIf(erbBool3(erbCmp(vInt(tc.OrganizedTranscriptCount), ">", vI(0))), func() Value { return vI(1) }, func() Value { return vI(0) }), erbIf(erbBool3(erbCmp(vInt(tc.OrganizedFieldNotesCount), ">", vI(0))), func() Value { return vI(1) }, func() Value { return vI(0) })), erbIf(erbBool3(erbCmp(vInt(tc.OrganizedProcessMapCount), ">", vI(0))), func() Value { return vI(1) }, func() Value { return vI(0) })), erbIf(erbBool3(erbCmp(vInt(tc.OrganizedMinedEventTraceCount), ">", vI(0))), func() Value { return vI(1) }, func() Value { return vI(0) })), erbIf(erbBool3(erbCmp(vInt(tc.OrganizedDocumentExcerptCount), ">", vI(0))), func() Value { return vI(1) }, func() Value { return vI(0) }))))
}

// CalcIsSingleKindFrame computes the IsSingleKindFrame calculated field
// TRUE when a scheme organizes several materials but only one kind of knowledge.
// Formula: =AND({{OrganizedMaterialCount}} >= 2, {{OrganizedKindCount}} = 1)
func (tc *Vocabularie) CalcIsSingleKindFrame() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.OrganizedMaterialCount), ">=", vI(2))), erbBool3(erbEq(vInt(tc.OrganizedKindCount), vI(1)))))
}

// CalcIsFrozenDespiteNewCollection computes the IsFrozenDespiteNewCollection calculated field
// TRUE when material collected after the scheme was established has never led to a refinement.
// Formula: =AND({{EstablishedAt}} <> "", {{LatestOrganizedMaterialAt}} <> "", {{LatestOrganizedMaterialAt}} > {{EstablishedAt}}, {{RefinementCount}} = 0)
func (tc *Vocabularie) CalcIsFrozenDespiteNewCollection() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.EstablishedAt))), erbBool3(erbIsNotBlank(vStr(tc.LatestOrganizedMaterialAt))), erbBool3(erbCmp(vStr(tc.LatestOrganizedMaterialAt), ">", erbNullif(vStr(tc.EstablishedAt)))), erbBool3(erbEq(vInt(tc.RefinementCount), vI(0)))))
}

// CalcOntologyPrecededVocabularyControl computes the OntologyPrecededVocabularyControl calculated field
// TRUE when ontology modeling began before vocabulary control was established for the domain.
// Formula: =AND({{OntologyModelingStartedAt}} <> "", OR({{EstablishedAt}} = "", {{OntologyModelingStartedAt}} < {{EstablishedAt}}))
func (tc *Vocabularie) CalcOntologyPrecededVocabularyControl() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.OntologyModelingStartedAt))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.EstablishedAt))), erbBool3(erbCmp(erbNullif(vStr(tc.OntologyModelingStartedAt)), "<", erbNullif(vStr(tc.EstablishedAt))))))))
}

