// =============================================================================
// KNOWLEDGEBROKERLINKS TABLE
// An informal expertise-network edge: one agent naming another as who they actually go to for a topic, independent of any formal Role or RoleAssignment. RoleAssignments and CommunitiesOfPractice record who is SUPPOSED to know something; this records who people ACTUALLY rely on.
// =============================================================================

// KnowledgeBrokerLink represents a row in the KnowledgeBrokerLinks table
type KnowledgeBrokerLink struct {
	KnowledgeBrokerLinkId string `json:"knowledge_broker_link_id"` // Stored logical identifier for one KnowledgeBrokerLinks row.
	Name *string `json:"name"` // Human-readable calculated display alias for the KnowledgeBrokerLinks row.
	Seeker *string `json:"seeker"` // The agent who goes to someone else for this topic.
	Broker *string `json:"broker"` // The agent who is actually consulted, whether or not they hold a formal role for it.
	Topic *string `json:"topic"` // The controlled topic this reliance is about.
	Frequency *string `json:"frequency"` // Rarely, Sometimes, or Often.
	LastConsultedAt *string `json:"last_consulted_at"` // When the seeker last actually consulted the broker on this topic.
	EvaluationContext *string `json:"evaluation_context"` // The evaluation context this row's time-dependent witnesses are judged under.
	AsOfInstant *string `json:"as_of_instant"` // The evaluation instant this row's time-dependent witnesses are judged under.
	DaysSinceConsulted *int `json:"days_since_consulted"` // Days elapsed since the seeker last consulted the broker.
	IsActiveReliance *bool `json:"is_active_reliance"` // TRUE when this is a live, ongoing informal dependency rather than a one-off or stale contact.
	BrokerIsStillEngaged *bool `json:"broker_is_still_engaged"` // Whether the broker being relied on still holds any current role at all.
	IsAtRiskReliance *bool `json:"is_at_risk_reliance"` // TRUE when someone is actively relying on a broker who has already left every role they held.
	ActiveRelianceBrokerKey *string `json:"active_reliance_broker_key"` // Composite-key echo: the broker this link names when the reliance is active, else blank.
	AtRiskBrokerKey *string `json:"at_risk_broker_key"` // Composite-key echo: the broker this link names when the reliance is at risk, else blank.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension class IRI.
	PointsToKnowHow *string `json:"points_to_know_how"` // The know-how the broker points the seeker to.
	PointedHolder *string `json:"pointed_holder"` // Who carries that know-how.
	LocatesOtherHolder *bool `json:"locates_other_holder"` // TRUE when the broker knows where know-how is held by someone other than themselves.
	SeekerVocabulary *string `json:"seeker_vocabulary"` // The vocabulary the seeker's community speaks.
	SeekerWording *string `json:"seeker_wording"` // The seeker's word for the topic.
	HolderVocabulary *string `json:"holder_vocabulary"` // The vocabulary of the community holding the know-how.
	HolderWording *string `json:"holder_wording"` // The holding community's word for the topic.
	TranslationBetweenVocabularies *string `json:"translation_between_vocabularies"` // The broker's translation between the two communities' words; blank when none was needed.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the KnowledgeBrokerLinks row.
// Formula: ={{Seeker}} & " -> " & {{Broker}}
func (tc *KnowledgeBrokerLink) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Seeker)), vS(" -> "), erbText(vStr(tc.Broker))))
}

// CalcDaysSinceConsulted computes the DaysSinceConsulted calculated field
// Days elapsed since the seeker last consulted the broker.
// Formula: =DATETIME_DIFF({{AsOfInstant}}, {{LastConsultedAt}}, "days")
func (tc *KnowledgeBrokerLink) CalcDaysSinceConsulted() *int {
	return toIntPtr(erbInteger(erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.LastConsultedAt), vS("days"))))
}

// CalcIsActiveReliance computes the IsActiveReliance calculated field
// TRUE when this is a live, ongoing informal dependency rather than a one-off or stale contact.
// Formula: =AND(NOT({{Frequency}} = "Rarely"), {{DaysSinceConsulted}} <= 180)
func (tc *KnowledgeBrokerLink) CalcIsActiveReliance() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNot(erbBool3(erbEq(erbNullif(vStr(tc.Frequency)), vS("Rarely"))))), erbBool3(erbCmp(vInt(tc.DaysSinceConsulted), "<=", vI(180)))))
}

// CalcIsAtRiskReliance computes the IsAtRiskReliance calculated field
// TRUE when someone is actively relying on a broker who has already left every role they held.
// Formula: =AND({{IsActiveReliance}}, NOT({{BrokerIsStillEngaged}}))
func (tc *KnowledgeBrokerLink) CalcIsAtRiskReliance() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsActiveReliance)), erbBool3(erbNot(erbBool3(vBool(tc.BrokerIsStillEngaged))))))
}

// CalcActiveRelianceBrokerKey computes the ActiveRelianceBrokerKey calculated field
// Composite-key echo: the broker this link names when the reliance is active, else blank.
// Formula: =IF({{IsActiveReliance}}, {{Broker}}, "")
func (tc *KnowledgeBrokerLink) CalcActiveRelianceBrokerKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsActiveReliance)), func() Value { return vStr(tc.Broker) }, func() Value { return vS("") }))
}

// CalcAtRiskBrokerKey computes the AtRiskBrokerKey calculated field
// Composite-key echo: the broker this link names when the reliance is at risk, else blank.
// Formula: =IF({{IsAtRiskReliance}}, {{Broker}}, "")
func (tc *KnowledgeBrokerLink) CalcAtRiskBrokerKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsAtRiskReliance)), func() Value { return vStr(tc.Broker) }, func() Value { return vS("") }))
}

// CalcLocatesOtherHolder computes the LocatesOtherHolder calculated field
// TRUE when the broker knows where know-how is held by someone other than themselves.
// Formula: =AND({{PointsToKnowHow}} <> "", {{PointedHolder}} <> "", {{PointedHolder}} <> {{Broker}})
func (tc *KnowledgeBrokerLink) CalcLocatesOtherHolder() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.PointsToKnowHow))), erbBool3(erbIsNotBlank(vStr(tc.PointedHolder))), erbBool3(erbNe(vStr(tc.PointedHolder), erbNullif(vStr(tc.Broker))))))
}

// CalcTranslationBetweenVocabularies computes the TranslationBetweenVocabularies calculated field
// The broker's translation between the two communities' words; blank when none was needed.
// Formula: =IF(AND({{SeekerVocabulary}} <> "", {{HolderVocabulary}} <> "", {{SeekerVocabulary}} <> {{HolderVocabulary}}), CONCAT({{SeekerWording}}, " (", {{SeekerVocabulary}}, ") = ", {{HolderWording}}, " (", {{HolderVocabulary}}, ")"), "")
func (tc *KnowledgeBrokerLink) CalcTranslationBetweenVocabularies() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.SeekerVocabulary))), erbBool3(erbIsNotBlank(vStr(tc.HolderVocabulary))), erbBool3(erbNe(erbNullif(vStr(tc.SeekerVocabulary)), erbNullif(vStr(tc.HolderVocabulary)))))), func() Value { return erbConcat(erbText(vStr(tc.SeekerWording)), vS(" ("), erbText(vStr(tc.SeekerVocabulary)), vS(") = "), erbText(vStr(tc.HolderWording)), vS(" ("), erbText(vStr(tc.HolderVocabulary)), vS(")")) }, func() Value { return vS("") }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *KnowledgeBrokerLink) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "days_since_consulted", func() { tc.DaysSinceConsulted = tc.CalcDaysSinceConsulted() })
	calcGuard(tc, "locates_other_holder", func() { tc.LocatesOtherHolder = tc.CalcLocatesOtherHolder() })
	calcGuard(tc, "translation_between_vocabularies", func() { tc.TranslationBetweenVocabularies = tc.CalcTranslationBetweenVocabularies() })
	// Level 2
	calcGuard(tc, "is_active_reliance", func() { tc.IsActiveReliance = tc.CalcIsActiveReliance() })
	// Level 3
	calcGuard(tc, "is_at_risk_reliance", func() { tc.IsAtRiskReliance = tc.CalcIsAtRiskReliance() })
	calcGuard(tc, "active_reliance_broker_key", func() { tc.ActiveRelianceBrokerKey = tc.CalcActiveRelianceBrokerKey() })
	// Level 4
	calcGuard(tc, "at_risk_broker_key", func() { tc.AtRiskBrokerKey = tc.CalcAtRiskBrokerKey() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *KnowledgeBrokerLink) ComputeAll() *KnowledgeBrokerLink {
	tc.erbComputeCalculations()
	return tc
}

