// =============================================================================
// CLAIMEVIDENCE TABLE
// A proposed piece of evidence that the model covers a claim, with the justification a skeptic can audit. Whether it counts is computed in IsValid from measured facts, never asserted.
// =============================================================================

// ClaimEvidence represents a row in the ClaimEvidence table
type ClaimEvidence struct {
	ClaimEvidenceId string `json:"claim_evidence_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	ArticleClaim *string `json:"article_claim"` // The claim this evidence supports.
	EvidenceKind *string `json:"evidence_kind"` // Field | Table | RoleQuestion | OntologyProfile | KnowledgeMethod | Procedure.
	RulebookField *string `json:"rulebook_field"` // Evidence field, when EvidenceKind is Field.
	RulebookTable *string `json:"rulebook_table"` // Evidence table, when EvidenceKind is Table.
	RoleQuestion *string `json:"role_question"` // Evidence question, when EvidenceKind is RoleQuestion.
	OntologyProfile *string `json:"ontology_profile"` // Evidence profile, when EvidenceKind is OntologyProfile.
	KnowledgeMethod *string `json:"knowledge_method"` // Evidence method, when EvidenceKind is KnowledgeMethod.
	Procedure *string `json:"procedure"` // Evidence procedure, when EvidenceKind is Procedure.
	Justification *string `json:"justification"` // How this evidence answers the claim, in words a skeptic can check.
	ClaimKind *string `json:"claim_kind"` // Kind of the claim this evidence supports.
	FieldCatalogName *string `json:"field_catalog_name"` // The evidence field's name as the catalog records it; blank when the field does not exist.
	FieldIsWitness *bool `json:"field_is_witness"` // Whether the evidence field was invented for a role question.
	FieldHasData *bool `json:"field_has_data"` // Whether Postgres holds data for the evidence field.
	FieldIsDiscriminating *bool `json:"field_is_discriminating"` // Whether the evidence field tells rows apart.
	FieldIsContested *bool `json:"field_is_contested"` // Whether a graded substrate disagrees on the evidence field.
	TableHasRows *bool `json:"table_has_rows"` // Whether Postgres holds rows of the evidence table.
	QuestionIsAnswered *bool `json:"question_is_answered"` // Whether the evidence question has predicates.
	QuestionWitnessedAnswer *string `json:"question_witnessed_answer"` // The substrate-computed answer of the evidence question.
	ProfileMappingCount *int `json:"profile_mapping_count"` // Semantic mappings using the evidence profile.
	MethodIsApplied *bool `json:"method_is_applied"` // Whether a seeded row applies the evidence method.
	ProcedureExecutionCount *int `json:"procedure_execution_count"` // Recorded executions of the evidence procedure.
	HasJustification *bool `json:"has_justification"` // TRUE when the justification is written.
	IsWitnessProof *bool `json:"is_witness_proof"` // Evidence is an existing field invented for a role question that discriminates.
	IsStructuralProof *bool `json:"is_structural_proof"` // Evidence is a table with rows or a field with data.
	IsQuestionProof *bool `json:"is_question_proof"` // Evidence is an answered role question with a computed answer.
	IsStandardProof *bool `json:"is_standard_proof"` // Evidence is a mapped ontology profile or an applied knowledge method.
	IsScenarioProof *bool `json:"is_scenario_proof"` // Evidence is a procedure with recorded executions.
	IsValid *bool `json:"is_valid"` // TRUE when the evidence is justified and is the kind of proof this claim's kind demands.
	IsContested *bool `json:"is_contested"` // TRUE when the evidence field is disputed by a graded substrate.
	IsAgreedEvidence *bool `json:"is_agreed_evidence"` // TRUE when the evidence is valid and no graded substrate disputes it.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{ArticleClaim}} & " <- " & {{EvidenceKind}}
func (tc *ClaimEvidence) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ArticleClaim)), vS(" <- "), erbText(vStr(tc.EvidenceKind))))
}

// CalcHasJustification computes the HasJustification calculated field
// TRUE when the justification is written.
// Formula: ={{Justification}} <> ""
func (tc *ClaimEvidence) CalcHasJustification() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.Justification)))
}

// CalcIsWitnessProof computes the IsWitnessProof calculated field
// Evidence is an existing field invented for a role question that discriminates.
// Formula: =AND({{EvidenceKind}} = "Field", {{FieldCatalogName}} <> "", {{FieldIsWitness}}, {{FieldIsDiscriminating}})
func (tc *ClaimEvidence) CalcIsWitnessProof() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.EvidenceKind)), vS("Field"))), erbBool3(erbIsNotBlank(vStr(tc.FieldCatalogName))), erbBool3(vBool(tc.FieldIsWitness)), erbBool3(vBool(tc.FieldIsDiscriminating))))
}

// CalcIsStructuralProof computes the IsStructuralProof calculated field
// Evidence is a table with rows or a field with data.
// Formula: =OR(AND({{EvidenceKind}} = "Table", {{TableHasRows}}), AND({{EvidenceKind}} = "Field", {{FieldCatalogName}} <> "", {{FieldHasData}}))
func (tc *ClaimEvidence) CalcIsStructuralProof() *bool {
	return toBoolPtr(erbOr(erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.EvidenceKind)), vS("Table"))), erbBool3(vBool(tc.TableHasRows)))), erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.EvidenceKind)), vS("Field"))), erbBool3(erbIsNotBlank(vStr(tc.FieldCatalogName))), erbBool3(vBool(tc.FieldHasData))))))
}

// CalcIsQuestionProof computes the IsQuestionProof calculated field
// Evidence is an answered role question with a computed answer.
// Formula: =AND({{EvidenceKind}} = "RoleQuestion", {{QuestionIsAnswered}}, {{QuestionWitnessedAnswer}} <> "")
func (tc *ClaimEvidence) CalcIsQuestionProof() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.EvidenceKind)), vS("RoleQuestion"))), erbBool3(vBool(tc.QuestionIsAnswered)), erbBool3(erbIsNotBlank(vStr(tc.QuestionWitnessedAnswer)))))
}

// CalcIsStandardProof computes the IsStandardProof calculated field
// Evidence is a mapped ontology profile or an applied knowledge method.
// Formula: =OR(AND({{EvidenceKind}} = "OntologyProfile", {{ProfileMappingCount}} > 0), AND({{EvidenceKind}} = "KnowledgeMethod", {{MethodIsApplied}}))
func (tc *ClaimEvidence) CalcIsStandardProof() *bool {
	return toBoolPtr(erbOr(erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.EvidenceKind)), vS("OntologyProfile"))), erbBool3(erbCmp(vInt(tc.ProfileMappingCount), ">", vI(0))))), erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.EvidenceKind)), vS("KnowledgeMethod"))), erbBool3(vBool(tc.MethodIsApplied))))))
}

// CalcIsScenarioProof computes the IsScenarioProof calculated field
// Evidence is a procedure with recorded executions.
// Formula: =AND({{EvidenceKind}} = "Procedure", {{ProcedureExecutionCount}} > 0)
func (tc *ClaimEvidence) CalcIsScenarioProof() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.EvidenceKind)), vS("Procedure"))), erbBool3(erbCmp(vInt(tc.ProcedureExecutionCount), ">", vI(0)))))
}

// CalcIsValid computes the IsValid calculated field
// TRUE when the evidence is justified and is the kind of proof this claim's kind demands.
// Formula: =AND({{HasJustification}}, OR(AND(OR({{ClaimKind}} = "Prescription", {{ClaimKind}} = "Illustration"), {{IsWitnessProof}}), AND({{ClaimKind}} = "Concept", {{IsStructuralProof}}), AND({{ClaimKind}} = "CompetencyQuestion", {{IsQuestionProof}}), AND({{ClaimKind}} = "Standard", {{IsStandardProof}}), AND({{ClaimKind}} = "Scenario", {{IsScenarioProof}})))
func (tc *ClaimEvidence) CalcIsValid() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasJustification)), erbBool3(erbOr(erbBool3(erbAnd(erbBool3(erbOr(erbBool3(erbEq(vStr(tc.ClaimKind), vS("Prescription"))), erbBool3(erbEq(vStr(tc.ClaimKind), vS("Illustration"))))), erbBool3(vBool(tc.IsWitnessProof)))), erbBool3(erbAnd(erbBool3(erbEq(vStr(tc.ClaimKind), vS("Concept"))), erbBool3(vBool(tc.IsStructuralProof)))), erbBool3(erbAnd(erbBool3(erbEq(vStr(tc.ClaimKind), vS("CompetencyQuestion"))), erbBool3(vBool(tc.IsQuestionProof)))), erbBool3(erbAnd(erbBool3(erbEq(vStr(tc.ClaimKind), vS("Standard"))), erbBool3(vBool(tc.IsStandardProof)))), erbBool3(erbAnd(erbBool3(erbEq(vStr(tc.ClaimKind), vS("Scenario"))), erbBool3(vBool(tc.IsScenarioProof))))))))
}

// CalcIsContested computes the IsContested calculated field
// TRUE when the evidence field is disputed by a graded substrate.
// Formula: =AND({{EvidenceKind}} = "Field", {{FieldIsContested}})
func (tc *ClaimEvidence) CalcIsContested() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.EvidenceKind)), vS("Field"))), erbBool3(vBool(tc.FieldIsContested))))
}

// CalcIsAgreedEvidence computes the IsAgreedEvidence calculated field
// TRUE when the evidence is valid and no graded substrate disputes it.
// Formula: =AND({{IsValid}}, {{IsContested}} = FALSE)
func (tc *ClaimEvidence) CalcIsAgreedEvidence() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsValid)), erbBool3(erbEq(vBool(tc.IsContested), vB(false)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ClaimEvidence) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_justification", func() { tc.HasJustification = tc.CalcHasJustification() })
	calcGuard(tc, "is_witness_proof", func() { tc.IsWitnessProof = tc.CalcIsWitnessProof() })
	calcGuard(tc, "is_structural_proof", func() { tc.IsStructuralProof = tc.CalcIsStructuralProof() })
	calcGuard(tc, "is_question_proof", func() { tc.IsQuestionProof = tc.CalcIsQuestionProof() })
	calcGuard(tc, "is_standard_proof", func() { tc.IsStandardProof = tc.CalcIsStandardProof() })
	calcGuard(tc, "is_scenario_proof", func() { tc.IsScenarioProof = tc.CalcIsScenarioProof() })
	calcGuard(tc, "is_contested", func() { tc.IsContested = tc.CalcIsContested() })
	// Level 2
	calcGuard(tc, "is_valid", func() { tc.IsValid = tc.CalcIsValid() })
	// Level 3
	calcGuard(tc, "is_agreed_evidence", func() { tc.IsAgreedEvidence = tc.CalcIsAgreedEvidence() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ClaimEvidence) ComputeAll() *ClaimEvidence {
	tc.erbComputeCalculations()
	return tc
}

