// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Step}} & " " & {{Direction}} & " " & {{Label}}
func (tc *StepVariable) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Step)), vS(" "), erbText(vStr(tc.Direction)), vS(" "), erbText(vStr(tc.Label))))
}

// CalcIsDanglingInput computes the IsDanglingInput calculated field
// TRUE for an input no earlier step produces and nobody declared as external: the step cannot be run as specified.
// Formula: =AND({{Direction}} = "Input", {{SourceVariable}} = "", {{IsExternalInput}} = FALSE)
func (tc *StepVariable) CalcIsDanglingInput() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.Direction)), vS("Input"))), erbBool3(erbIsBlank(vStr(tc.SourceVariable))), erbBool3(erbEq(erbNullif(vBool(tc.IsExternalInput)), vB(false)))))
}

// CalcIsMiswiredSource computes the IsMiswiredSource calculated field
// TRUE when an input is fed from a variable that is not an output.
// Formula: =AND({{SourceVariable}} <> "", {{SourceDirection}} <> "Output")
func (tc *StepVariable) CalcIsMiswiredSource() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.SourceVariable))), erbBool3(erbNe(vStr(tc.SourceDirection), vS("Output")))))
}

