// AUTHORINGSUBMISSIONS TABLE
// Procedures submitted through the no-code capture form, validated against the PKO profile.
// =============================================================================

// AuthoringSubmission represents a row in the AuthoringSubmissions table
type AuthoringSubmission struct {
	AuthoringSubmissionId string `json:"authoring_submission_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	ProcedureVersion *string `json:"procedure_version"` // Version the submission authors.
	SubmittedByAgent *string `json:"submitted_by_agent"` // Who submitted it.
	SubmittedAt *string `json:"submitted_at"` // When.
	AuthoringTool *string `json:"authoring_tool"` // Tool used.
	SubmitterExpertise *string `json:"submitter_expertise"` // DomainExpert or KnowledgeEngineer.
	StepCount *int `json:"step_count"` // Steps authored.
	ProfileValidationPassed *bool `json:"profile_validation_passed"` // Whether it validated against the PKO profile.
	ValidationErrorCount *int `json:"validation_error_count"` // Profile violations found.
	WasAccepted *bool `json:"was_accepted"` // Whether it was accepted into the rulebook.
	IsExpertAuthoredConforming *bool `json:"is_expert_authored_conforming"` // TRUE when a domain expert with no ontology training produced a submission that conforms to the profile.
	IsNonConformingAccepted *bool `json:"is_non_conforming_accepted"` // TRUE when a submission that failed profile validation was accepted anyway.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{ProcedureVersion}} & " by " & {{SubmittedByAgent}}
func (tc *AuthoringSubmission) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ProcedureVersion)), vS(" by "), erbText(vStr(tc.SubmittedByAgent))))
}

// CalcIsExpertAuthoredConforming computes the IsExpertAuthoredConforming calculated field
// TRUE when a domain expert with no ontology training produced a submission that conforms to the profile.
// Formula: =AND({{SubmitterExpertise}} = "DomainExpert", {{ProfileValidationPassed}})
func (tc *AuthoringSubmission) CalcIsExpertAuthoredConforming() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.SubmitterExpertise)), vS("DomainExpert"))), erbIsTrue(vBool(tc.ProfileValidationPassed))))
}

// CalcIsNonConformingAccepted computes the IsNonConformingAccepted calculated field
// TRUE when a submission that failed profile validation was accepted anyway.
// Formula: =AND({{WasAccepted}}, {{ProfileValidationPassed}} = FALSE)
func (tc *AuthoringSubmission) CalcIsNonConformingAccepted() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.WasAccepted)), erbBool3(erbEq(erbNullif(vBool(tc.ProfileValidationPassed)), vB(false)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *AuthoringSubmission) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_expert_authored_conforming", func() { tc.IsExpertAuthoredConforming = tc.CalcIsExpertAuthoredConforming() })
	calcGuard(tc, "is_non_conforming_accepted", func() { tc.IsNonConformingAccepted = tc.CalcIsNonConformingAccepted() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *AuthoringSubmission) ComputeAll() *AuthoringSubmission {
	tc.erbComputeCalculations()
	return tc
}

