func (tc *TacticalResourceAllocation) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Step)), vS(" / "), erbText(vStr(tc.ResourceLabel))))
}

// CalcUtilizationPercent computes the UtilizationPercent calculated field
// Demand as a percentage of capacity.
// Formula: =IF({{AvailableUnitsPerWeek}} = 0, 0, ROUND({{DemandedUnitsPerWeek}} * 100 / {{AvailableUnitsPerWeek}}, 1))
func (tc *TacticalResourceAllocation) CalcUtilizationPercent() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbEq(erbNullif(vNum(tc.AvailableUnitsPerWeek)), vI(0))), func() Value { return vI(0) }, func() Value { return erbRound(erbDiv(erbMul(vNum(tc.DemandedUnitsPerWeek), vI(100)), vNum(tc.AvailableUnitsPerWeek)), vI(1)) }))
}

// CalcIsBottleneck computes the IsBottleneck calculated field
// TRUE when demand on the resource exceeds the capacity allocated to it.
// Formula: ={{DemandedUnitsPerWeek}} > {{AvailableUnitsPerWeek}}
func (tc *TacticalResourceAllocation) CalcIsBottleneck() *bool {
	return toBoolPtr(erbCmp(erbNullif(vNum(tc.DemandedUnitsPerWeek)), ">", erbNullif(vNum(tc.AvailableUnitsPerWeek))))
}

