// CalcIsDependencyInvisibleToChange computes the IsDependencyInvisibleToChange calculated field
// TRUE when the material was encoded into a model but no trace records what rests on it, so a change to it reveals nothing.
// Formula: =AND({{EncodedIntoVersion}} <> "", {{DependentTraceCount}} = 0)
func (tc *CollectedSourceMaterial) CalcIsDependencyInvisibleToChange() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.EncodedIntoVersion))), erbBool3(erbEq(vInt(tc.DependentTraceCount), vI(0)))))
}

// CalcHasKnowledgeAffectedBySourceChange computes the HasKnowledgeAffectedBySourceChange calculated field
// TRUE when a revision of the source affects organized knowledge taken from it.
// Formula: ={{ChangedDependentCount}} > 0
func (tc *CollectedSourceMaterial) CalcHasKnowledgeAffectedBySourceChange() *bool {
	return toBoolPtr(erbCmp(vInt(tc.ChangedDependentCount), ">", vI(0)))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *CollectedSourceMaterial) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_modeled_before_organized", func() { tc.IsModeledBeforeOrganized = tc.CalcIsModeledBeforeOrganized() })
	calcGuard(tc, "is_document_source", func() { tc.IsDocumentSource = tc.CalcIsDocumentSource() })
	calcGuard(tc, "is_people_capture", func() { tc.IsPeopleCapture = tc.CalcIsPeopleCapture() })
	calcGuard(tc, "is_practice_evidence", func() { tc.IsPracticeEvidence = tc.CalcIsPracticeEvidence() })
	calcGuard(tc, "is_captured_in_flow_of_work", func() { tc.IsCapturedInFlowOfWork = tc.CalcIsCapturedInFlowOfWork() })
	calcGuard(tc, "is_dependency_invisible_to_change", func() { tc.IsDependencyInvisibleToChange = tc.CalcIsDependencyInvisibleToChange() })
	calcGuard(tc, "has_knowledge_affected_by_source_change", func() { tc.HasKnowledgeAffectedBySourceChange = tc.CalcHasKnowledgeAffectedBySourceChange() })
}

