// TERMLABELVARIANTS TABLE
// Preferred and alternative labels of a controlled concept, one row per wording, so variant wordings can be matched.
// =============================================================================

// TermLabelVariant represents a row in the TermLabelVariants table
type TermLabelVariant struct {
	TermLabelVariantId string `json:"term_label_variant_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	VocabularyTerm *string `json:"vocabulary_term"` // Concept labeled.
	LabelKind *string `json:"label_kind"` // pref (skos:prefLabel) or alt (skos:altLabel).
	Wording *string `json:"wording"` // The wording, lower case.
	TermScheme *string `json:"term_scheme"` // Scheme the concept belongs to.
	TermPrefLabel *string `json:"term_pref_label"` // The preferred label of the concept this wording belongs to. What a vocabulary search answers with, whichever wording was typed.
	WordingKey *string `json:"wording_key"` // Scheme and wording.
	PrefWordingKey *string `json:"pref_wording_key"` // Scheme and wording for a preferred label.
	ConceptsSharingWording *int `json:"concepts_sharing_wording"` // Labels in the same scheme with this exact wording.
	IsAmbiguousLabel *bool `json:"is_ambiguous_label"` // TRUE when one wording is a label of more than one concept in the scheme, so it cannot normalize to one canonical concept.
	PractitionerMentionCount *int `json:"practitioner_mention_count"` // Practitioner mentions using this wording in this scheme.
	PrefWording *string `json:"pref_wording"` // Wording of a preferred label, regardless of scheme.
	SamePrefWordingCount *int `json:"same_pref_wording_count"` // Preferred labels in any scheme with this wording.
	IsCrossSchemeDuplicatePref *bool `json:"is_cross_scheme_duplicate_pref"` // TRUE when the same concern is defined as a separate preferred concept in more than one scheme instead of being shared.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{VocabularyTerm}} & " " & {{LabelKind}} & ": " & {{Wording}}
func (tc *TermLabelVariant) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.VocabularyTerm)), vS(" "), erbText(vStr(tc.LabelKind)), vS(": "), erbText(vStr(tc.Wording))))
}

// CalcWordingKey computes the WordingKey calculated field
// Scheme and wording.
// Formula: ={{TermScheme}} & "|" & {{Wording}}
func (tc *TermLabelVariant) CalcWordingKey() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.TermScheme)), vS("|"), erbText(vStr(tc.Wording))))
}

// CalcPrefWordingKey computes the PrefWordingKey calculated field
// Scheme and wording for a preferred label.
// Formula: =IF({{LabelKind}} = "pref", {{WordingKey}}, "")
func (tc *TermLabelVariant) CalcPrefWordingKey() *string {
	return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.LabelKind)), vS("pref"))), func() Value { return vStr(tc.WordingKey) }, func() Value { return vS("") }))
}

// CalcIsAmbiguousLabel computes the IsAmbiguousLabel calculated field
// TRUE when one wording is a label of more than one concept in the scheme, so it cannot normalize to one canonical concept.
// Formula: ={{ConceptsSharingWording}} > 1
func (tc *TermLabelVariant) CalcIsAmbiguousLabel() *bool {
	return toBoolPtr(erbCmp(vInt(tc.ConceptsSharingWording), ">", vI(1)))
}

// CalcPrefWording computes the PrefWording calculated field
// Wording of a preferred label, regardless of scheme.
// Formula: =IF({{LabelKind}} = "pref", {{Wording}}, "")
func (tc *TermLabelVariant) CalcPrefWording() *string {
	return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.LabelKind)), vS("pref"))), func() Value { return vStr(tc.Wording) }, func() Value { return vS("") }))
}

// CalcIsCrossSchemeDuplicatePref computes the IsCrossSchemeDuplicatePref calculated field
// TRUE when the same concern is defined as a separate preferred concept in more than one scheme instead of being shared.
// Formula: =AND({{LabelKind}} = "pref", {{SamePrefWordingCount}} > 1)
func (tc *TermLabelVariant) CalcIsCrossSchemeDuplicatePref() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.LabelKind)), vS("pref"))), erbBool3(erbCmp(vInt(tc.SamePrefWordingCount), ">", vI(1)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *TermLabelVariant) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "wording_key", func() { tc.WordingKey = tc.CalcWordingKey() })
	calcGuard(tc, "is_ambiguous_label", func() { tc.IsAmbiguousLabel = tc.CalcIsAmbiguousLabel() })
	calcGuard(tc, "pref_wording", func() { tc.PrefWording = tc.CalcPrefWording() })
	calcGuard(tc, "is_cross_scheme_duplicate_pref", func() { tc.IsCrossSchemeDuplicatePref = tc.CalcIsCrossSchemeDuplicatePref() })
	// Level 2
	calcGuard(tc, "pref_wording_key", func() { tc.PrefWordingKey = tc.CalcPrefWordingKey() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *TermLabelVariant) ComputeAll() *TermLabelVariant {
	tc.erbComputeCalculations()
	return tc
}

