// =============================================================================
// CONSUMERSYSTEMSYNCS TABLE
// Which procedure version a consuming system currently holds, from what source, and when it was synced.
// =============================================================================

// ConsumerSystemSync represents a row in the ConsumerSystemSyncs table
type ConsumerSystemSync struct {
	ConsumerSystemSyncId string `json:"consumer_system_sync_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	ConsumerSystem *string `json:"consumer_system"` // Consuming system.
	LoadedVersion *string `json:"loaded_version"` // Procedure version the system holds.
	SyncedAt *string `json:"synced_at"` // When the system last took the version.
	SourceResource *string `json:"source_resource"` // A document the system was fed from instead of the shared model; blank when fed from the model.
	CarriesProvenance *bool `json:"carries_provenance"` // TRUE when the system's copy kept who authored the knowledge and where it came from.
	SystemAudience *string `json:"system_audience"` // Who reads through the system.
	LoadedProcedure *string `json:"loaded_procedure"` // Procedure of the loaded version.
	CanonicalVersion *string `json:"canonical_version"` // The procedure's current version in the model.
	CanonicalVersionModifiedAt *string `json:"canonical_version_modified_at"` // When the current version last changed.
	LoadedVersionCreator *string `json:"loaded_version_creator"` // Who authored the loaded version.
	IsBehindCanonicalVersion *bool `json:"is_behind_canonical_version"` // TRUE when a consuming system holds a different version from the one the model says is current.
	PredatesVersionChange *bool `json:"predates_version_change"` // TRUE when the system holds the current version but took it before that version last changed.
	IsAiFedFromForkedCopy *bool `json:"is_ai_fed_from_forked_copy"` // TRUE when a system read by AI is fed from a separate document rather than the shared model humans use.
	DropsProvenanceInTransit *bool `json:"drops_provenance_in_transit"` // TRUE when the version had an author on record and the system's copy dropped the provenance.
	ReachesHumans *bool `json:"reaches_humans"` // TRUE when the system is read by people.
	ReachesMachines *bool `json:"reaches_machines"` // TRUE when the system is read by AI.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{ConsumerSystem}} & " holds " & {{LoadedVersion}}
func (tc *ConsumerSystemSync) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ConsumerSystem)), vS(" holds "), erbText(vStr(tc.LoadedVersion))))
}

// CalcIsBehindCanonicalVersion computes the IsBehindCanonicalVersion calculated field
// TRUE when a consuming system holds a different version from the one the model says is current.
// Formula: =AND({{CanonicalVersion}} <> "", {{LoadedVersion}} <> {{CanonicalVersion}})
func (tc *ConsumerSystemSync) CalcIsBehindCanonicalVersion() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.CanonicalVersion))), erbBool3(erbNe(erbNullif(vStr(tc.LoadedVersion)), vStr(tc.CanonicalVersion)))))
}

// CalcPredatesVersionChange computes the PredatesVersionChange calculated field
// TRUE when the system holds the current version but took it before that version last changed.
// Formula: =AND({{LoadedVersion}} = {{CanonicalVersion}}, {{SyncedAt}} < {{CanonicalVersionModifiedAt}})
func (tc *ConsumerSystemSync) CalcPredatesVersionChange() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.LoadedVersion)), vStr(tc.CanonicalVersion))), erbBool3(erbCmp(erbNullif(vStr(tc.SyncedAt)), "<", vStr(tc.CanonicalVersionModifiedAt)))))
}

// CalcIsAiFedFromForkedCopy computes the IsAiFedFromForkedCopy calculated field
// TRUE when a system read by AI is fed from a separate document rather than the shared model humans use.
// Formula: =AND({{SystemAudience}} <> "Human", {{SourceResource}} <> "")
func (tc *ConsumerSystemSync) CalcIsAiFedFromForkedCopy() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNe(vStr(tc.SystemAudience), vS("Human"))), erbBool3(erbIsNotBlank(vStr(tc.SourceResource)))))
}

// CalcDropsProvenanceInTransit computes the DropsProvenanceInTransit calculated field
// TRUE when the version had an author on record and the system's copy dropped the provenance.
// Formula: =AND({{LoadedVersionCreator}} <> "", {{CarriesProvenance}} = FALSE)
func (tc *ConsumerSystemSync) CalcDropsProvenanceInTransit() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.LoadedVersionCreator))), erbBool3(erbEq(erbNullif(vBool(tc.CarriesProvenance)), vB(false)))))
}

// CalcReachesHumans computes the ReachesHumans calculated field
// TRUE when the system is read by people.
// Formula: =OR({{SystemAudience}} = "Human", {{SystemAudience}} = "Both")
func (tc *ConsumerSystemSync) CalcReachesHumans() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(vStr(tc.SystemAudience), vS("Human"))), erbBool3(erbEq(vStr(tc.SystemAudience), vS("Both")))))
}

// CalcReachesMachines computes the ReachesMachines calculated field
// TRUE when the system is read by AI.
// Formula: =OR({{SystemAudience}} = "AI", {{SystemAudience}} = "Both")
func (tc *ConsumerSystemSync) CalcReachesMachines() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(vStr(tc.SystemAudience), vS("AI"))), erbBool3(erbEq(vStr(tc.SystemAudience), vS("Both")))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ConsumerSystemSync) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_behind_canonical_version", func() { tc.IsBehindCanonicalVersion = tc.CalcIsBehindCanonicalVersion() })
	calcGuard(tc, "predates_version_change", func() { tc.PredatesVersionChange = tc.CalcPredatesVersionChange() })
	calcGuard(tc, "is_ai_fed_from_forked_copy", func() { tc.IsAiFedFromForkedCopy = tc.CalcIsAiFedFromForkedCopy() })
	calcGuard(tc, "drops_provenance_in_transit", func() { tc.DropsProvenanceInTransit = tc.CalcDropsProvenanceInTransit() })
	calcGuard(tc, "reaches_humans", func() { tc.ReachesHumans = tc.CalcReachesHumans() })
	calcGuard(tc, "reaches_machines", func() { tc.ReachesMachines = tc.CalcReachesMachines() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ConsumerSystemSync) ComputeAll() *ConsumerSystemSync {
	tc.erbComputeCalculations()
	return tc
}

