// =============================================================================
// AGENTINTEGRATIONS TABLE
// The central registry of AI agent integrations: which agent reads which knowledge system, over which pathway, served which graph.
// =============================================================================

// AgentIntegration represents a row in the AgentIntegrations table
type AgentIntegration struct {
	AgentIntegrationId string `json:"agent_integration_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	Agent *string `json:"agent"` // Integrated AI agent.
	KnowledgeSystem *string `json:"knowledge_system"` // System it reads knowledge from.
	Pathway *string `json:"pathway"` // Pathway used.
	ServesSnapshot *string `json:"serves_snapshot"` // Graph snapshot the integration serves the agent.
	DeliveryMode *string `json:"delivery_mode"` // Runtime (retrieved when the agent acts) or BakedIn (copied into a prompt or model once).
	RegistryEntryKey *string `json:"registry_entry_key"` // Entry in the central integration registry; blank when never registered.
	ConnectedAt *string `json:"connected_at"` // When connected.
	PathwayIntegrationCount *int `json:"pathway_integration_count"` // Integrations sharing this pathway.
	ObservedAnswerCount *int `json:"observed_answer_count"` // Assistant answers delivered through this integration.
	IsShadowIntegration *bool `json:"is_shadow_integration"` // TRUE when an integration is in live use but has no entry in the central registry.
	IsOneOffConnection *bool `json:"is_one_off_connection"` // TRUE when no other integration shares the pathway this one uses.
	SnapshotIsGoverned *bool `json:"snapshot_is_governed"` // Whether the served snapshot is governed.
	IsDeployedOnUngovernedGraph *bool `json:"is_deployed_on_ungoverned_graph"` // TRUE when an AI agent is deployed against a graph snapshot nobody governs.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Agent}} & " via " & {{Pathway}}
func (tc *AgentIntegration) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Agent)), vS(" via "), erbText(vStr(tc.Pathway))))
}

// CalcIsShadowIntegration computes the IsShadowIntegration calculated field
// TRUE when an integration is in live use but has no entry in the central registry.
// Formula: =AND({{ObservedAnswerCount}} > 0, {{RegistryEntryKey}} = "")
func (tc *AgentIntegration) CalcIsShadowIntegration() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.ObservedAnswerCount), ">", vI(0))), erbBool3(erbIsBlank(vStr(tc.RegistryEntryKey)))))
}

// CalcIsOneOffConnection computes the IsOneOffConnection calculated field
// TRUE when no other integration shares the pathway this one uses.
// Formula: ={{PathwayIntegrationCount}} <= 1
func (tc *AgentIntegration) CalcIsOneOffConnection() *bool {
	return toBoolPtr(erbCmp(vInt(tc.PathwayIntegrationCount), "<=", vI(1)))
}

