// REASONERRUNS TABLE
// One reasoner run over a grounding snapshot: consistency, materialization, budget and dropped axioms.
// =============================================================================

// ReasonerRun represents a row in the ReasonerRuns table
type ReasonerRun struct {
	ReasonerRunId string `json:"reasoner_run_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	Snapshot *string `json:"snapshot"` // Snapshot reasoned over.
	ReasonerProfile *string `json:"reasoner_profile"` // OWL 2 RL, OWL 2 DL or RDFS.
	RanAt *string `json:"ran_at"` // When run.
	MaterializedAt *string `json:"materialized_at"` // When entailments were written into the snapshot; blank if not.
	IsConsistent *bool `json:"is_consistent"` // Whether the reasoner found the snapshot consistent.
	InferredTripleCount *int `json:"inferred_triple_count"` // Triples inferred.
	DurationSeconds *float64 `json:"duration_seconds"` // Run time.
	TimeBudgetSeconds *float64 `json:"time_budget_seconds"` // Time allowed before serving.
	DroppedAxiomCount *int `json:"dropped_axiom_count"` // Axioms the profile could not express and dropped.
	SchemaValidationPassed *bool `json:"schema_validation_passed"` // Whether the export passed plain schema (shape of the tables) validation.
	IsRichnessTractabilityFailure *bool `json:"is_richness_tractability_failure"` // TRUE when a run either blew its reasoning budget or kept to budget only by dropping axioms.
	PassesSchemaButFailsReasoner *bool `json:"passes_schema_but_fails_reasoner"` // TRUE when an export that validates as a table design is found inconsistent by the reasoner.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Snapshot}} & " / " & {{ReasonerProfile}}
func (tc *ReasonerRun) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Snapshot)), vS(" / "), erbText(vStr(tc.ReasonerProfile))))
}

// CalcIsRichnessTractabilityFailure computes the IsRichnessTractabilityFailure calculated field
// TRUE when a run either blew its reasoning budget or kept to budget only by dropping axioms.
// Formula: =OR({{DurationSeconds}} > {{TimeBudgetSeconds}}, {{DroppedAxiomCount}} > 0)
func (tc *ReasonerRun) CalcIsRichnessTractabilityFailure() *bool {
	return toBoolPtr(erbOr(erbBool3(erbCmp(erbNullif(vNum(tc.DurationSeconds)), ">", erbNullif(vNum(tc.TimeBudgetSeconds)))), erbBool3(erbCmp(erbNullif(vInt(tc.DroppedAxiomCount)), ">", vI(0)))))
}

// CalcPassesSchemaButFailsReasoner computes the PassesSchemaButFailsReasoner calculated field
// TRUE when an export that validates as a table design is found inconsistent by the reasoner.
// Formula: =AND({{SchemaValidationPassed}}, {{IsConsistent}} = FALSE)
func (tc *ReasonerRun) CalcPassesSchemaButFailsReasoner() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.SchemaValidationPassed)), erbBool3(erbEq(erbNullif(vBool(tc.IsConsistent)), vB(false)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ReasonerRun) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_richness_tractability_failure", func() { tc.IsRichnessTractabilityFailure = tc.CalcIsRichnessTractabilityFailure() })
	calcGuard(tc, "passes_schema_but_fails_reasoner", func() { tc.PassesSchemaButFailsReasoner = tc.CalcPassesSchemaButFailsReasoner() })
}

