// SnapshotAssertion represents a row in the SnapshotAssertions table
type SnapshotAssertion struct {
	SnapshotAssertionId string `json:"snapshot_assertion_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	Snapshot *string `json:"snapshot"` // Snapshot.
	SubjectIdentifier *string `json:"subject_identifier"` // Identifier of the subject individual.
	Predicate *string `json:"predicate"` // Predicate.
	ObjectValue *string `json:"object_value"` // Object.
	IsInferred *bool `json:"is_inferred"` // TRUE when the reasoner inferred the assertion.
	SourceProcedureVersion *string `json:"source_procedure_version"` // Procedure version the assertion came from.
	SourceStep *string `json:"source_step"` // Step the assertion came from.
	SourceRoleAssignment *string `json:"source_role_assignment"` // Role assignment the assertion came from.
	AboutAgent *string `json:"about_agent"` // Agent the assertion is about, for accountability and category assertions.
	ProvenanceUri *string `json:"provenance_uri"` // Where the assertion came from.
	DcTitle *string `json:"dc_title"` // dcterms:title of the subject.
	DcDescription *string `json:"dc_description"` // dcterms:description of the subject.
	PresentedStatus *string `json:"presented_status"` // Status the assertion presents the subject as: Current or Deprecated.
	SourceVersionStatus *string `json:"source_version_status"` // Status of the source version.
	SourceAssignmentIsCurrent *bool `json:"source_assignment_is_current"` // Whether the source role assignment is current.
	SnapshotConsistentRunCount *int `json:"snapshot_consistent_run_count"` // Consistent reasoner runs over the snapshot.
	SnapshotIsReasoned *bool `json:"snapshot_is_reasoned"` // TRUE when the assertion sits in a snapshot a reasoner found consistent.
	IsStaleRoleAssertion *bool `json:"is_stale_role_assertion"` // TRUE when the assertion rests on a role assignment that is no longer current.
	PresentsDeprecatedAsCurrent *bool `json:"presents_deprecated_as_current"` // TRUE when the assertion presents a deprecated or archived version as current.
	LacksProvenance *bool `json:"lacks_provenance"` // TRUE when a served assertion links back to nothing: no provenance URI, version, step or assignment.
	HasOpaqueIdentifier *bool `json:"has_opaque_identifier"` // TRUE when the subject identifier is a UUID URN or blank node a person or model cannot read or cite.
	LacksDublinCore *bool `json:"lacks_dublin_core"` // TRUE when the subject carries no Dublin Core title or no description.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{SubjectIdentifier}} & " " & {{Predicate}} & " " & {{ObjectValue}}
func (tc *SnapshotAssertion) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.SubjectIdentifier)), vS(" "), erbText(vStr(tc.Predicate)), vS(" "), erbText(vStr(tc.ObjectValue))))
}

// CalcSnapshotIsReasoned computes the SnapshotIsReasoned calculated field
// TRUE when the assertion sits in a snapshot a reasoner found consistent.
// Formula: ={{SnapshotConsistentRunCount}} > 0
func (tc *SnapshotAssertion) CalcSnapshotIsReasoned() *bool {
	return toBoolPtr(erbCmp(vInt(tc.SnapshotConsistentRunCount), ">", vI(0)))
}

// CalcIsStaleRoleAssertion computes the IsStaleRoleAssertion calculated field
// TRUE when the assertion rests on a role assignment that is no longer current.
// Formula: =AND({{SourceRoleAssignment}} <> "", {{SourceAssignmentIsCurrent}} = FALSE)
func (tc *SnapshotAssertion) CalcIsStaleRoleAssertion() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.SourceRoleAssignment))), erbBool3(erbEq(vBool(tc.SourceAssignmentIsCurrent), vB(false)))))
}

// CalcPresentsDeprecatedAsCurrent computes the PresentsDeprecatedAsCurrent calculated field
// TRUE when the assertion presents a deprecated or archived version as current.
// Formula: =AND(OR({{SourceVersionStatus}} = "Deprecated", {{SourceVersionStatus}} = "Archived"), {{PresentedStatus}} = "Current")
func (tc *SnapshotAssertion) CalcPresentsDeprecatedAsCurrent() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(vStr(tc.SourceVersionStatus), vS("Deprecated"))), erbBool3(erbEq(vStr(tc.SourceVersionStatus), vS("Archived"))))), erbBool3(erbEq(erbNullif(vStr(tc.PresentedStatus)), vS("Current")))))
}

// CalcLacksProvenance computes the LacksProvenance calculated field
// TRUE when a served assertion links back to nothing: no provenance URI, version, step or assignment.
// Formula: =AND({{ProvenanceUri}} = "", {{SourceProcedureVersion}} = "", {{SourceStep}} = "", {{SourceRoleAssignment}} = "")
func (tc *SnapshotAssertion) CalcLacksProvenance() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsBlank(vStr(tc.ProvenanceUri))), erbBool3(erbIsBlank(vStr(tc.SourceProcedureVersion))), erbBool3(erbIsBlank(vStr(tc.SourceStep))), erbBool3(erbIsBlank(vStr(tc.SourceRoleAssignment)))))
}

// CalcHasOpaqueIdentifier computes the HasOpaqueIdentifier calculated field
// TRUE when the subject identifier is a UUID URN or blank node a person or model cannot read or cite.
// Formula: =OR(LEFT({{SubjectIdentifier}}, 9) = "urn:uuid:", LEFT({{SubjectIdentifier}}, 2) = "_:")
func (tc *SnapshotAssertion) CalcHasOpaqueIdentifier() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbLeft(vStr(tc.SubjectIdentifier), vI(9)), vS("urn:uuid:"))), erbBool3(erbEq(erbLeft(vStr(tc.SubjectIdentifier), vI(2)), vS("_:")))))
}

// CalcLacksDublinCore computes the LacksDublinCore calculated field
// TRUE when the subject carries no Dublin Core title or no description.
// Formula: =OR({{DcTitle}} = "", {{DcDescription}} = "")
func (tc *SnapshotAssertion) CalcLacksDublinCore() *bool {
	return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.DcTitle))), erbBool3(erbIsBlank(vStr(tc.DcDescription)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *SnapshotAssertion) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "snapshot_is_reasoned", func() { tc.SnapshotIsReasoned = tc.CalcSnapshotIsReasoned() })
	calcGuard(tc, "is_stale_role_assertion", func() { tc.IsStaleRoleAssertion = tc.CalcIsStaleRoleAssertion() })
	calcGuard(tc, "presents_deprecated_as_current", func() { tc.PresentsDeprecatedAsCurrent = tc.CalcPresentsDeprecatedAsCurrent() })
	calcGuard(tc, "lacks_provenance", func() { tc.LacksProvenance = tc.CalcLacksProvenance() })
	calcGuard(tc, "has_opaque_identifier", func() { tc.HasOpaqueIdentifier = tc.CalcHasOpaqueIdentifier() })
	calcGuard(tc, "lacks_dublin_core", func() { tc.LacksDublinCore = tc.CalcLacksDublinCore() })
}

