	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.AuthorAgentKind))), erbBool3(erbNe(vStr(tc.AuthorAgentKind), vS("Human"))), erbBool3(erbIsBlank(vStr(tc.AccountableRole)))))
