// =============================================================================
// ASSISTANTANSWERS TABLE
// One answer, guidance or recommendation an AI assistant delivered, recorded with its context and review. The model does not run the AI; it records what it said.
// =============================================================================

// AssistantAnswer represents a row in the AssistantAnswers table
type AssistantAnswer struct {
	AssistantAnswerId string `json:"assistant_answer_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	AnsweringAgent *string `json:"answering_agent"` // AI agent that answered.
	AskedByAgent *string `json:"asked_by_agent"` // Who asked.
	ViaIntegration *string `json:"via_integration"` // Integration the answer came through.
	StepExecution *string `json:"step_execution"` // Step execution under way when the question was asked.
	AskedAt *string `json:"asked_at"` // When asked.
	AnsweredAt *string `json:"answered_at"` // When answered.
	AnswerKind *string `json:"answer_kind"` // Guidance, Recommendation or Lookup.
	QuestionTopic *string `json:"question_topic"` // Authority, Safety, Sequence, Scheduling or General.
	QuestionText *string `json:"question_text"` // The question.
	AnswerText *string `json:"answer_text"` // The answer.
	RetrievalMode *string `json:"retrieval_mode"` // StructuredQuery, DocumentPassage or None.
	DerivationPerformedBy *string `json:"derivation_performed_by"` // Reasoner, StructuredQuery or LanguageModel: what produced the logic of the answer.
	NeedsInference *bool `json:"needs_inference"` // TRUE when the answer requires deriving something not stated outright.
	AssumedCurrentStep *string `json:"assumed_current_step"` // Step the assistant believed the execution was at.
	AssertedNextStep *string `json:"asserted_next_step"` // Step the assistant said comes next.
	RecommendedStep *string `json:"recommended_step"` // Step a recommendation acts on.
	RaisedSafetyConcern *bool `json:"raised_safety_concern"` // TRUE when the answer raised a possible safety problem.
	DeliveryDisposition *string `json:"delivery_disposition"` // Delivered or Withheld.
	WasActedOn *bool `json:"was_acted_on"` // TRUE when someone acted on the answer.
	HumanReviewedBy *string `json:"human_reviewed_by"` // Expert who reviewed the answer before it was used.
	ReviewedForInitiative *string `json:"reviewed_for_initiative"` // Automation pilot whose output this expert review belongs to.
	WasCorrect *bool `json:"was_correct"` // Expert verdict on the answer.
	DocumentedInaccuracy *string `json:"documented_inaccuracy"` // What was wrong, as documented.
	TaskOutcome *string `json:"task_outcome"` // Completed, Failed or Abandoned.
	GroundingCount *int `json:"grounding_count"` // Groundings of the answer.
	OwnKnowledgeGroundingCount *int `json:"own_knowledge_grounding_count"` // Groundings in the organization's own assertions or segments.
	CitedGroundingCount *int `json:"cited_grounding_count"` // Groundings shown to the person as citations.
	StaleGroundingCount *int `json:"stale_grounding_count"` // Groundings on stale or deprecated assertions.
	IsNotFromOwnKnowledge *bool `json:"is_not_from_own_knowledge"` // TRUE when a delivered answer rests on nothing from the organization's own procedural knowledge.
	IsUntraceableToSource *bool `json:"is_untraceable_to_source"` // TRUE when a delivered answer was grounded but showed the person none of its sources.
	ContextUnescalatedDangerCueCount *int `json:"context_unescalated_danger_cue_count"` // Danger cues seen and not escalated on the step under way.
	StayedSilentOnSafetyProblem *bool `json:"stayed_silent_on_safety_problem"` // TRUE when an unescalated danger cue was on record for the step and the answer raised no safety concern.
	ContextStepEndedAt *string `json:"context_step_ended_at"` // When the step under way ended.
	ArrivedAfterStepEnded *bool `json:"arrived_after_step_ended"` // TRUE when guidance for a step arrived after the step had already ended.
	ExecutionOfContext *string `json:"execution_of_context"` // Procedure execution under way.
	ContextStep *string `json:"context_step"` // Step under way.
	AssumedStepCompletedCount *int `json:"assumed_step_completed_count"` // Completed runs, in the same execution, of the step the assistant believed it was at.
	LostTrackOfState *bool `json:"lost_track_of_state"` // TRUE when the assistant acted as if a step were done that the execution record shows never completed.
	SpecifiedTransitionCount *int `json:"specified_transition_count"` // Transitions the model allows from the assumed step to the asserted next step.
	ContradictsSharedModel *bool `json:"contradicts_shared_model"` // TRUE when the assistant asserted a next step the procedure's transition graph does not allow.
	IsExplicitlyGroundedRecommendation *bool `json:"is_explicitly_grounded_recommendation"` // TRUE for a recommendation that names at least one piece of the organization's explicit process knowledge.
	RecommendationRestsOnNothingExplicit *bool `json:"recommendation_rests_on_nothing_explicit"` // TRUE for a recommendation traceable to no explicit process knowledge.
	RecommendedStepRegulatoryCount *int `json:"recommended_step_regulatory_count"` // Regulatory requirements on the recommended step.
	RequirementCheckCount *int `json:"requirement_check_count"` // Requirement checks run on the answer.
	ConflictCount *int `json:"conflict_count"` // Checks that found a conflict.
	ConflictsWithRegulation *bool `json:"conflicts_with_regulation"` // TRUE when a check found the recommended action conflicts with an applicable requirement.
	IsUncheckedRegulatedRecommendation *bool `json:"is_unchecked_regulated_recommendation"` // TRUE for a recommendation on a regulated step that was never checked against its requirements.
	DeliveredDespiteConflict *bool `json:"delivered_despite_conflict"` // TRUE when the check found a regulatory conflict and the recommendation was delivered anyway.
	RecommendedStepNeedsHuman *bool `json:"recommended_step_needs_human"` // Whether the recommended step requires human confirmation.
	ActedOnWithoutHumanJudgment *bool `json:"acted_on_without_human_judgment"` // TRUE when an AI recommendation on a step that requires human judgment was acted on with no expert review.
	AnsweredComplianceQuestionFromDocuments *bool `json:"answered_compliance_question_from_documents"` // TRUE when an authority or safety question was answered from document passages rather than a structured query.
	DocumentInterpretationErred *bool `json:"document_interpretation_erred"` // TRUE when an authority question answered by interpreting a document passage came back wrong.
	ModelDidTheReasoning *bool `json:"model_did_the_reasoning"` // TRUE when an answer that needed inference had its logic produced by the language model, not a reasoner or query.
	WrongBecauseGraphWasStale *bool `json:"wrong_because_graph_was_stale"` // TRUE when a graph-grounded answer was wrong and rested on a stale or deprecated assertion.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	OwnerOrganization *string `json:"owner_organization"` // The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
	ModelReasonedAndTaskFailed *bool `json:"model_reasoned_and_task_failed"` // The language model did the reasoning for this answer itself, and the task it was asked about ended in failure.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{AnsweringAgent}} & ": " & LEFT({{QuestionText}}, 50)
func (tc *AssistantAnswer) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.AnsweringAgent)), vS(": "), erbText(erbLeft(vStr(tc.QuestionText), vI(50)))))
}

// CalcIsNotFromOwnKnowledge computes the IsNotFromOwnKnowledge calculated field
// TRUE when a delivered answer rests on nothing from the organization's own procedural knowledge.
// Formula: =AND({{DeliveryDisposition}} = "Delivered", {{OwnKnowledgeGroundingCount}} = 0)
func (tc *AssistantAnswer) CalcIsNotFromOwnKnowledge() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.DeliveryDisposition)), vS("Delivered"))), erbBool3(erbEq(vInt(tc.OwnKnowledgeGroundingCount), vI(0)))))
}

// CalcIsUntraceableToSource computes the IsUntraceableToSource calculated field
// TRUE when a delivered answer was grounded but showed the person none of its sources.
// Formula: =AND({{DeliveryDisposition}} = "Delivered", {{GroundingCount}} > 0, {{CitedGroundingCount}} = 0)
func (tc *AssistantAnswer) CalcIsUntraceableToSource() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.DeliveryDisposition)), vS("Delivered"))), erbBool3(erbCmp(vInt(tc.GroundingCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.CitedGroundingCount), vI(0)))))
}

// CalcStayedSilentOnSafetyProblem computes the StayedSilentOnSafetyProblem calculated field
// TRUE when an unescalated danger cue was on record for the step and the answer raised no safety concern.
// Formula: =AND({{ContextUnescalatedDangerCueCount}} > 0, {{RaisedSafetyConcern}} = FALSE)
func (tc *AssistantAnswer) CalcStayedSilentOnSafetyProblem() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.ContextUnescalatedDangerCueCount), ">", vI(0))), erbBool3(erbEq(erbNullif(vBool(tc.RaisedSafetyConcern)), vB(false)))))
}

// CalcArrivedAfterStepEnded computes the ArrivedAfterStepEnded calculated field
// TRUE when guidance for a step arrived after the step had already ended.
// Formula: =AND({{AnswerKind}} = "Guidance", {{ContextStepEndedAt}} <> "", {{AnsweredAt}} > {{ContextStepEndedAt}})
func (tc *AssistantAnswer) CalcArrivedAfterStepEnded() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AnswerKind)), vS("Guidance"))), erbBool3(erbIsNotBlank(vStr(tc.ContextStepEndedAt))), erbBool3(erbCmp(erbNullif(vStr(tc.AnsweredAt)), ">", vStr(tc.ContextStepEndedAt)))))
}

// CalcLostTrackOfState computes the LostTrackOfState calculated field
// TRUE when the assistant acted as if a step were done that the execution record shows never completed.
// Formula: =AND({{AssumedCurrentStep}} <> "", {{ExecutionOfContext}} <> "", {{AssumedStepCompletedCount}} = 0)
func (tc *AssistantAnswer) CalcLostTrackOfState() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.AssumedCurrentStep))), erbBool3(erbIsNotBlank(vStr(tc.ExecutionOfContext))), erbBool3(erbEq(vInt(tc.AssumedStepCompletedCount), vI(0)))))
}

// CalcContradictsSharedModel computes the ContradictsSharedModel calculated field
// TRUE when the assistant asserted a next step the procedure's transition graph does not allow.
// Formula: =AND({{AssertedNextStep}} <> "", {{SpecifiedTransitionCount}} = 0)
func (tc *AssistantAnswer) CalcContradictsSharedModel() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.AssertedNextStep))), erbBool3(erbEq(vInt(tc.SpecifiedTransitionCount), vI(0)))))
}

// CalcIsExplicitlyGroundedRecommendation computes the IsExplicitlyGroundedRecommendation calculated field
// TRUE for a recommendation that names at least one piece of the organization's explicit process knowledge.
// Formula: =AND({{AnswerKind}} = "Recommendation", {{OwnKnowledgeGroundingCount}} > 0)
func (tc *AssistantAnswer) CalcIsExplicitlyGroundedRecommendation() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AnswerKind)), vS("Recommendation"))), erbBool3(erbCmp(vInt(tc.OwnKnowledgeGroundingCount), ">", vI(0)))))
}

// CalcRecommendationRestsOnNothingExplicit computes the RecommendationRestsOnNothingExplicit calculated field
// TRUE for a recommendation traceable to no explicit process knowledge.
// Formula: =AND({{AnswerKind}} = "Recommendation", {{OwnKnowledgeGroundingCount}} = 0)
func (tc *AssistantAnswer) CalcRecommendationRestsOnNothingExplicit() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AnswerKind)), vS("Recommendation"))), erbBool3(erbEq(vInt(tc.OwnKnowledgeGroundingCount), vI(0)))))
}

// CalcConflictsWithRegulation computes the ConflictsWithRegulation calculated field
// TRUE when a check found the recommended action conflicts with an applicable requirement.
// Formula: ={{ConflictCount}} > 0
func (tc *AssistantAnswer) CalcConflictsWithRegulation() *bool {
	return toBoolPtr(erbCmp(vInt(tc.ConflictCount), ">", vI(0)))
}

// CalcIsUncheckedRegulatedRecommendation computes the IsUncheckedRegulatedRecommendation calculated field
// TRUE for a recommendation on a regulated step that was never checked against its requirements.
// Formula: =AND({{AnswerKind}} = "Recommendation", {{RecommendedStepRegulatoryCount}} > 0, {{RequirementCheckCount}} = 0)
func (tc *AssistantAnswer) CalcIsUncheckedRegulatedRecommendation() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AnswerKind)), vS("Recommendation"))), erbBool3(erbCmp(vInt(tc.RecommendedStepRegulatoryCount), ">", vI(0))), erbBool3(erbEq(vInt(tc.RequirementCheckCount), vI(0)))))
}

// CalcDeliveredDespiteConflict computes the DeliveredDespiteConflict calculated field
// TRUE when the check found a regulatory conflict and the recommendation was delivered anyway.
// Formula: =AND({{ConflictCount}} > 0, {{DeliveryDisposition}} = "Delivered")
func (tc *AssistantAnswer) CalcDeliveredDespiteConflict() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.ConflictCount), ">", vI(0))), erbBool3(erbEq(erbNullif(vStr(tc.DeliveryDisposition)), vS("Delivered")))))
}

// CalcActedOnWithoutHumanJudgment computes the ActedOnWithoutHumanJudgment calculated field
// TRUE when an AI recommendation on a step that requires human judgment was acted on with no expert review.
// Formula: =AND({{RecommendedStepNeedsHuman}}, {{WasActedOn}}, {{HumanReviewedBy}} = "")
func (tc *AssistantAnswer) CalcActedOnWithoutHumanJudgment() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RecommendedStepNeedsHuman)), erbIsTrue(vBool(tc.WasActedOn)), erbBool3(erbIsBlank(vStr(tc.HumanReviewedBy)))))
}

// CalcAnsweredComplianceQuestionFromDocuments computes the AnsweredComplianceQuestionFromDocuments calculated field
// TRUE when an authority or safety question was answered from document passages rather than a structured query.
// Formula: =AND(OR({{QuestionTopic}} = "Authority", {{QuestionTopic}} = "Safety"), {{RetrievalMode}} = "DocumentPassage")
func (tc *AssistantAnswer) CalcAnsweredComplianceQuestionFromDocuments() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.QuestionTopic)), vS("Authority"))), erbBool3(erbEq(erbNullif(vStr(tc.QuestionTopic)), vS("Safety"))))), erbBool3(erbEq(erbNullif(vStr(tc.RetrievalMode)), vS("DocumentPassage")))))
}

// CalcDocumentInterpretationErred computes the DocumentInterpretationErred calculated field
// TRUE when an authority question answered by interpreting a document passage came back wrong.
// Formula: =AND({{RetrievalMode}} = "DocumentPassage", {{QuestionTopic}} = "Authority", {{WasCorrect}} = FALSE)
func (tc *AssistantAnswer) CalcDocumentInterpretationErred() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.RetrievalMode)), vS("DocumentPassage"))), erbBool3(erbEq(erbNullif(vStr(tc.QuestionTopic)), vS("Authority"))), erbBool3(erbEq(erbNullif(vBool(tc.WasCorrect)), vB(false)))))
}

// CalcModelDidTheReasoning computes the ModelDidTheReasoning calculated field
// TRUE when an answer that needed inference had its logic produced by the language model, not a reasoner or query.
// Formula: =AND({{NeedsInference}}, {{DerivationPerformedBy}} = "LanguageModel")
func (tc *AssistantAnswer) CalcModelDidTheReasoning() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.NeedsInference)), erbBool3(erbEq(erbNullif(vStr(tc.DerivationPerformedBy)), vS("LanguageModel")))))
}

// CalcWrongBecauseGraphWasStale computes the WrongBecauseGraphWasStale calculated field
// TRUE when a graph-grounded answer was wrong and rested on a stale or deprecated assertion.
// Formula: =AND({{RetrievalMode}} = "StructuredQuery", {{WasCorrect}} = FALSE, {{StaleGroundingCount}} > 0)
func (tc *AssistantAnswer) CalcWrongBecauseGraphWasStale() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.RetrievalMode)), vS("StructuredQuery"))), erbBool3(erbEq(erbNullif(vBool(tc.WasCorrect)), vB(false))), erbBool3(erbCmp(vInt(tc.StaleGroundingCount), ">", vI(0)))))
}

// CalcModelReasonedAndTaskFailed computes the ModelReasonedAndTaskFailed calculated field
// The language model did the reasoning for this answer itself, and the task it was asked about ended in failure.
// Formula: =AND({{ModelDidTheReasoning}}, {{TaskOutcome}} = "Failed")
func (tc *AssistantAnswer) CalcModelReasonedAndTaskFailed() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.ModelDidTheReasoning)), erbBool3(erbEq(erbNullif(vStr(tc.TaskOutcome)), vS("Failed")))))
}

