// LoadAssistantAnswerRecords reads AssistantAnswers rows from a JSON array file.
func LoadAssistantAnswerRecords(path string) ([]AssistantAnswer, error) {
	records, err := loadRecords(path, func() Record { return &AssistantAnswer{} })
	if err != nil {
		return nil, err
	}
	rows := make([]AssistantAnswer, len(records))
	for i, r := range records {
		rows[i] = *r.(*AssistantAnswer)
	}
	return rows, nil
}

// =============================================================================
// ANSWERGROUNDINGS TABLE
// Which served assertion, segment or external source grounded an assistant answer, and whether it was cited.
// =============================================================================

// AnswerGrounding represents a row in the AnswerGroundings table
type AnswerGrounding struct {
	AnswerGroundingId string `json:"answer_grounding_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	AssistantAnswer *string `json:"assistant_answer"` // Answer.
	SnapshotAssertion *string `json:"snapshot_assertion"` // Served assertion.
	RetrievalSegment *string `json:"retrieval_segment"` // Retrieved segment.
	ExternalSourceUri *string `json:"external_source_uri"` // External content outside the organization's knowledge.
	CitedToUser *bool `json:"cited_to_user"` // TRUE when shown to the person as a citation.
	IsFromOwnKnowledge *bool `json:"is_from_own_knowledge"` // TRUE when the grounding is the organization's own assertion or segment.
	AssertionIsStale *bool `json:"assertion_is_stale"` // Whether the assertion rests on an ended role assignment.
	AssertionPresentsDeprecated *bool `json:"assertion_presents_deprecated"` // Whether the assertion presents a deprecated version as current.
	GroundsOnStaleAssertion *bool `json:"grounds_on_stale_assertion"` // TRUE when the grounding assertion is stale or deprecated.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{AssistantAnswer}} & " <- " & {{SnapshotAssertion}} & {{RetrievalSegment}} & {{ExternalSourceUri}}
func (tc *AnswerGrounding) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.AssistantAnswer)), vS(" <- "), erbText(vStr(tc.SnapshotAssertion)), erbText(vStr(tc.RetrievalSegment)), erbText(vStr(tc.ExternalSourceUri))))
}

// CalcIsFromOwnKnowledge computes the IsFromOwnKnowledge calculated field
// TRUE when the grounding is the organization's own assertion or segment.
// Formula: =AND({{ExternalSourceUri}} = "", OR({{SnapshotAssertion}} <> "", {{RetrievalSegment}} <> ""))
func (tc *AnswerGrounding) CalcIsFromOwnKnowledge() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsBlank(vStr(tc.ExternalSourceUri))), erbBool3(erbOr(erbBool3(erbIsNotBlank(vStr(tc.SnapshotAssertion))), erbBool3(erbIsNotBlank(vStr(tc.RetrievalSegment)))))))
}

// CalcGroundsOnStaleAssertion computes the GroundsOnStaleAssertion calculated field
// TRUE when the grounding assertion is stale or deprecated.
// Formula: =AND({{SnapshotAssertion}} <> "", OR({{AssertionIsStale}}, {{AssertionPresentsDeprecated}}))
func (tc *AnswerGrounding) CalcGroundsOnStaleAssertion() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.SnapshotAssertion))), erbBool3(erbOr(erbBool3(vBool(tc.AssertionIsStale)), erbBool3(vBool(tc.AssertionPresentsDeprecated))))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *AnswerGrounding) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_from_own_knowledge", func() { tc.IsFromOwnKnowledge = tc.CalcIsFromOwnKnowledge() })
	calcGuard(tc, "grounds_on_stale_assertion", func() { tc.GroundsOnStaleAssertion = tc.CalcGroundsOnStaleAssertion() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *AnswerGrounding) ComputeAll() *AnswerGrounding {
	tc.erbComputeCalculations()
	return tc
}

