// MODELANNOTATIONS TABLE
// Comments, questions, suggestions, alternative interpretations, outdated flags and new or missing knowledge practitioners attach to the model.
// =============================================================================

// ModelAnnotation represents a row in the ModelAnnotations table
type ModelAnnotation struct {
	ModelAnnotationId string `json:"model_annotation_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	ProcedureVersion *string `json:"procedure_version"` // Version annotated.
	Step *string `json:"step"` // Step annotated.
	AnnotatedByAgent *string `json:"annotated_by_agent"` // Who annotated.
	AnnotatedAt *string `json:"annotated_at"` // When.
	AnnotationKind *string `json:"annotation_kind"` // Comment, Question, Suggestion, AlternativeInterpretation, FlagOutdated, NewKnowledge or MissingKnowledge.
	Body *string `json:"body"` // The annotation.
	Status *string `json:"status"` // Open, Accepted or Declined.
	EnteredThrough *string `json:"entered_through"` // AnnotationPanel or EmailToSteward.
	StoredIn *string `json:"stored_in"` // AnnotationLayer or AuthoritativeRulebook.
	LifecycleStage *string `json:"lifecycle_stage"` // Lifecycle stage the feedback concerns.
	PromotedToFragment *string `json:"promoted_to_fragment"` // Knowledge fragment new knowledge became.
	RaisedKnowledgeGap *string `json:"raised_knowledge_gap"` // Knowledge gap a missing-knowledge report became.
	IsDiscussionInAuthoritativeModel *bool `json:"is_discussion_in_authoritative_model"` // TRUE when a comment, question, suggestion or alternative reading was written into the authoritative rulebook.
	FlagBypassedAnnotationInterface *bool `json:"flag_bypassed_annotation_interface"` // TRUE when a practitioner had to flag outdated guidance outside the annotation interface.
	IsLostNewKnowledge *bool `json:"is_lost_new_knowledge"` // TRUE when new knowledge a practitioner added was not declined and never became a knowledge fragment.
	IsFrictionWithoutGap *bool `json:"is_friction_without_gap"` // TRUE when friction from missing knowledge was reported and never recorded as a knowledge gap.
	IsOpenOutdatedFlag *bool `json:"is_open_outdated_flag"` // TRUE for guidance a practitioner flagged as outdated that is still open.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{AnnotationKind}} & ": " & LEFT({{Body}}, 50)
func (tc *ModelAnnotation) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.AnnotationKind)), vS(": "), erbText(erbLeft(vStr(tc.Body), vI(50)))))
}

// CalcIsDiscussionInAuthoritativeModel computes the IsDiscussionInAuthoritativeModel calculated field
// TRUE when a comment, question, suggestion or alternative reading was written into the authoritative rulebook.
// Formula: =AND(OR({{AnnotationKind}} = "Comment", {{AnnotationKind}} = "Question", {{AnnotationKind}} = "Suggestion", {{AnnotationKind}} = "AlternativeInterpretation"), {{StoredIn}} = "AuthoritativeRulebook")
func (tc *ModelAnnotation) CalcIsDiscussionInAuthoritativeModel() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.AnnotationKind)), vS("Comment"))), erbBool3(erbEq(erbNullif(vStr(tc.AnnotationKind)), vS("Question"))), erbBool3(erbEq(erbNullif(vStr(tc.AnnotationKind)), vS("Suggestion"))), erbBool3(erbEq(erbNullif(vStr(tc.AnnotationKind)), vS("AlternativeInterpretation"))))), erbBool3(erbEq(erbNullif(vStr(tc.StoredIn)), vS("AuthoritativeRulebook")))))
}

// CalcFlagBypassedAnnotationInterface computes the FlagBypassedAnnotationInterface calculated field
// TRUE when a practitioner had to flag outdated guidance outside the annotation interface.
// Formula: =AND({{AnnotationKind}} = "FlagOutdated", {{EnteredThrough}} <> "AnnotationPanel")
func (tc *ModelAnnotation) CalcFlagBypassedAnnotationInterface() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AnnotationKind)), vS("FlagOutdated"))), erbBool3(erbNe(erbNullif(vStr(tc.EnteredThrough)), vS("AnnotationPanel")))))
}

// CalcIsLostNewKnowledge computes the IsLostNewKnowledge calculated field
// TRUE when new knowledge a practitioner added was not declined and never became a knowledge fragment.
// Formula: =AND({{AnnotationKind}} = "NewKnowledge", {{Status}} <> "Declined", {{PromotedToFragment}} = "")
func (tc *ModelAnnotation) CalcIsLostNewKnowledge() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AnnotationKind)), vS("NewKnowledge"))), erbBool3(erbNe(erbNullif(vStr(tc.Status)), vS("Declined"))), erbBool3(erbIsBlank(vStr(tc.PromotedToFragment)))))
}

// CalcIsFrictionWithoutGap computes the IsFrictionWithoutGap calculated field
// TRUE when friction from missing knowledge was reported and never recorded as a knowledge gap.
// Formula: =AND({{AnnotationKind}} = "MissingKnowledge", {{RaisedKnowledgeGap}} = "")
func (tc *ModelAnnotation) CalcIsFrictionWithoutGap() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AnnotationKind)), vS("MissingKnowledge"))), erbBool3(erbIsBlank(vStr(tc.RaisedKnowledgeGap)))))
}

// CalcIsOpenOutdatedFlag computes the IsOpenOutdatedFlag calculated field
// TRUE for guidance a practitioner flagged as outdated that is still open.
// Formula: =AND({{AnnotationKind}} = "FlagOutdated", {{Status}} = "Open")
func (tc *ModelAnnotation) CalcIsOpenOutdatedFlag() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.AnnotationKind)), vS("FlagOutdated"))), erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Open")))))
}

