// KnowledgeOutcomeMeasurement represents a row in the KnowledgeOutcomeMeasurements table
type KnowledgeOutcomeMeasurement struct {
	KnowledgeOutcomeMeasurementId string `json:"knowledge_outcome_measurement_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	Label *string `json:"label"` // Measurement.
	MeasuredGroup *string `json:"measured_group"` // Team measured.
	Facility *string `json:"facility"` // Where.
	ProcedureVersion *string `json:"procedure_version"` // Knowledge the outcome is linked to.
	AiInitiative *string `json:"ai_initiative"` // AI initiative measured.
	KnowledgeScope *string `json:"knowledge_scope"` // Procedural, or ProductQuality for knowledge about products rather than procedures.
	MeasuredAt *string `json:"measured_at"` // When.
	KnowledgeAccessScore *float64 `json:"knowledge_access_score"` // Access to process knowledge, 0 to 100.
	ErrorRatePercent *float64 `json:"error_rate_percent"` // Error rate.
	MinutesPerRun *float64 `json:"minutes_per_run"` // Efficiency: minutes per run.
	SatisfactionScore *float64 `json:"satisfaction_score"` // Customer satisfaction, 1 to 5.
	EfficiencyGainPercent *float64 `json:"efficiency_gain_percent"` // Measured efficiency gain.
	TargetErrorRatePercent *float64 `json:"target_error_rate_percent"` // Tolerated error rate.
	InformedChangeRequest *string `json:"informed_change_request"` // Change request the measurement fed.
	InformedInvestmentDecision *string `json:"informed_investment_decision"` // Investment decision the measurement fed.
	ComparisonBaseline *string `json:"comparison_baseline"` // The lower-access team this is compared with.
	BaselineAccessScore *float64 `json:"baseline_access_score"` // Baseline access.
	BaselineErrorRate *float64 `json:"baseline_error_rate"` // Baseline error rate.
	BaselineMinutesPerRun *float64 `json:"baseline_minutes_per_run"` // Baseline minutes per run.
	BaselineSatisfaction *float64 `json:"baseline_satisfaction"` // Baseline satisfaction.
	HigherAccessFewerErrors *bool `json:"higher_access_fewer_errors"` // TRUE when this team has better access to process knowledge than its baseline and fewer errors.
	HigherAccessMoreEfficient *bool `json:"higher_access_more_efficient"` // TRUE when this team has better access than its baseline and takes fewer minutes per run.
	HigherAccessMoreSatisfied *bool `json:"higher_access_more_satisfied"` // TRUE when this team has better access than its baseline and higher satisfaction.
	IsUnactedAdverseOutcome *bool `json:"is_unacted_adverse_outcome"` // TRUE when an outcome worse than tolerated fed no change request and no investment decision.
	IsGainOutsideProceduralScope *bool `json:"is_gain_outside_procedural_scope"` // TRUE for an efficiency gain measured on knowledge that is not about procedures.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Label}}
func (tc *KnowledgeOutcomeMeasurement) CalcName() *string {
	return toStringPtr(vStr(tc.Label))
}

// CalcHigherAccessFewerErrors computes the HigherAccessFewerErrors calculated field
// TRUE when this team has better access to process knowledge than its baseline and fewer errors.
// Formula: =AND({{ComparisonBaseline}} <> "", {{KnowledgeAccessScore}} > {{BaselineAccessScore}}, {{ErrorRatePercent}} < {{BaselineErrorRate}})
func (tc *KnowledgeOutcomeMeasurement) CalcHigherAccessFewerErrors() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ComparisonBaseline))), erbBool3(erbCmp(erbNullif(vNum(tc.KnowledgeAccessScore)), ">", vNum(tc.BaselineAccessScore))), erbBool3(erbCmp(erbNullif(vNum(tc.ErrorRatePercent)), "<", vNum(tc.BaselineErrorRate)))))
}

// CalcHigherAccessMoreEfficient computes the HigherAccessMoreEfficient calculated field
// TRUE when this team has better access than its baseline and takes fewer minutes per run.
// Formula: =AND({{ComparisonBaseline}} <> "", {{KnowledgeAccessScore}} > {{BaselineAccessScore}}, {{MinutesPerRun}} < {{BaselineMinutesPerRun}})
func (tc *KnowledgeOutcomeMeasurement) CalcHigherAccessMoreEfficient() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ComparisonBaseline))), erbBool3(erbCmp(erbNullif(vNum(tc.KnowledgeAccessScore)), ">", vNum(tc.BaselineAccessScore))), erbBool3(erbCmp(erbNullif(vNum(tc.MinutesPerRun)), "<", vNum(tc.BaselineMinutesPerRun)))))
}

// CalcHigherAccessMoreSatisfied computes the HigherAccessMoreSatisfied calculated field
// TRUE when this team has better access than its baseline and higher satisfaction.
// Formula: =AND({{ComparisonBaseline}} <> "", {{KnowledgeAccessScore}} > {{BaselineAccessScore}}, {{SatisfactionScore}} > {{BaselineSatisfaction}})
func (tc *KnowledgeOutcomeMeasurement) CalcHigherAccessMoreSatisfied() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ComparisonBaseline))), erbBool3(erbCmp(erbNullif(vNum(tc.KnowledgeAccessScore)), ">", vNum(tc.BaselineAccessScore))), erbBool3(erbCmp(erbNullif(vNum(tc.SatisfactionScore)), ">", vNum(tc.BaselineSatisfaction)))))
}

// CalcIsUnactedAdverseOutcome computes the IsUnactedAdverseOutcome calculated field
// TRUE when an outcome worse than tolerated fed no change request and no investment decision.
// Formula: =AND({{ErrorRatePercent}} > {{TargetErrorRatePercent}}, {{InformedChangeRequest}} = "", {{InformedInvestmentDecision}} = "")
func (tc *KnowledgeOutcomeMeasurement) CalcIsUnactedAdverseOutcome() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vNum(tc.ErrorRatePercent)), ">", erbNullif(vNum(tc.TargetErrorRatePercent)))), erbBool3(erbIsBlank(vStr(tc.InformedChangeRequest))), erbBool3(erbIsBlank(vStr(tc.InformedInvestmentDecision)))))
}

// CalcIsGainOutsideProceduralScope computes the IsGainOutsideProceduralScope calculated field
// TRUE for an efficiency gain measured on knowledge that is not about procedures.
// Formula: =AND({{EfficiencyGainPercent}} > 0, {{KnowledgeScope}} <> "Procedural")
func (tc *KnowledgeOutcomeMeasurement) CalcIsGainOutsideProceduralScope() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vNum(tc.EfficiencyGainPercent)), ">", vI(0))), erbBool3(erbNe(erbNullif(vStr(tc.KnowledgeScope)), vS("Procedural")))))
}

