// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Label}}
func (tc *AssistantBenchmark) CalcName() *string {
	return toStringPtr(vStr(tc.Label))
}

// CalcAccuracyLiftPoints computes the AccuracyLiftPoints calculated field
// Accuracy points gained by grounding.
// Formula: ={{GraphGroundedAccuracyPercent}} - {{UngroundedAccuracyPercent}}
func (tc *AssistantBenchmark) CalcAccuracyLiftPoints() *float64 {
	return toFloatPtr(erbSub(vNum(tc.GraphGroundedAccuracyPercent), vNum(tc.UngroundedAccuracyPercent)))
}

// CalcShowsSpatialLiftFromGraphQueries computes the ShowsSpatialLiftFromGraphQueries calculated field
// TRUE when a spatial task gained 20 or more points once the assistant queried the graph.
// Formula: =AND({{TaskFamily}} = "Spatial", {{GeneratesDatabaseQueries}}, {{AccuracyLiftPoints}} >= 20)
func (tc *AssistantBenchmark) CalcShowsSpatialLiftFromGraphQueries() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.TaskFamily)), vS("Spatial"))), erbIsTrue(vBool(tc.GeneratesDatabaseQueries)), erbBool3(erbCmp(vNum(tc.AccuracyLiftPoints), ">=", vI(20)))))
}

// CalcShowsGeospatialRetrievalLift computes the ShowsGeospatialRetrievalLift calculated field
// TRUE when geospatial retrieval gained 20 or more points once linked to the graph.
// Formula: =AND({{TaskFamily}} = "Geospatial", {{AccuracyLiftPoints}} >= 20)
func (tc *AssistantBenchmark) CalcShowsGeospatialRetrievalLift() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.TaskFamily)), vS("Geospatial"))), erbBool3(erbCmp(vNum(tc.AccuracyLiftPoints), ">=", vI(20)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *AssistantBenchmark) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "accuracy_lift_points", func() { tc.AccuracyLiftPoints = tc.CalcAccuracyLiftPoints() })
	// Level 2
	calcGuard(tc, "shows_spatial_lift_from_graph_queries", func() { tc.ShowsSpatialLiftFromGraphQueries = tc.CalcShowsSpatialLiftFromGraphQueries() })
	calcGuard(tc, "shows_geospatial_retrieval_lift", func() { tc.ShowsGeospatialRetrievalLift = tc.CalcShowsGeospatialRetrievalLift() })
}

