func (tc *GovernedModel) erbErrors() map[string]string {
	if tc.ErbErrors == nil {
		tc.ErbErrors = map[string]string{}
	}
	return tc.ErbErrors
}

func (tc *GovernedModel) erbResetErrors() { tc.ErbErrors = nil }

func (tc *GovernedModel) erbAggregate(name string) Value { return tc.erbAggregates[name] }

func (tc *GovernedModel) erbSetAggregate(name string, v Value) {
	if tc.erbAggregates == nil {
		tc.erbAggregates = map[string]Value{}
	}
	tc.erbAggregates[name] = v
}

// LoadGovernedModelRecords reads GovernedModels rows from a JSON array file.
func LoadGovernedModelRecords(path string) ([]GovernedModel, error) {
	records, err := loadRecords(path, func() Record { return &GovernedModel{} })
	if err != nil {
		return nil, err
	}
	rows := make([]GovernedModel, len(records))
	for i, r := range records {
		rows[i] = *r.(*GovernedModel)
	}
	return rows, nil
}

// =============================================================================
// MODELCHARTERS TABLE
// Ownership charters: who stewards a governed model and who holds authority over it, with written responsibilities, for a period.
// =============================================================================

// ModelCharter represents a row in the ModelCharters table
type ModelCharter struct {
	ModelCharterId string `json:"model_charter_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	GovernedModel *string `json:"governed_model"` // Model chartered.
	StewardRole *string `json:"steward_role"` // Role responsible for the model's health.
	AuthorityRole *string `json:"authority_role"` // Role empowered to approve changes.
	StewardResponsibilities *string `json:"steward_responsibilities"` // The steward's written responsibilities.
	AuthorityApprovalScope *string `json:"authority_approval_scope"` // What the authority approves, stated.
	CharterTemplate *string `json:"charter_template"` // Corporate charter template this charter was drawn from, if any.
	LocalAdaptation *string `json:"local_adaptation"` // How this organization fitted the template to its own procedures, systems and constraints.
	ValidFrom *string `json:"valid_from"` // Charter start.
	ValidTo *string `json:"valid_to"` // Charter end.
	SupersedesCharter *string `json:"supersedes_charter"` // Charter this one replaced.
	EvaluationContext *string `json:"evaluation_context"` // Evaluation context.
	AsOfInstant *string `json:"as_of_instant"` // The modeled instant this row is judged against.
	IsCurrent *bool `json:"is_current"` // TRUE when the charter is in force at the modeled instant.
	StewardAgent *string `json:"steward_agent"` // Who holds the steward role.
	AuthorityAgent *string `json:"authority_agent"` // Who holds the authority role.
	AuthorityOrganization *string `json:"authority_organization"` // Organization the authority role belongs to.
	ModelKind *string `json:"model_kind"` // Kind of model chartered.
	ModelDomainOwner *string `json:"model_domain_owner"` // Function owning the modeled domain.
	ModelHeadcount *int `json:"model_headcount"` // Headcount of the governing organization.
	ModelToolingOwnerRole *string `json:"model_tooling_owner_role"` // Role owning the model's tooling.
	ModelFirstControlAdoptedAt *string `json:"model_first_control_adopted_at"` // When the model's first non-ownership control was adopted.
	IsStewardUnwritten *bool `json:"is_steward_unwritten"` // TRUE when no steward is named or the steward has no written responsibilities.
	IsAuthorityScopeUnstated *bool `json:"is_authority_scope_unstated"` // TRUE when no authority is named or nothing states what it approves.
	ConflatesStewardAndAuthority *bool `json:"conflates_steward_and_authority"` // TRUE when one role is chartered as both steward and authority, so the two responsibilities are never defined apart.
	IsSanctionedDualHolding *bool `json:"is_sanctioned_dual_holding"` // TRUE when one person holds two distinct steward and authority roles in an organization of fifty or fewer, which needs no committee.
	IsAuthorityOutsideDomainOwner *bool `json:"is_authority_outside_domain_owner"` // TRUE when authority over the model rests with a function other than the one that owns the domain.
	ControlsPrecedeOwnership *bool `json:"controls_precede_ownership"` // TRUE when governance controls were adopted before the model's first owner was named.
	StewardActivityCount *int `json:"steward_activity_count"` // Steward activities recorded under the charter.
	LastDriftWatchAt *string `json:"last_drift_watch_at"` // Most recent drift watch under the charter.
	DaysSinceDriftWatch *int `json:"days_since_drift_watch"` // Days since the steward last watched for drift, or since the charter began.
	IsDriftWatchLapsed *bool `json:"is_drift_watch_lapsed"` // TRUE when the steward of a charter in force has not watched for drift in more than ninety days.
	ProcedureDecisionCount *int `json:"procedure_decision_count"` // Procedure change requests the authority role has decided.
	ModelReviewCount *int `json:"model_review_count"` // Model change requests that received authority review.
	IsNamedButUnexercised *bool `json:"is_named_but_unexercised"` // TRUE when a charter in force names a steward who has done nothing or an authority that has decided nothing.
	StewardIsOutsideTooling *bool `json:"steward_is_outside_tooling"` // TRUE when an ontology's steward is not the role that owns the tooling it is built and published with.
	AdoptedTemplateWithoutAdaptation *bool `json:"adopted_template_without_adaptation"` // TRUE when a charter copied a corporate template without fitting it to the organization's own procedures and constraints.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{GovernedModel}} & " / " & {{StewardRole}} & " + " & {{AuthorityRole}}
func (tc *ModelCharter) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.GovernedModel)), vS(" / "), erbText(vStr(tc.StewardRole)), vS(" + "), erbText(vStr(tc.AuthorityRole))))
}

// CalcIsCurrent computes the IsCurrent calculated field
// TRUE when the charter is in force at the modeled instant.
// Formula: =AND({{ValidFrom}} <= {{AsOfInstant}}, OR({{ValidTo}} = "", {{ValidTo}} > {{AsOfInstant}}))
func (tc *ModelCharter) CalcIsCurrent() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vStr(tc.ValidFrom)), "<=", vStr(tc.AsOfInstant))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.ValidTo))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidTo)), ">", vStr(tc.AsOfInstant)))))))
}

// CalcIsStewardUnwritten computes the IsStewardUnwritten calculated field
// TRUE when no steward is named or the steward has no written responsibilities.
// Formula: =OR({{StewardRole}} = "", {{StewardResponsibilities}} = "")
func (tc *ModelCharter) CalcIsStewardUnwritten() *bool {
	return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.StewardRole))), erbBool3(erbIsBlank(vStr(tc.StewardResponsibilities)))))
}

// CalcIsAuthorityScopeUnstated computes the IsAuthorityScopeUnstated calculated field
// TRUE when no authority is named or nothing states what it approves.
// Formula: =OR({{AuthorityRole}} = "", {{AuthorityApprovalScope}} = "")
func (tc *ModelCharter) CalcIsAuthorityScopeUnstated() *bool {
	return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.AuthorityRole))), erbBool3(erbIsBlank(vStr(tc.AuthorityApprovalScope)))))
}

// CalcConflatesStewardAndAuthority computes the ConflatesStewardAndAuthority calculated field
// TRUE when one role is chartered as both steward and authority, so the two responsibilities are never defined apart.
// Formula: =AND({{StewardRole}} <> "", {{StewardRole}} = {{AuthorityRole}})
func (tc *ModelCharter) CalcConflatesStewardAndAuthority() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.StewardRole))), erbBool3(erbEq(erbNullif(vStr(tc.StewardRole)), erbNullif(vStr(tc.AuthorityRole))))))
}

// CalcIsSanctionedDualHolding computes the IsSanctionedDualHolding calculated field
// TRUE when one person holds two distinct steward and authority roles in an organization of fifty or fewer, which needs no committee.
// Formula: =AND({{StewardRole}} <> {{AuthorityRole}}, {{StewardAgent}} <> "", {{StewardAgent}} = {{AuthorityAgent}}, {{ModelHeadcount}} <= 50)
func (tc *ModelCharter) CalcIsSanctionedDualHolding() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNe(erbNullif(vStr(tc.StewardRole)), erbNullif(vStr(tc.AuthorityRole)))), erbBool3(erbIsNotBlank(vStr(tc.StewardAgent))), erbBool3(erbEq(vStr(tc.StewardAgent), vStr(tc.AuthorityAgent))), erbBool3(erbCmp(vInt(tc.ModelHeadcount), "<=", vI(50)))))
}

// CalcIsAuthorityOutsideDomainOwner computes the IsAuthorityOutsideDomainOwner calculated field
// TRUE when authority over the model rests with a function other than the one that owns the domain.
// Formula: =AND({{AuthorityOrganization}} <> "", {{ModelDomainOwner}} <> "", {{AuthorityOrganization}} <> {{ModelDomainOwner}})
func (tc *ModelCharter) CalcIsAuthorityOutsideDomainOwner() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.AuthorityOrganization))), erbBool3(erbIsNotBlank(vStr(tc.ModelDomainOwner))), erbBool3(erbNe(vStr(tc.AuthorityOrganization), vStr(tc.ModelDomainOwner)))))
}

// CalcControlsPrecedeOwnership computes the ControlsPrecedeOwnership calculated field
// TRUE when governance controls were adopted before the model's first owner was named.
// Formula: =AND({{SupersedesCharter}} = "", {{ModelFirstControlAdoptedAt}} <> "", {{ModelFirstControlAdoptedAt}} < {{ValidFrom}})
func (tc *ModelCharter) CalcControlsPrecedeOwnership() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsBlank(vStr(tc.SupersedesCharter))), erbBool3(erbIsNotBlank(vStr(tc.ModelFirstControlAdoptedAt))), erbBool3(erbCmp(vStr(tc.ModelFirstControlAdoptedAt), "<", erbNullif(vStr(tc.ValidFrom))))))
}

// CalcDaysSinceDriftWatch computes the DaysSinceDriftWatch calculated field
// Days since the steward last watched for drift, or since the charter began.
// Formula: =IF({{LastDriftWatchAt}} = "", DATETIME_DIFF({{AsOfInstant}}, {{ValidFrom}}, "days"), DATETIME_DIFF({{AsOfInstant}}, {{LastDriftWatchAt}}, "days"))
func (tc *ModelCharter) CalcDaysSinceDriftWatch() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.LastDriftWatchAt))), func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.ValidFrom), vS("days")) }, func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.LastDriftWatchAt), vS("days")) })))
}

// CalcIsDriftWatchLapsed computes the IsDriftWatchLapsed calculated field
// TRUE when the steward of a charter in force has not watched for drift in more than ninety days.
// Formula: =AND({{IsCurrent}}, {{DaysSinceDriftWatch}} > 90)
func (tc *ModelCharter) CalcIsDriftWatchLapsed() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsCurrent)), erbBool3(erbCmp(vInt(tc.DaysSinceDriftWatch), ">", vI(90)))))
}

// CalcIsNamedButUnexercised computes the IsNamedButUnexercised calculated field
// TRUE when a charter in force names a steward who has done nothing or an authority that has decided nothing.
// Formula: =AND({{IsCurrent}}, OR({{StewardActivityCount}} = 0, ({{ProcedureDecisionCount}} + {{ModelReviewCount}}) = 0))
func (tc *ModelCharter) CalcIsNamedButUnexercised() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsCurrent)), erbBool3(erbOr(erbBool3(erbEq(vInt(tc.StewardActivityCount), vI(0))), erbBool3(erbEq(erbAdd(vInt(tc.ProcedureDecisionCount), vInt(tc.ModelReviewCount)), vI(0)))))))
}

// CalcStewardIsOutsideTooling computes the StewardIsOutsideTooling calculated field
// TRUE when an ontology's steward is not the role that owns the tooling it is built and published with.
// Formula: =AND({{ModelKind}} = "Ontology", {{ModelToolingOwnerRole}} <> "", {{StewardRole}} <> {{ModelToolingOwnerRole}})
func (tc *ModelCharter) CalcStewardIsOutsideTooling() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(vStr(tc.ModelKind), vS("Ontology"))), erbBool3(erbIsNotBlank(vStr(tc.ModelToolingOwnerRole))), erbBool3(erbNe(erbNullif(vStr(tc.StewardRole)), vStr(tc.ModelToolingOwnerRole)))))
}

// CalcAdoptedTemplateWithoutAdaptation computes the AdoptedTemplateWithoutAdaptation calculated field
// TRUE when a charter copied a corporate template without fitting it to the organization's own procedures and constraints.
// Formula: =AND({{CharterTemplate}} <> "", {{LocalAdaptation}} = "")
func (tc *ModelCharter) CalcAdoptedTemplateWithoutAdaptation() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.CharterTemplate))), erbBool3(erbIsBlank(vStr(tc.LocalAdaptation)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ModelCharter) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_current", func() { tc.IsCurrent = tc.CalcIsCurrent() })
	calcGuard(tc, "is_steward_unwritten", func() { tc.IsStewardUnwritten = tc.CalcIsStewardUnwritten() })
	calcGuard(tc, "is_authority_scope_unstated", func() { tc.IsAuthorityScopeUnstated = tc.CalcIsAuthorityScopeUnstated() })
	calcGuard(tc, "conflates_steward_and_authority", func() { tc.ConflatesStewardAndAuthority = tc.CalcConflatesStewardAndAuthority() })
	calcGuard(tc, "is_sanctioned_dual_holding", func() { tc.IsSanctionedDualHolding = tc.CalcIsSanctionedDualHolding() })
	calcGuard(tc, "is_authority_outside_domain_owner", func() { tc.IsAuthorityOutsideDomainOwner = tc.CalcIsAuthorityOutsideDomainOwner() })
	calcGuard(tc, "controls_precede_ownership", func() { tc.ControlsPrecedeOwnership = tc.CalcControlsPrecedeOwnership() })
	calcGuard(tc, "days_since_drift_watch", func() { tc.DaysSinceDriftWatch = tc.CalcDaysSinceDriftWatch() })
	calcGuard(tc, "steward_is_outside_tooling", func() { tc.StewardIsOutsideTooling = tc.CalcStewardIsOutsideTooling() })
	calcGuard(tc, "adopted_template_without_adaptation", func() { tc.AdoptedTemplateWithoutAdaptation = tc.CalcAdoptedTemplateWithoutAdaptation() })
	// Level 2
	calcGuard(tc, "is_drift_watch_lapsed", func() { tc.IsDriftWatchLapsed = tc.CalcIsDriftWatchLapsed() })
	calcGuard(tc, "is_named_but_unexercised", func() { tc.IsNamedButUnexercised = tc.CalcIsNamedButUnexercised() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ModelCharter) ComputeAll() *ModelCharter {
	tc.erbComputeCalculations()
	return tc
}

