// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Title}}
func (tc *ModelChangeRequest) CalcName() *string {
	return toStringPtr(vStr(tc.Title))
}

// CalcRuleKey computes the RuleKey calculated field
// Key of the change-authority rule for this model and layer.
// Formula: ={{GovernedModel}} & "|" & {{ChangeLayer}}
func (tc *ModelChangeRequest) CalcRuleKey() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.GovernedModel)), vS("|"), erbText(vStr(tc.ChangeLayer))))
}

// CalcIsAccepted computes the IsAccepted calculated field
// TRUE once approved or deployed.
// Formula: =OR({{Status}} = "Approved", {{Status}} = "Deployed")
func (tc *ModelChangeRequest) CalcIsAccepted() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Approved"))), erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Deployed")))))
}

// CalcIsModelingChange computes the IsModelingChange calculated field
// TRUE for a modeling change rather than a data operation.
// Formula: ={{Classification}} = "ModelingChange"
func (tc *ModelChangeRequest) CalcIsModelingChange() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.Classification)), vS("ModelingChange")))
}

// CalcIsSchemaChange computes the IsSchemaChange calculated field
// TRUE for a change to the schema layer.
// Formula: ={{ChangeLayer}} = "Schema"
func (tc *ModelChangeRequest) CalcIsSchemaChange() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Schema")))
}

// CalcHasAuthorityReview computes the HasAuthorityReview calculated field
// TRUE when the authority reviewed the change.
// Formula: ={{AuthorityReviewedAt}} <> ""
func (tc *ModelChangeRequest) CalcHasAuthorityReview() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.AuthorityReviewedAt)))
}

// CalcRequiresAuthorityReview computes the RequiresAuthorityReview calculated field
// TRUE when the change alters or retires existing elements or vocabularies, adds disjointness, or is major.
// Formula: =OR({{ChangeOperation}} = "RenameClass", {{ChangeOperation}} = "RemoveClass", {{ChangeOperation}} = "ChangeDomainRange", {{ChangeOperation}} = "AddDisjointness", {{ChangeOperation}} = "AddVocabularyTerm", {{ChangeOperation}} = "RetireDefinition", {{DeclaredScale}} = "Major")
func (tc *ModelChangeRequest) CalcRequiresAuthorityReview() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("RenameClass"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("RemoveClass"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("ChangeDomainRange"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("AddDisjointness"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("AddVocabularyTerm"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("RetireDefinition"))), erbBool3(erbEq(erbNullif(vStr(tc.DeclaredScale)), vS("Major")))))
}

// CalcIsMinorScope computes the IsMinorScope calculated field
// TRUE for a change the steward may approve and deploy alone.
// Formula: =AND({{RequiresAuthorityReview}} = FALSE, {{DeclaredScale}} <> "Major")
func (tc *ModelChangeRequest) CalcIsMinorScope() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(vBool(tc.RequiresAuthorityReview), vB(false))), erbBool3(erbNe(erbNullif(vStr(tc.DeclaredScale)), vS("Major")))))
}

// CalcStewardOwnChangeUnreviewed computes the StewardOwnChangeUnreviewed calculated field
// TRUE when the steward raised a change beyond minor scope and the authority never reviewed it.
// Formula: =AND({{StewardAgent}} <> "", {{RequestedByAgent}} = {{StewardAgent}}, {{IsMinorScope}} = FALSE, {{HasAuthorityReview}} = FALSE)
func (tc *ModelChangeRequest) CalcStewardOwnChangeUnreviewed() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.StewardAgent))), erbBool3(erbEq(erbNullif(vStr(tc.RequestedByAgent)), vStr(tc.StewardAgent))), erbBool3(erbEq(vBool(tc.IsMinorScope), vB(false))), erbBool3(erbEq(vBool(tc.HasAuthorityReview), vB(false)))))
}

// CalcStewardApprovalOutOfBounds computes the StewardApprovalOutOfBounds calculated field
// TRUE when a steward who is not also the authority approved a change beyond the minor changes a steward is authorized to approve.
// Formula: =AND({{ApprovedByAgent}} <> "", {{ApprovedByAgent}} = {{StewardAgent}}, {{ApprovedByAgent}} <> {{AuthorityAgent}}, {{IsMinorScope}} = FALSE)
func (tc *ModelChangeRequest) CalcStewardApprovalOutOfBounds() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ApprovedByAgent))), erbBool3(erbEq(erbNullif(vStr(tc.ApprovedByAgent)), vStr(tc.StewardAgent))), erbBool3(erbNe(erbNullif(vStr(tc.ApprovedByAgent)), vStr(tc.AuthorityAgent))), erbBool3(erbEq(vBool(tc.IsMinorScope), vB(false)))))
}

