// CalcName computes the Name calculated field
// Display name.
// Formula: ={{ModelChangeRequest}} & " " & {{RunPurpose}} & " run"
func (tc *ChangeValidationRun) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ModelChangeRequest)), vS(" "), erbText(vStr(tc.RunPurpose)), vS(" run")))
}

// CalcHasUninspectedFailures computes the HasUninspectedFailures calculated field
// TRUE when a run failed tests and nobody inspected the failures.
// Formula: =AND({{FailureCount}} > 0, {{FailuresInspectedAt}} = "")
func (tc *ChangeValidationRun) CalcHasUninspectedFailures() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vInt(tc.FailureCount)), ">", vI(0))), erbBool3(erbIsBlank(vStr(tc.FailuresInspectedAt)))))
}

// CalcIsUnconfirmedConsistency computes the IsUnconfirmedConsistency calculated field
// TRUE when a run did not confirm the model free of logical inconsistency.
// Formula: ={{ConsistencyCheckOutcome}} <> "Consistent"
func (tc *ChangeValidationRun) CalcIsUnconfirmedConsistency() *bool {
	return toBoolPtr(erbNe(erbNullif(vStr(tc.ConsistencyCheckOutcome)), vS("Consistent")))
}

// CalcMissesExpectedInference computes the MissesExpectedInference calculated field
// TRUE when an expected inference chain was not produced in the run.
// Formula: ={{UnproducedChainCount}} > 0
func (tc *ChangeValidationRun) CalcMissesExpectedInference() *bool {
	return toBoolPtr(erbCmp(vInt(tc.UnproducedChainCount), ">", vI(0)))
}

