func (tc *ChangeValidationRun) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_uninspected_failures", func() { tc.HasUninspectedFailures = tc.CalcHasUninspectedFailures() })
	calcGuard(tc, "is_unconfirmed_consistency", func() { tc.IsUnconfirmedConsistency = tc.CalcIsUnconfirmedConsistency() })
	calcGuard(tc, "misses_expected_inference", func() { tc.MissesExpectedInference = tc.CalcMissesExpectedInference() })
}

