// CalcDaysOpen computes the DaysOpen calculated field
// Days from asking to response, or to now when unanswered.
// Formula: =IF({{AnsweredAt}} = "", DATETIME_DIFF({{AsOfInstant}}, {{AskedAt}}, "days"), DATETIME_DIFF({{AnsweredAt}}, {{AskedAt}}, "days"))
func (tc *StakeholderQuestion) CalcDaysOpen() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.AnsweredAt))), func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.AskedAt), vS("days")) }, func() Value { return erbDatetimeDiff(vStr(tc.AnsweredAt), vStr(tc.AskedAt), vS("days")) })))
}

