	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsOriginalBaseline)), erbBool3(erbCmp(vInt(tc.DaysSinceAdded), ">", vI(365))), erbBool3(erbEq(erbNullif(vStr(tc.RelevanceVerdict)), vS("NoLongerRelevant")))))
