// CalcName computes the Name calculated field
// Display name.
// Formula: ={{ChangeOperation}} & ": " & LEFT({{ChangeSummary}}, 50)
func (tc *ModelChangeLogEntrie) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ChangeOperation)), vS(": "), erbText(erbLeft(vStr(tc.ChangeSummary), vI(50)))))
}

// CalcAltersLogicalModel computes the AltersLogicalModel calculated field
// TRUE for a schema or vocabulary change, as opposed to documentation or instance data.
// Formula: =OR({{ChangeLayer}} = "Schema", {{ChangeLayer}} = "Vocabulary")
func (tc *ModelChangeLogEntrie) CalcAltersLogicalModel() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Schema"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Vocabulary")))))
}

// CalcIsClassRemovalOrRename computes the IsClassRemovalOrRename calculated field
// TRUE when a class is removed or renamed.
// Formula: =OR({{ChangeOperation}} = "RemoveClass", {{ChangeOperation}} = "RenameClass")
func (tc *ModelChangeLogEntrie) CalcIsClassRemovalOrRename() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("RemoveClass"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("RenameClass")))))
}

// CalcIsInvalidatingDomainRangeChange computes the IsInvalidatingDomainRangeChange calculated field
// TRUE for a domain or range change that invalidates existing assertions.
// Formula: =AND({{ChangeOperation}} = "ChangeDomainRange", {{InvalidatesInstances}})
func (tc *ModelChangeLogEntrie) CalcIsInvalidatingDomainRangeChange() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("ChangeDomainRange"))), erbIsTrue(vBool(tc.InvalidatesInstances))))
}

// CalcIsInconsistentDisjointness computes the IsInconsistentDisjointness calculated field
// TRUE for a disjointness axiom that makes existing individuals inconsistent.
// Formula: =AND({{ChangeOperation}} = "AddDisjointness", {{InvalidatesInstances}})
func (tc *ModelChangeLogEntrie) CalcIsInconsistentDisjointness() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("AddDisjointness"))), erbIsTrue(vBool(tc.InvalidatesInstances))))
}

// CalcIsBackwardIncompatible computes the IsBackwardIncompatible calculated field
// TRUE when the change breaks existing data or queries.
// Formula: =OR({{IsClassRemovalOrRename}}, {{InvalidatesInstances}})
func (tc *ModelChangeLogEntrie) CalcIsBackwardIncompatible() *bool {
	return toBoolPtr(erbOr(erbBool3(vBool(tc.IsClassRemovalOrRename)), erbIsTrue(vBool(tc.InvalidatesInstances))))
}

// CalcIsAdditiveSchemaChange computes the IsAdditiveSchemaChange calculated field
// TRUE for a purely additive schema change.
// Formula: =AND({{ChangeLayer}} = "Schema", OR({{ChangeOperation}} = "AddClass", {{ChangeOperation}} = "AddProperty"))
func (tc *ModelChangeLogEntrie) CalcIsAdditiveSchemaChange() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Schema"))), erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("AddClass"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeOperation)), vS("AddProperty")))))))
}

// CalcIsUnexplainedModification computes the IsUnexplainedModification calculated field
// TRUE when a schema or instance modification is logged with no rationale.
// Formula: =AND(OR({{ChangeLayer}} = "Schema", {{ChangeLayer}} = "Instance"), {{Rationale}} = "")
func (tc *ModelChangeLogEntrie) CalcIsUnexplainedModification() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Schema"))), erbBool3(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Instance"))))), erbBool3(erbIsBlank(vStr(tc.Rationale)))))
}

// CalcRationaleWithoutQuestion computes the RationaleWithoutQuestion calculated field
// TRUE when a rationale was recorded but no competency question stands behind it.
// Formula: =AND({{Rationale}} <> "", {{MotivatingQuestion}} = "")
func (tc *ModelChangeLogEntrie) CalcRationaleWithoutQuestion() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.Rationale))), erbBool3(erbIsBlank(vStr(tc.MotivatingQuestion)))))
}

// CalcIsSchemaChangeWithoutIncrement computes the IsSchemaChangeWithoutIncrement calculated field
// TRUE when a schema change shipped in no versioned release.
// Formula: =AND({{ChangeLayer}} = "Schema", {{Release}} = "")
func (tc *ModelChangeLogEntrie) CalcIsSchemaChangeWithoutIncrement() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Schema"))), erbBool3(erbIsBlank(vStr(tc.Release)))))
}

// CalcIsInstanceChangeInSchemaRelease computes the IsInstanceChangeInSchemaRelease calculated field
// TRUE when an instance data change was versioned as a schema release instead of a data version.
// Formula: =AND({{ChangeLayer}} = "Instance", {{Release}} <> "")
func (tc *ModelChangeLogEntrie) CalcIsInstanceChangeInSchemaRelease() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Instance"))), erbBool3(erbIsNotBlank(vStr(tc.Release)))))
}

// CalcSchemaChangeWithoutRequest computes the SchemaChangeWithoutRequest calculated field
// TRUE when a schema change was made outside the change process, with no change request.
// Formula: =AND({{ChangeLayer}} = "Schema", {{ModelChangeRequest}} = "")
func (tc *ModelChangeLogEntrie) CalcSchemaChangeWithoutRequest() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ChangeLayer)), vS("Schema"))), erbBool3(erbIsBlank(vStr(tc.ModelChangeRequest)))))
}

// CalcCannotBeAudited computes the CannotBeAudited calculated field
// TRUE when a change names nobody who made it or no version it belongs to.
// Formula: =OR({{ChangedByAgent}} = "", AND({{Release}} = "", {{InstanceDataVersion}} = ""))
func (tc *ModelChangeLogEntrie) CalcCannotBeAudited() *bool {
	return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.ChangedByAgent))), erbBool3(erbAnd(erbBool3(erbIsBlank(vStr(tc.Release))), erbBool3(erbIsBlank(vStr(tc.InstanceDataVersion)))))))
}

// CalcCannotBeRolledBack computes the CannotBeRolledBack calculated field
// TRUE when no prior-state commit is recorded, so the change cannot be rolled back.
// Formula: ={{PriorStateCommit}} = ""
func (tc *ModelChangeLogEntrie) CalcCannotBeRolledBack() *bool {
	return toBoolPtr(erbIsBlank(vStr(tc.PriorStateCommit)))
}

// CalcIsUntraceableBreakingChange computes the IsUntraceableBreakingChange calculated field
// TRUE when a breaking change cannot be traced to a documented versioning decision.
// Formula: =AND({{IsBackwardIncompatible}}, OR({{Release}} = "", {{ReleaseDecisionUndocumented}}))
func (tc *ModelChangeLogEntrie) CalcIsUntraceableBreakingChange() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsBackwardIncompatible)), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.Release))), erbBool3(vBool(tc.ReleaseDecisionUndocumented))))))
}

