// KNOWLEDGEAUDITS TABLE
// Audits of the procedural knowledge an organization holds against what it needs.
// =============================================================================

// KnowledgeAudit represents a row in the KnowledgeAudits table
type KnowledgeAudit struct {
	KnowledgeAuditId string `json:"knowledge_audit_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	Organization *string `json:"organization"` // Audited organization.
	Title *string `json:"title"` // Audit title.
	ConductedAt *string `json:"conducted_at"` // When the audit was concluded.
	ConductedByAgent *string `json:"conducted_by_agent"` // Who led it.
	ProblemFraming *string `json:"problem_framing"` // How the audit states its problem: KnowledgeDeficit, or CostEfficiency.
	FindingCount *int `json:"finding_count"` // Items where held knowledge falls short of what is needed.
	TreatsDeficitAsCostProblem *bool `json:"treats_deficit_as_cost_problem"` // TRUE when an audit finds knowledge shortfalls but frames them as a cost or efficiency problem instead of acknowledging a knowledge deficit.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Organization}} & ": " & {{Title}}
func (tc *KnowledgeAudit) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Organization)), vS(": "), erbText(vStr(tc.Title))))
}

// CalcTreatsDeficitAsCostProblem computes the TreatsDeficitAsCostProblem calculated field
// TRUE when an audit finds knowledge shortfalls but frames them as a cost or efficiency problem instead of acknowledging a knowledge deficit.
// Formula: =AND({{FindingCount}} > 0, {{ProblemFraming}} <> "KnowledgeDeficit")
func (tc *KnowledgeAudit) CalcTreatsDeficitAsCostProblem() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.FindingCount), ">", vI(0))), erbBool3(erbNe(erbNullif(vStr(tc.ProblemFraming)), vS("KnowledgeDeficit")))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *KnowledgeAudit) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "treats_deficit_as_cost_problem", func() { tc.TreatsDeficitAsCostProblem = tc.CalcTreatsDeficitAsCostProblem() })
}

// ComputeAll computes every calculated field from the row's current inputs.
