// =============================================================================
// KNOWLEDGEAUDITITEMS TABLE
// One knowledge area an audit assessed: the level needed, the level the client holds, and any provider that holds it.
// =============================================================================

// KnowledgeAuditItem represents a row in the KnowledgeAuditItems table
type KnowledgeAuditItem struct {
	KnowledgeAuditItemId string `json:"knowledge_audit_item_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	KnowledgeAudit *string `json:"knowledge_audit"` // Audit.
	SourcingFunction *string `json:"sourcing_function"` // Function the knowledge belongs to.
	KnowledgeArea *string `json:"knowledge_area"` // What must be known.
	KnowledgeKind *string `json:"knowledge_kind"` // Specification (what is built) or Method (how it is built).
	NeededLevel *int `json:"needed_level"` // Level needed: 0 none, 1 aware, 2 can perform with help, 3 can perform and teach.
	HeldInternalLevel *int `json:"held_internal_level"` // Level the client's own people hold, on the same scale.
	ProviderHoldingKnowledge *string `json:"provider_holding_knowledge"` // Provider that holds the knowledge, when one does.
	ProviderHeldLevel *int `json:"provider_held_level"` // Level the provider holds.
	InternalHoldingTeamCount *int `json:"internal_holding_team_count"` // Internal teams that hold the knowledge at the needed level.
	NamedKnowledgeGap *string `json:"named_knowledge_gap"` // The knowledge gap row that names this finding.
	ClientOrganization *string `json:"client_organization"` // The audited organization.
	HasInternalShortfall *bool `json:"has_internal_shortfall"` // TRUE when the client holds less than it needs.
	IsKnowledgeDependency *bool `json:"is_knowledge_dependency"` // TRUE when the client falls short and relies on a provider that holds the knowledge at the needed level.
	IsCoverageGap *bool `json:"is_coverage_gap"` // TRUE when the client falls short and no provider available to it holds the knowledge either.
	IsUnnamedFinding *bool `json:"is_unnamed_finding"` // TRUE when an audit found a gap or dependency and nobody recorded it as a named knowledge gap.
	IsSingleTeamSilo *bool `json:"is_single_team_silo"` // TRUE when knowledge the client does hold sits with exactly one internal team.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{KnowledgeAudit}} & " / " & {{KnowledgeArea}}
func (tc *KnowledgeAuditItem) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.KnowledgeAudit)), vS(" / "), erbText(vStr(tc.KnowledgeArea))))
}

// CalcHasInternalShortfall computes the HasInternalShortfall calculated field
// TRUE when the client holds less than it needs.
// Formula: ={{HeldInternalLevel}} < {{NeededLevel}}
func (tc *KnowledgeAuditItem) CalcHasInternalShortfall() *bool {
	return toBoolPtr(erbCmp(erbNullif(vInt(tc.HeldInternalLevel)), "<", erbNullif(vInt(tc.NeededLevel))))
}

// CalcIsKnowledgeDependency computes the IsKnowledgeDependency calculated field
// TRUE when the client falls short and relies on a provider that holds the knowledge at the needed level.
// Formula: =AND({{HasInternalShortfall}}, {{ProviderHoldingKnowledge}} <> "", {{ProviderHeldLevel}} >= {{NeededLevel}})
func (tc *KnowledgeAuditItem) CalcIsKnowledgeDependency() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasInternalShortfall)), erbBool3(erbIsNotBlank(vStr(tc.ProviderHoldingKnowledge))), erbBool3(erbCmp(erbNullif(vInt(tc.ProviderHeldLevel)), ">=", erbNullif(vInt(tc.NeededLevel))))))
}

// CalcIsCoverageGap computes the IsCoverageGap calculated field
// TRUE when the client falls short and no provider available to it holds the knowledge either.
// Formula: =AND({{HasInternalShortfall}}, NOT({{IsKnowledgeDependency}}))
func (tc *KnowledgeAuditItem) CalcIsCoverageGap() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasInternalShortfall)), erbBool3(erbNot(erbBool3(vBool(tc.IsKnowledgeDependency))))))
}

// CalcIsUnnamedFinding computes the IsUnnamedFinding calculated field
// TRUE when an audit found a gap or dependency and nobody recorded it as a named knowledge gap.
// Formula: =AND({{HasInternalShortfall}}, {{NamedKnowledgeGap}} = "")
func (tc *KnowledgeAuditItem) CalcIsUnnamedFinding() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasInternalShortfall)), erbBool3(erbIsBlank(vStr(tc.NamedKnowledgeGap)))))
}

// CalcIsSingleTeamSilo computes the IsSingleTeamSilo calculated field
// TRUE when knowledge the client does hold sits with exactly one internal team.
// Formula: =AND({{HeldInternalLevel}} >= {{NeededLevel}}, {{InternalHoldingTeamCount}} = 1)
func (tc *KnowledgeAuditItem) CalcIsSingleTeamSilo() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vInt(tc.HeldInternalLevel)), ">=", erbNullif(vInt(tc.NeededLevel)))), erbBool3(erbEq(erbNullif(vInt(tc.InternalHoldingTeamCount)), vI(1)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *KnowledgeAuditItem) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_internal_shortfall", func() { tc.HasInternalShortfall = tc.CalcHasInternalShortfall() })
	calcGuard(tc, "is_single_team_silo", func() { tc.IsSingleTeamSilo = tc.CalcIsSingleTeamSilo() })
	// Level 2
	calcGuard(tc, "is_knowledge_dependency", func() { tc.IsKnowledgeDependency = tc.CalcIsKnowledgeDependency() })
	calcGuard(tc, "is_unnamed_finding", func() { tc.IsUnnamedFinding = tc.CalcIsUnnamedFinding() })
	// Level 3
	calcGuard(tc, "is_coverage_gap", func() { tc.IsCoverageGap = tc.CalcIsCoverageGap() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *KnowledgeAuditItem) ComputeAll() *KnowledgeAuditItem {
	tc.erbComputeCalculations()
	return tc
}

