// =============================================================================
// PROVIDERENGAGEMENTS TABLE
// A client's relationship with a provider for one function, with the knowledge terms it carries.
// =============================================================================

// ProviderEngagement represents a row in the ProviderEngagements table
type ProviderEngagement struct {
	ProviderEngagementId string `json:"provider_engagement_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	ClientOrganization *string `json:"client_organization"` // Client.
	Provider *string `json:"provider"` // Provider.
	SourcingFunction *string `json:"sourcing_function"` // Function the provider performs.
	StartedAt *string `json:"started_at"` // When the engagement started.
	TermMonths *int `json:"term_months"` // Contract term in months.
	Status *string `json:"status"` // Active or Ended.
	DocumentationOwnership *string `json:"documentation_ownership"` // ProviderIP when the documentation the provider produces stays its intellectual property; ClientOwned or Joint otherwise.
	KnowledgeDutyTerms *string `json:"knowledge_duty_terms"` // Any duty the provider carries to build up the client's knowledge; blank when there is none.
	ProviderTreatsKnowHowAsDifferentiator *bool `json:"provider_treats_know_how_as_differentiator"` // TRUE when the provider positions its procedural know-how as its competitive differentiator.
	HasKnowledgeAccessClause *bool `json:"has_knowledge_access_clause"` // TRUE when the contract gives the client access to the process knowledge needed to run the operation.
	KnowledgeReturnPlan *string `json:"knowledge_return_plan"` // How the knowledge comes back to the client; blank when nobody planned it.
	IsActive *bool `json:"is_active"` // TRUE for a running engagement.
	ReliedDependencyCount *int `json:"relied_dependency_count"` // Audit findings where the client relies on this provider's knowledge.
	IsUnplannedKnowledgeReturn *bool `json:"is_unplanned_knowledge_return"` // TRUE when the client relies on a provider's knowledge, the provider keeps the documentation as its property, and nobody planned how the knowledge comes back.
	IsKnowledgeAccessUnsecured *bool `json:"is_knowledge_access_unsecured"` // TRUE when a running engagement is a knowledge dependency and the client has no contractual access to that knowledge.
	RequiredDeliverableCount *int `json:"required_deliverable_count"` // Knowledge deliverables the engagement requires.
	ToClientRequiredCount *int `json:"to_client_required_count"` // Deliverables that move knowledge from the provider to the client.
	ToClientDeliveredCount *int `json:"to_client_delivered_count"` // Delivered knowledge moving from provider to client.
	ToProviderDeliveredCount *int `json:"to_provider_delivered_count"` // Delivered knowledge moving from client to provider.
	JointDeliverableCount *int `json:"joint_deliverable_count"` // Knowledge assets the client and provider build jointly.
	LacksKnowledgeDeliverables *bool `json:"lacks_knowledge_deliverables"` // TRUE when a running engagement requires no knowledge deliverable at all.
	IsOneWayLearning *bool `json:"is_one_way_learning"` // TRUE when a running engagement has knowledge deliverables but knowledge has actually moved in only one direction.
	IsShortTermWithoutJointKnowledge *bool `json:"is_short_term_without_joint_knowledge"` // TRUE when a running engagement is contracted for under three years and builds no knowledge jointly.
	ObligesKnowledgeFlowBack *bool `json:"obliges_knowledge_flow_back"` // TRUE when the engagement requires knowledge deliverables to the client and plans how the knowledge comes back.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{ClientOrganization}} & " <- " & {{Provider}}
func (tc *ProviderEngagement) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ClientOrganization)), vS(" <- "), erbText(vStr(tc.Provider))))
}

// CalcIsActive computes the IsActive calculated field
// TRUE for a running engagement.
// Formula: ={{Status}} = "Active"
func (tc *ProviderEngagement) CalcIsActive() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.Status)), vS("Active")))
}

// CalcIsUnplannedKnowledgeReturn computes the IsUnplannedKnowledgeReturn calculated field
// TRUE when the client relies on a provider's knowledge, the provider keeps the documentation as its property, and nobody planned how the knowledge comes back.
// Formula: =AND({{ReliedDependencyCount}} > 0, {{DocumentationOwnership}} = "ProviderIP", {{KnowledgeReturnPlan}} = "")
func (tc *ProviderEngagement) CalcIsUnplannedKnowledgeReturn() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.ReliedDependencyCount), ">", vI(0))), erbBool3(erbEq(erbNullif(vStr(tc.DocumentationOwnership)), vS("ProviderIP"))), erbBool3(erbIsBlank(vStr(tc.KnowledgeReturnPlan)))))
}

// CalcIsKnowledgeAccessUnsecured computes the IsKnowledgeAccessUnsecured calculated field
// TRUE when a running engagement is a knowledge dependency and the client has no contractual access to that knowledge.
// Formula: =AND({{IsActive}}, {{ReliedDependencyCount}} > 0, {{HasKnowledgeAccessClause}} = FALSE)
func (tc *ProviderEngagement) CalcIsKnowledgeAccessUnsecured() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsActive)), erbBool3(erbCmp(vInt(tc.ReliedDependencyCount), ">", vI(0))), erbBool3(erbEq(erbNullif(vBool(tc.HasKnowledgeAccessClause)), vB(false)))))
}

// CalcLacksKnowledgeDeliverables computes the LacksKnowledgeDeliverables calculated field
// TRUE when a running engagement requires no knowledge deliverable at all.
// Formula: =AND({{IsActive}}, {{RequiredDeliverableCount}} = 0)
func (tc *ProviderEngagement) CalcLacksKnowledgeDeliverables() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsActive)), erbBool3(erbEq(vInt(tc.RequiredDeliverableCount), vI(0)))))
}

// CalcIsOneWayLearning computes the IsOneWayLearning calculated field
// TRUE when a running engagement has knowledge deliverables but knowledge has actually moved in only one direction.
// Formula: =AND({{IsActive}}, {{RequiredDeliverableCount}} > 0, OR({{ToClientDeliveredCount}} = 0, {{ToProviderDeliveredCount}} = 0))
func (tc *ProviderEngagement) CalcIsOneWayLearning() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsActive)), erbBool3(erbCmp(vInt(tc.RequiredDeliverableCount), ">", vI(0))), erbBool3(erbOr(erbBool3(erbEq(vInt(tc.ToClientDeliveredCount), vI(0))), erbBool3(erbEq(vInt(tc.ToProviderDeliveredCount), vI(0)))))))
}

// CalcIsShortTermWithoutJointKnowledge computes the IsShortTermWithoutJointKnowledge calculated field
// TRUE when a running engagement is contracted for under three years and builds no knowledge jointly.
// Formula: =AND({{IsActive}}, {{TermMonths}} < 36, {{JointDeliverableCount}} = 0)
func (tc *ProviderEngagement) CalcIsShortTermWithoutJointKnowledge() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsActive)), erbBool3(erbCmp(erbNullif(vInt(tc.TermMonths)), "<", vI(36))), erbBool3(erbEq(vInt(tc.JointDeliverableCount), vI(0)))))
}

// CalcObligesKnowledgeFlowBack computes the ObligesKnowledgeFlowBack calculated field
// TRUE when the engagement requires knowledge deliverables to the client and plans how the knowledge comes back.
// Formula: =AND({{ToClientRequiredCount}} > 0, {{KnowledgeReturnPlan}} <> "")
func (tc *ProviderEngagement) CalcObligesKnowledgeFlowBack() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.ToClientRequiredCount), ">", vI(0))), erbBool3(erbIsNotBlank(vStr(tc.KnowledgeReturnPlan)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ProviderEngagement) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_active", func() { tc.IsActive = tc.CalcIsActive() })
	calcGuard(tc, "is_unplanned_knowledge_return", func() { tc.IsUnplannedKnowledgeReturn = tc.CalcIsUnplannedKnowledgeReturn() })
	calcGuard(tc, "obliges_knowledge_flow_back", func() { tc.ObligesKnowledgeFlowBack = tc.CalcObligesKnowledgeFlowBack() })
	// Level 2
	calcGuard(tc, "is_knowledge_access_unsecured", func() { tc.IsKnowledgeAccessUnsecured = tc.CalcIsKnowledgeAccessUnsecured() })
	calcGuard(tc, "lacks_knowledge_deliverables", func() { tc.LacksKnowledgeDeliverables = tc.CalcLacksKnowledgeDeliverables() })
	calcGuard(tc, "is_one_way_learning", func() { tc.IsOneWayLearning = tc.CalcIsOneWayLearning() })
	calcGuard(tc, "is_short_term_without_joint_knowledge", func() { tc.IsShortTermWithoutJointKnowledge = tc.CalcIsShortTermWithoutJointKnowledge() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ProviderEngagement) ComputeAll() *ProviderEngagement {
	tc.erbComputeCalculations()
	return tc
}

