// ROLEASSIGNMENTUPDATETASKS TABLE
// The audit record of one change to who fills a role: what triggered it, who triggered it, when it was completed, and the run that depended on it.
// =============================================================================

// RoleAssignmentUpdateTask represents a row in the RoleAssignmentUpdateTasks table
type RoleAssignmentUpdateTask struct {
	RoleAssignmentUpdateTaskId string `json:"role_assignment_update_task_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	Role *string `json:"role"` // Role whose filler changes.
	GoverningPolicy *string `json:"governing_policy"` // Policy governing the update.
	TriggerEvent *string `json:"trigger_event"` // Departure, ModelUpgrade, AiToHumanHandover or HumanToAutomationHandover.
	Reason *string `json:"reason"` // Why the change was made.
	TriggerOccurredAt *string `json:"trigger_occurred_at"` // When the triggering event happened.
	TriggeredAt *string `json:"triggered_at"` // When someone triggered the update; blank when nobody did.
	TriggeredByAgent *string `json:"triggered_by_agent"` // Who triggered it.
	CompletedAt *string `json:"completed_at"` // When the assignment change was recorded in the model; blank when not yet.
	EndingAssignment *string `json:"ending_assignment"` // Assignment that ends.
	ReplacementAssignment *string `json:"replacement_assignment"` // Assignment that replaces it, when there is one.
	DependentExecution *string `json:"dependent_execution"` // The first procedure run after the trigger that needed the role.
	EvaluationContext *string `json:"evaluation_context"` // The instant the row is judged against.
	AsOfInstant *string `json:"as_of_instant"` // The modeled evaluation instant.
	PolicyTriggerOwnerRole *string `json:"policy_trigger_owner_role"` // Role the policy makes responsible for triggering.
	TriggerOwnerCoverCount *int `json:"trigger_owner_cover_count"` // Assignments currently covering that role.
	LacksNamedTriggerOwner *bool `json:"lacks_named_trigger_owner"` // TRUE when governance names no role responsible for triggering the update, or names one nobody holds.
	PolicySlaHours *int `json:"policy_sla_hours"` // Service level in hours.
	ElapsedMinutes *float64 `json:"elapsed_minutes"` // Minutes from the trigger to completion, or to the evaluation instant while incomplete.
	ExceededUpdateSla *bool `json:"exceeded_update_sla"` // TRUE when no service level is defined, or the update took longer than it allows.
	EndingRole *string `json:"ending_role"` // Role of the ending assignment.
	ReplacementRole *string `json:"replacement_role"` // Role of the replacement assignment.
	ChangedRoleInsteadOfAssignment *bool `json:"changed_role_instead_of_assignment"` // TRUE when a change of who does the work was made by moving it to a different role, so the steps bound to the old role had to be re-pointed.
	DependentRunVersion *string `json:"dependent_run_version"` // Version the dependent run enacted.
	DependentRunStartedAt *string `json:"dependent_run_started_at"` // When the dependent run started.
	DependentRunRoleStepCount *int `json:"dependent_run_role_step_count"` // Steps of the dependent run's version assigned to the role.
	MissedNextDependentRun *bool `json:"missed_next_dependent_run"` // TRUE when a run that needs the role started after the trigger and before the assignment change was recorded.
	FailedNoticeCount *int `json:"failed_notice_count"` // Notices for the role in the dependent run that reached the wrong person or nobody.
	StaleAssignmentBrokeRouting *bool `json:"stale_assignment_broke_routing"` // TRUE when the assignment was still stale at a run that needed it and that run's notice for the role reached the wrong person or nobody.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Role}} & " " & {{TriggerEvent}} & " @ " & {{TriggerOccurredAt}}
func (tc *RoleAssignmentUpdateTask) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Role)), vS(" "), erbText(vStr(tc.TriggerEvent)), vS(" @ "), erbDatetimeText(vStr(tc.TriggerOccurredAt))))
}

// CalcLacksNamedTriggerOwner computes the LacksNamedTriggerOwner calculated field
// TRUE when governance names no role responsible for triggering the update, or names one nobody holds.
// Formula: =OR({{PolicyTriggerOwnerRole}} = "", {{TriggerOwnerCoverCount}} = 0)
func (tc *RoleAssignmentUpdateTask) CalcLacksNamedTriggerOwner() *bool {
	return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.PolicyTriggerOwnerRole))), erbBool3(erbEq(vInt(tc.TriggerOwnerCoverCount), vI(0)))))
}

// CalcElapsedMinutes computes the ElapsedMinutes calculated field
// Minutes from the trigger to completion, or to the evaluation instant while incomplete.
// Formula: =IF({{CompletedAt}} = "", DATETIME_DIFF({{AsOfInstant}}, {{TriggerOccurredAt}}, "minutes"), DATETIME_DIFF({{CompletedAt}}, {{TriggerOccurredAt}}, "minutes"))
func (tc *RoleAssignmentUpdateTask) CalcElapsedMinutes() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbIsBlank(vStr(tc.CompletedAt))), func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.TriggerOccurredAt), vS("minutes")) }, func() Value { return erbDatetimeDiff(vStr(tc.CompletedAt), vStr(tc.TriggerOccurredAt), vS("minutes")) }))
}

// CalcExceededUpdateSla computes the ExceededUpdateSla calculated field
// TRUE when no service level is defined, or the update took longer than it allows.
// Formula: =OR({{PolicySlaHours}} = 0, {{ElapsedMinutes}} > ({{PolicySlaHours}} * 60))
func (tc *RoleAssignmentUpdateTask) CalcExceededUpdateSla() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(vInt(tc.PolicySlaHours), vI(0))), erbBool3(erbCmp(vNum(tc.ElapsedMinutes), ">", erbMul(vInt(tc.PolicySlaHours), vI(60))))))
}

// CalcChangedRoleInsteadOfAssignment computes the ChangedRoleInsteadOfAssignment calculated field
// TRUE when a change of who does the work was made by moving it to a different role, so the steps bound to the old role had to be re-pointed.
// Formula: =AND({{ReplacementAssignment}} <> "", {{ReplacementRole}} <> {{EndingRole}})
func (tc *RoleAssignmentUpdateTask) CalcChangedRoleInsteadOfAssignment() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ReplacementAssignment))), erbBool3(erbNe(vStr(tc.ReplacementRole), vStr(tc.EndingRole)))))
}

// CalcMissedNextDependentRun computes the MissedNextDependentRun calculated field
// TRUE when a run that needs the role started after the trigger and before the assignment change was recorded.
// Formula: =AND({{DependentRunRoleStepCount}} > 0, {{DependentRunStartedAt}} > {{TriggerOccurredAt}}, OR({{CompletedAt}} = "", {{CompletedAt}} > {{DependentRunStartedAt}}))
func (tc *RoleAssignmentUpdateTask) CalcMissedNextDependentRun() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.DependentRunRoleStepCount), ">", vI(0))), erbBool3(erbCmp(vStr(tc.DependentRunStartedAt), ">", erbNullif(vStr(tc.TriggerOccurredAt)))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.CompletedAt))), erbBool3(erbCmp(erbNullif(vStr(tc.CompletedAt)), ">", vStr(tc.DependentRunStartedAt)))))))
}

// CalcStaleAssignmentBrokeRouting computes the StaleAssignmentBrokeRouting calculated field
// TRUE when the assignment was still stale at a run that needed it and that run's notice for the role reached the wrong person or nobody.
// Formula: =AND({{MissedNextDependentRun}}, {{FailedNoticeCount}} > 0)
func (tc *RoleAssignmentUpdateTask) CalcStaleAssignmentBrokeRouting() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.MissedNextDependentRun)), erbBool3(erbCmp(vInt(tc.FailedNoticeCount), ">", vI(0)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *RoleAssignmentUpdateTask) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "lacks_named_trigger_owner", func() { tc.LacksNamedTriggerOwner = tc.CalcLacksNamedTriggerOwner() })
	calcGuard(tc, "elapsed_minutes", func() { tc.ElapsedMinutes = tc.CalcElapsedMinutes() })
	calcGuard(tc, "changed_role_instead_of_assignment", func() { tc.ChangedRoleInsteadOfAssignment = tc.CalcChangedRoleInsteadOfAssignment() })
	calcGuard(tc, "missed_next_dependent_run", func() { tc.MissedNextDependentRun = tc.CalcMissedNextDependentRun() })
	// Level 2
	calcGuard(tc, "exceeded_update_sla", func() { tc.ExceededUpdateSla = tc.CalcExceededUpdateSla() })
	calcGuard(tc, "stale_assignment_broke_routing", func() { tc.StaleAssignmentBrokeRouting = tc.CalcStaleAssignmentBrokeRouting() })
}

