// CalcName computes the Name calculated field
// Display name.
// Formula: ={{ProcedureExecution}} & " / " & {{NoticeStep}} & " -> " & {{RoutedToAgent}}
func (tc *AssignmentRoutedNotice) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ProcedureExecution)), vS(" / "), erbText(vStr(tc.NoticeStep)), vS(" -> "), erbText(vStr(tc.RoutedToAgent))))
}

// CalcRecipientRoleKey computes the RecipientRoleKey calculated field
// Recipient and role, as one key.
// Formula: ={{RoutedToAgent}} & "|" & {{NoticeRole}}
func (tc *AssignmentRoutedNotice) CalcRecipientRoleKey() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.RoutedToAgent)), vS("|"), erbText(vStr(tc.NoticeRole))))
}

// CalcRecipientHeldRoleWhenSent computes the RecipientHeldRoleWhenSent calculated field
// TRUE when the recipient's assignment to the step's role was valid at the moment the notice was sent.
// Formula: =AND({{RoutedToAgent}} <> "", {{RecipientPairAssignmentCount}} > 0, {{RecipientValidFrom}} <= {{SentAt}}, OR({{RecipientOpenEndedCount}} > 0, {{RecipientLatestValidTo}} > {{SentAt}}))
func (tc *AssignmentRoutedNotice) CalcRecipientHeldRoleWhenSent() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.RoutedToAgent))), erbBool3(erbCmp(vInt(tc.RecipientPairAssignmentCount), ">", vI(0))), erbBool3(erbCmp(vStr(tc.RecipientValidFrom), "<=", erbNullif(vStr(tc.SentAt)))), erbBool3(erbOr(erbBool3(erbCmp(vInt(tc.RecipientOpenEndedCount), ">", vI(0))), erbBool3(erbCmp(vStr(tc.RecipientLatestValidTo), ">", erbNullif(vStr(tc.SentAt))))))))
}

// CalcReachedWrongPersonOrNobody computes the ReachedWrongPersonOrNobody calculated field
// TRUE when a notice went to someone who did not hold the step's role when it was sent, or to nobody.
// Formula: =NOT({{RecipientHeldRoleWhenSent}})
func (tc *AssignmentRoutedNotice) CalcReachedWrongPersonOrNobody() *bool {
	return toBoolPtr(erbNot(erbBool3(vBool(tc.RecipientHeldRoleWhenSent))))
}

// CalcRoutedAroundModel computes the RoutedAroundModel calculated field
// TRUE when a notice was routed from a separately maintained list and reached someone the model's assignments did not name for the role.
// Formula: =AND({{RoutingSource}} <> "RoleAssignments", NOT({{RecipientHeldRoleWhenSent}}))
func (tc *AssignmentRoutedNotice) CalcRoutedAroundModel() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNe(erbNullif(vStr(tc.RoutingSource)), vS("RoleAssignments"))), erbBool3(erbNot(erbBool3(vBool(tc.RecipientHeldRoleWhenSent))))))
}

