	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ExpertKind)), vS("Detection"))), erbBool3(erbIsNotBlank(vStr(tc.UnstatedBasis))), erbBool3(erbCmp(erbNullif(vInt(tc.ReliableCallCount)), ">=", vI(3)))))
