	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ExpertKind)), vS("DesignForesight"))), erbBool3(erbIsNotBlank(vStr(tc.UnstatedBasis))), erbIsTrue(vBool(tc.ForesightConfirmed))))
