// OBSERVEDACTIONS TABLE
// Actions an observer saw during shadowing or observation, typed as small choices, unofficial workarounds, steps omitted from the practitioner's own account, or documented steps, with the reason given when the observer asked.
// =============================================================================

// ObservedAction represents a row in the ObservedActions table
type ObservedAction struct {
	ObservedActionId string `json:"observed_action_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	ElicitationSession *string `json:"elicitation_session"` // The observation session.
	Step *string `json:"step"` // The step the action belongs to.
	Practitioner *string `json:"practitioner"` // The practitioner observed.
	ActionDescription *string `json:"action_description"` // What the observer saw.
	ActionKind *string `json:"action_kind"` // SmallChoice, Workaround, OmittedObviousStep or DocumentedStep.
	MentionedInOwnAccount *bool `json:"mentioned_in_own_account"` // TRUE when the practitioner's own interview account included the action.
	StatedReason *string `json:"stated_reason"` // The reason the practitioner gave when the observer asked; blank when nobody asked.
	CounterfactualCondition *string `json:"counterfactual_condition"` // The different condition the observer asked about.
	CounterfactualAnswer *string `json:"counterfactual_answer"` // What the practitioner said they would do under that condition.
	CapturedAsFragment *string `json:"captured_as_fragment"` // The knowledge fragment the action was captured as.
	IsSmallChoice *bool `json:"is_small_choice"` // TRUE for a small choice made during actual practice.
	IsUnofficialWorkaround *bool `json:"is_unofficial_workaround"` // TRUE for an unofficial workaround.
	IsOmittedFromOwnAccount *bool `json:"is_omitted_from_own_account"` // TRUE when observation saw an action the practitioner's own account left out.
	IsMissedStepLeftUncaptured *bool `json:"is_missed_step_left_uncaptured"` // TRUE when an action the interview missed was observed but never captured as knowledge.
	IsWatchedNotQuestioned *bool `json:"is_watched_not_questioned"` // TRUE when a small choice or workaround was watched but no reason was asked for and recorded.
	HasRecordedReason *bool `json:"has_recorded_reason"` // TRUE when a reason is recorded against the observed action.
	HasCounterfactualAnswer *bool `json:"has_counterfactual_answer"` // TRUE when the practitioner said what they would do if a condition were different.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{ActionKind}} & ": " & LEFT({{ActionDescription}}, 60)
func (tc *ObservedAction) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ActionKind)), vS(": "), erbText(erbLeft(vStr(tc.ActionDescription), vI(60)))))
}

// CalcIsSmallChoice computes the IsSmallChoice calculated field
// TRUE for a small choice made during actual practice.
// Formula: ={{ActionKind}} = "SmallChoice"
func (tc *ObservedAction) CalcIsSmallChoice() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.ActionKind)), vS("SmallChoice")))
}

// CalcIsUnofficialWorkaround computes the IsUnofficialWorkaround calculated field
// TRUE for an unofficial workaround.
// Formula: ={{ActionKind}} = "Workaround"
func (tc *ObservedAction) CalcIsUnofficialWorkaround() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.ActionKind)), vS("Workaround")))
}

// CalcIsOmittedFromOwnAccount computes the IsOmittedFromOwnAccount calculated field
// TRUE when observation saw an action the practitioner's own account left out.
// Formula: =AND({{ElicitationSession}} <> "", NOT({{MentionedInOwnAccount}}))
func (tc *ObservedAction) CalcIsOmittedFromOwnAccount() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ElicitationSession))), erbBool3(erbNot(erbIsTrue(vBool(tc.MentionedInOwnAccount))))))
}

// CalcIsMissedStepLeftUncaptured computes the IsMissedStepLeftUncaptured calculated field
// TRUE when an action the interview missed was observed but never captured as knowledge.
// Formula: =AND({{IsOmittedFromOwnAccount}}, {{CapturedAsFragment}} = "")
func (tc *ObservedAction) CalcIsMissedStepLeftUncaptured() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsOmittedFromOwnAccount)), erbBool3(erbIsBlank(vStr(tc.CapturedAsFragment)))))
}

// CalcIsWatchedNotQuestioned computes the IsWatchedNotQuestioned calculated field
// TRUE when a small choice or workaround was watched but no reason was asked for and recorded.
// Formula: =AND(OR({{ActionKind}} = "SmallChoice", {{ActionKind}} = "Workaround"), {{StatedReason}} = "")
func (tc *ObservedAction) CalcIsWatchedNotQuestioned() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.ActionKind)), vS("SmallChoice"))), erbBool3(erbEq(erbNullif(vStr(tc.ActionKind)), vS("Workaround"))))), erbBool3(erbIsBlank(vStr(tc.StatedReason)))))
}

// CalcHasRecordedReason computes the HasRecordedReason calculated field
// TRUE when a reason is recorded against the observed action.
// Formula: ={{StatedReason}} <> ""
func (tc *ObservedAction) CalcHasRecordedReason() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.StatedReason)))
}

// CalcHasCounterfactualAnswer computes the HasCounterfactualAnswer calculated field
// TRUE when the practitioner said what they would do if a condition were different.
// Formula: =AND({{CounterfactualCondition}} <> "", {{CounterfactualAnswer}} <> "")
func (tc *ObservedAction) CalcHasCounterfactualAnswer() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.CounterfactualCondition))), erbBool3(erbIsNotBlank(vStr(tc.CounterfactualAnswer)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ObservedAction) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_small_choice", func() { tc.IsSmallChoice = tc.CalcIsSmallChoice() })
	calcGuard(tc, "is_unofficial_workaround", func() { tc.IsUnofficialWorkaround = tc.CalcIsUnofficialWorkaround() })
	calcGuard(tc, "is_omitted_from_own_account", func() { tc.IsOmittedFromOwnAccount = tc.CalcIsOmittedFromOwnAccount() })
	calcGuard(tc, "is_watched_not_questioned", func() { tc.IsWatchedNotQuestioned = tc.CalcIsWatchedNotQuestioned() })
	calcGuard(tc, "has_recorded_reason", func() { tc.HasRecordedReason = tc.CalcHasRecordedReason() })
	calcGuard(tc, "has_counterfactual_answer", func() { tc.HasCounterfactualAnswer = tc.CalcHasCounterfactualAnswer() })
	// Level 2
	calcGuard(tc, "is_missed_step_left_uncaptured", func() { tc.IsMissedStepLeftUncaptured = tc.CalcIsMissedStepLeftUncaptured() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ObservedAction) ComputeAll() *ObservedAction {
	tc.erbComputeCalculations()
	return tc
}

