// WORKFLOWVIEWDIVERGENCES TABLE
// Differing views of how work flows, brought into the open in an elicitation session, and the reconciled account when one was reached.
// =============================================================================

// WorkflowViewDivergence represents a row in the WorkflowViewDivergences table
type WorkflowViewDivergence struct {
	WorkflowViewDivergenceId string `json:"workflow_view_divergence_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	ElicitationSession *string `json:"elicitation_session"` // The session where the views surfaced.
	ProcedureVersion *string `json:"procedure_version"` // The version the divergence is about.
	Step *string `json:"step"` // The step the views differ on.
	ViewA *string `json:"view_a"` // One account of how the work flows.
	HolderA *string `json:"holder_a"` // Who holds the first account.
	ViewB *string `json:"view_b"` // The differing account.
	HolderB *string `json:"holder_b"` // Who holds the second account.
	ReconciledStatement *string `json:"reconciled_statement"` // The account the participants settled on; blank while unsettled.
	ReconciledAt *string `json:"reconciled_at"` // When it was settled.
	ReconciledIntoFragment *string `json:"reconciled_into_fragment"` // The fragment recording the settled account.
	IsReconciled *bool `json:"is_reconciled"` // TRUE when a settled account is recorded.
	IsSurfacedButUnreconciled *bool `json:"is_surfaced_but_unreconciled"` // TRUE when two differing views were brought into the open but never reconciled.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{Step}} & ": " & LEFT({{ViewA}}, 40) & " / " & LEFT({{ViewB}}, 40)
func (tc *WorkflowViewDivergence) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Step)), vS(": "), erbText(erbLeft(vStr(tc.ViewA), vI(40))), vS(" / "), erbText(erbLeft(vStr(tc.ViewB), vI(40)))))
}

// CalcIsReconciled computes the IsReconciled calculated field
// TRUE when a settled account is recorded.
// Formula: ={{ReconciledStatement}} <> ""
func (tc *WorkflowViewDivergence) CalcIsReconciled() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.ReconciledStatement)))
}

// CalcIsSurfacedButUnreconciled computes the IsSurfacedButUnreconciled calculated field
// TRUE when two differing views were brought into the open but never reconciled.
// Formula: =AND({{ViewA}} <> "", {{ViewB}} <> "", {{ReconciledStatement}} = "")
func (tc *WorkflowViewDivergence) CalcIsSurfacedButUnreconciled() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ViewA))), erbBool3(erbIsNotBlank(vStr(tc.ViewB))), erbBool3(erbIsBlank(vStr(tc.ReconciledStatement)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *WorkflowViewDivergence) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_reconciled", func() { tc.IsReconciled = tc.CalcIsReconciled() })
	calcGuard(tc, "is_surfaced_but_unreconciled", func() { tc.IsSurfacedButUnreconciled = tc.CalcIsSurfacedButUnreconciled() })
}

