// Formula: =AND({{FormalizedAs}} = "", {{Carrier}} <> "ProcedureRulebook")
func (tc *KnowledgeHolding) CalcIsUnformalizedProcessKnowledge() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsBlank(vStr(tc.FormalizedAs))), erbBool3(erbNe(erbNullif(vStr(tc.Carrier)), vS("ProcedureRulebook")))))
}

// CalcIsProceduralKnowledge computes the IsProceduralKnowledge calculated field
// TRUE once the knowledge is formalized as a typed fragment of the procedure ontology.
// Formula: ={{FormalizedAs}} <> ""
func (tc *KnowledgeHolding) CalcIsProceduralKnowledge() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.FormalizedAs)))
}

// CalcIsJudgmentOutsideDocument computes the IsJudgmentOutsideDocument calculated field
// TRUE for unformalized knowledge the written SOP says nothing about.
// Formula: =AND({{IsUnsaidInSop}}, {{IsUnformalizedProcessKnowledge}})
func (tc *KnowledgeHolding) CalcIsJudgmentOutsideDocument() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsUnsaidInSop)), erbBool3(vBool(tc.IsUnformalizedProcessKnowledge))))
}

// CalcIsVeteranDiscretion computes the IsVeteranDiscretion calculated field
// TRUE when a veteran resolves an exception or discretionary decision that nothing written encodes.
// Formula: =AND({{HolderIsVeteran}}, {{HandlesExceptionOrDiscretion}}, {{IsUnformalizedProcessKnowledge}})
func (tc *KnowledgeHolding) CalcIsVeteranDiscretion() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.HolderIsVeteran)), erbIsTrue(vBool(tc.HandlesExceptionOrDiscretion)), erbBool3(vBool(tc.IsUnformalizedProcessKnowledge))))
}

// CalcIsFormalizedWithoutElicitationWork computes the IsFormalizedWithoutElicitationWork calculated field
// TRUE when knowledge was formalized into a fragment that no observation, interview or other elicitation produced.
// Formula: =AND({{FormalizedAs}} <> "", {{FormalizedFragmentSession}} = "")
func (tc *KnowledgeHolding) CalcIsFormalizedWithoutElicitationWork() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.FormalizedAs))), erbBool3(erbIsBlank(vStr(tc.FormalizedFragmentSession)))))
}

