// CalcIsMachineAuthored computes the IsMachineAuthored calculated field
// TRUE when an AI agent or pipeline wrote the entry.
// Formula: =AND({{AuthorAgent}} <> "", OR({{AuthorAgentKind}} = "AIAgent", {{AuthorAgentKind}} = "AutomatedPipeline"))
func (tc *KnowledgeRepositoryEntrie) CalcIsMachineAuthored() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.AuthorAgent))), erbBool3(erbOr(erbBool3(erbEq(vStr(tc.AuthorAgentKind), vS("AIAgent"))), erbBool3(erbEq(vStr(tc.AuthorAgentKind), vS("AutomatedPipeline")))))))
}

// CalcOutlivesAuthorTenure computes the OutlivesAuthorTenure calculated field
// TRUE when the entry is still current although its author has left.
// Formula: =AND({{AuthorAgent}} <> "", {{AuthorIsStillEngaged}} = FALSE, {{IsStale}} = FALSE)
func (tc *KnowledgeRepositoryEntrie) CalcOutlivesAuthorTenure() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.AuthorAgent))), erbBool3(erbEq(vBool(tc.AuthorIsStillEngaged), vB(false))), erbBool3(erbEq(vBool(tc.IsStale), vB(false)))))
}

