// =============================================================================
// KNOWLEDGETRACES TABLE
// One trace from a piece of organized knowledge (a process model, an activity definition or a constraint) to the collected material it rests on, with the role the material plays (origin, validation, extension, contradiction), how the knowledge was derived, and who confirmed it.
// =============================================================================

// KnowledgeTrace represents a row in the KnowledgeTraces table
type KnowledgeTrace struct {
	KnowledgeTraceId string `json:"knowledge_trace_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	TargetKind *string `json:"target_kind"` // ProcessModel, ActivityDefinition or Constraint.
	ProcedureVersion *string `json:"procedure_version"` // The process model the traced knowledge belongs to.
	Step *string `json:"step"` // The activity definition traced, when the target is a step.
	Requirement *string `json:"requirement"` // The constraint traced, when the target is a requirement.
	SourceMaterial *string `json:"source_material"` // The collected material the knowledge traces to.
	TraceRole *string `json:"trace_role"` // Origin (knowledge was taken from it), Validates, Extends, or Contradicts.
	TracedAspect *string `json:"traced_aspect"` // What the source is cited for: Sequence, StepDescription, Workaround, ActualExecution or Constraint.
	SourceStatement *string `json:"source_statement"` // Paraphrase of what the source says about the target.
	DerivationRoute *string `json:"derivation_route"` // How the knowledge was produced from the source.
	DerivedByAgent *string `json:"derived_by_agent"` // Who (or what) derived the knowledge from the source.
	ValidatedByAgent *string `json:"validated_by_agent"` // Who confirmed the derived knowledge.
	ValidatedAt *string `json:"validated_at"` // When it was confirmed.
	SourceStatedDurationMinutes *int `json:"source_stated_duration_minutes"` // Duration the source states for the traced step, when it states one.
	ContradictedDocument *string `json:"contradicted_document"` // For a contradiction: the document whose prescription practice departs from.
	SourceMaterialKind *string `json:"source_material_kind"` // Kind of the source material.
	SourceCollectedAt *string `json:"source_collected_at"` // When the knowledge was taken: the material's collection instant.
	SourceRevisedAt *string `json:"source_revised_at"` // Last revision of the document the material was excerpted from.
	SourceIsDocument *bool `json:"source_is_document"` // TRUE when the source is an excerpt of an existing document.
	SourceIsPeopleCapture *bool `json:"source_is_people_capture"` // TRUE when the source was captured from people (transcript or field notes).
	SourceIsPracticeEvidence *bool `json:"source_is_practice_evidence"` // TRUE when the source records work as performed (field notes or an event trace).
	IsSourceChangedSinceTaken *bool `json:"is_source_changed_since_taken"` // TRUE when the source document was revised after the knowledge was taken from it.
	ModeledDurationMinutes *int `json:"modeled_duration_minutes"` // Duration the modeled step carries.
	IsUnfaithfulToSource *bool `json:"is_unfaithful_to_source"` // TRUE when the modeled step's duration differs from the duration its source states.
	DerivedByAgentKind *string `json:"derived_by_agent_kind"` // Kind of the deriving agent.
	IsMachineDerived *bool `json:"is_machine_derived"` // TRUE when a software or AI agent derived the knowledge from its source.
	IsSelfValidated *bool `json:"is_self_validated"` // TRUE when the agent who derived the knowledge is the one who confirmed it.
	HasIncompleteProvenance *bool `json:"has_incomplete_provenance"` // TRUE when the origin, the derivation route or the confirmation is missing.
	ProvenanceStatement *string `json:"provenance_statement"` // Origin, route and confirmation in one line.
	IsAspectUnsupportedBySourceKind *bool `json:"is_aspect_unsupported_by_source_kind"` // TRUE when a workaround is cited to something other than observation notes, or actual execution to something other than an event trace.
	IsDocumentOrigin *bool `json:"is_document_origin"` // TRUE when the knowledge was first taken from a document.
	StepElicitedValidationCount *int `json:"step_elicited_validation_count"` // Validations of the traced step captured from people.
	StepElicitedExtensionCount *int `json:"step_elicited_extension_count"` // Extensions of the traced step captured from people.
	IsDocumentStartNeverValidated *bool `json:"is_document_start_never_validated"` // TRUE when a step taken from a document has never been confirmed by capture from people.
	IsDocumentStartNeverExtended *bool `json:"is_document_start_never_extended"` // TRUE when a step taken from a document has never been extended by capture from people.
	ContradictedDocumentRevisedAt *string `json:"contradicted_document_revised_at"` // Last revision of the contradicted document.
	IsDocumentTrailingPractice *bool `json:"is_document_trailing_practice"` // TRUE when practice evidence collected after the document's last revision contradicts it.
	PrescribedVersusEnacted *string `json:"prescribed_versus_enacted"` // For a contradiction: what the document prescribes against what practice evidence shows.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Display name.
// Formula: ={{TargetKind}} & " <- " & {{SourceMaterial}} & " (" & {{TraceRole}} & ")"
func (tc *KnowledgeTrace) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.TargetKind)), vS(" <- "), erbText(vStr(tc.SourceMaterial)), vS(" ("), erbText(vStr(tc.TraceRole)), vS(")")))
}

// CalcIsSourceChangedSinceTaken computes the IsSourceChangedSinceTaken calculated field
// TRUE when the source document was revised after the knowledge was taken from it.
// Formula: =AND({{SourceRevisedAt}} <> "", {{SourceRevisedAt}} > {{SourceCollectedAt}})
func (tc *KnowledgeTrace) CalcIsSourceChangedSinceTaken() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.SourceRevisedAt))), erbBool3(erbCmp(vStr(tc.SourceRevisedAt), ">", vStr(tc.SourceCollectedAt)))))
}

// CalcIsUnfaithfulToSource computes the IsUnfaithfulToSource calculated field
// TRUE when the modeled step's duration differs from the duration its source states.
// Formula: =AND({{Step}} <> "", {{SourceStatedDurationMinutes}} > 0, {{ModeledDurationMinutes}} <> {{SourceStatedDurationMinutes}})
func (tc *KnowledgeTrace) CalcIsUnfaithfulToSource() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.Step))), erbBool3(erbCmp(erbNullif(vInt(tc.SourceStatedDurationMinutes)), ">", vI(0))), erbBool3(erbNe(vInt(tc.ModeledDurationMinutes), erbNullif(vInt(tc.SourceStatedDurationMinutes))))))
}

// CalcIsMachineDerived computes the IsMachineDerived calculated field
// TRUE when a software or AI agent derived the knowledge from its source.
// Formula: =AND({{DerivedByAgent}} <> "", {{DerivedByAgentKind}} <> "Human")
func (tc *KnowledgeTrace) CalcIsMachineDerived() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.DerivedByAgent))), erbBool3(erbNe(vStr(tc.DerivedByAgentKind), vS("Human")))))
}

// CalcIsSelfValidated computes the IsSelfValidated calculated field
// TRUE when the agent who derived the knowledge is the one who confirmed it.
// Formula: =AND({{ValidatedByAgent}} <> "", {{ValidatedByAgent}} = {{DerivedByAgent}})
func (tc *KnowledgeTrace) CalcIsSelfValidated() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.ValidatedByAgent))), erbBool3(erbEq(erbNullif(vStr(tc.ValidatedByAgent)), erbNullif(vStr(tc.DerivedByAgent))))))
}

// CalcHasIncompleteProvenance computes the HasIncompleteProvenance calculated field
// TRUE when the origin, the derivation route or the confirmation is missing.
// Formula: =OR({{SourceMaterial}} = "", {{DerivationRoute}} = "", {{ValidatedByAgent}} = "")
func (tc *KnowledgeTrace) CalcHasIncompleteProvenance() *bool {
	return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.SourceMaterial))), erbBool3(erbIsBlank(vStr(tc.DerivationRoute))), erbBool3(erbIsBlank(vStr(tc.ValidatedByAgent)))))
}

// CalcProvenanceStatement computes the ProvenanceStatement calculated field
// Origin, route and confirmation in one line.
// Formula: ="From " & {{SourceMaterial}} & "; route: " & {{DerivationRoute}} & "; derived by " & {{DerivedByAgent}} & "; confirmed by " & {{ValidatedByAgent}}
func (tc *KnowledgeTrace) CalcProvenanceStatement() *string {
	return toStringPtr(erbConcat(vS("From "), erbText(vStr(tc.SourceMaterial)), vS("; route: "), erbText(vStr(tc.DerivationRoute)), vS("; derived by "), erbText(vStr(tc.DerivedByAgent)), vS("; confirmed by "), erbText(vStr(tc.ValidatedByAgent))))
}

// CalcIsAspectUnsupportedBySourceKind computes the IsAspectUnsupportedBySourceKind calculated field
// TRUE when a workaround is cited to something other than observation notes, or actual execution to something other than an event trace.
// Formula: =OR(AND({{TracedAspect}} = "Workaround", {{SourceMaterialKind}} <> "FieldNotes"), AND({{TracedAspect}} = "ActualExecution", {{SourceMaterialKind}} <> "MinedEventTrace"))
func (tc *KnowledgeTrace) CalcIsAspectUnsupportedBySourceKind() *bool {
	return toBoolPtr(erbOr(erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.TracedAspect)), vS("Workaround"))), erbBool3(erbNe(vStr(tc.SourceMaterialKind), vS("FieldNotes"))))), erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.TracedAspect)), vS("ActualExecution"))), erbBool3(erbNe(vStr(tc.SourceMaterialKind), vS("MinedEventTrace")))))))
}

// CalcIsDocumentOrigin computes the IsDocumentOrigin calculated field
// TRUE when the knowledge was first taken from a document.
// Formula: =AND({{TraceRole}} = "Origin", {{SourceIsDocument}})
func (tc *KnowledgeTrace) CalcIsDocumentOrigin() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.TraceRole)), vS("Origin"))), erbBool3(vBool(tc.SourceIsDocument))))
}

// CalcIsDocumentStartNeverValidated computes the IsDocumentStartNeverValidated calculated field
// TRUE when a step taken from a document has never been confirmed by capture from people.
// Formula: =AND({{IsDocumentOrigin}}, {{Step}} <> "", {{StepElicitedValidationCount}} = 0)
func (tc *KnowledgeTrace) CalcIsDocumentStartNeverValidated() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsDocumentOrigin)), erbBool3(erbIsNotBlank(vStr(tc.Step))), erbBool3(erbEq(vInt(tc.StepElicitedValidationCount), vI(0)))))
}

// CalcIsDocumentStartNeverExtended computes the IsDocumentStartNeverExtended calculated field
// TRUE when a step taken from a document has never been extended by capture from people.
// Formula: =AND({{IsDocumentOrigin}}, {{Step}} <> "", {{StepElicitedExtensionCount}} = 0)
func (tc *KnowledgeTrace) CalcIsDocumentStartNeverExtended() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsDocumentOrigin)), erbBool3(erbIsNotBlank(vStr(tc.Step))), erbBool3(erbEq(vInt(tc.StepElicitedExtensionCount), vI(0)))))
}

// CalcIsDocumentTrailingPractice computes the IsDocumentTrailingPractice calculated field
// TRUE when practice evidence collected after the document's last revision contradicts it.
// Formula: =AND({{TraceRole}} = "Contradicts", {{ContradictedDocument}} <> "", {{SourceIsPracticeEvidence}}, {{SourceCollectedAt}} > {{ContradictedDocumentRevisedAt}})
func (tc *KnowledgeTrace) CalcIsDocumentTrailingPractice() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.TraceRole)), vS("Contradicts"))), erbBool3(erbIsNotBlank(vStr(tc.ContradictedDocument))), erbBool3(vBool(tc.SourceIsPracticeEvidence)), erbBool3(erbCmp(vStr(tc.SourceCollectedAt), ">", vStr(tc.ContradictedDocumentRevisedAt)))))
}

// CalcPrescribedVersusEnacted computes the PrescribedVersusEnacted calculated field
// For a contradiction: what the document prescribes against what practice evidence shows.
// Formula: =IF({{ContradictedDocument}} = "", "", "Prescribed in " & {{ContradictedDocument}} & "; enacted per " & {{SourceMaterial}} & ": " & {{SourceStatement}})
func (tc *KnowledgeTrace) CalcPrescribedVersusEnacted() *string {
	return toStringPtr(erbIf(erbBool3(erbIsBlank(vStr(tc.ContradictedDocument))), func() Value { return vS("") }, func() Value { return erbConcat(vS("Prescribed in "), erbText(vStr(tc.ContradictedDocument)), vS("; enacted per "), erbText(vStr(tc.SourceMaterial)), vS(": "), erbText(vStr(tc.SourceStatement))) }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *KnowledgeTrace) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_source_changed_since_taken", func() { tc.IsSourceChangedSinceTaken = tc.CalcIsSourceChangedSinceTaken() })
	calcGuard(tc, "is_unfaithful_to_source", func() { tc.IsUnfaithfulToSource = tc.CalcIsUnfaithfulToSource() })
	calcGuard(tc, "is_machine_derived", func() { tc.IsMachineDerived = tc.CalcIsMachineDerived() })
	calcGuard(tc, "is_self_validated", func() { tc.IsSelfValidated = tc.CalcIsSelfValidated() })
	calcGuard(tc, "has_incomplete_provenance", func() { tc.HasIncompleteProvenance = tc.CalcHasIncompleteProvenance() })
	calcGuard(tc, "provenance_statement", func() { tc.ProvenanceStatement = tc.CalcProvenanceStatement() })
	calcGuard(tc, "is_aspect_unsupported_by_source_kind", func() { tc.IsAspectUnsupportedBySourceKind = tc.CalcIsAspectUnsupportedBySourceKind() })
	calcGuard(tc, "is_document_origin", func() { tc.IsDocumentOrigin = tc.CalcIsDocumentOrigin() })
	calcGuard(tc, "is_document_trailing_practice", func() { tc.IsDocumentTrailingPractice = tc.CalcIsDocumentTrailingPractice() })
	calcGuard(tc, "prescribed_versus_enacted", func() { tc.PrescribedVersusEnacted = tc.CalcPrescribedVersusEnacted() })
	// Level 2
	calcGuard(tc, "is_document_start_never_validated", func() { tc.IsDocumentStartNeverValidated = tc.CalcIsDocumentStartNeverValidated() })
	calcGuard(tc, "is_document_start_never_extended", func() { tc.IsDocumentStartNeverExtended = tc.CalcIsDocumentStartNeverExtended() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *KnowledgeTrace) ComputeAll() *KnowledgeTrace {
	tc.erbComputeCalculations()
	return tc
}

