// TRUE when a mined hand-off is recorded as intended logic and nobody decided it should be.
// Formula: =AND({{RecordedStance}} = "Intended", {{IntentDecisionBy}} = "")
func (tc *MinedFlowEdge) CalcIsMinedPathRecordedAsIntentWithoutDecision() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.RecordedStance)), vS("Intended"))), erbBool3(erbIsBlank(vStr(tc.IntentDecisionBy)))))
}

