// ArtifactHandoff represents a row in the ArtifactHandoffs table
type ArtifactHandoff struct {
	ArtifactHandoffId string `json:"artifact_handoff_id"` // Stored identifier.
	Name *string `json:"name"` // Display name.
	StepVariable *string `json:"step_variable"` // The consuming step's input variable this hand-off feeds.
	FromStep *string `json:"from_step"` // Step that produces the artifact.
	ToStep *string `json:"to_step"` // Step that consumes it.
	DeclaredSourceStep *string `json:"declared_source_step"` // Producing step the input variable itself declares.
	DeclaredConsumerStep *string `json:"declared_consumer_step"` // Step that declares the input variable.
	DisagreesWithDeclaredVariable *bool `json:"disagrees_with_declared_variable"` // TRUE when a recorded hand-off names different steps than the input variable it feeds declares, so traversal and declaration have drifted apart.
	HandoffClosure any `json:"handoff_closure"` // Transitive closure of artifact hand-offs (FromStep -> ToStep), materialized as vw_artifact_handoffs_closure: every step an artifact can reach in one or more hand-offs.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Semantic type IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

